// Content for Choosing & Building (node g53, ages 22+, Chapter 7): NEW v2 build to GDD 53 (mechanic-embodying),
// the OPENER of Chapter 7 (Building a Life), where the story turns from 'me' to 'us' (Thread D · Relationships).
// "A wedding is a day; a partnership is the work." 84 researched, India-grounded scenarios across choosing-well →
// what-it-takes → commitment-clearly → love-and-arranged → starting-strong → tools-and-help, each encoded as one
// of the shared v2 play actions (branch / strike-rewrite / sort / reflect / role-play / match / spot): no binary
// "tap the right card". Lead: branch (your move), strike-rewrite (bust the myth), sort. Five themes: choosing well
// (values & compatibility over sparks and timeline), what it takes (communication, trust, repair, interdependence
// build 'us' without erasing 'me'), commitment clearly (thoughtful, eyes-open, not pressure; busts 'marriage
// will fix/complete me'; UN&RE), love & arranged (BOTH paths, the same skills; CONSENT essential in any path;
// family involvement respected but the couple's judgement leads; forced marriage routed to help), starting strong
// (expectations, communication, equality from day one), tools/help. EVERY path respected, including not marrying
// (the counterpoint g54); no pressure toward or against marriage. Consent and respect carried from g31/g44. India:
// marriage is the central life event (arranged & love), with relational pressures (timeline, in-laws, 'log kya
// kahenge'); coercion or forced marriage routed to help (181, 1091, 112, Childline 1098). Builds on g46 & g31;
// sets up g55 & g57. gameId "choosing-building".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"cb-001","cat":"choosing-well","type":"strike-rewrite","hook":"\"Choose a partner on chemistry and sparks alone.\"","myth":{"un":"Choose a partner on chemistry and sparks alone.","re":"Compatibility and shared values are what keep love going; chemistry draws you together, compatibility keeps you together.","why":"Spark fades; shared values and respect last."},"relearn":"Compatibility and shared values keep love going; chemistry alone doesn't.","persona":"Sneha","source":"compatibility over chemistry"},
  {"id":"cb-002","cat":"choosing-well","type":"sort","hook":"Sort each into a deep green flag for a long-term partner, or just surface appeal.","items":[{"id":"a","text":"Treats waiters and elders with respect"},{"id":"b","text":"Looks great in photos"},{"id":"c","text":"Handles disagreement calmly"},{"id":"d","text":"Has an impressive job title"},{"id":"e","text":"Owns a mistake and apologises"},{"id":"f","text":"Wears expensive brands"}],"bins":[{"id":"green","label":"Deep green flag","valence":"pos"},{"id":"surface","label":"Surface appeal","valence":"neutral"}],"key":{"a":"green","b":"surface","c":"green","d":"surface","e":"green","f":"surface"},"relearn":"How they treat others, handle conflict and own mistakes are deep green flags; looks and status are surface.","persona":"any","source":"green flags"},
  {"id":"cb-003","cat":"choosing-well","type":"branch","persona":"any","source":"values vs spark","hook":"The spark with Rehan is strong, but he laughs off your wish to decide money together.","steps":[{"prompt":"He texts to plan a fifth date. What do you do?","options":[{"text":"Say yes, and raise the money comment on the date","then":"Rehan looks surprised and says he was joking. He doesn't ask what you meant.","best":true},{"text":"Say yes and let it go. The spark matters more right now","then":"The date is fun. The money comment never comes up, and you push the feeling away."},{"text":"Stop replying without explaining","then":"Rehan sends two confused messages. You feel relieved, and unsure if you misread him."},{"text":"Ask your cousin whether he seems right for you","then":"Your cousin says he sounds fine. You still feel uneasy and haven't said a word to Rehan."}],"why":"Raising it early shows you how he responds before you invest more."},{"prompt":"A week later, a friend asks how it's going with Rehan. What do you focus on?","options":[{"text":"Whether our values on money fit","then":"Saying it out loud, you realise the laugh bothered you more than you admitted.","best":true},{"text":"How rare this kind of chemistry is","then":"Your friend grins. You leave excited and no clearer."},{"text":"Whether my family would like him","then":"You picture your parents approving, and the money question slips out of view."},{"text":"Whether I'm being too picky about one joke","then":"You start doubting yourself instead of the thing that bothered you."}],"why":"Values decide how a couple handles hard things; chemistry alone doesn't."},{"prompt":"Rehan says money talk is unromantic and asks to just see where things go. What do you do?","options":[{"text":"Say it matters and ask how he sees money in a couple","then":"He pauses, then tells you his parents fought over money. It's your first real talk.","best":true},{"text":"Agree and keep things light for now","then":"The evening stays easy. The question waits for a bigger, harder moment."},{"text":"End it on the spot, since he should already know","then":"Rehan is stunned. You never learn whether he could have met you halfway."},{"text":"Say you're fine with him handling all the money decisions","then":"He relaxes. You feel a small knot of regret on the way home."}],"why":"Asking how he sees it tests your values directly, instead of guessing or giving in."}],"debrief":"Chemistry can't carry a partnership through clashing values. Talk about them early.","relearn":"Take a values mismatch seriously, even when the chemistry is strong."},
  {"id":"cb-004","cat":"choosing-well","type":"strike-rewrite","hook":"\"How someone treats you when calm is the real them.\"","myth":{"un":"How someone treats you when calm is the real them.","re":"How a person behaves under stress, disagreement and when they don't get their way reveals them most.","why":"Anyone is pleasant when things are easy."},"relearn":"How someone behaves under stress and disagreement reveals them most.","persona":"any","source":"under stress"},
  {"id":"cb-005","cat":"choosing-well","type":"match","hook":"Match what to weigh in a long-term partner to why it matters.","relearn":"Shared values, conflict-handling, respect, kindness and honesty are what to weigh in a long-term partner.","persona":"any","source":"what to weigh","pairs":[{"left":"Shared values","right":"Aligns your two lives"},{"left":"How they handle conflict","right":"Predicts the daily peace"},{"left":"Mutual respect","right":"The foundation it all rests on"},{"left":"Kindness to others","right":"Shows their real character"},{"left":"Honesty under pressure","right":"Tells you trust is safe"}]},
  {"id":"cb-006","cat":"choosing-well","type":"branch","persona":"any","source":"your own lens","hook":"Your family is excited about a match, mostly for his caste, salary and looks.","steps":[{"prompt":"Your aunt slides over his biodata: good caste, big salary, model height. What do you do?","options":[{"text":"Agree to meet, and plan to judge him on values","then":"Your aunt beams. You quietly decide what you'll actually ask him.","best":true},{"text":"Say yes right away, since the biodata sounds ideal","then":"Your aunt is thrilled and starts planning the meeting on the family's timeline."},{"text":"Refuse to meet at all, tired of being sized up","then":"Your aunt sighs and sets up one short meeting anyway, just to be polite."},{"text":"Ask her for three more relatives' opinions first","then":"She happily lists them. You still know nothing about him."}],"why":"Meeting on your own terms lets you judge the person, not just the paperwork."},{"prompt":"At the meeting, his family talks proudly about his post and his complexion. What do you focus on?","options":[{"text":"How he talks about his goals and how he listens to you","then":"He turns to you directly and asks what you actually want from life.","best":true},{"text":"Whether his post and paycheck match what your family expects","then":"You leave with a tidy checklist ticked, and barely know him."},{"text":"How impressive the whole family sounds together","then":"The room is warm and easy, and you still haven't heard much of his voice."},{"text":"Whether you two look good together for photos","then":"Everyone agrees you'd make a striking couple in the album."}],"why":"How he talks about goals and listens tells you more than status ever could."},{"prompt":"Later, your mother asks what you thought of him. What do you tell her?","options":[{"text":"That you want to talk to him again before deciding","then":"She nods, surprised, and says that's fair.","best":true},{"text":"That his caste and salary make him a clear yes","then":"She's delighted and starts telling relatives it's settled."},{"text":"That you're unsure, but you'll go along with her view","then":"She takes that as agreement and moves ahead without you."},{"text":"That the looks and status don't matter to you at all","then":"She's puzzled, since you haven't said what does matter instead."}],"why":"Saying what you need keeps the choice values led, not just caste and salary."}],"debrief":"Whatever the route, weighing values and compatibility yourself leads to a sounder choice.","relearn":"Apply your own values-and-compatibility lens, not just status and looks."},
  {"id":"cb-007","cat":"choosing-well","type":"spot","hook":"A partner's behaviour list. Spot the two red flags.","scene":[{"id":"a","text":"They listen and own their mistakes","trick":false},{"id":"b","text":"They love-bomb then go cold","trick":true},{"id":"c","text":"They respect your boundaries","trick":false},{"id":"d","text":"They mock your goals to keep you small","trick":true},{"id":"e","text":"They cheer your wins genuinely","trick":false}],"why":"Love-bombing then cold and mocking your goals are the red flags; listening, respecting boundaries and cheering wins are green.","relearn":"Love-bombing then going cold, and mocking your goals, are red flags; listening and respecting boundaries are green.","persona":"any","source":"green vs red"},
  {"id":"cb-008","cat":"choosing-well","type":"strike-rewrite","hook":"\"Red flags will sort themselves out once you're committed.\"","myth":{"un":"Red flags will sort themselves out once you're committed.","re":"Commitment rarely fixes red flags like control or contempt; they tend to grow.","why":"A ring doesn't change character."},"relearn":"Commitment rarely fixes red flags; control and contempt tend to grow, not vanish.","persona":"any","source":"red flags persist"},
  {"id":"cb-009","cat":"choosing-well","type":"spot","hook":"Partner-choosing patterns. Spot the two that repeat a costly mistake.","scene":[{"id":"a","text":"Valuing steadiness and respect","trick":false},{"id":"b","text":"Chasing only the thrill","trick":true},{"id":"c","text":"Valuing real compatibility","trick":false},{"id":"d","text":"Picking on looks and status alone","trick":true},{"id":"e","text":"Watching how they handle conflict","trick":false}],"why":"Chasing only thrill and picking on looks and status repeat the costly pattern; valuing steadiness, compatibility and conflict-handling is the healthy shift.","relearn":"Shift from chasing thrill, looks and status to valuing steadiness, respect, compatibility and conflict-handling.","persona":"any","source":"changing the pattern"},
  {"id":"cb-010","cat":"choosing-well","type":"choose","persona":"any","source":"the real question","hook":"Ananya and Dev have dated eight months and are starting to talk about forever.","prompt":"Which questions tell them the most about a life together?","options":[{"text":"How do we handle it when we disagree?","fits":true,"note":"How two people disagree shapes almost every year they'd share."},{"text":"What's a fair split of the home work?","fits":true,"note":"Daily fairness at home is part of whether a life together works."},{"text":"How involved will our families be?","fits":true,"note":"Family expectations touch money, time and decisions, so they matter early."},{"text":"Do we like the same music?","fits":false,"note":"Shared music is fun, but it says little about building a life."},{"text":"Are we both big foodies?","fits":false,"note":"Enjoying food together is lovely, but it won't show how you'd handle hard years."},{"text":"Would we look good in wedding photos?","fits":false,"note":"Looking good together is about one day, not the years after it."}],"relearn":"The question that matters isn't just liking someone, but whether you could build a life together."},
  {"id":"cb-011","cat":"choosing-well","type":"sort","hook":"Sort each into a sign of real compatibility, or just infatuation.","items":[{"id":"a","text":"You want similar things from life"},{"id":"b","text":"You can't stop thinking about them"},{"id":"c","text":"You resolve conflict well together"},{"id":"d","text":"The early romance is intense"},{"id":"e","text":"Your core values line up"},{"id":"f","text":"You idealise them and skip their flaws"}],"bins":[{"id":"compat","label":"Compatibility","valence":"pos"},{"id":"infat","label":"Infatuation","valence":"uhoh"}],"key":{"a":"compat","b":"infat","c":"compat","d":"infat","e":"compat","f":"infat"},"relearn":"Wanting similar things, shared values and resolving conflict well is compatibility; intensity and idealising are infatuation.","persona":"any","source":"compatibility signs"},
  {"id":"cb-012","cat":"choosing-well","type":"choose","persona":"any","source":"take your time","hook":"Lavanya is in no rush to decide about the proposal she's just received.","prompt":"Which are real reasons to slow down?","options":[{"text":"She hasn't seen him handle a hard day","fits":true,"note":"Seeing how someone handles a hard day tells her something a good week can't."},{"text":"Some big questions are still unanswered","fits":true,"note":"Not having talked through the big things yet is a solid reason to wait."},{"text":"She wants to be sure it's her own choice","fits":true,"note":"Making sure the yes is truly hers, not borrowed, is worth taking time over."},{"text":"She's got the usual pre-wedding nerves","fits":false,"note":"Ordinary nerves are common; a doubt about how she's treated would be different."},{"text":"Relatives keep asking when it's happening","fits":false,"note":"Other people's curiosity is about them, not a sign she should slow down."},{"text":"Everyone says he's a good catch","fits":false,"note":"Other people's praise isn't a reason either way; her own read matters."}],"relearn":"Take your time choosing a partner; it's one of life's biggest decisions."},
  {"id":"cb-013","cat":"what-it-takes","type":"strike-rewrite","hook":"\"If you really love each other, you won't need to work at it.\"","myth":{"un":"If you really love each other, you won't need to work at it.","re":"Every lasting partnership takes communication, trust and repair; love is built, not just felt.","why":"Even great couples do the daily work."},"relearn":"Every lasting partnership takes work; love is built, not just felt.","persona":"any","source":"love is built"},
  {"id":"cb-014","cat":"what-it-takes","type":"sort","hook":"Sort: builds a lasting partnership, or erodes it?","items":[{"id":"a","text":"Repairing after a fight"},{"id":"b","text":"Letting resentment pile up"},{"id":"c","text":"Appreciating each other often"},{"id":"d","text":"Keeping score of wrongs"},{"id":"e","text":"Owning your share of a mistake"},{"id":"f","text":"Stonewalling when you're upset"}],"bins":[{"id":"builds","label":"Builds it","valence":"pos"},{"id":"erodes","label":"Erodes it","valence":"neg"}],"key":{"a":"builds","b":"erodes","c":"builds","d":"erodes","e":"builds","f":"erodes"},"relearn":"Repair, appreciation and owning your share build a partnership; resentment, scorekeeping and stonewalling erode it.","persona":"any","source":"the daily work"},
  {"id":"cb-015","cat":"what-it-takes","type":"role-play","persona":"any","source":"raising issues","hook":"Your partner Arjun has been on his phone through dinner all week, and it bothers you.","setup":"Tonight he looks up and notices your face.","steps":[{"prompt":"Arjun asks: \"What's wrong? You've been quiet.\"","options":[{"text":"\"I've felt unheard at dinner lately. Can we talk?\"","then":"He puts his phone down. \"Oh. I didn't realise. Tell me.\"","best":true},{"text":"\"Nothing. I'm fine.\"","then":"He shrugs, then puts the phone down after a minute. The silence feels heavier."},{"text":"\"You never listen to me. That's what's wrong.\"","then":"Arjun stiffens. \"That's not fair. I listen all the time.\""},{"text":"\"Maybe we should just eat separately if you're so busy.\"","then":"He looks hurt. \"Is that what you want?\""}],"why":"An \"I felt\" opener names the problem without attacking, so he can listen."},{"prompt":"Arjun says: \"Work has been crazy. I didn't think it mattered.\"","options":[{"text":"\"I get that. Could we keep phones away at dinner?\"","then":"\"That's fair,\" he says. \"Maybe I need that break too.\"","best":true},{"text":"\"It matters. You should have known without me saying.\"","then":"He folds his arms. \"I'm not a mind reader.\""},{"text":"\"Forget it. It's not a big deal.\"","then":"He nods, relieved, and the problem stays exactly where it was."},{"text":"\"Your work always comes first, doesn't it?\"","then":"\"That's not true,\" he snaps, and dinner ends in silence."}],"why":"A small, specific ask is easier to say yes to than blame."},{"prompt":"The next evening, Arjun offers: \"Phones away at dinner. But what if work calls?\"","options":[{"text":"\"Then take it and tell me. The rest is ours.\"","then":"He smiles. \"Deal. Remind me if I slip?\"","best":true},{"text":"\"Then don't answer. Ever.\"","then":"Arjun frowns. \"You know I can't promise that.\""},{"text":"\"Do whatever you want.\"","then":"He can't tell whether you mean it, and neither can you."},{"text":"\"Honestly, we'll see if you even try this time.\"","then":"His face falls. \"I said I would.\""}],"why":"Leaving room for real exceptions makes the agreement fair, so it lasts."}],"relearn":"Raise an issue with an 'I felt...' opener, not a 'you never' attack."},
  {"id":"cb-016","cat":"what-it-takes","type":"strike-rewrite","hook":"\"A good partnership means becoming one person and losing yourself.\"","myth":{"un":"A partnership means losing yourself in the other.","re":"Healthy partnership is interdependence, a team of two whole people; build 'us' without erasing 'me'.","why":"Two whole people make the strongest team."},"relearn":"Healthy partnership is two whole people as a team; build 'us' without erasing 'me'.","persona":"Pooja","source":"us without erasing me"},
  {"id":"cb-017","cat":"what-it-takes","type":"branch","persona":"any","source":"recurring fights","hook":"You and your partner keep having the same argument about chores, and it goes nowhere.","steps":[{"prompt":"The same fight flares up again tonight. What do you do?","options":[{"text":"Keep arguing until someone gives in","then":"The fight drags on for another twenty minutes and ends with both of you drained."},{"text":"Go silent and walk out of the room","then":"The house goes quiet. The chores and the tension are both still there tomorrow."},{"text":"Make a sarcastic joke and drop it","then":"Your partner half laughs, but you can tell the joke didn't land where it needed to."},{"text":"Pause and ask to talk about this properly","then":"Your partner exhales and nods. You move to the sofa instead of the kitchen doorway.","best":true}],"why":"Naming that this keeps happening opens the door to solving it, not just surviving tonight."},{"prompt":"Once you're both calmer, what do you bring up?","options":[{"text":"The same list of who did what this week","then":"You both recite the usual tally. Nothing about it feels different this time."},{"text":"A comment about their personality","then":"Your partner stiffens. The conversation turns defensive fast."},{"text":"A new chore rulebook you drafted alone","then":"Your partner looks at the list warily, unsure where their voice was in it."},{"text":"What each of you actually needs here","then":"Your partner pauses, like no one has asked that part before.","best":true}],"why":"Getting underneath the chores to the real need is what resolves a recurring fight."},{"prompt":"Your partner says they just want to feel noticed for what they already do. What do you do?","options":[{"text":"Say that's not really the issue","then":"Your partner's face closes. The thing they just said gets brushed past."},{"text":"Agree to fix the chore split and stop there","then":"The list changes, but the feeling underneath it never gets a reply."},{"text":"Get defensive about your own effort","then":"The conversation tips back into who has done more instead of moving forward."},{"text":"Share what you've been needing too","then":"You both end up talking about things the chore fight was never really about.","best":true}],"why":"Naming your own need back keeps this a two-way conversation, not one person's confession."},{"prompt":"A similar tension starts building again the next week. What do you do?","options":[{"text":"Let it build until it boils over again","then":"By Friday you're both short with each other, right back where you started."},{"text":"Bring up what you learned before it escalates","then":"The conversation stays calm, and it's shorter than the last one.","best":true},{"text":"Avoid the topic completely this time","then":"The chores pile up quietly, and so does the irritation."},{"text":"Keep a private tally of who's tried harder","then":"You start noticing their effort less and their gaps more."}],"why":"Checking in early, using what you learned, stops the old pattern from repeating."}],"debrief":"Recurring fights usually hide unmet needs. Addressing those, not just the surface, is the work.","relearn":"For a recurring argument, get underneath to what each of you really needs."},
  {"id":"cb-018","cat":"what-it-takes","type":"sort","hook":"Sort: builds trust in a partnership, or breaks it?","items":[{"id":"a","text":"Keeping your promises"},{"id":"b","text":"Hiding things from each other"},{"id":"c","text":"Being reliable day to day"},{"id":"d","text":"Sharing their secrets with others"},{"id":"e","text":"Telling a hard truth gently"},{"id":"f","text":"Snooping through their phone"}],"bins":[{"id":"builds","label":"Builds trust","valence":"pos"},{"id":"breaks","label":"Breaks it","valence":"neg"}],"key":{"a":"builds","b":"breaks","c":"builds","d":"breaks","e":"builds","f":"breaks"},"relearn":"Promises kept, reliability and honest gentleness build trust; hiding, breaking confidences and snooping break it.","persona":"any","source":"trust"},
  {"id":"cb-019","cat":"what-it-takes","type":"role-play","persona":"any","source":"appreciation","hook":"Your partner quietly picked up your mother from the station so you wouldn't miss a work deadline.","setup":"That evening he asks about dinner as if it were nothing.","steps":[{"prompt":"He asks: \"So, what should we order tonight?\"","options":[{"text":"\"Wait, first, thank you. Today really helped me.\"","then":"He pauses, then smiles. \"It wasn't a big deal. I'm glad I could.\"","best":true},{"text":"\"Sure, whatever's easy tonight.\"","then":"He orders food. The station pickup never comes up again."},{"text":"\"You always handle these things so well.\"","then":"He shrugs. \"Someone has to, I guess.\""},{"text":"\"I owe you one for that, seriously. Pizza's on me.\"","then":"He waves it off. \"Don't worry about it.\" The moment passes."}],"why":"Naming it specifically is what lands; a vague nod or a debt isn't the same as thanks."},{"prompt":"A few days later he mentions, almost in passing: \"I moved my Saturday plans for your deadline.\"","options":[{"text":"\"I noticed that, and it means a lot. Thank you.\"","then":"He looks a little surprised, then warmer. \"I'd do it again.\"","best":true},{"text":"\"Oh, you didn't have to do that.\"","then":"He nods slowly. \"I know. I wanted to.\""},{"text":"\"You're basically a saint at this point.\"","then":"He laughs, but it lands a little flat this time."},{"text":"\"Noted, thanks. I'll make it up to you sometime.\"","then":"He goes quiet and changes the subject."}],"why":"Appreciation still counts the second time; it isn't a one-off box to tick."},{"prompt":"Weeks later, after another quiet favour, he half-jokes: \"Do you even notice when I do this stuff?\"","options":[{"text":"\"I do, and I don't say it enough. I see you.\"","then":"He exhales, relieved. \"Okay. That actually helps to hear.\"","best":true},{"text":"\"Of course I notice, don't be dramatic.\"","then":"He half-smiles, but the question hangs there unanswered."},{"text":"\"You know I appreciate you. I just don't say it much.\"","then":"He nods. \"Maybe start saying it, then.\""},{"text":"\"I do plenty for you too, you know.\"","then":"He stiffens. \"That's not what I asked.\""}],"why":"Saying it plainly, out loud, right then, is the whole ask."}],"relearn":"Express appreciation out loud; it's small to do and big for the bond."},
  {"id":"cb-020","cat":"what-it-takes","type":"choose","persona":"any","source":"turning toward","hook":"Anita just told Suresh, mid-chores, that she got a small win at work today.","prompt":"Which responses turn toward her right now?","options":[{"text":"He stops and asks her more about it","fits":true,"note":"Stopping to ask more, even for a minute, is turning toward the moment."},{"text":"He brings it up again at dinner","fits":true,"note":"Bringing it up later shows the small win actually landed and stayed with him."},{"text":"He gives a quick nod and keeps working","fits":false,"note":"A quick nod is polite, but it turns away from the moment, not toward it."},{"text":"He changes the subject to his own day","fits":false,"note":"Changing the subject misses the small opening she just offered."},{"text":"He plans a big weekend trip to celebrate","fits":false,"note":"A big planned trip is generous, but it skips the small moment she shared today."},{"text":"He buys her flowers a week later","fits":false,"note":"Flowers later are sweet, but they don't replace noticing her in the moment."}],"relearn":"A strong partnership is two people turning toward each other, again and again."},
  {"id":"cb-021","cat":"what-it-takes","type":"branch","persona":"any","source":"staying connected","hook":"Life's gotten busy, and you and your partner have stopped really talking.","steps":[{"prompt":"You finally get a free evening together. What do you do?","options":[{"text":"Scroll your phones in the same room","then":"The evening passes side by side, and somehow you still feel far apart."},{"text":"Catch up on errands instead","then":"The list gets shorter. The distance between you doesn't."},{"text":"Wait for your partner to suggest something","then":"You both end up watching something neither of you really chose."},{"text":"Suggest a proper check-in, phones away","then":"Your partner looks up, surprised and glad you said it first.","best":true}],"why":"Naming the drift and choosing to connect is what actually closes the distance."},{"prompt":"Next week fills up fast again, and time together starts slipping. What do you do?","options":[{"text":"Let it slide since this week was fine","then":"Two weeks pass before you notice the gap creeping back."},{"text":"Assume one good evening fixed it","then":"You relax, and the old busyness quietly returns."},{"text":"Wait until you're both stressed to try again","then":"By the time you circle back, you're both running on empty."},{"text":"Put a standing time on the calendar together","then":"It's a small block on both your phones now, hard to accidentally skip.","best":true}],"why":"A protected, repeating time survives busy weeks in a way good intentions alone don't."},{"prompt":"Something urgent threatens the one evening you'd kept for each other this week. What do you do?","options":[{"text":"Cancel it without saying anything","then":"The slot quietly disappears, and neither of you mentions it."},{"text":"Keep it, but stay distracted the whole time","then":"You're both there, but neither of you is really there."},{"text":"Cancel and feel guilty about it alone","then":"You carry the guilt instead of just saying what happened."},{"text":"Reschedule it together instead of skipping","then":"You find a new slot in two minutes, and it feels like less of a loss.","best":true}],"why":"Moving the time together protects the habit instead of quietly letting it lapse."}],"debrief":"Partnerships need protected time to connect. Busyness is exactly when it matters most.","relearn":"Protect regular time to connect. Don't let busyness quietly erode the bond."},
  {"id":"cb-022","cat":"what-it-takes","type":"sort","hook":"Sort: interdependence, or losing yourself?","items":[{"id":"a","text":"Keeping your own friends and interests"},{"id":"b","text":"Giving up everything that's yours"},{"id":"c","text":"Supporting each other's growth"},{"id":"d","text":"Merging into one identity"},{"id":"e","text":"Voicing your own opinion freely"},{"id":"f","text":"Needing permission for small choices"}],"bins":[{"id":"inter","label":"Interdependence","valence":"pos"},{"id":"lost","label":"Losing yourself","valence":"neg"}],"key":{"a":"inter","b":"lost","c":"inter","d":"lost","e":"inter","f":"lost"},"relearn":"Own life, supporting growth and voicing yourself is interdependence; giving it all up is losing yourself.","persona":"any","source":"interdependence"},
  {"id":"cb-023","cat":"commitment-clearly","type":"strike-rewrite","hook":"\"Marriage will fix our problems and complete me.\"","myth":{"un":"Marriage will fix our problems and complete me.","re":"A partnership is built by two whole people; it isn't a cure for problems or loneliness.","why":"Commitment amplifies what's already there, good and bad."},"relearn":"Marriage isn't a cure for problems or loneliness; a partnership is built by two whole people.","persona":"any","source":"marriage won't complete you"},
  {"id":"cb-024","cat":"commitment-clearly","type":"strike-rewrite","hook":"\"A wedding is the goal; after that it's all sorted.\"","myth":{"un":"A wedding is the goal; after that it's sorted.","re":"A wedding is a day; the partnership is the ongoing work that follows.","why":"The real life begins after the celebration."},"relearn":"A wedding is a day; the partnership is the ongoing work.","persona":"any","source":"wedding vs partnership"},
  {"id":"cb-025","cat":"commitment-clearly","type":"branch","persona":"Sneha","source":"not from pressure","hook":"A cousin's wedding video hits the family group, and someone tags you: 'your turn?'","steps":[{"prompt":"Your phone keeps buzzing with the same joke about your turn next. What do you do?","options":[{"text":"Mute the group and think about what you want","then":"The buzzing stops. You notice how relieved that makes you feel.","best":true},{"text":"Reply with a laughing emoji to keep the peace","then":"Three more relatives pile on with the same joke all evening."},{"text":"Ask a family friend if they know any good matches","then":"Within a day, two numbers land in your inbox before you've decided anything."},{"text":"Type back that you'll be married within the year","then":"Your massi screenshots it and starts telling people it's confirmed."}],"why":"Stepping back from the noise gives you room to hear your own answer, not theirs."},{"prompt":"At the next family dinner, someone asks straight out when you'll settle down. What do you say?","options":[{"text":"That you'll marry once you've genuinely chosen someone","then":"Your uncle looks surprised, then shrugs and passes the rice.","best":true},{"text":"That you're 'working on it', mostly to end the conversation","then":"It buys you silence tonight. The same question returns next month."},{"text":"That your job has put you behind schedule","then":"They nod sympathetically, as if something needs fixing in you."},{"text":"That it's nobody's business, sharply","then":"The table goes quiet, and your mother looks embarrassed."}],"why":"Naming a real reason to marry, not a deadline, keeps the choice yours."},{"prompt":"A friend who married last year asks if the pressure ever gets to you. What do you tell her?","options":[{"text":"That pressure won't pick your partner for you","then":"She smiles and says that sounds like the right way to hold it.","best":true},{"text":"That you're starting to wonder if they're right","then":"She says every family has an opinion, and hers hasn't stopped either."},{"text":"That you'll probably give in eventually","then":"She goes quiet, unsure what to say back."},{"text":"That you envy how settled she seems now","then":"She laughs and says it's not as simple as it looks from outside."}],"why":"Refusing to let pressure choose for you is what makes a commitment genuinely yours."}],"debrief":"Marrying to escape pressure or timelines rarely ends well; commitment should be a real choice.","relearn":"Commit when you genuinely choose it, not from pressure or timeline."},
  {"id":"cb-026","cat":"commitment-clearly","type":"strike-rewrite","hook":"\"You should commit because everyone your age is settling down.\"","myth":{"un":"You should commit because everyone your age is settling down.","re":"Your timeline is your own; drifting into commitment to match others rarely lasts.","why":"Other people's timelines aren't yours."},"relearn":"Your timeline is your own; don't drift into commitment to match others.","persona":"any","source":"your timeline"},
  {"id":"cb-027","type":"sort","persona":"any","source":"reasons to commit","hook":"Sort: a sound reason to commit, or a shaky one?","items":[{"id":"a","text":"You choose this person and the work"},{"id":"b","text":"Everyone's asking when"},{"id":"c","text":"You've talked through the real stuff"},{"id":"d","text":"You're afraid of being alone"},{"id":"e","text":"You respect how they treat others"},{"id":"f","text":"You'd look behind if you waited"}],"bins":[{"id":"sound","label":"Sound","valence":"pos"},{"id":"shaky","label":"Shaky","valence":"neg"}],"key":{"a":"sound","b":"shaky","c":"sound","d":"shaky","e":"sound","f":"shaky"},"relearn":"Choosing the person, having talked things through and mutual respect is sound; social pressure and fear of being alone are shaky.","cat":"commitment-clearly"},
  {"id":"cb-028","cat":"commitment-clearly","type":"branch","persona":"any","source":"eyes open","hook":"You and your partner are talking marriage, but money, kids and roles have never come up.","steps":[{"prompt":"You decide to bring up money first. How do you open it?","options":[{"text":"Ask how he imagines handling money together","then":"He pauses, then admits he's never really pictured it either.","best":true},{"text":"Suggest keeping finances totally separate to avoid a fight","then":"He agrees fast, relieved the conversation is already over."},{"text":"Wait for him to bring it up instead","then":"The moment passes, and money quietly goes back on the unspoken list."},{"text":"Say your family will expect him to handle everything","then":"He goes quiet, unsure if that's really what you both want."}],"why":"A curious question, not an assumption, opens the money talk honestly."},{"prompt":"A few days later, the topic turns to children. What do you do?","options":[{"text":"Ask directly whether, and when, he pictures having kids","then":"He says he assumed you'd want them soon. You're glad you asked.","best":true},{"text":"Assume you'll decide once you're actually married","then":"You both let it drop, relieved to skip an awkward guess."},{"text":"Say you already know what you want and expect him to agree","then":"He nods along, though you're not sure he means it."},{"text":"Joke about it to keep the mood light","then":"You both laugh, and the real question goes unanswered again."}],"why":"Asking directly beats assuming you'll agree once you're married."},{"prompt":"Next, the question of roles comes up: who manages the house, money, family visits. What do you do?","options":[{"text":"Talk through what feels fair to each of you, specifically","then":"You both admit you'd pictured different versions of 'normal'.","best":true},{"text":"Assume it'll fall into place like it did for your parents","then":"Neither of you says what you actually want it to look like."},{"text":"Say you'll handle most of it so it's one less fight","then":"He agrees quickly, and the question closes before it opens."},{"text":"Leave it for later, since wedding planning is busy enough","then":"The topic gets pushed past the wedding, again."}],"why":"Naming what feels fair to each of you beats copying a pattern you never chose."},{"prompt":"As the wedding gets closer, what's your approach to these conversations?","options":[{"text":"Agree to keep revisiting these as you plan, not just once","then":"You both feel steadier, having said the hard things out loud.","best":true},{"text":"Consider it done, since you've talked once","then":"You relax, though some of what you said stays only half settled."},{"text":"Decide the hard parts can wait until after the wedding","then":"The wedding gets closer, and the same questions stay open."},{"text":"Let his answers settle it and stop asking your own","then":"You feel lighter for now, and unsure if you were fully heard."}],"why":"Eyes-open commitment means these talks continue, not a one-time box you tick."}],"debrief":"Eyes-open commitment means discussing the big things, money, children, roles, before, not after.","relearn":"Talk through the big topics honestly before you commit."},
  {"id":"cb-029","cat":"commitment-clearly","type":"choose","persona":"any","source":"clear choice","hook":"Sameer is working out, honestly, why he wants to marry Ayesha.","prompt":"Which are solid reasons to say yes?","options":[{"text":"He trusts her through hard days too","fits":true,"note":"Trust that holds under stress says more than butterflies ever could."},{"text":"He loves who she actually is","fits":true,"note":"Loving her as she is, not a version he hopes for, is a steady reason."},{"text":"He wants the life, not just the wedding","fits":true,"note":"Wanting the years together, not only the event, is what makes it real."},{"text":"He'd choose her again most days","fits":true,"note":"A reason that survives ordinary days is worth more than a spark."},{"text":"Everyone their age is settling down","fits":false,"note":"What his friends are doing says nothing about what's right for him."},{"text":"Their families have started planning it","fits":false,"note":"Family excitement is lovely, but it isn't his reason to say yes."}],"relearn":"Commit as a clear, free choice, not because of pressure or drift."},
  {"id":"cb-030","cat":"commitment-clearly","type":"choose","persona":"any","source":"valid not to","hook":"Omkar and Rupali have been together six years and are in no hurry to marry.","prompt":"Which of these are true about them?","options":[{"text":"Their bond is serious without a ring","fits":true,"note":"A ring isn't what makes a relationship serious; how they treat each other does."},{"text":"They can decide together, at their pace","fits":true,"note":"When and whether to marry is genuinely theirs to decide, at their own pace."},{"text":"They're free never to marry, too","fits":true,"note":"Waiting can end in marriage or not, and both are their call."},{"text":"They must decide something soon","fits":false,"note":"There's no deadline they owe anyone; their pace is genuinely their own."},{"text":"Not marrying means it isn't serious","fits":false,"note":"Marriage isn't what measures how serious two people are about each other."},{"text":"Waiting this long means one has doubts","fits":false,"note":"Taking their time says nothing about doubt; it can just be their pace."}],"relearn":"Choosing not to commit yet, or to wait, is just as valid a path."},
  {"id":"cb-031","cat":"love-and-arranged","type":"strike-rewrite","hook":"\"An arranged match means you have no choice or consent.\"","myth":{"un":"An arranged match means no choice or consent.","re":"Consent is essential in any path; you have the right to say yes or no and to take your time.","why":"A match is a proposal, not a command."},"relearn":"Consent is essential in any path; you have the right to say yes or no and to take time.","persona":"any","source":"consent in arranged"},
  {"id":"cb-032","cat":"love-and-arranged","type":"strike-rewrite","hook":"\"Love marriages and arranged marriages need completely different things.\"","myth":{"un":"Love and arranged marriages need completely different things.","re":"Love and arranged marriages need the same foundations: values, compatibility, communication and consent.","why":"The path differs; the skills don't."},"relearn":"Love and arranged marriages need the same foundations: values, compatibility, communication, consent.","persona":"any","source":"same skills"},
  {"id":"cb-033","cat":"love-and-arranged","type":"branch","persona":"any","source":"take time","hook":"The families want an answer on your arranged match within the week.","steps":[{"prompt":"Your parents ask if you're ready to say yes. What do you do?","options":[{"text":"Say you need a few real conversations with him first","then":"Your parents look surprised, then agree to arrange another meeting.","best":true},{"text":"Say yes, since everyone else seems satisfied","then":"The families start planning, and fix one more meeting before the engagement."},{"text":"Say no outright, uneasy about the rush itself","then":"Your parents are confused, and ask you to meet him once more before deciding."},{"text":"Ask your parents to decide for you, since they know him better","then":"They're glad to, and the choice quietly stops being yours."}],"why":"Asking for real conversations brings your own judgement into a rushed process."},{"prompt":"At the next meeting, you get twenty minutes alone with him before tea is served. What do you ask?","options":[{"text":"What he actually wants from a partner and a life together","then":"He relaxes and tells you something he hasn't said to his own family.","best":true},{"text":"Whether he's fine with however the families decide","then":"He says yes to everything, and you learn nothing about him."},{"text":"Nothing much, since twenty minutes feels too short to matter","then":"The tea arrives, and the moment for a real question passes."},{"text":"Whether he'd be comfortable moving the wedding date up","then":"He agrees easily, and the pace never actually slows down."}],"why":"A direct question about what he wants tells you more than twenty polite minutes usually would."},{"prompt":"Both families push to fix the date this week. What do you do?","options":[{"text":"Ask for a bit more time before any date is fixed","then":"There's a pause, then your father says that's reasonable.","best":true},{"text":"Go along with the date to avoid an awkward scene","then":"The date gets fixed before you've finished weighing your own answer."},{"text":"Let your partner decide the date for you both","then":"He picks quickly, unsure it's really his call to make either."},{"text":"Say the rush itself means the answer should be no","then":"Everyone is startled, and you lose the chance to simply ask for space."}],"why":"Asking for time keeps the pace yours, without needing to end things over it."}],"debrief":"You can apply a values-and-compatibility lens, ask real questions, and take time in any process.","relearn":"In an arranged process, ask for time and real conversations before deciding."},
  {"id":"cb-034","type":"match","hook":"Match the question to what it reveals about a match.","relearn":"Asking about goals, conflict style and values reveals real fit.","pairs":[{"left":"\"What do you want from a partnership?\"","right":"Their goals"},{"left":"\"How do you handle disagreements?\"","right":"Conflict style"},{"left":"\"What matters most to you?\"","right":"Their values"},{"left":"\"How should we share money and chores?\"","right":"Fairness expectations"},{"left":"\"How close should our families be?\"","right":"Family boundaries"}],"persona":"any","source":"real questions","cat":"love-and-arranged"},
  {"id":"cb-035","cat":"love-and-arranged","type":"strike-rewrite","hook":"\"Family knows best; the couple's own judgement doesn't really matter.\"","myth":{"un":"Family knows best; the couple's judgement doesn't matter.","re":"Family involvement can be respected, but the couple's own judgement and consent should lead.","why":"They're the ones who'll live the marriage."},"relearn":"Family involvement can be respected, but the couple's own judgement and consent should lead.","persona":"any","source":"couple's judgement"},
  {"id":"cb-036","cat":"love-and-arranged","type":"branch","persona":"any","source":"forced marriage","hook":"Your family has fixed a marriage, and you've said clearly that you don't want it.","steps":[{"prompt":"Your parents say the decision is already made. What do you do?","options":[{"text":"Repeat your no calmly, and tell a trusted person outside the house","then":"A trusted aunt listens quietly and asks how she can help.","best":true},{"text":"Go quiet and hope it somehow doesn't happen","then":"The wedding planning moves ahead without your voice in it."},{"text":"Agree out loud, planning to object again closer to the date","then":"Everyone relaxes, believing it's settled, and the date gets fixed."},{"text":"Threaten to leave the house that night if they don't back down","then":"No one takes it seriously, and the house only watches you more closely."}],"why":"Naming your no to someone outside the house is not disloyalty, and it's not your fault."},{"prompt":"A relative tells you this is normal and you'll thank them later. What do you do?","options":[{"text":"Say your consent is needed, and ask that person for help","then":"She hesitates, then admits she's uneasy about it too.","best":true},{"text":"Stay silent, since arguing has changed nothing so far","then":"The silence gets read as acceptance, and the plans continue."},{"text":"Apologise for causing trouble, to smooth things over","then":"The apology is accepted, and the wedding date isn't."},{"text":"Agree it might work out fine in the end","then":"Your relative repeats it to others as your own words."}],"why":"Your consent is required on any path, and asking for help is not causing trouble."},{"prompt":"With the date approaching, what do you do next?","options":[{"text":"Call a helpline and ask what your options are","then":"Someone listens without judging you, and walks you through what's next.","best":true},{"text":"Wait and see if it resolves itself before the date","then":"The date gets closer with nothing changed."},{"text":"Ask a friend to talk your family out of it for you","then":"Your friend tries, and your family stops listening to outside voices too."},{"text":"Go through with it, since refusing feels impossible now","then":"You lose the chance to let your own consent lead this choice."}],"why":"A helpline exists exactly for this, and calling one is never something to be ashamed of."}],"debrief":"A marriage without your consent is forced marriage, and it is never acceptable. Being pressured into it is never your fault, and help exists.","relearn":"Forced marriage is never okay; your consent is required, and help exists (181, 1098, 112)."},
  {"id":"cb-037","cat":"love-and-arranged","type":"role-play","persona":"any","source":"asking for time","hook":"Your parents want an answer for Vikram's family by the end of the week.","setup":"Your mother sits with you after they leave, hopeful.","steps":[{"prompt":"Your mother asks: \"So? What did you think of him?\"","options":[{"text":"\"He seemed nice. I'd like more time before I decide.\"","then":"She nods slowly, thinking it over.","best":true},{"text":"\"He seemed fine, I suppose, and his family was lovely.\"","then":"She brightens. \"So it's settled then. I'll call them.\""},{"text":"\"I don't know, whatever you all think is best.\"","then":"She smiles, relieved. \"We think he's perfect for you.\""},{"text":"\"Why does it have to be this week?\"","then":"She sighs. \"Their side is asking. It's not really up to us.\""}],"why":"Naming it as wanting time, not just an unsure \"fine\", keeps the choice yours."},{"prompt":"Your mother pauses: \"Before we call them, what would help you feel sure?\"","options":[{"text":"\"A couple of real conversations with him first, not just families.\"","then":"She considers this. \"That's fair, I suppose. I'll ask his side.\"","best":true},{"text":"\"To think it over on my own for a bit.\"","then":"She frowns slightly. \"Think over what? He's a good match on paper.\""},{"text":"\"Honestly, I just have a feeling about it I can't fully explain yet.\"","then":"She looks worried. \"A feeling about what? Did he say something?\""},{"text":"\"Enough time that it doesn't feel rushed.\"","then":"She nods, but presses: \"How much time, then?\""}],"why":"Asking for real conversations, not just a delay, gives the time a clear purpose."},{"prompt":"Your father joins in: \"His family is good, and log kya kahenge if we keep them waiting.\"","options":[{"text":"\"I get that worry, but this is my life to choose carefully.\"","then":"He pauses, then softens. \"Fair enough. Just don't take too long.\"","best":true},{"text":"\"Fine, let's just tell them yes before they ask again.\"","then":"He looks relieved. Your own doubt stays quietly unspoken."},{"text":"\"People will talk regardless of what I do, so let them.\"","then":"He shakes his head. \"That's easy to say. Harder to live with.\""},{"text":"\"Then you decide. I don't mind either way.\"","then":"He looks surprised. \"You don't mind who you marry?\""}],"why":"Naming it as your life to choose meets the worry without letting it decide for you."},{"prompt":"Later, your mother asks gently: \"If you could take the time you wanted, how much would you need?\"","options":[{"text":"\"A few weeks, with two or three honest talks with him in that time.\"","then":"She writes it down. \"Alright. I'll tell his family that much.\"","best":true},{"text":"\"I'm not sure, maybe just a little longer.\"","then":"She hesitates. \"That's hard to tell his family, but alright.\""},{"text":"\"However long it takes, honestly, I really can't put a number on it yet.\"","then":"She looks unsettled by the open-endedness but agrees anyway."},{"text":"\"Let's just say next week and hope that's enough.\"","then":"She agrees, though a week barely changes anything."}],"why":"A clear, specific ask for time is easier for everyone to respect than a vague one."}],"relearn":"You can respectfully ask family for more time and real conversations before deciding on a match."},
  {"id":"cb-038","cat":"love-and-arranged","type":"choose","persona":"any","source":"every path, consent","hook":"Farah's wedding is next month, and relatives keep asking how the match came about.","prompt":"What actually makes this marriage hers?","options":[{"text":"She could still have said no","fits":true,"note":"That real possibility of no is what makes her yes hers."},{"text":"She understood what she was agreeing to","fits":true,"note":"Knowing what you're saying yes to is what makes it yours."},{"text":"No one pressured her into it","fits":true,"note":"A choice made freely, without pressure, is genuinely hers."},{"text":"It began as a love marriage","fits":false,"note":"How they met is a nice detail, not what makes the choice hers."},{"text":"Both families agreed easily","fits":false,"note":"Easy family agreement is lovely, but it isn't her consent."},{"text":"The biodata matched on paper","fits":false,"note":"A good match on paper says nothing about her actual yes."}],"relearn":"Every path is valid; your consent and judgement make it yours."},
  {"id":"cb-039","type":"sort","hook":"Sort: respects the couple, or overrides them?","items":[{"id":"a","text":"Family suggesting, couple deciding"},{"id":"b","text":"Forcing a match against a no"},{"id":"c","text":"Giving the couple time to know each other"},{"id":"d","text":"Ignoring the couple's consent"},{"id":"e","text":"Welcoming the partner the couple chose"},{"id":"f","text":"Silencing the couple's questions"}],"bins":[{"id":"respects","label":"Respects them","valence":"pos"},{"id":"overrides","label":"Overrides them","valence":"neg"}],"key":{"a":"respects","b":"overrides","c":"respects","d":"overrides","e":"respects","f":"overrides"},"relearn":"Suggesting-but-couple-deciding and giving time respects them; forcing against a no overrides them.","persona":"any","source":"respect vs override","cat":"love-and-arranged"},
  {"id":"cb-040","cat":"love-and-arranged","type":"branch","persona":"Aditya","source":"many forms","hook":"Your partner's parents keep asking when you'll have 'a proper wedding' like his cousin's.","steps":[{"prompt":"At a family function, an uncle asks when you'll do things 'the normal way'. What do you do?","options":[{"text":"Say you're building the partnership that's right for you two","then":"He looks unsure, then asks what that actually looks like for you.","best":true},{"text":"Change the subject quickly to avoid any argument at the function","then":"The question goes unanswered, and it comes up again within the hour."},{"text":"Explain the legal position in detail to justify it","then":"His eyes glaze over, and the conversation drifts away from you both."},{"text":"Agree you'll figure out 'the normal way' eventually","then":"He nods, satisfied, though that was never really true."}],"why":"Naming your own kind of partnership, not the expected one, is what actually answers him."},{"prompt":"Later, your partner asks how you want to describe your commitment to his family. What do you say?","options":[{"text":"That you want to name it clearly, your way","then":"He exhales, relieved you both want to say it out loud.","best":true},{"text":"That it's easier left undefined for now","then":"He agrees, though you can tell it costs him something."},{"text":"That his family should decide what to call it","then":"He looks uncomfortable handing that choice away."},{"text":"That labels don't matter as long as you know","then":"He says he still wants the words said, even privately."}],"why":"Saying it clearly, together, is what makes the commitment feel real to you both."},{"prompt":"Planning how to build a life together, what do you focus on?","options":[{"text":"The values, trust and care any partnership needs","then":"You both realise you're already building it, whatever it's called.","best":true},{"text":"Waiting until the law fully recognises you first","then":"You keep your life on hold for a date neither of you controls."},{"text":"Copying the wedding your cousin just had","then":"It looks right in photos, and doesn't quite feel like yours."},{"text":"Downplaying it so it's easier for his parents","then":"It stays easier for them, and smaller for you."}],"why":"The same foundations, values, trust and care, build any partnership, whatever its shape."}],"debrief":"Partnerships come in many valid forms; the skills of values, communication and respect apply to all.","relearn":"Build the partnership that's right for you two; many forms are valid."},
  {"id":"cb-041","cat":"starting-strong","type":"strike-rewrite","hook":"\"Talking about money, roles and expectations before marriage is unromantic.\"","myth":{"un":"Talking about money, roles and expectations is unromantic.","re":"Early talks about money, roles and expectations are how you start strong and avoid painful surprises later.","why":"Clarity now prevents conflict later."},"relearn":"Early talks about money, roles and expectations start a partnership strong, not unromantic.","persona":"any","source":"the early talks"},
  {"id":"cb-042","cat":"starting-strong","type":"branch","persona":"Karthik","source":"equality from day one","hook":"You and Pooja are about to move in together and haven't discussed how you'll share the load.","steps":[{"prompt":"You're planning move-in week. What do you bring up first?","options":[{"text":"Assume it'll sort itself out naturally","then":"You both unpack in silence, each quietly guessing what the other expects."},{"text":"Wait for Pooja to raise it first","then":"The boxes get unpacked before the conversation ever starts."},{"text":"Plan to just help out when you notice something","then":"You picture pitching in, without either of you naming who owns what."},{"text":"Suggest agreeing a fair share of chores and money","then":"Pooja looks relieved someone said it before you'd even moved a box.","best":true}],"why":"Agreeing a fair share from day one is far easier than fixing a lopsided habit later."},{"prompt":"A week in, Pooja asks what a fair split should actually look like for you two. What do you say?","options":[{"text":"Whatever her parents did works fine","then":"Pooja raises an eyebrow. That's not really an answer about the two of you."},{"text":"Whatever's easiest for your own schedule","then":"Pooja notices the plan leans conveniently in your favour."},{"text":"However your own parents have always split it","then":"Pooja points out that was one household, not necessarily yours."},{"text":"Split by what you can each realistically manage","then":"You end up with a list that actually fits both your weeks.","best":true}],"why":"A split based on your real schedules, not a default, is what makes it fair to both of you."},{"prompt":"A month in, the new system needs a tweak. What do you do?","options":[{"text":"Let the imbalance continue quietly","then":"You notice yourself doing more, and saying nothing about it."},{"text":"Assume Pooja will mention it if it bothers her","then":"She's been assuming the same thing about you."},{"text":"Drop the whole system since change is annoying","then":"Without a plan, you both drift back toward old defaults."},{"text":"Bring it up and adjust it together","then":"You redraw one line on the list, and it fits again.","best":true}],"why":"Treating the split as adjustable, not fixed, keeps it fair as your weeks actually change."}],"debrief":"Building equality in from day one is far easier than renegotiating an unfair default later.","relearn":"Agree a fair share of work and money from the start. Don't default to old roles."},
  {"id":"cb-043","cat":"starting-strong","type":"role-play","persona":"any","source":"setting the tone","hook":"You and your fiance Rohan are freshly engaged, and relatives keep joking about who'll be 'boss' of the house.","setup":"That evening, Rohan brings it up himself, half-joking.","steps":[{"prompt":"Rohan says: \"Everyone keeps asking which of us will be in charge. Weird question, right?\"","options":[{"text":"\"Weird. Let's decide now: we build this as equals.\"","then":"He grins. \"Yeah. Equals. I like the sound of that.\"","best":true},{"text":"\"Ha, you can be in charge. I honestly don't mind at all.\"","then":"He laughs it off. \"Sure, sure.\" Neither of you means it."},{"text":"\"People will assume what they assume.\"","then":"He shrugs. \"True.\" The actual question stays unanswered."},{"text":"\"Let's just see how it naturally works out.\"","then":"He nods easily. \"Yeah, it'll sort itself out.\""}],"why":"Naming equal as the plan now sets the tone before habits quietly form."},{"prompt":"Rohan asks: \"So how do we actually split things day to day, then?\"","options":[{"text":"\"Sharing the load and the big decisions, neither of us defaulting to the other.\"","then":"\"Deal,\" he says. \"Let's actually check in on that, not just say it once.\"","best":true},{"text":"\"You handle the money like your dad did, and I'll handle the house like your mum did.\"","then":"He nods, unsure. \"Okay, but how do we know if it's fair?\""},{"text":"\"You handle money, and I'll handle the house, like everyone does.\"","then":"He pauses. \"Isn't that just the old roles again?\""},{"text":"\"Let's not overthink it before we're even married.\"","then":"He looks unconvinced but drops it for now."}],"why":"Spelling out shared load and shared decisions gives \"equal\" something to hold onto."},{"prompt":"Rohan's mother later tells you both: \"In my day, the wife ran the house and that was that.\"","options":[{"text":"\"We're sharing it between us. That's what works for us.\"","then":"She raises an eyebrow, then shrugs. \"Well, it's your household.\"","best":true},{"text":"\"Of course, Aunty, I'll manage the house.\"","then":"Rohan glances at you, surprised, and says nothing."},{"text":"\"Times have changed, Aunty. Nobody does it that way now.\"","then":"She bristles slightly. \"I'm aware, thank you.\""},{"text":"\"We'll figure it out as we go.\"","then":"She nods, unconvinced that anything will really change."}],"why":"Naming the shared plan out loud, even to family, protects it from quietly reverting."}],"relearn":"Name the intention to build as equals early; don't leave roles to default."},
  {"id":"cb-044","type":"spot","persona":"any","source":"strong start","hook":"Spot the two weak-start moves for a new partnership.","scene":[{"id":"a","text":"Honest talks about expectations","trick":false},{"id":"b","text":"Avoiding all hard topics","trick":true},{"id":"c","text":"Agreeing how to handle conflict","trick":false},{"id":"d","text":"Hoping problems just disappear","trick":true},{"id":"e","text":"Naming roles on purpose","trick":false}],"why":"Avoiding hard topics and hoping problems vanish are the weak-start moves; honest talks aren't.","relearn":"Honest talks and agreeing how to handle conflict start a partnership strong.","cat":"starting-strong"},
  {"id":"cb-045","cat":"starting-strong","type":"branch","persona":"any","source":"couple-unit (sets up g57)","hook":"Your families have very different expectations of your new marriage.","steps":[{"prompt":"Both sets of parents start giving conflicting advice. What do you do?","options":[{"text":"Follow whichever parent spoke most recently","then":"Your plans keep changing direction depending on the last phone call."},{"text":"Let each family pull you two in different directions","then":"You and your partner end up arguing about their families instead of talking to each other."},{"text":"Avoid the topic with both families","then":"The advice keeps coming anyway, just without your input in the room."},{"text":"Agree with your partner how to navigate it","then":"You and your partner spend an evening working out what you actually want.","best":true}],"why":"Deciding together first gives you a united answer before either family weighs in again."},{"prompt":"At the next family dinner, an elder pushes for their preference directly. What do you do?","options":[{"text":"Agree on the spot to avoid conflict","then":"You leave dinner having promised something you and your partner never actually agreed to."},{"text":"Blame your partner for the decision","then":"Your partner looks stung, right there at the table."},{"text":"Argue back sharply until they drop it","then":"The table goes quiet, and the elder looks more hurt than convinced."},{"text":"Kindly share the decision you made together","then":"The elder isn't thrilled, but hears it as a joint answer, not a rejection.","best":true}],"why":"Presenting it as a joint decision makes it about the couple's choice, not a personal snub."},{"prompt":"The other family hears about it and feels overlooked. What do you do?","options":[{"text":"Quietly switch to favour them instead","then":"You're now navigating the exact seesaw you were trying to avoid."},{"text":"Let your partner go smooth it over with that family alone","then":"Your partner ends up defending a decision you made together, by themselves."},{"text":"Avoid both families for a while","then":"The silence makes both sides more suspicious, not less."},{"text":"Explain the same reasoning to both families","then":"It takes two similar conversations, but both families hear the same thing.","best":true}],"why":"Treating both families the same way makes the boundary feel fair instead of picking sides."},{"prompt":"A similar clash comes up again at the next function. What do you do?","options":[{"text":"Go back to letting each side pull at you","then":"You're back to guessing whose advice wins this time."},{"text":"Let it slide since it's \"just one function\"","then":"One exception quietly becomes the new expectation."},{"text":"Let your partner decide alone this time","then":"Your partner carries a decision that was supposed to be shared."},{"text":"Lean on the boundary you already set together","then":"It takes less explaining this time. You've done it before.","best":true}],"why":"A boundary you've already agreed on holds up faster each time you use it together."}],"debrief":"Facing family expectations as a united couple, with kind boundaries, sets up the years ahead.","relearn":"Navigate family expectations together as a couple. Don't let each family pull you apart."},
  {"id":"cb-046","type":"spot","persona":"any","source":"early habits","hook":"Spot the two early habits that set a partnership up badly.","scene":[{"id":"a","text":"Communicating openly from the start","trick":false},{"id":"b","text":"Avoiding all hard topics early","trick":true},{"id":"c","text":"Repairing after small fights","trick":false},{"id":"d","text":"Letting resentment quietly build","trick":true},{"id":"e","text":"Saying thanks out loud","trick":false}],"why":"Avoiding hard topics and letting resentment build are the bad early habits; open talk and repair aren't.","relearn":"The habits you build early set the pattern; start with communication and repair.","cat":"starting-strong"},
  {"id":"cb-047","type":"sort","persona":"Nisha","source":"early conversations","hook":"Sort: a conversation worth having early, or one to skip?","items":[{"id":"a","text":"Whether and when to have children"},{"id":"b","text":"Nothing, just see what happens"},{"id":"c","text":"How money will work between you"},{"id":"d","text":"Steering clear of anything that might cause friction"},{"id":"e","text":"How you'll share home and care work"},{"id":"f","text":"Dodging topics to keep the peace"}],"bins":[{"id":"have","label":"Have it early","valence":"pos"},{"id":"skip","label":"Skip / avoid","valence":"neg"}],"key":{"a":"have","b":"skip","c":"have","d":"skip","e":"have","f":"skip"},"relearn":"Children, money and sharing work are worth having early; avoiding friction by avoiding topics isn't.","cat":"starting-strong"},
  {"id":"cb-048","cat":"tools-and-help","type":"match","persona":"any","source":"the toolkit","relearn":"A compatibility reflection helps choosing, 'I' statements help raising issues, repair attempts heal fights.","hook":"Match the partnership tool to what it's for.","pairs":[{"left":"A compatibility reflection","right":"Choosing well"},{"left":"'I felt...' statements","right":"Raising issues kindly"},{"left":"A repair attempt","right":"Healing after a fight"},{"left":"A regular check-in","right":"Staying connected"},{"left":"Naming the mental load","right":"Sharing it fairly"}]},
  {"id":"cb-049","cat":"tools-and-help","type":"match","persona":"any","source":"green vs warning","relearn":"Disagree-and-repair and feeling like a team signal building well; eggshells and contempt are warnings.","hook":"Match the sign to what it tells you about a partnership.","pairs":[{"left":"You disagree and repair","right":"Building well"},{"left":"You feel like a team","right":"Healthy bond"},{"left":"You walk on eggshells","right":"A warning sign"},{"left":"Contempt creeps in","right":"A red flag"},{"left":"You're both heard","right":"Mutual respect"}]},
  {"id":"cb-050","cat":"tools-and-help","type":"match","persona":"any","source":"the recipe","relearn":"Small steady moves, from early talks to quick repairs and fair chores, are what build a partnership.","hook":"Match the partnership step to what it does.","pairs":[{"left":"Talking about children before marrying","right":"No surprise about a big life goal"},{"left":"Saying sorry after a fight","right":"Trust starts to mend"},{"left":"A weekly check-in chat","right":"Small worries surface early"},{"left":"Splitting chores fairly","right":"Nobody quietly burns out"},{"left":"Asking for time before deciding","right":"A yes that is really yours"}]},
  {"id":"cb-051","cat":"tools-and-help","type":"match","persona":"Saxena","source":"help routes","relearn":"181 for forced marriage, 1091 for harassment, 112 in danger, 1098 for a child, a counsellor for a struggling bond.","hook":"Match the need to where help lives (India).","pairs":[{"left":"Pressure or forced marriage","right":"Women Helpline 181"},{"left":"A child being married off","right":"Childline 1098"},{"left":"A struggling partnership","right":"A couples counsellor"},{"left":"Immediate danger at home","right":"Emergency 112"},{"left":"A woman facing harassment","right":"Women-in-distress 1091"}]},
  {"id":"cb-052","cat":"tools-and-help","type":"role-play","persona":"any","source":"the real thing","hook":"Your friend Meher has spent three months planning her wedding and can't talk about anything else.","setup":"Over coffee, she pulls up yet another decor mood board.","steps":[{"prompt":"Meher asks: \"Gold or rose gold for the mandap lights? Be honest.\"","options":[{"text":"\"Rose gold, sure. Can I ask how things with Karan actually are?\"","then":"She blinks, then laughs. \"Oh. Fine, I guess? We haven't really talked lately.\"","best":true},{"text":"\"Rose gold, and honestly the whole thing needs to be perfect.\"","then":"She nods hard. \"Exactly. Perfect. That's exactly what I'm going for.\""},{"text":"\"Whatever you like, it's your day.\"","then":"She goes back to scrolling, and the question passes by unasked."},{"text":"\"Does it even matter that much?\"","then":"She looks stung. \"It matters to me, okay?\""}],"why":"Turning toward Karan, gently, opens space for what the planning is covering for."},{"prompt":"Meher sighs: \"Yeah, the wedding is everything right now, honestly.\"","options":[{"text":"\"The wedding's one day. What matters more is the life after it.\"","then":"She goes quiet for a second. \"I haven't really thought about after.\"","best":true},{"text":"\"It won't feel like everything forever, don't worry about it.\"","then":"She shrugs, then goes quiet over the flower photos."},{"text":"\"As long as you're happy, that's what counts.\"","then":"She nods and returns straight to the mood board."},{"text":"\"You only get one wedding day, make it count.\"","then":"She brightens. \"Right? That's what I keep telling myself.\""}],"why":"Naming the wedding as one day, not the whole story, gently widens the lens."},{"prompt":"She admits: \"I don't actually know what Karan and I have talked about, other than seating charts.\"","options":[{"text":"\"Maybe start there. One real talk, no decor, this week?\"","then":"She exhales. \"Yeah. Okay. I'll ask him tonight.\"","best":true},{"text":"\"You two will figure it out once the wedding's done, honestly.\"","then":"She looks relieved to hear that, and the topic drops."},{"text":"\"That's normal, everyone's like that before a wedding.\"","then":"She relaxes, reassured, and picks the mood board back up."},{"text":"\"Maybe you're not as ready as you think.\"","then":"She stiffens. \"That's a harsh thing to say.\""}],"why":"A concrete next step turns the realisation into something that actually happens."}],"relearn":"A wedding is a day; the partnership you build is the real thing."},
  {"id":"cb-053","cat":"tools-and-help","type":"branch","persona":"any","source":"helping friends","hook":"Your friend Meera is choosing a partner mostly to satisfy her family and the clock.","steps":[{"prompt":"Meera tells you she's decided to move ahead, mostly to stop the questions at home. What do you do?","options":[{"text":"Tell her to just get it over with","then":"Meera nods, like that settles it, and the conversation moves on."},{"text":"Congratulate her without asking anything","then":"Meera smiles and changes the subject to the wedding date."},{"text":"Tell her she's making a mistake she'll regret","then":"Meera goes quiet and stops bringing it up with you."},{"text":"Ask if she'd choose him with no clock ticking","then":"Meera goes quiet for a second, like she hasn't actually asked herself that.","best":true}],"why":"The question separates her own choice from the pressure, without telling her what to decide."},{"prompt":"A few days later, Meera admits she's still not sure about him. What do you do?","options":[{"text":"Fill the silence by changing the subject","then":"The moment passes, though she brings it up again the next day."},{"text":"Tell her not to overthink it","then":"Meera laughs it off, but the pause lingers in her face."},{"text":"Remind her of the family pressure again","then":"Meera's shoulders drop lower, and the clock feels louder."},{"text":"Ask what she actually values in a partner","then":"Meera starts talking, slowly, about things she hasn't said out loud before.","best":true}],"why":"Asking about her values gives her something steadier than the timeline to decide from."},{"prompt":"She says she needs more time to think. What do you do?","options":[{"text":"Tell her time is running out","then":"Meera's face falls, and she stops talking about it with you."},{"text":"Say you hope she hurries for her family's sake","then":"Meera forces a smile and drops the subject."},{"text":"Stop asking so you don't seem pushy","then":"Meera is left to sit with the decision entirely alone."},{"text":"Support her taking the time she needs","then":"Meera exhales, like someone finally gave her permission to slow down.","best":true}],"why":"Backing her right to take time helps her choose freely, on her own values, not the clock."}],"debrief":"A gentle nudge toward values-based, freely chosen partnering can change a friend's whole life.","relearn":"Encourage friends to choose a partner on values and their own choice, not just family and timeline."},
  {"id":"cb-054","cat":"tools-and-help","type":"sort","persona":"any","source":"the basis","relearn":"Shared values, respect and communication are reliable; chemistry-only and hoping-they'll-change are fragile.","hook":"Sort: a reliable basis for a partnership, or a fragile one?","items":[{"id":"a","text":"Shared values and respect"},{"id":"b","text":"Intense early chemistry only"},{"id":"c","text":"Good communication"},{"id":"d","text":"Hoping they'll change later"},{"id":"e","text":"How you handle conflict together"},{"id":"f","text":"A perfect first impression alone"}],"bins":[{"id":"reliable","label":"Reliable","valence":"pos"},{"id":"fragile","label":"Fragile","valence":"neg"}],"key":{"a":"reliable","b":"fragile","c":"reliable","d":"fragile","e":"reliable","f":"fragile"}},
  {"id":"cb-055","cat":"choosing-well","type":"spot","hook":"Reactions to a persistent 'something's off' feeling. Spot the two unwise ones.","scene":[{"id":"a","text":"Taking the gut feeling seriously","trick":false},{"id":"b","text":"Overriding it because they look right on paper","trick":true},{"id":"c","text":"Exploring why it feels off","trick":false},{"id":"d","text":"Rushing to commit before you've understood it","trick":true},{"id":"e","text":"Giving yourself time to sit with it","trick":false}],"why":"Overriding the unease for a paper match and rushing to commit are unwise; taking it seriously and exploring it is wise.","relearn":"Take a persistent 'something's off' feeling seriously; don't override it for a perfect-on-paper match.","persona":"any","source":"trust your gut"},
  {"id":"cb-056","cat":"what-it-takes","type":"branch","persona":"any","source":"repair","hook":"You hurt your partner with something you said, and you can feel the distance.","steps":[{"prompt":"You notice them go quiet after dinner. What do you do?","options":[{"text":"Wait for them to bring it up","then":"The evening passes with the quiet still sitting between you."},{"text":"Defend what you said, if they mention it","then":"You rehearse your reasons instead of watching them."},{"text":"Distract with a joke","then":"They give a small smile that doesn't reach their eyes."},{"text":"Go to them and name what you did","then":"They look up, a little surprised you noticed.","best":true}],"why":"Naming it yourself, before they have to raise it, shows you actually noticed the hurt."},{"prompt":"They say it really stung. What do you do?","options":[{"text":"Explain your side first so they understand","then":"They fold their arms. The hurt gets pushed aside again."},{"text":"Say sorry, but add \"you also\"","then":"The apology dissolves the moment the \"but\" lands."},{"text":"Change the subject","then":"The hurt stays exactly where it was, unspoken now instead of spoken."},{"text":"Apologise sincerely, without excuses","then":"They soften, just slightly, and actually meet your eyes.","best":true}],"why":"An apology without a but lets them feel heard instead of defending the hurt again."},{"prompt":"The next day, things between you still feel a little cautious. What do you do?","options":[{"text":"Assume it's fully fixed now","then":"You move on. They're still carrying a little of it alone."},{"text":"Over-apologise repeatedly","then":"Every repeat makes the moment feel bigger again, not smaller."},{"text":"Get annoyed they're still cautious","then":"The caution turns into something closer to hurt again."},{"text":"Ask what would help going forward","then":"They think about it, and tell you something small and doable.","best":true}],"why":"Asking what helps next turns the apology into repair, not just words."},{"prompt":"A similar moment almost happens again days later. What do you do?","options":[{"text":"Do it anyway since you already apologised once","then":"The old hurt resurfaces, this time with company."},{"text":"Blame the situation for making you snap","then":"The reason lands, but the repeat still stings."},{"text":"Avoid the topic that caused it","then":"Avoiding it doesn't make the next close call any less likely."},{"text":"Catch yourself and change course","then":"They notice the difference, even though you never mention it.","best":true}],"why":"Catching it before it repeats shows the apology actually changed something."}],"debrief":"Sincere repair after you've caused hurt is one of the most important partnership skills.","relearn":"Own your part, apologise sincerely, and make a repair after causing hurt."},
  {"id":"cb-057","cat":"commitment-clearly","type":"branch","persona":"any","source":"love isn't always enough","hook":"You love Meera deeply, but she wants to stay near her parents forever and you want to move abroad.","steps":[{"prompt":"She brings up the move again, worried. What do you do?","options":[{"text":"Say you want to talk through whether this can work","then":"She looks scared, then relieved someone finally said it plainly.","best":true},{"text":"Promise it'll work out somehow, without a plan","then":"She relaxes for now, and the real question stays buried."},{"text":"Say love will make the distance fine either way","then":"She wants to believe it, and neither of you tests whether it's true."},{"text":"Drop the topic, since it always ends in tension","then":"The silence feels calmer tonight, and nothing is actually settled."}],"why":"Saying the hard question out loud is what makes it possible to actually answer."},{"prompt":"A few days later, she asks what you'd actually be willing to give up. What do you say?","options":[{"text":"Name honestly what you would and wouldn't compromise on","then":"It's an uncomfortable answer, and she says she needed to hear it.","best":true},{"text":"Say you'd give up anything for her, in the moment","then":"It sounds romantic, and you're not sure it's true."},{"text":"Turn the question back and ask what she'd give up instead","then":"The conversation stalls into who should bend first."},{"text":"Say you haven't thought about it yet","then":"She's left carrying the question alone again."}],"why":"Naming a real compromise, even an uncomfortable one, tells you if this can genuinely work."},{"prompt":"Her mother mentions how close the family has always stayed. What do you do?","options":[{"text":"Ask Meera, later, how her mother's words sit with her","then":"She admits the weight of that closeness scares her a little too.","best":true},{"text":"Say nothing, to avoid seeming disrespectful","then":"The comment sits between you both, unspoken."},{"text":"Tell her mother your plans directly, before Meera's ready to","then":"Meera feels blindsided by a talk that was meant to be yours together."},{"text":"Decide privately that the move is off the table now","then":"You decide alone, until Meera asks to talk it through properly."}],"why":"Checking how family pressure lands on her keeps the decision between you two."},{"prompt":"You sit down to actually decide together. What matters most in that conversation?","options":[{"text":"Whether you can both live with the real compromise","then":"You land somewhere neither of you expected, and it feels honestly chosen.","best":true},{"text":"Whether love is strong enough to carry you through it","then":"You agree that it is, without saying what 'through it' looks like."},{"text":"Which of you wants the move more","then":"One of you gives in, and it settles nothing underneath."},{"text":"What would be easiest to explain to both families","then":"The families are satisfied, and the original question stays open."}],"why":"A compromise you can both live with matters more than who wants it more or what looks easiest."}],"debrief":"Love is necessary but not always sufficient; core compatibility on big things matters for the long haul.","relearn":"Talk honestly about whether core life-differences can work; love alone may not paper over them."},
  {"id":"cb-058","cat":"love-and-arranged","type":"choose","persona":"any","source":"still choosing","hook":"Arjun's family set up an introduction, and he's meeting her for coffee a second time.","prompt":"What counts as him choosing here?","options":[{"text":"Asking her questions that matter to him","fits":true,"note":"Bringing his own questions is exactly what choosing looks like."},{"text":"Noticing how he feels around her","fits":true,"note":"Paying attention to his own reactions is part of weighing it."},{"text":"Deciding to meet again, or not","fits":true,"note":"Saying yes or no to another meeting is a real choice each time."},{"text":"Letting his parents decide for him","fits":false,"note":"That hands the choosing over instead of him making it."},{"text":"Trusting the biodata says enough","fits":false,"note":"A biodata is a starting point, not the whole picture."},{"text":"Going along so no one is upset","fits":false,"note":"Choosing to please others isn't the same as choosing for himself."}],"relearn":"An arranged introduction is still a choice you get to weigh and consent to."},
  {"id":"cb-059","cat":"starting-strong","type":"role-play","persona":"any","source":"money talk","hook":"You and Divya just bought a big appliance together, without really planning for it.","setup":"That night, the cost comes up almost by accident.","steps":[{"prompt":"Divya says: \"That was a lot more than I expected to spend this month.\"","options":[{"text":"\"Yeah. Can we sit down and talk about how we'll handle money?\"","then":"She looks relieved. \"I've been wanting to ask that for a while.\"","best":true},{"text":"\"We'll figure out the money stuff eventually. I'm sure of it.\"","then":"She half-smiles, then comes back to it. \"No, let's not wait.\""},{"text":"\"It's fine. I'll just cover more of it this month.\"","then":"She frowns slightly. \"That's not really what I meant.\""},{"text":"\"You're the one who wanted the expensive model.\"","then":"She stiffens. \"We both agreed on it, actually.\""}],"why":"Naming the real ask, an actual talk, moves past a passing comment about the bill."},{"prompt":"Divya asks: \"Okay, so where do we even start with this?\"","options":[{"text":"\"What's fair and open to both of us, not just what one of us assumes.\"","then":"She nods. \"Fair and open. I can work with that.\"","best":true},{"text":"\"Whatever is easiest to manage day to day, honestly, I really don't mind.\"","then":"She hesitates. \"Easiest for who, though?\""},{"text":"\"I'll just keep handling the big stuff like I have been.\"","then":"She goes quiet. \"I didn't realise that's how you saw it.\""},{"text":"\"Let's not make this complicated.\"","then":"She nods slowly, though the actual plan stays unclear."}],"why":"Naming fairness and openness as the goal, not just ease, sets a real starting point."},{"prompt":"Divya asks: \"Separate accounts, joint, or some mix? What do you actually want?\"","options":[{"text":"\"Let's look at our incomes and costs first, then decide.\"","then":"She grabs a notebook. \"Okay, good, let's actually look at the numbers.\"","best":true},{"text":"\"Whatever most couples our age are doing, probably.\"","then":"She shrugs. \"I don't really know what that is, though.\""},{"text":"\"Joint account, obviously. We're a team now.\"","then":"She pauses. \"Maybe, but can we think it through first?\""},{"text":"\"Let's just decide later, no rush.\"","then":"She nods, though the appliance bill is still sitting there unresolved."}],"why":"Looking at the real numbers first grounds the decision in facts, not assumptions."}],"relearn":"Open an honest conversation about handling money fairly and openly, early."},
  {"id":"cb-060","cat":"tools-and-help","type":"spot","persona":"any","source":"foundations","relearn":"Shared values, communication, respect and repair last; intense passion alone and 'they'll change' don't.","hook":"Spot the two shaky bases someone might mistake for a foundation.","scene":[{"id":"a","text":"Shared values and good communication","trick":false},{"id":"b","text":"Only intense early passion","trick":true},{"id":"c","text":"Mutual respect and repair","trick":false},{"id":"d","text":"Hoping they'll change after the wedding","trick":true},{"id":"e","text":"Both willing to do the daily work","trick":false}],"why":"Passion-alone and 'they'll change' are the shaky bases; values, communication, respect and repair last."},
  {"id":"cb-061","cat":"choosing-well","type":"choose","persona":"any","source":"adds not shrinks","hook":"Six months in, Sonal is settling into her life with Yusuf.","prompt":"Which signs show he adds to her life?","options":[{"text":"He cheers her on for the promotion","fits":true,"note":"Cheering her ambitions on is what a partner who adds to her life looks like."},{"text":"He texts her all day to stay close","fits":false,"note":"Constant texting can feel close, but it can crowd out the rest of her day."},{"text":"She feels more like herself around him","fits":true,"note":"Feeling more yourself, not less, is one of the clearest signs of fit."},{"text":"He wants every evening together","fits":false,"note":"Wanting every evening together can sound loving, but it slowly narrows her life."},{"text":"He picks what she should wear","fits":false,"note":"Choosing her outfits is deciding for her, not adding to who she is."},{"text":"He plans every weekend for them","fits":false,"note":"Planning it all can feel like care, but it quietly takes her choices away."}],"relearn":"The right partner adds to your life and respects who you are; they don't shrink you."},
  {"id":"cb-062","cat":"what-it-takes","type":"role-play","persona":"any","source":"small kindnesses","hook":"On an ordinary evening, nothing special has happened, and you catch yourself watching your partner in the kitchen.","setup":"He catches you looking and raises an eyebrow.","steps":[{"prompt":"He asks, amused: \"What? Do I have something on my face?\"","options":[{"text":"\"No. I just don't say enough how much I value you. So: I do.\"","then":"He goes a little still, then smiles. \"That's really nice to hear, actually.\"","best":true},{"text":"\"Nothing, just thinking about how normal and easy this all feels lately.\"","then":"He laughs. \"In a good way, I hope?\" The moment passes without more."},{"text":"\"Nothing, don't worry about it.\"","then":"He shrugs and goes back to the dishes."},{"text":"\"Just admiring the view, obviously.\"","then":"He grins. \"Smooth.\" It stays a joke, nothing more said."}],"why":"Saying the plain, unprompted thing is what lands, not a joke that lets it pass."},{"prompt":"Later, he asks, half-joking: \"You've been looking at me like that all evening. What brought this on?\"","options":[{"text":"\"Nothing happened. I just don't want to wait for something big.\"","then":"He wipes his hands and actually sits down. \"I like that you said it anyway.\"","best":true},{"text":"\"I don't know. I guess I'm just in a really good mood tonight.\"","then":"He nods, pleased but a little unsure if he heard it right."},{"text":"\"You've just been around a lot lately, I guess.\"","then":"He laughs. \"Where else would I be?\" It reads as a joke, not thanks."},{"text":"\"Forget I said anything.\"","then":"He looks a little disappointed, but doesn't push it."}],"why":"Naming that it isn't tied to a big moment shows this is how you mean to show up."},{"prompt":"Later, folding laundry together, he says quietly: \"You don't have to keep saying stuff like that.\"","options":[{"text":"\"I want to. It shouldn't take a special occasion.\"","then":"He smiles down at the towel he's folding. \"Okay. I won't stop you, then.\"","best":true},{"text":"\"Fine, I'll save it for special occasions then.\"","then":"He looks a little unsure whether that's actually what he wanted."},{"text":"\"You're right. It's probably too much.\"","then":"He shakes his head quickly. \"That's not what I meant, actually.\""},{"text":"\"Noted, I'll dial it back.\"","then":"He frowns slightly, and the warmth from earlier fades a little."}],"why":"Small, spoken appreciation works best as a habit, not an occasional gesture."}],"relearn":"Small, spoken kindnesses are the real glue of a partnership."},
  {"id":"cb-063","type":"sort","persona":"any","source":"eyes open vs shut","hook":"Sort: eyes-open commitment, or eyes-shut?","items":[{"id":"a","text":"Discussing the hard topics first"},{"id":"b","text":"Avoiding all difficult questions"},{"id":"c","text":"Choosing freely and clearly"},{"id":"d","text":"Drifting in to avoid a decision"},{"id":"e","text":"Meeting each other's real daily life"},{"id":"f","text":"Assuming you agree on everything"}],"bins":[{"id":"open","label":"Eyes open","valence":"pos"},{"id":"shut","label":"Eyes shut","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"relearn":"Discussing hard topics, choosing freely and meeting real life is eyes-open; avoiding, drifting and assuming is eyes-shut.","cat":"commitment-clearly"},
  {"id":"cb-064","cat":"love-and-arranged","type":"branch","persona":"any","source":"right to decline","hook":"Across three arranged meetings, Karan has snapped at a waiter twice and talked over you both times.","steps":[{"prompt":"At the third meeting, he interrupts you again mid sentence. What do you do?","options":[{"text":"Note it plainly to yourself as a real pattern, not a mood","then":"You realise this isn't nerves. It's simply how he treats people.","best":true},{"text":"Assume he's just nervous meeting your family","then":"You explain away the same thing you noticed the first two times."},{"text":"Interrupt him back to see how he reacts","then":"He gets sharper, and the table goes tense."},{"text":"Say nothing and let your parents keep the conversation going","then":"The meeting ends smoothly, and the pattern goes unmentioned."}],"why":"Naming the pattern plainly, not excusing it as nerves, is what lets you actually see it."},{"prompt":"Afterwards, your mother says his family is otherwise very respectable. What do you do?","options":[{"text":"Say what you noticed about how he treats people","then":"She goes quiet, then asks you to say more.","best":true},{"text":"Agree the families seem like a good match","then":"The pattern you noticed gets filed away as unimportant."},{"text":"Say you're probably just being too picky about him","then":"You start doubting your own read of what you saw."},{"text":"Say nothing, unsure how to explain a feeling","then":"The discomfort stays with you, unnamed to anyone."}],"why":"Saying what you noticed out loud tests it against silence, instead of burying it."},{"prompt":"A relative asks whether you're ready to move forward. What do you do?","options":[{"text":"Say clearly that you want to decline this match","then":"There's a pause, and then your relative nods, taking it seriously.","best":true},{"text":"Ask for one more meeting to be completely sure","then":"The pattern repeats itself a third time, right on schedule."},{"text":"Say yes, since three meetings feels like enough already","then":"The families begin moving toward a date."},{"text":"Say you'll leave it to your parents to decide","then":"The decision moves ahead without your read of him in it."}],"why":"A clear decline is the whole point of noticing red flags in the first place."},{"prompt":"Your parents gently ask what's bothering you about him. What do you tell them?","options":[{"text":"How he spoke over you and others at every meeting","then":"They think back, and admit they'd noticed it too.","best":true},{"text":"That you just didn't feel a spark","then":"They're puzzled, since spark was never really the question."},{"text":"That you're not ready for marriage at all","then":"They accept it, though it isn't quite the real reason."},{"text":"That you'd rather not explain, since it's only a feeling","then":"They respect it, and the actual pattern goes unspoken."}],"why":"Naming the actual pattern helps your parents read the next match better too."}],"debrief":"Red flags are red flags in any process; you always have the right to decline a match.","relearn":"Take red flags seriously in an arranged match; you can always say no."},
  {"id":"cb-065","cat":"starting-strong","type":"branch","persona":"Nisha","source":"children conversation","hook":"You assume Rohit shares your view on having children, but you've never actually asked.","steps":[{"prompt":"The topic comes up lightly over dinner. What do you do?","options":[{"text":"Assume you already know his answer","then":"The conversation moves on, and the assumption goes untested."},{"text":"Change the subject since it feels heavy","then":"Dinner continues, and the question sits there, still unasked."},{"text":"Wait for a \"better\" moment that keeps not coming","then":"Weeks pass, and dinner after dinner slips by the same way."},{"text":"Ask him directly and share your own view","then":"Rohit puts his fork down, like he's been waiting for someone to ask.","best":true}],"why":"Asking directly, and sharing your own view, is the only way to find out where you actually stand."},{"prompt":"A few days later, Rohit brings it up himself, and his view isn't what you expected. What do you do?","options":[{"text":"Pretend you're fine with it to avoid conflict","then":"You nod along, while something in you quietly disagrees."},{"text":"Insist he come around to your view","then":"Rohit gets defensive, and the conversation stalls."},{"text":"Drop the topic since it's now awkward","then":"The gap between your answers stays exactly where it landed."},{"text":"Ask more about what's behind his view","then":"Rohit explains, and it's more thought through than you expected.","best":true}],"why":"Understanding what's behind his view matters more than reacting to the answer itself."},{"prompt":"Weeks later, the question of children comes up again. What do you do?","options":[{"text":"Settle it in one conversation and never revisit it","then":"Neither of you mentions it again, even as your thinking shifts."},{"text":"Avoid it now that the hard part is over","then":"The topic goes quiet, right when it could keep growing."},{"text":"Let whoever feels stronger about it decide","then":"One of you ends up carrying the whole decision alone."},{"text":"Agree to keep revisiting it honestly as you both grow","then":"You set a loose check-in, and it feels less like a landmine now.","best":true}],"why":"Treating it as an ongoing honest conversation fits something this big better than one verdict."}],"debrief":"Whether and when to have children is too big to assume. Talk it through early and honestly.","relearn":"Discuss whether and when to have children honestly before committing. Don't assume alignment."},
  {"id":"cb-066","cat":"what-it-takes","type":"role-play","persona":"any","source":"turning toward","hook":"Ishaan has been quiet and short with you for two days, clearly carrying something.","setup":"Tonight he sits apart from you on the couch, scrolling without really looking.","steps":[{"prompt":"You ask if he's okay, and he says: \"I'm fine. Just tired.\"","options":[{"text":"\"You seem weighed down. Want to talk, or just sit together?\"","then":"He looks up, surprised. \"Actually, yeah. Just sit, maybe.\"","best":true},{"text":"\"Okay, let me know if you ever want to talk about it.\"","then":"He nods and goes back to his phone. Neither of you moves closer."},{"text":"\"You've been off for two days now.\"","then":"He tenses. \"I said I'm fine.\""},{"text":"\"Alright. I'll leave you to it and check on you later.\"","then":"You stand to go, and he quietly asks you to stay."}],"why":"Naming what you see and offering presence, not pressure, opens the door gently."},{"prompt":"After a quiet minute, he says: \"Work's just been a lot. I don't really want to get into it.\"","options":[{"text":"\"That's okay. I'll just stay here with you for a bit.\"","then":"He leans back, a little closer to you. \"Thanks. This actually helps.\"","best":true},{"text":"\"Okay, well, you know where I am whenever that changes, no pressure.\"","then":"He nods, and you drift back to your own screen."},{"text":"\"You never want to get into it, though.\"","then":"He sighs. \"Can we not do this right now?\""},{"text":"\"Fine, I'll just watch my show then.\"","then":"He glances over, then looks away again, a little further apart."}],"why":"Staying present without pushing respects his pace and keeps you close anyway."},{"prompt":"The next evening he's distant again, and snaps: \"Can you just not ask if I'm okay for once?\"","options":[{"text":"\"Okay. I'm still here whenever you're ready.\"","then":"He looks caught off guard, then quieter. \"Thanks for not pushing.\"","best":true},{"text":"\"Fine, I won't ask anymore, message received.\"","then":"He nods, but something closes off between you for the evening."},{"text":"\"I'm just trying to help, you know.\"","then":"He rubs his face. \"I know. It's not about you.\""},{"text":"\"Wow, okay then.\"","then":"He winces. \"That came out wrong. I'm just tired of everything.\""}],"why":"Staying available without taking the snap personally keeps the door open."},{"prompt":"Later that night, he says quietly: \"I know I've been distant. That wasn't fair to you.\"","options":[{"text":"\"Thanks for saying that. I want to be with you through it.\"","then":"He exhales, some of the tension leaving his shoulders. \"That means a lot.\"","best":true},{"text":"\"It's okay. I know work gets like this sometimes.\"","then":"He nods, though something about it still feels a little unfinished."},{"text":"\"You have been distant, yeah. Took you long enough to notice.\"","then":"He looks down. \"Right. Sorry, again.\""},{"text":"\"Don't worry. I've been busy with my own stuff too.\"","then":"He nods, and the moment of closeness quietly slips past."}],"why":"Meeting the repair with closeness, not just agreement, is what reconnects you."}],"relearn":"Turn toward a stressed partner gently; presence reconnects."},
  {"id":"cb-067","cat":"choosing-well","type":"strike-rewrite","hook":"\"You can change a partner into who you want after committing.\"","myth":{"un":"You can change a partner into who you want after committing.","re":"Choose someone you respect as they are; committing to 'fix' someone rarely works.","why":"People change for themselves, not on demand."},"relearn":"Choose someone you respect as they are; you can't reliably change a partner to fit.","persona":"any","source":"can't change them"},
  {"id":"cb-068","cat":"commitment-clearly","type":"choose","persona":"any","source":"keep choosing","hook":"Anil and Sujata have been married eleven years now.","prompt":"Which show he's still choosing her?","options":[{"text":"Showing up for her on the hard days","fits":true,"note":"Choosing to be there when it's difficult is commitment in action, daily."},{"text":"Making time for her in a busy week","fits":true,"note":"Carving out time, even now, shows she's still a priority, not a given."},{"text":"Planning something she'd enjoy","fits":true,"note":"Thinking about what would make her happy is choosing her in a small way."},{"text":"Asking how her day actually went","fits":true,"note":"Staying curious about her life is choosing her, long after the wedding."},{"text":"Keeping the wedding ring on","fits":false,"note":"A ring on a finger doesn't show what happens between them day to day."},{"text":"Posting their anniversary photo online","fits":false,"note":"A yearly post says little about how they actually treat each other."}],"relearn":"A partnership is a choice you keep making, not a one-time event."},
  {"id":"cb-069","type":"match","hook":"Match each move in a match process to what it tells you.","relearn":"Meeting, talking and asking the real questions bring your own judgement to a match.","pairs":[{"left":"Meeting a few times and talking","right":"How you get along in person"},{"left":"Checking shared values","right":"Whether you want the same life"},{"left":"Asking how they handle conflict","right":"What a hard day together might look like"},{"left":"Meeting their family","right":"The household you might join"},{"left":"Asking about money habits","right":"Whether spending could cause friction"}],"persona":"any","source":"judgement in any path","cat":"love-and-arranged"},
  {"id":"cb-070","type":"spot","persona":"Pooja","source":"us and me","hook":"Spot the two signs 'us' is starting to erase 'me'.","scene":[{"id":"a","text":"You each keep your own friends","trick":false},{"id":"b","text":"One of you gives up everything","trick":true},{"id":"c","text":"You support each other's growth","trick":false},{"id":"d","text":"One loses every interest they had","trick":true},{"id":"e","text":"You keep your own goals too","trick":false}],"why":"Giving up everything and losing every interest are the signs 'us' is erasing 'me'; keeping your life isn't.","relearn":"Building 'us' shouldn't erase 'me'; the best partnerships have room for both.","cat":"starting-strong"},
  {"id":"cb-071","cat":"tools-and-help","type":"match","persona":"any","source":"myth to truth","relearn":"Two whole people, consent always, built daily, values over sparks, and a wedding-is-a-day replace the myths.","hook":"Match the myth to the truth that replaces it.","pairs":[{"left":"\"Marriage completes me\"","right":"Built by two whole people"},{"left":"\"Arranged means no consent\"","right":"Your yes matters on every path"},{"left":"\"Love needs no work\"","right":"Partnership is built daily"},{"left":"\"Sparks are enough\"","right":"Values keep it going"},{"left":"\"The wedding is the goal\"","right":"It's one day of many years"}]},
  {"id":"cb-072","cat":"choosing-well","type":"sort","hook":"Sort each into a question that reveals long-term fit, or a distraction.","items":[{"id":"a","text":"How do they treat people with less power?"},{"id":"b","text":"How fancy is their car?"},{"id":"c","text":"Do our life goals align?"},{"id":"d","text":"How many followers do they have?"},{"id":"e","text":"How do they handle being told no?"},{"id":"f","text":"How big is their wedding budget?"}],"bins":[{"id":"reveals","label":"Reveals fit","valence":"pos"},{"id":"distraction","label":"Distraction","valence":"neutral"}],"key":{"a":"reveals","b":"distraction","c":"reveals","d":"distraction","e":"reveals","f":"distraction"},"relearn":"How they treat the less powerful, whether goals align and how they take a no reveals fit; cars, followers and budgets distract.","persona":"any","source":"revealing questions"},
  {"id":"cb-073","cat":"what-it-takes","type":"strike-rewrite","hook":"\"Conflict means the partnership is failing.\"","myth":{"un":"Conflict means the partnership is failing.","re":"Conflict is normal; how you repair and treat each other through it is what matters.","why":"All close partners disagree sometimes."},"relearn":"Conflict is normal; how you repair through it is what matters, not whether you fight.","persona":"any","source":"conflict is normal"},
  {"id":"cb-074","cat":"commitment-clearly","type":"branch","persona":"Sneha","source":"the 'when' question","hook":"At every wedding you attend, someone eventually asks, 'so when's yours?'","steps":[{"prompt":"At a cousin's sangeet, an aunty asks the question again. What do you do?","options":[{"text":"Smile and say you'll get there in your own time","then":"She laughs and moves on to the next relative to pester.","best":true},{"text":"Give a fake date just to end the conversation","then":"She repeats the date to three more people before dinner."},{"text":"Explain in detail why you're not ready yet","then":"She listens, then asks the same question again a moment later."},{"text":"Avoid her for the rest of the function","then":"You spend the evening managing where you stand instead of enjoying it."}],"why":"A light, unbothered answer holds your pace without starting a fight."},{"prompt":"At the next function, a different uncle asks the same thing in front of your parents. What do you do?","options":[{"text":"Give the same calm answer as before, unbothered","then":"Your parents relax, seeing you're not rattled by it.","best":true},{"text":"Look to your parents to answer for you","then":"Your mother improvises an answer that isn't quite true."},{"text":"Snap that people should stop asking","then":"Your parents look embarrassed, and the room goes quiet."},{"text":"Laugh it off, but feel it sting more than you show","then":"You leave the function carrying more of it than anyone sees."}],"why":"Staying calm and consistent shows your parents, and you, that the questions don't move you."},{"prompt":"By the third function this month, what do you decide going forward?","options":[{"text":"To keep answering lightly, on your own timeline","then":"Eventually the questions get shorter, since you're never rattled.","best":true},{"text":"To stop attending family functions for a while","then":"You dodge the question, and miss the people you actually enjoy."},{"text":"To get engaged soon just so the questions stop","then":"The questions stop, though not for a reason you actually chose."},{"text":"To let it wear you down and say nothing at all","then":"The questions keep landing, and you keep absorbing them quietly."}],"why":"Keeping your own pace, function after function, is what actually protects your choice."}],"debrief":"Social pressure about timelines is relentless in India; keeping the decision yours is wisdom.","relearn":"Hold your own pace; don't rush commitment to silence the 'when' questions."},
  {"id":"cb-075","cat":"love-and-arranged","type":"role-play","persona":"Aditya","source":"every family is real","hook":"At a cousin's wedding, your uncle calls your partnership with Dev 'not a real family'.","setup":"He says it again, waiting for your response.","steps":[{"prompt":"Your uncle says: \"Two men, no children, that's not a real family, beta.\"","options":[{"text":"\"What we're building is real, with the love any family needs.\"","then":"He frowns, but has no quick reply. Others at the table go quiet, listening.","best":true},{"text":"\"That's a pretty old-fashioned way to think about it, honestly.\"","then":"He bristles. \"Old-fashioned? I'm just saying what everyone thinks.\""},{"text":"\"Maybe you're right. It is different.\"","then":"He nods, satisfied, and repeats it louder for the table."},{"text":"\"Can we not do this here, please?\"","then":"He shrugs. \"I'm only saying what's true.\""}],"why":"Naming your family as real, plainly, meets the dismissal without accepting it."},{"prompt":"He presses: \"So who's the husband and who's the wife, then?\"","options":[{"text":"\"Neither. We're just two equal partners, like any couple.\"","then":"He looks puzzled, but for once says nothing back.","best":true},{"text":"\"That's honestly a pretty rude thing to ask me, Uncle, in front of everyone.\"","then":"He waves a hand. \"I'm only curious, no need to get upset.\""},{"text":"\"I guess I handle more of the traditional wife things.\"","then":"He nods, satisfied that he's slotted you into something familiar."},{"text":"\"Does it matter?\"","then":"He shrugs. \"It matters to me. I like things to make sense.\""}],"why":"Naming equal partnership, not roles, corrects the frame instead of playing along."},{"prompt":"Later, your mother quietly asks: \"Are you alright? He can be like that.\"","options":[{"text":"\"I'm fine. His view of family isn't the only one here.\"","then":"She squeezes your hand. \"It isn't. Not to me, either.\"","best":true},{"text":"\"I'm used to it by now. It's honestly fine.\"","then":"She looks a little sad. \"You shouldn't have to be used to it, though.\""},{"text":"\"Can you talk to him for me next time?\"","then":"She hesitates. \"I can try. He doesn't always listen to me either.\""},{"text":"\"Honestly, I'm considering skipping these events.\"","then":"She looks concerned. \"I don't want you to feel pushed out of the family.\""}],"why":"Naming it plainly to someone on your side turns a private hurt into shared ground."}],"relearn":"Your partnership is real and built on the same foundations as any; hold that with dignity."},
  {"id":"cb-076","type":"sort","persona":"Karthik","source":"equality from start","hook":"Sort: builds equality from the start, or builds in imbalance?","items":[{"id":"a","text":"Sharing chores and decisions"},{"id":"b","text":"One person defaults to all the housework"},{"id":"c","text":"Both careers taken seriously"},{"id":"d","text":"One person's plans always come first"},{"id":"e","text":"Splitting the mental load fairly"},{"id":"f","text":"The higher earner controls the money"}],"bins":[{"id":"equal","label":"Equality","valence":"pos"},{"id":"imbalance","label":"Imbalance","valence":"neg"}],"key":{"a":"equal","b":"imbalance","c":"equal","d":"imbalance","e":"equal","f":"imbalance"},"relearn":"Sharing chores, decisions, careers and the mental load builds equality; one-sided defaults build imbalance.","cat":"starting-strong"},
  {"id":"cb-077","cat":"choosing-well","type":"role-play","persona":"Sneha","source":"you deserve good","hook":"Your friend Priya is about to say yes to Karan mainly because he's the first one who's stuck around.","setup":"She shows you his message, looking for reassurance.","steps":[{"prompt":"Priya asks: \"He's fine, right? I should just say yes?\"","options":[{"text":"\"You deserve someone good for you, not just available.\"","then":"She looks away. \"I know. I'm just tired of waiting for good.\"","best":true},{"text":"\"He seems nice enough, I guess, so sure.\"","then":"She brightens. \"Right? Okay, I'll say yes then.\""},{"text":"\"Honestly, just take what you can get at this point.\"","then":"She nods slowly, and types out a yes she doesn't sound sure of."},{"text":"\"Do whatever makes you happy.\"","then":"She shrugs. \"I don't actually know what that is right now.\""}],"why":"Naming the real standard, good for you, not just present, is what she needs."},{"prompt":"Priya says: \"But what if no one better ever comes along?\"","options":[{"text":"\"Then you're still better off than settling for someone wrong.\"","then":"She's quiet for a moment. \"That's a scarier thought, honestly.\"","best":true},{"text":"\"Someone better always comes along eventually, don't worry.\"","then":"She looks hopeful, though it's a promise you can't actually make."},{"text":"\"You're not getting any younger, you know.\"","then":"She flinches. \"Wow. Thanks for that.\""},{"text":"\"That's a risk you'll just have to take, I guess.\"","then":"She nods, unconvinced, and goes quiet."}],"why":"Being alone isn't the real risk here; settling for the wrong person is."},{"prompt":"She asks quietly: \"What should I actually be looking for, then?\"","options":[{"text":"\"Someone who treats you well and shares what matters to you.\"","then":"She nods slowly. \"Okay. I don't think Karan's that, if I'm honest.\"","best":true},{"text":"\"Someone who makes you feel excited again, like at the start.\"","then":"She nods, though that's not quite what was missing with Karan."},{"text":"\"I can't tell you that, only you know.\"","then":"She looks a little lost. \"I was hoping you'd help me figure it out.\""},{"text":"\"Someone your family will approve of, at least.\"","then":"She frowns. \"That's not really what I asked.\""}],"why":"Naming values and treatment, not spark alone, gives her a real standard to check."}],"relearn":"You deserve a partner who's genuinely good for you, not just available."},
  {"id":"cb-078","cat":"what-it-takes","type":"sort","hook":"Sort: a habit that keeps love alive, or lets it fade?","items":[{"id":"a","text":"Regular check-ins about how you both are"},{"id":"b","text":"Assuming everything's fine, always"},{"id":"c","text":"Expressing appreciation"},{"id":"d","text":"Taking each other for granted"},{"id":"e","text":"Protecting time to connect"},{"id":"f","text":"Letting busyness eat every evening"}],"bins":[{"id":"alive","label":"Keeps it alive","valence":"pos"},{"id":"fade","label":"Lets it fade","valence":"neg"}],"key":{"a":"alive","b":"fade","c":"alive","d":"fade","e":"alive","f":"fade"},"relearn":"Check-ins, appreciation and protected time keep love alive; assuming, taking for granted and busyness let it fade.","persona":"any","source":"keeping love alive"},
  {"id":"cb-079","cat":"commitment-clearly","type":"strike-rewrite","hook":"\"Doubts before commitment mean it's definitely wrong.\"","myth":{"un":"Any doubts before commitment mean it's definitely wrong.","re":"Some nerves are normal; persistent doubts about core respect or values, though, are worth heeding.","why":"Distinguish ordinary nerves from real red flags."},"relearn":"Some nerves are normal; but persistent doubts about core respect or values are worth heeding.","persona":"any","source":"nerves vs real doubt"},
  {"id":"cb-080","cat":"love-and-arranged","type":"choose","persona":"any","source":"the goal","hook":"Kabir and Meera are settling into married life and working out how to run their home.","prompt":"Which of these looks like equal partners?","options":[{"text":"They each have a say over money","fits":true,"note":"Having a voice in shared finances is part of being equal partners."},{"text":"Big decisions get made together","fits":true,"note":"Deciding together, not one overruling the other, is equality."},{"text":"Either can raise a worry and be heard","fits":true,"note":"Both voices counting is what a partnership of equals sounds like."},{"text":"Whoever earns more decides more","fits":false,"note":"A bigger pay cheque isn't a bigger vote in the relationship."},{"text":"The elder in the house has final say","fits":false,"note":"Respecting elders is one thing; the couple still decides together."},{"text":"Each copies the roles their parents had","fits":false,"note":"Roles taken on by default skip the talk equal partners have about who does what."}],"relearn":"On any path, the goal is a partnership of equals built on consent and respect."},
  {"id":"cb-081","cat":"starting-strong","type":"branch","persona":"any","source":"shared culture","hook":"You and your partner come from families with different traditions and expectations.","steps":[{"prompt":"Wedding planning surfaces the first real difference. What do you do?","options":[{"text":"Let one family's way simply win","then":"The other family notices, even if no one says it out loud."},{"text":"Avoid the topic until the wedding forces a decision","then":"The decision gets made for you, by the deadline instead of by you two."},{"text":"Follow whichever tradition is louder","then":"The quieter family's customs quietly disappear from the day."},{"text":"Talk through what you'll keep, blend or set aside","then":"You end up with a plan that has both your families in it.","best":true}],"why":"Deciding together, on purpose, is how you build a culture that's actually yours as a couple."},{"prompt":"A relative asks why you're not just doing it \"the normal way.\" What do you do?","options":[{"text":"Cave and follow the normal way, since relatives expect it","then":"The plan you two built together quietly gets replaced."},{"text":"Get defensive and shut the conversation down","then":"The relative backs off, but so does the goodwill in the room."},{"text":"Blame your partner for the change","then":"Your partner hears you explain their idea as if it were a problem."},{"text":"Explain kindly that you're building your own version","then":"The relative isn't fully convinced, but hears that it's a joint choice.","best":true}],"why":"Explaining it as a shared choice, kindly, protects the plan without picking a fight."},{"prompt":"A new occasion brings up another tradition question. What do you do?","options":[{"text":"Let this one go to whichever side pushes harder","then":"The pattern you were trying to avoid starts again."},{"text":"Avoid deciding until the last moment","then":"You end up scrambling instead of choosing."},{"text":"Assume last time's answer applies without checking","then":"It turns out this occasion needed a different conversation entirely."},{"text":"Use the same both-of-you approach again","then":"It's quicker this time. You already know how to do this part.","best":true}],"why":"Using the same approach each time turns a one-off decision into a habit that holds."}],"debrief":"A partnership often means consciously building your own shared culture from two backgrounds.","relearn":"Decide together what to keep, blend or set aside. Build your own shared culture."},
  {"id":"cb-082","cat":"tools-and-help","type":"choose","persona":"any","source":"counselling reframe","hook":"Rohit and Kavya have a good marriage and are trying out a couples counsellor together.","prompt":"Which are good reasons to go?","options":[{"text":"To learn to argue better, not less","fits":true,"note":"Counselling can sharpen how a couple disagrees, not just stop it."},{"text":"To build habits before problems grow","fits":true,"note":"Building strong habits early is exactly what counselling is for."},{"text":"To understand each other more deeply","fits":true,"note":"Getting to know each other better is reason enough on its own."},{"text":"Because a checkup helps even when fine","fits":true,"note":"Like a health checkup, it helps even when nothing is wrong."},{"text":"Only once things start breaking down","fits":false,"note":"Waiting for a crisis isn't the only time it helps."},{"text":"To prove the other one is the problem","fits":false,"note":"Counselling isn't for keeping score of who's at fault."}],"relearn":"A couples counsellor is for building better, not only for crises."},
  {"id":"cb-083","cat":"tools-and-help","type":"sort","persona":"any","source":"the stance","relearn":"Choosing on values and respecting every path is the stance; pressuring to marry or wedding-as-goal isn't.","hook":"Sort: something this game stands for, or against?","items":[{"id":"a","text":"Choosing on values and consent"},{"id":"b","text":"Pressuring anyone to marry"},{"id":"c","text":"Respecting every path, including not marrying"},{"id":"d","text":"Treating a wedding as the whole goal"},{"id":"e","text":"Equal partnership from day one"},{"id":"f","text":"Romanticising one path over another"}],"bins":[{"id":"for","label":"Stands for","valence":"pos"},{"id":"against","label":"Stands against","valence":"neg"}],"key":{"a":"for","b":"against","c":"for","d":"against","e":"for","f":"against"}},
  {"id":"cb-084","cat":"tools-and-help","type":"reflect","hook":"You've met four big ideas about choosing and building a partnership.","prompt":"Which will you carry into your own?","options":["Values over sparks","Partnership is built","Commit with eyes open","Every path, with consent"],"affirm":"Carry that one, and you're set to build a partnership that genuinely lasts, on your own terms.","ask":"What makes that idea matter to you?","deeper":"Which idea might a friend carry instead, and why?","relearn":"Values over sparks, partnership is built, commit with eyes open, every path with consent.","persona":"any","source":"carry forward"},
  {"id":"cb-900","cat":"choosing-well","type":"strike-rewrite","hook":"\"If the spark is strong, the rest sorts itself out.\"","myth":{"un":"If the spark is strong, the rest sorts itself out.","re":"A strong spark can sit beside clashing values; only shared values and respect carry a partnership over years.","why":"Spark is a feeling; compatibility is the thing you live in daily."},"relearn":"A strong spark doesn't sort out a values clash; compatibility does the carrying.","persona":"any","source":"spark isn't enough"},
  {"id":"cb-901","cat":"choosing-well","type":"strike-rewrite","hook":"\"A good match means you never really fight.\"","myth":{"un":"A good match means you never really fight.","re":"Good matches disagree too; what tells you fit is whether you can disagree with respect and repair after.","why":"No two people want the same thing every time; the skill is in the recovery."},"relearn":"Fit isn't never fighting; it's disagreeing with respect and repairing after.","persona":"any","source":"fighting isn't the signal"},
  {"id":"cb-902","cat":"choosing-well","type":"strike-rewrite","hook":"\"Pick the one your relatives will approve of most.\"","myth":{"un":"Pick the one your relatives will approve of most.","re":"Approval matters less than fit; you'll live the daily life, so weigh values and compatibility yourself.","why":"Relatives go home; you stay in the partnership."},"relearn":"Approval is a factor, not the basis; weigh values and compatibility yourself.","persona":"any","source":"approval isn't fit"},
  {"id":"cb-903","cat":"choosing-well","type":"strike-rewrite","hook":"\"They're rude to staff and drivers, but they're sweet to me, so it's fine.\"","myth":{"un":"They're rude to staff and drivers, but sweet to me, so it's fine.","re":"How someone treats people with less power is who they are; the sweetness to you can be conditional.","why":"Character shows most where there's nothing to gain."},"relearn":"How they treat people with less power reveals real character.","persona":"any","source":"treats the less powerful"},
  {"id":"cb-904","cat":"choosing-well","type":"strike-rewrite","hook":"\"Jealousy means they really love you.\"","myth":{"un":"Jealousy means they really love you.","re":"Possessive jealousy is about control, not love; trust and respect for your freedom are the green flags.","why":"Love wants you free; control wants you watched."},"relearn":"Possessive jealousy is a control flag, not proof of love.","persona":"any","source":"jealousy isn't love"},
  {"id":"cb-905","cat":"choosing-well","type":"strike-rewrite","hook":"\"They earn a lot and look great, so they'll be a good partner.\"","myth":{"un":"They earn a lot and look great, so they'll be a good partner.","re":"Income and looks predict little about partnership; kindness, honesty and how they handle conflict predict a lot.","why":"You build a life with someone's character, not their salary slip."},"relearn":"Money and looks predict little; character and conflict-handling predict a lot.","persona":"any","source":"status isn't fit"},
  {"id":"cb-906","cat":"choosing-well","type":"strike-rewrite","hook":"\"If you wait for the 'right' values match, you'll be single forever.\"","myth":{"un":"If you wait for a real values match, you'll be single forever.","re":"Holding out for shared core values isn't fussiness; it's choosing a partnership that can actually last.","why":"Settling on a values clash costs more, for longer, than waiting."},"relearn":"Holding out for shared core values is sound choosing, not fussiness.","persona":"Sneha","source":"not fussiness"},
  {"id":"cb-907","cat":"choosing-well","type":"strike-rewrite","hook":"\"Love-bombing early on just means they're very romantic.\"","myth":{"un":"Love-bombing early on just means they're very romantic.","re":"Intense, rushing affection that floods then withdraws is a control pattern, not steady romance.","why":"Real warmth is consistent; flooding-then-cold keeps you off balance."},"relearn":"Flooding affection then going cold is a control pattern, not romance.","persona":"any","source":"love-bombing flag"},
  {"id":"cb-908","cat":"choosing-well","type":"strike-rewrite","hook":"\"Same caste or community automatically means you're compatible.\"","myth":{"un":"Same caste or community automatically means you're compatible.","re":"A shared background doesn't guarantee shared values, goals or respect; you still have to weigh the person.","why":"Two people from one community can want completely different lives."},"relearn":"Shared background isn't compatibility; weigh the actual person.","persona":"any","source":"background isn't fit"},
  {"id":"cb-909","cat":"choosing-well","type":"strike-rewrite","hook":"\"They put me down 'as a joke', but they don't mean it.\"","myth":{"un":"They put me down 'as a joke', but they don't mean it.","re":"Regular contempt dressed as jokes is a red flag; a partner who respects you doesn't belittle you for laughs.","why":"Constant 'jokes' at your expense wear down respect over time."},"relearn":"Contempt disguised as jokes is a red flag, not harmless teasing.","persona":"any","source":"contempt as jokes"},
  {"id":"cb-910","cat":"choosing-well","type":"strike-rewrite","hook":"\"Once we're married, they'll finally stop the controlling behaviour.\"","myth":{"un":"Once we're married, they'll stop the controlling behaviour.","re":"Marriage rarely ends control; behaviour you accept while choosing tends to become the norm after.","why":"A wedding changes the label, not the pattern."},"relearn":"Marriage rarely ends control; the pattern usually stays or grows.","persona":"any","source":"marriage won't fix it"},
  {"id":"cb-911","cat":"choosing-well","type":"strike-rewrite","hook":"\"A partner who agrees with everything you say is the dream.\"","myth":{"un":"A partner who agrees with everything you say is the dream.","re":"Someone with their own views who can disagree respectfully is a stronger partner than a yes-person.","why":"A whole person brings their own judgement; that's what a team needs."},"relearn":"A partner with their own respectful views beats a yes-person.","persona":"any","source":"not a yes-person"},
  {"id":"cb-912","cat":"choosing-well","type":"sort","hook":"Sort each into deep green flag or surface appeal.","items":[{"id":"a","text":"Owns it and apologises when wrong"},{"id":"b","text":"Has a big designer wardrobe"},{"id":"c","text":"Listens when you disagree"},{"id":"d","text":"Drives a flashy car"},{"id":"e","text":"Respects your no without sulking"},{"id":"f","text":"Has a huge social following"}],"bins":[{"id":"green","label":"Deep green flag","valence":"pos"},{"id":"surface","label":"Surface appeal","valence":"neutral"}],"key":{"a":"green","b":"surface","c":"green","d":"surface","e":"green","f":"surface"},"relearn":"Owning mistakes, listening and respecting a no are deep green flags; possessions and followers are surface.","persona":"any","source":"green vs surface"},
  {"id":"cb-913","cat":"choosing-well","type":"sort","hook":"Sort each sign into real compatibility or just infatuation.","items":[{"id":"a","text":"You want similar things from life"},{"id":"b","text":"You can't stop checking your phone for them"},{"id":"c","text":"You handle disagreements as a team"},{"id":"d","text":"The early weeks feel like a high"},{"id":"e","text":"Your day-to-day values line up"},{"id":"f","text":"You idealise them and skip their flaws"}],"bins":[{"id":"compat","label":"Compatibility","valence":"pos"},{"id":"infat","label":"Infatuation","valence":"uhoh"}],"key":{"a":"compat","b":"infat","c":"compat","d":"infat","e":"compat","f":"infat"},"relearn":"Shared goals, values and teamwork are compatibility; a high and idealising are infatuation.","persona":"any","source":"compat vs infatuation"},
  {"id":"cb-914","cat":"choosing-well","type":"sort","hook":"Sort each into reveals real fit or just a distraction.","items":[{"id":"a","text":"How do they treat people who can't help them?"},{"id":"b","text":"How expensive was the first date?"},{"id":"c","text":"Do our goals for the next ten years align?"},{"id":"d","text":"How good do we look as a couple online?"},{"id":"e","text":"How do they handle being told no?"},{"id":"f","text":"How impressive is their job title?"}],"bins":[{"id":"reveals","label":"Reveals fit","valence":"pos"},{"id":"distraction","label":"Distraction","valence":"neutral"}],"key":{"a":"reveals","b":"distraction","c":"reveals","d":"distraction","e":"reveals","f":"distraction"},"relearn":"How they treat the powerless, where goals align and how they take a no reveal fit; cost and titles distract.","persona":"any","source":"revealing questions"},
  {"id":"cb-915","cat":"choosing-well","type":"sort","hook":"Sort each behaviour into builds respect or erodes respect.","items":[{"id":"a","text":"Hears your view before deciding"},{"id":"b","text":"Mocks your interests to friends"},{"id":"c","text":"Keeps the small promises they make"},{"id":"d","text":"Checks your phone without asking"},{"id":"e","text":"Owns it when they're wrong"},{"id":"f","text":"Gives the silent treatment to win"}],"bins":[{"id":"builds","label":"Builds respect","valence":"pos"},{"id":"erodes","label":"Erodes respect","valence":"neg"}],"key":{"a":"builds","b":"erodes","c":"builds","d":"erodes","e":"builds","f":"erodes"},"relearn":"Listening, keeping promises and owning mistakes build respect; mocking, snooping and stonewalling erode it.","persona":"any","source":"builds vs erodes"},
  {"id":"cb-916","cat":"choosing-well","type":"sort","hook":"Sort each into a sound reason to choose them or a shaky one.","items":[{"id":"a","text":"We share core values and goals"},{"id":"b","text":"Everyone says we look good together"},{"id":"c","text":"We handle conflict with respect"},{"id":"d","text":"They're the most attractive person I've dated"},{"id":"e","text":"They treat my family and theirs kindly"},{"id":"f","text":"My relatives are impressed by their job"}],"bins":[{"id":"sound","label":"Sound reason","valence":"pos"},{"id":"shaky","label":"Shaky reason","valence":"uhoh"}],"key":{"a":"sound","b":"shaky","c":"sound","d":"shaky","e":"sound","f":"shaky"},"relearn":"Shared values, respectful conflict and kindness are sound reasons; looks, image and others' approval are shaky.","persona":"any","source":"sound vs shaky"},
  {"id":"cb-917","cat":"choosing-well","type":"sort","hook":"Sort each into a reliable basis for choosing or a fragile one.","items":[{"id":"a","text":"We've seen each other stressed and still respectful"},{"id":"b","text":"The chemistry is electric"},{"id":"c","text":"We agree on money and family big-picture"},{"id":"d","text":"We've only ever met on perfect dates"},{"id":"e","text":"They listen and adjust when I raise something"},{"id":"f","text":"I'm hoping they'll change after we commit"}],"bins":[{"id":"reliable","label":"Reliable basis","valence":"pos"},{"id":"fragile","label":"Fragile basis","valence":"uhoh"}],"key":{"a":"reliable","b":"fragile","c":"reliable","d":"fragile","e":"reliable","f":"fragile"},"relearn":"Seeing them stressed, agreeing big-picture and being heard are reliable; chemistry-only and 'they'll change' are fragile.","persona":"any","source":"reliable vs fragile"},
  {"id":"cb-918","cat":"choosing-well","type":"sort","hook":"Sort each into a question worth asking before committing or one that misses the point.","items":[{"id":"a","text":"How do you want to split money and work?"},{"id":"b","text":"What's your star sign, really?"},{"id":"c","text":"How do you handle it when we disagree?"},{"id":"d","text":"Which of us has the fancier degree?"},{"id":"e","text":"Do you want children, and when?"},{"id":"f","text":"Whose family is better connected?"}],"bins":[{"id":"worth","label":"Worth asking","valence":"pos"},{"id":"misses","label":"Misses the point","valence":"neutral"}],"key":{"a":"worth","b":"misses","c":"worth","d":"misses","e":"worth","f":"misses"},"relearn":"Money, conflict and children are worth asking before committing; signs, degrees and connections miss the point.","persona":"any","source":"questions worth asking"},
  {"id":"cb-919","cat":"choosing-well","type":"sort","hook":"Sort each into what makes a partnership strong or what just looks good to others.","items":[{"id":"a","text":"We respect each other as equals"},{"id":"b","text":"We'd make a 'proper' couple in photos"},{"id":"c","text":"We can repair after a hard talk"},{"id":"d","text":"Others approve of how we pair up"},{"id":"e","text":"Our core values genuinely align"},{"id":"f","text":"We tick the boxes a brochure would list"}],"bins":[{"id":"strong","label":"Makes it strong","valence":"pos"},{"id":"looks","label":"Just looks good","valence":"neutral"}],"key":{"a":"strong","b":"looks","c":"strong","d":"looks","e":"strong","f":"looks"},"relearn":"Equal respect, repair and shared values make a partnership strong, whatever shape it takes; appearances don't.","persona":"Aditya","source":"strong not for show"},
  {"id":"cb-920","cat":"choosing-well","type":"sort","hook":"Sort each into a green flag in how they handle conflict or a red flag.","items":[{"id":"a","text":"Stays on the topic instead of attacking you"},{"id":"b","text":"Brings up old wins to score points"},{"id":"c","text":"Can say 'I was wrong' and mean it"},{"id":"d","text":"Threatens to leave to end every argument"},{"id":"e","text":"Takes a breather, then comes back to talk"},{"id":"f","text":"Goes silent for days to punish you"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Staying on topic, owning fault and taking a healthy pause are green flags; scorekeeping, threats and stonewalling are red.","persona":"any","source":"conflict flags"},
  {"id":"cb-921","cat":"choosing-well","type":"branch","persona":"any","source":"respects your goals","hook":"Farhan is warm and attentive, but keeps calling your promotion push 'not that important'.","steps":[{"prompt":"He says it again while you're excitedly planning your next work milestone. What do you do?","options":[{"text":"Tell him plainly that your goals matter to you","then":"He looks a little caught out, and asks why it stung.","best":true},{"text":"Laugh it off, since he means it lightly","then":"He says it again a week later, just as lightly."},{"text":"Stop mentioning your work plans around him","then":"The topic quietly disappears from your conversations."},{"text":"Say his goals don't matter to you either, to match","then":"He's stung, and neither of you says what you actually meant."}],"why":"Naming it plainly gives him a real chance to show how he treats your ambitions."},{"prompt":"A friend asks how he feels about your career. What do you say?","options":[{"text":"That you're watching closely how seriously he takes it","then":"Saying it out loud, you realise how much this has been bothering you.","best":true},{"text":"That he's warm in every other way, so it's minor","then":"You talk yourself past the one thing that's actually nagging at you."},{"text":"That you haven't really thought about it","then":"You leave the question unexamined, again."},{"text":"That every partner probably says something like that","then":"You lower the bar before you've even tested it."}],"why":"Admitting it's been bothering you is what lets you actually look at the signal."},{"prompt":"He brings it up himself, saying he didn't realise it bothered you. What do you do?","options":[{"text":"Explain why your goals matter and see how he responds","then":"He listens fully, then asks what support would actually look like.","best":true},{"text":"Say it's all fine now, since he's noticed and apologised","then":"The pattern goes unaddressed, waiting to repeat."},{"text":"Downplay it so he doesn't feel bad","then":"He relaxes, and the real question stays unanswered."},{"text":"Test him by mentioning an even bigger goal","then":"You get a reaction to test him, instead of a real answer."}],"why":"How he responds when it's named directly previews how he'll treat your goals for years."}],"debrief":"How someone treats your goals while courting previews the partnership.","relearn":"How they treat your goals is a real values signal, not a side detail."},
  {"id":"cb-922","cat":"choosing-well","type":"branch","persona":"any","source":"trust the unease","hook":"On paper, Vikram is exactly what you'd have asked for, but something quietly feels off.","steps":[{"prompt":"Your friends keep saying how lucky you are. What do you do with the unease?","options":[{"text":"Sit with it and try to name what's actually bothering you","then":"You realise it's something about how he talks about his exes.","best":true},{"text":"Push it aside, since the match looks so right","then":"The feeling doesn't go away. It just gets quieter."},{"text":"Tell your friends about it and let them decide if it matters","then":"They shrug it off fast, and you're no closer to knowing."},{"text":"Assume it's just nerves about a big decision","then":"You label it and move on without actually checking it."}],"why":"Naming the unease, instead of pushing past it, is the only way to actually check it."},{"prompt":"You notice the feeling again after your next conversation with him. What do you do?","options":[{"text":"Ask him directly about the thing that's bothering you","then":"His answer is careful, and it doesn't fully settle your unease.","best":true},{"text":"Say nothing and watch a bit longer before deciding","then":"You gather more moments like it, and still say nothing."},{"text":"Decide you're overthinking a good thing","then":"You talk yourself out of checking any further."},{"text":"Bring it up with your mother instead of him","then":"She reassures you, though she hasn't seen what you have."}],"why":"A direct question tests the unease against something real, not just a feeling."},{"prompt":"The wedding talk starts moving faster. What do you do?","options":[{"text":"Ask to slow the process down until the unease is clearer","then":"There's some friction, but your family agrees to ease the pace.","best":true},{"text":"Let the momentum carry you, since stopping feels dramatic","then":"The unease rides along with the momentum, unresolved."},{"text":"Decide the feeling doesn't matter next to how well things look","then":"You override the one thing that's actually been asking for attention."},{"text":"Wait for the feeling to resolve on its own","then":"It doesn't, and the date keeps approaching anyway."}],"why":"Slowing down gives the unease room to be understood before a lifelong choice."},{"prompt":"With more time, what finally helps you understand the unease?","options":[{"text":"An honest talk about the exact thing that worried you","then":"You finally get a clear answer, one way or the other.","best":true},{"text":"Time simply passing and the feeling fading on its own","then":"It fades from attention, without ever actually being answered."},{"text":"Deciding the paper-perfect match outweighs one bad feeling","then":"You move forward, with the question still quietly unresolved."},{"text":"Asking a friend to meet him and give a second opinion","then":"Your friend likes him fine, which isn't quite the same as your answer."}],"why":"A specific, honest conversation actually resolves a persistent unease, not time or hope."}],"debrief":"A persistent 'something's off' is worth understanding before a lifelong choice.","relearn":"Take a persistent gut unease seriously, even with a perfect-on-paper match."},
  {"id":"cb-923","cat":"choosing-well","type":"branch","persona":"any","source":"control vs trust","hook":"Rohan asks for your phone passcode, saying real commitment means no secrets.","steps":[{"prompt":"He holds out his hand, waiting. What do you do?","options":[{"text":"Say no, and that trust doesn't need passwords","then":"He looks annoyed, then says fine, a little too quickly.","best":true},{"text":"Hand it over so he knows you have nothing to hide","then":"He scrolls for a while, longer than you expected."},{"text":"Give him an old password that doesn't actually work","then":"He tries it, gets locked out, and grows more suspicious."},{"text":"Ask for his passcode too, to make it even","then":"He hesitates before handing his over, slower than you did."}],"why":"Naming it as a boundary, not a fight, protects your privacy without escalating."},{"prompt":"The next week, he asks why you were texting a friend so late. What do you do?","options":[{"text":"Say your friendships are yours, and ask why he's checking","then":"He goes quiet, then admits he'd been reading your messages.","best":true},{"text":"Explain the whole conversation in detail to reassure him","then":"He asks for more detail than you're comfortable giving."},{"text":"Stop replying to that friend late at night from now on","then":"One boundary shrinks, and you're not sure it'll be the last."},{"text":"Get angry that he's even asking","then":"The fight ends the topic for tonight, without actually settling it."}],"why":"Asking why he's checking turns the question back where it belongs."},{"prompt":"He says checking your phone is just how he shows he cares. What do you do?","options":[{"text":"Say plainly that checking isn't care, and hold your boundary","then":"He's quiet for a moment, unused to hearing it named directly.","best":true},{"text":"Agree it's sweet, even though it doesn't quite feel that way","then":"The checking continues, now with your blessing."},{"text":"Suggest a compromise where he checks just sometimes","then":"The checking continues on his terms, dressed up as a compromise."},{"text":"Say nothing and hope it fades with time","then":"It doesn't fade. It becomes the normal way things are."}],"why":"Saying plainly that checking isn't care keeps trust, not surveillance, as the standard."}],"debrief":"Wanting access to your private life isn't closeness; trust is the green flag.","relearn":"Demanding passwords and monitoring is a control flag, not closeness."},
  {"id":"cb-924","cat":"choosing-well","type":"branch","persona":"Sneha","source":"your lens leads","hook":"Your relatives are pushing hard for one match: big salary, respected family name.","steps":[{"prompt":"Your masi calls, excited, urging you to say yes fast. What do you do?","options":[{"text":"Thank her, and say you'll meet him and judge for yourself","then":"She's pleased, and a little surprised you want to meet him first.","best":true},{"text":"Say yes on her word, since she knows best","then":"The match moves forward before you've asked him a single question."},{"text":"Say no immediately, just to push back on the pressure","then":"Your family talks you into one meeting anyway, and you go in already closed."},{"text":"Ask her to just handle the whole process for you","then":"She happily takes over, and your own judgement stays on the sidelines."}],"why":"Thanking her while keeping your own judgement lets you use her enthusiasm without handing her the decision."},{"prompt":"You finally meet him. He's polite, but talks mostly about his job title. What do you notice?","options":[{"text":"Whether he asks anything real about you in return","then":"By the end, you realise he never once asked what you wanted.","best":true},{"text":"How well his job title matches what your family wanted","then":"It matches perfectly, and you learn almost nothing else about him."},{"text":"How smoothly the conversation with your parents goes","then":"The parents get along well, and you're barely part of the exchange."},{"text":"How this will look announced to the rest of the family","then":"You picture the announcement before you've actually decided anything."}],"why":"Noticing whether he's curious about you shows whether this is mutual, not just suitable."},{"prompt":"Your relatives ask if you're ready to say yes. What do you tell them?","options":[{"text":"That salary and name aren't enough for you to decide on","then":"There's a pause, then your masi asks what you're actually looking for.","best":true},{"text":"Yes, since the family name is hard to turn down","then":"The families begin celebrating before you've said much else."},{"text":"That you need them to convince you, since you're unsure","then":"You hand the decision to people who won't be the ones living it."},{"text":"That you'll decide later, without saying why","then":"The pressure just returns tomorrow, unanswered."}],"why":"Naming what you're actually looking for keeps your lens leading, not theirs."}],"debrief":"Family input is welcome, but you live the partnership, so your lens should lead.","relearn":"Weigh values and compatibility yourself; salary and name alone are shaky."},
  {"id":"cb-925","cat":"choosing-well","type":"branch","persona":"any","source":"honesty isn't selective","hook":"Priya is fun and attentive, but you've caught her exaggerating small things to friends more than once.","steps":[{"prompt":"She tells a friend a clearly inflated story about her new job. What do you do?","options":[{"text":"Notice it as a real pattern worth paying attention to","then":"You start quietly tracking how often this actually happens.","best":true},{"text":"Assume it's harmless, since everyone embellishes sometimes","then":"You wave off the same thing you'll notice again next week."},{"text":"Call her out in front of her friend","then":"She's embarrassed, and the conversation gets tense fast."},{"text":"Decide it's none of your concern since it's not about you","then":"You miss what the habit might mean for how she treats you."}],"why":"Treating it as a pattern, not a one-off, is what lets you actually read it."},{"prompt":"Later, alone, you mention what you noticed. What do you say?","options":[{"text":"Ask her, gently, why she felt she needed to stretch the truth","then":"She's quiet, then admits she does it more than she'd like to.","best":true},{"text":"Say nothing, since it isn't really your business","then":"The pattern continues, unexamined by either of you."},{"text":"Joke about it lightly to keep things easy","then":"She laughs it off, and nothing actually shifts."},{"text":"Tell her plainly you'll never trust anything she says to you again","then":"She shuts down completely, and you learn nothing further."}],"why":"A gentle, direct question tests the pattern instead of ignoring it."},{"prompt":"A few weeks later, you catch a small dishonesty aimed at you directly. What do you do?","options":[{"text":"Connect it to the pattern you noticed with others","then":"It clicks. This was never really about other people.","best":true},{"text":"Treat it as a one-off, separate from before","then":"You reset the count, and the pattern keeps its hold on you."},{"text":"Let it go without mentioning it, to keep things easy","then":"Small dishonesty toward you starts feeling ordinary."},{"text":"Overreact to this one instance alone","then":"The bigger pattern gets lost inside one heated argument."}],"why":"Connecting the dots shows the habit was never only about other people."},{"prompt":"Deciding how to move forward with her, what matters most?","options":[{"text":"That easy dishonesty with others rarely stays there","then":"You trust what you've actually observed over how charming she is.","best":true},{"text":"That she's never technically lied to your face","then":"You lean on a technicality the pattern doesn't really support."},{"text":"That she's warm and fun regardless","then":"You let the warmth outweigh what you've actually seen."},{"text":"That confronting her again might finally fix it","then":"You wait on a change the pattern gives you no real reason to expect."}],"why":"Easy dishonesty toward others is information about how you'll likely be treated too."}],"debrief":"Dishonesty toward others is a red flag about character, not a habit that stops at you.","relearn":"Easy dishonesty toward others is a red flag about how they'll treat you."},
  {"id":"cb-926","cat":"choosing-well","type":"branch","persona":"any","source":"first conflict reveals","hook":"After your first real disagreement, Naveen has gone cold and silent for three days.","steps":[{"prompt":"His messages have gone short and distant since the argument. What do you do?","options":[{"text":"Notice how he handles conflict as real information about him","then":"You start paying closer attention to this, not just the silence itself.","best":true},{"text":"Assume he needs space and say nothing more","then":"The days pass, and the actual disagreement stays unresolved."},{"text":"Apologise for the argument, even though you're not sure you're wrong","then":"He warms up, and you're left unsure what you even apologised for."},{"text":"Match his silence and wait him out","then":"The standoff continues, with neither of you moving first."}],"why":"Treating how he handles conflict as real data is what actually tells you about fit."},{"prompt":"By day four, the disagreement still hasn't really been talked about. What do you do?","options":[{"text":"Ask how he usually handles disagreements, honestly","then":"He admits he shuts down rather than says what he's actually feeling.","best":true},{"text":"Say you're sorry again, just to end the silence","then":"The silence ends, and the real pattern stays unnamed."},{"text":"Tell him three days of silence isn't fair, and leave it there","then":"He agrees it wasn't fair, without saying what he'll do differently."},{"text":"Wait for him to reach out first this time","then":"Another day passes with neither of you speaking."}],"why":"A direct, honest question about his pattern reveals more than another apology would."},{"prompt":"He finally opens up about the disagreement. What do you focus on?","options":[{"text":"Whether he's willing to handle the next one differently","then":"He says he'll try to say something rather than go quiet next time.","best":true},{"text":"Just being relieved the silence is over","then":"The relief feels good, and the pattern itself goes unaddressed."},{"text":"Getting him to admit he was wrong","then":"You win the point, and learn nothing about how he'll handle the next one."},{"text":"Moving on quickly, since talking about it feels tense","then":"You skip the one conversation that would actually tell you something."}],"why":"Whether he can change how he handles conflict matters more than who was right this time."}],"debrief":"How a person handles the first real conflict tells you more than easy days.","relearn":"How they handle conflict and repair is some of the clearest data on fit."},
  {"id":"cb-927","cat":"choosing-well","type":"match","hook":"Match each thing worth weighing in a partner to why it matters.","relearn":"Shared values, conflict-handling, respect, honesty and kindness to others are what to weigh in a partner.","persona":"any","source":"what to weigh","pairs":[{"left":"Shared core values","right":"Decides if your lives can align"},{"left":"How they handle conflict","right":"Sets your daily peace for years"},{"left":"Mutual respect","right":"The foundation everything rests on"},{"left":"Honesty under pressure","right":"Tells you if trust is safe"},{"left":"Kindness to the powerless","right":"Shows their real character"}]},
  {"id":"cb-928","cat":"choosing-well","type":"match","hook":"Match each behaviour to the flag it is.","relearn":"Owning mistakes and respecting a no are green flags; love-bombing, contempt and control are red.","persona":"any","source":"flag reading","pairs":[{"left":"Owns it when wrong","right":"Green flag: accountable"},{"left":"Love-bombs then goes cold","right":"Red flag: control pattern"},{"left":"Respects your no calmly","right":"Green flag: honours boundaries"},{"left":"Mocks you to feel superior","right":"Red flag: contempt"},{"left":"Tracks where you are","right":"Red flag: surveillance"}]},
  {"id":"cb-929","cat":"choosing-well","type":"match","hook":"Match each early sign to what it really tells you.","relearn":"Read early signs for character, not just chemistry; flooding affection and rushing are warnings.","persona":"any","source":"early signs","pairs":[{"left":"Rushes you to commit fast","right":"Wants control before you can see clearly"},{"left":"Asks about your goals and listens","right":"Curious about the real you"},{"left":"Bad-mouths every ex","right":"May never own their own part"},{"left":"Treats your friends warmly","right":"Welcomes your whole life"},{"left":"Tests you with little ultimatums","right":"Early control, dressed as standards"}]},
  {"id":"cb-930","cat":"choosing-well","type":"match","hook":"Match each question to what it helps you read in a partner.","relearn":"The right questions read values, conflict-style, money, children and family fit, not surface appeal.","persona":"any","source":"questions to fit","pairs":[{"left":"How do you handle being told no?","right":"Conflict and ego"},{"left":"How should money and work be shared?","right":"Fairness and roles"},{"left":"Do you want children, and when?","right":"Life direction"},{"left":"How involved should families be?","right":"Boundaries"},{"left":"What do you do after a fight?","right":"Repair skill"}]},
  {"id":"cb-931","cat":"choosing-well","type":"match","hook":"Match each phrase to whether it's spark talking or compatibility talking.","relearn":"Spark talks in highs and intensity; compatibility talks in shared direction and steady respect.","persona":"any","source":"spark vs compatibility","pairs":[{"left":"\"I can't stop thinking about them\"","right":"Spark: a feeling"},{"left":"\"We want the same kind of life\"","right":"Compatibility: direction"},{"left":"\"It's so intense right now\"","right":"Spark: a high"},{"left":"\"We disagree well and recover\"","right":"Compatibility: skill"},{"left":"\"We respect each other's no\"","right":"Compatibility: foundation"}]},
  {"id":"cb-932","cat":"choosing-well","type":"match","hook":"Match each basis for choosing to what it really is.","relearn":"Values, respect and conflict-handling are a sound basis; looks, status and 'they'll change' are shaky.","persona":"any","source":"sound vs shaky basis","pairs":[{"left":"We share core values","right":"Sound: a lasting foundation"},{"left":"They're the best-looking I've dated","right":"Shaky: attraction alone fades"},{"left":"We repair well after conflict","right":"Sound: a real skill"},{"left":"My relatives are impressed","right":"Shaky: that's their fit, not yours"},{"left":"I'm hoping they'll change later","right":"Shaky: a wish, not a plan"}]},
  {"id":"cb-933","cat":"choosing-well","type":"match","hook":"Match each foundation to why it holds any partnership, whatever its shape.","relearn":"Every partnership, including queer ones, rests on the same foundations: values, respect, communication, consent.","persona":"Aditya","source":"same foundations","pairs":[{"left":"Shared values","right":"Keeps two lives pointed the same way"},{"left":"Mutual respect","right":"Lets each stay a whole person"},{"left":"Honest communication","right":"Keeps small things from festering"},{"left":"Real consent","right":"Makes the choice genuinely free"},{"left":"Repair after conflict","right":"Lets the bond survive hard days"}]},
  {"id":"cb-934","cat":"choosing-well","type":"spot","hook":"A partner's behaviour list. Spot the two red flags.","scene":[{"id":"a","text":"Listens when you raise something hard","trick":false},{"id":"b","text":"Decides where you can go and who you see","trick":true},{"id":"c","text":"Owns it and apologises when wrong","trick":false},{"id":"d","text":"Mocks your dreams to 'keep you grounded'","trick":true},{"id":"e","text":"Respects your no without a fight","trick":false}],"why":"Controlling your movements and mocking your dreams are control and contempt, the red flags to catch.","relearn":"Control over your life and contempt for your dreams are red flags; listening and owning mistakes are green.","persona":"any","source":"spot red flags"},
  {"id":"cb-935","cat":"choosing-well","type":"spot","hook":"Early dating signs. Spot the two warning flags.","scene":[{"id":"a","text":"Asks about your goals and remembers them","trick":false},{"id":"b","text":"Pushes you to commit far faster than you want","trick":true},{"id":"c","text":"Is warm to your friends and family","trick":false},{"id":"d","text":"Floods you with affection, then goes cold","trick":true},{"id":"e","text":"Hears a no and respects it","trick":false}],"why":"Rushing commitment and flooding-then-cold are control patterns, the warning flags to catch.","relearn":"Rushing you and love-bombing then withdrawing are warning flags, not strong romance.","persona":"any","source":"spot early warnings"},
  {"id":"cb-936","cat":"choosing-well","type":"spot","hook":"How a 'perfect-on-paper' match treats people. Spot the two red flags.","scene":[{"id":"a","text":"Is patient with waiters and drivers","trick":false},{"id":"b","text":"Is cold and rude to anyone who can't help them","trick":true},{"id":"c","text":"Thanks people who do small things for them","trick":false},{"id":"d","text":"Snaps at staff to look powerful in front of you","trick":true},{"id":"e","text":"Treats your elders with real respect","trick":false}],"why":"Rudeness to the powerless and snapping at staff to look big reveal the real character, the flags to catch.","relearn":"How someone treats people with no power over them reveals their real character.","persona":"any","source":"spot character"},
  {"id":"cb-937","cat":"choosing-well","type":"spot","hook":"Reasons people give for a match. Spot the two shaky ones.","scene":[{"id":"a","text":"\"We want the same kind of life\"","trick":false},{"id":"b","text":"\"Everyone says we look great together\"","trick":true},{"id":"c","text":"\"We handle disagreements with respect\"","trick":false},{"id":"d","text":"\"Their family name will impress mine\"","trick":true},{"id":"e","text":"\"We're honest with each other under stress\"","trick":false}],"why":"Looking good to others and impressing family are shaky bases; values, respect and honesty are sound.","relearn":"Image and others' approval are shaky reasons; shared values and respect are sound.","persona":"any","source":"spot shaky reasons"},
  {"id":"cb-938","cat":"choosing-well","type":"spot","hook":"A friend describes their new partner. Spot the two control flags.","scene":[{"id":"a","text":"\"They ask my opinion before big decisions\"","trick":false},{"id":"b","text":"\"They get angry if I see my friends\"","trick":true},{"id":"c","text":"\"They keep the small promises they make\"","trick":false},{"id":"d","text":"\"They check my phone whenever they like\"","trick":true},{"id":"e","text":"\"They respect it when I need space\"","trick":false}],"why":"Anger at your friendships and checking your phone are control, the flags to catch; the rest are green.","relearn":"Isolating you from friends and monitoring your phone are control flags, not care.","persona":"any","source":"spot control"},
  {"id":"cb-939","cat":"choosing-well","type":"spot","hook":"Lines from a partner during a fight. Spot the two contempt flags.","scene":[{"id":"a","text":"\"Help me understand what upset you\"","trick":false},{"id":"b","text":"\"You're too stupid to get my point\"","trick":true},{"id":"c","text":"\"I was wrong about that, I'm sorry\"","trick":false},{"id":"d","text":"\"No wonder nobody else wanted you\"","trick":true},{"id":"e","text":"\"Let's take a breath and come back to it\"","trick":false}],"why":"Insulting your intelligence and cutting you down are contempt, the red flags to catch in conflict.","relearn":"Insults and cutting you down in a fight are contempt, a serious red flag.","persona":"any","source":"spot contempt"},
  {"id":"cb-940","cat":"choosing-well","type":"spot","hook":"A partner reacts to your career win. Spot the two red flags.","scene":[{"id":"a","text":"\"That's brilliant, you earned it\"","trick":false},{"id":"b","text":"\"Don't get too ambitious, it's not your place\"","trick":true},{"id":"c","text":"\"How can I support the next step?\"","trick":false},{"id":"d","text":"\"Now you'll think you're better than me\"","trick":true},{"id":"e","text":"\"Let's celebrate this properly\"","trick":false}],"why":"Diminishing your ambition and resenting your success are red flags; a good partner cheers your growth.","relearn":"A partner who diminishes or resents your success is a red flag; a good one celebrates it.","persona":"any","source":"spot resentment"},
  {"id":"cb-941","cat":"choosing-well","type":"spot","hook":"Sneha's relatives say things to push a match. Spot the two that aren't real reasons.","scene":[{"id":"a","text":"\"Have you talked through your values together?\"","trick":false},{"id":"b","text":"\"He's from a big family, just say yes\"","trick":true},{"id":"c","text":"\"Do you each respect how the other handles money?\"","trick":false},{"id":"d","text":"\"You're 31, you can't be picky now\"","trick":true},{"id":"e","text":"\"Take your time and meet properly first\"","trick":false}],"why":"Family size and 'you can't be picky' are pressure, not fit; values and time are real reasons.","relearn":"Status and timeline pressure aren't reasons to choose; values and your own time are.","persona":"Sneha","source":"spot pressure"},
  {"id":"cb-942","cat":"choosing-well","type":"spot","hook":"Behaviours after a disagreement. Spot the two that are warning flags.","scene":[{"id":"a","text":"Comes back to talk once you've both cooled off","trick":false},{"id":"b","text":"Gives the silent treatment for days to punish you","trick":true},{"id":"c","text":"Can say sorry and mean it","trick":false},{"id":"d","text":"Threatens to leave to win every argument","trick":true},{"id":"e","text":"Stays on the topic instead of attacking you","trick":false}],"why":"Stonewalling and leave-threats are warning flags; returning to repair and owning fault are green.","relearn":"Stonewalling and threats to leave are warning flags; repair and owning fault are green.","persona":"any","source":"spot conflict flags"},
  {"id":"cb-943","cat":"choosing-well","type":"choose","persona":"any","source":"the real question","hook":"Naveen and Priyanka have been dating for three intense, exciting months.","prompt":"What matters more than the spark right now?","options":[{"text":"Whether they keep small promises","fits":true,"note":"Small promises kept over months show a reliability no spark can."},{"text":"Whether they take a small 'no' well","fits":true,"note":"Taking a small no gracefully is an early sign of respect."},{"text":"How intense the chemistry feels","fits":false,"note":"Strong chemistry feels wonderful, but it doesn't predict a steady partner."},{"text":"How many texts a day they send","fits":false,"note":"Lots of messages feels close, but it's no proof of a shared life ahead."},{"text":"How grand their gestures are","fits":false,"note":"Big romantic gestures are lovely, but they say little about daily reliability."},{"text":"How fast it feels serious","fits":false,"note":"Feeling serious fast is exciting, but speed alone tells you very little."}],"relearn":"The first months, not the spark, show whether two people could build a good life together."},
  {"id":"cb-944","cat":"choosing-well","type":"choose","persona":"any","source":"hard days reveal","hook":"Varun's flight got cancelled and his whole weekend plan with Sana fell apart.","prompt":"Which moments reveal the most about a partner?","options":[{"text":"How they react when plans collapse","fits":true,"note":"A cancelled plan shows the real, unscripted version of someone."},{"text":"How they behave on a tiring, stressful day","fits":true,"note":"Tiredness and stress strip away performance, so this is honest information."},{"text":"A thoughtful gift on your birthday","fits":false,"note":"A thoughtful gift is sweet, but easy days rarely test who someone really is."},{"text":"A fun night out together","fits":false,"note":"A fun night out is lovely, but it says little about a harder day."},{"text":"A well-planned romantic trip","fits":false,"note":"A well-planned trip is a happy memory, not a test of character."},{"text":"A sweet good morning message","fits":false,"note":"A sweet message is nice, but it costs little on an easy day."}],"relearn":"How someone treats you on a hard day reveals more than a hundred easy ones."},
  {"id":"cb-945","cat":"choosing-well","type":"choose","persona":"any","source":"who they are on a bad day","hook":"Manish and Leela are arguing about whose turn it was to call the landlord.","prompt":"Which reactions are a good sign here?","options":[{"text":"Staying to hear the other one out","fits":true,"note":"Staying present during a hard talk is how disagreements actually get resolved."},{"text":"Saying sorry when they're wrong","fits":true,"note":"Owning a mistake, even mid-argument, builds real trust over time."},{"text":"Taking a breather, then coming back","fits":true,"note":"A short break followed by returning shows the talk still matters to them."},{"text":"Going quiet just to end the fight","fits":false,"note":"Silence can look calm, but it usually buries the issue instead of solving it."},{"text":"Saying 'I feel' instead of blaming","fits":true,"note":"Talking about your own feelings keeps it a conversation, not an attack."},{"text":"Turning it into a joke every time","fits":false,"note":"Joking it off every time avoids the conversation instead of having it."}],"relearn":"How a partner handles a disagreement reveals more than their easy, good-day charm."},
  {"id":"cb-946","cat":"choosing-well","type":"choose","persona":"any","source":"their deadline not yours","hook":"Tara's uncle tells her, again, that she should marry by twenty-eight.","prompt":"Which keep her timeline and the family peace?","options":[{"text":"Smiling and saying she'll know when","fits":true,"note":"A warm, simple answer keeps the decision with her without a fight."},{"text":"Steering the talk elsewhere, kindly","fits":true,"note":"A gentle redirect is a fair way to hold the line without a fight."},{"text":"Agreeing to a date to end the conversation","fits":false,"note":"Agreeing just to close the topic hands the timeline to him, not her."},{"text":"Arguing back until he drops it","fits":false,"note":"Arguing may end the talk, but it costs the peace she also wants."},{"text":"Avoiding every family gathering after that","fits":false,"note":"Staying away protects her timeline, but costs her time with family."},{"text":"Meeting his friend's son to keep the peace","fits":false,"note":"Meeting someone to please him still hands him her timeline."}],"relearn":"Other people's marriage deadlines are their anxiety, not your timeline."},
  {"id":"cb-947","cat":"choosing-well","type":"choose","persona":"any","source":"weigh values too","hook":"Aditi and Rohan have great chemistry, but they differ on some big things.","prompt":"Which of their differences are worth weighing?","options":[{"text":"Whether they both want children","fits":true,"note":"Wanting children or not is a life-shaping difference, best faced honestly now."},{"text":"How they'll handle money","fits":true,"note":"Different money habits can strain a partnership if they're never talked through."},{"text":"Different circles of friends","fits":false,"note":"Different friends can enrich a couple; it's rarely a deal-breaker on its own."},{"text":"Their taste in movies","fits":false,"note":"Different taste in movies is easy to work around and rarely matters long term."},{"text":"Their favourite foods","fits":false,"note":"Different favourite foods just mean more variety on the table."},{"text":"Early riser or night owl","fits":false,"note":"Being an early riser or a night owl is a habit, not a sign of a mismatch."}],"relearn":"Weigh real differences like children and money, not just the spark and small tastes."},
  {"id":"cb-948","cat":"choosing-well","type":"choose","persona":"any","source":"not a project","hook":"Tanvi is already picturing the version of Arvind she hopes he'll become.","prompt":"Which of her hopes are really plans to change him?","options":[{"text":"Wanting him to dress how she prefers","fits":true,"note":"Wanting to dress him her way is choosing an image, not respecting who he is."},{"text":"Wanting him to see his friends less","fits":true,"note":"Shrinking his friendships is control dressed up as closeness."},{"text":"Hoping he'll drop his weekend hobby","fits":true,"note":"Wanting to end a hobby he loves is picking a project, not a partner."},{"text":"Wanting him to be more like her father","fits":true,"note":"Wanting him to resemble someone else means she hasn't chosen him as he is."},{"text":"Hoping they both grow more patient","fits":false,"note":"Growing more patient together is a shared aim, not a demand on one person."},{"text":"Wanting them to learn to argue well","fits":false,"note":"Learning to argue well together is a skill couples build side by side."}],"relearn":"Respect a partner as they are; don't pick someone as a project to change."},
  {"id":"cb-949","cat":"choosing-well","type":"choose","persona":"any","source":"treats the powerless","hook":"Vikram is taking Aarti to meet his parents for the first time today.","prompt":"Which of his moments today reveal his character?","options":[{"text":"How he tips and thanks the driver","fits":true,"note":"How he treats a driver, who can't do much for him, shows his real manners."},{"text":"How he treats the waiter at lunch","fits":true,"note":"How he treats a waiter says more than how he treats people who matter to him."},{"text":"How warmly he greets his parents","fits":false,"note":"Warmth to parents is natural and lovely, but it isn't a hard test of character."},{"text":"How he charms the restaurant manager","fits":false,"note":"Charming someone who can seat them well is easy when there's something to gain."},{"text":"How attentive he seems while his parents watch","fits":false,"note":"Performing well for an audience is common and tells you little on its own."},{"text":"How much he praises his mother's cooking","fits":false,"note":"Praising a parent's cooking is kind, but it costs nothing and proves little."}],"relearn":"How a partner treats people who can't help them shows who they really are."},
  {"id":"cb-950","cat":"choosing-well","type":"reflect","hook":"Aditya and his partner chose each other on fit, like any couple.","prompt":"What matters most to you in a partner?","options":["Shared values","Mutual respect","Honest communication","Being free to be myself"],"affirm":"Every partnership rests on the same foundations: values, respect, communication and consent.","ask":"What makes that one matter most to you?","deeper":"What would you want a partner to know about why it matters?","relearn":"Every partnership, whatever its shape, rests on the same foundations.","persona":"Aditya","source":"same foundations"},
  {"id":"cb-951","cat":"choosing-well","type":"choose","persona":"any","source":"eyes open","hook":"Divya has only been seeing Siddharth a few weeks, but a few moments stuck with her.","prompt":"Which moments are worth noticing, not explaining away?","options":[{"text":"He went through her phone while she was out","fits":true,"note":"Going through her phone is a sign of wanting to watch her, and worth noticing early."},{"text":"He's annoyed if she makes plans alone","fits":true,"note":"Being annoyed at her own plans is an early sign of wanting control."},{"text":"He sulks when she wants a girls' night","fits":true,"note":"Sulking to punish her plans with friends is pressure, even if it's quiet."},{"text":"He was nervous on their first date","fits":false,"note":"First-date nerves are ordinary and say nothing about how he treats her."},{"text":"He forgot one plan, then apologised","fits":false,"note":"One missed plan with a genuine apology is human, not a pattern."},{"text":"He has strong opinions about politics","fits":false,"note":"A different view isn't a red flag by itself; how he handles disagreement matters."}],"relearn":"Noticing a red flag early is choosing with your eyes open, not being negative."},
  {"id":"cb-952","cat":"choosing-well","type":"role-play","persona":"Sneha","source":"don't settle for available","hook":"Your friend Naveen is about to commit to Ritika, mostly out of dating-app exhaustion.","setup":"He shows her profile again, sounding resigned.","steps":[{"prompt":"Naveen says: \"She's around, she's nice enough. Maybe that's enough, honestly.\"","options":[{"text":"\"You deserve someone good for you, not just around.\"","then":"He sighs. \"I know. I'm just so tired of the apps.\"","best":true},{"text":"\"Being tired of dating is a good enough reason.\"","then":"He nods, relieved. \"Right? Okay, I'll stop looking, then.\""},{"text":"\"Honestly, just take what you can get at this point.\"","then":"He nods slowly, and drafts a message he doesn't seem excited about."},{"text":"\"You'll never find anyone if you're this picky.\"","then":"He looks stung. \"I don't think I'm being picky, actually.\""}],"why":"Exhaustion is real, but it isn't the same as her being right for him."},{"prompt":"He asks: \"But what if this is as good as it gets for me?\"","options":[{"text":"\"Then you're still better off waiting than settling for good enough.\"","then":"He exhales. \"That's harder to sit with than just saying yes.\"","best":true},{"text":"\"It probably is, honestly, and most people just settle for this eventually.\"","then":"He nods, and the thought seems to settle something in him, sadly."},{"text":"\"That's dramatic. You're still young.\"","then":"He shrugs. \"Doesn't feel that way most days.\""},{"text":"\"Just give it six more months and see.\"","then":"He nods, though nothing about the actual question gets answered."}],"why":"Being alone a while longer beats committing to someone who isn't right."},{"prompt":"He asks: \"Okay, so what am I actually supposed to be looking for?\"","options":[{"text":"\"Someone good for you, not just the easiest option left.\"","then":"He nods slowly. \"Yeah. I don't think that's Ritika, if I'm honest.\"","best":true},{"text":"\"Someone who doesn't exhaust you the way the apps do.\"","then":"He nods, though that's more about the search than about her."},{"text":"\"I can't tell you that, only you know what you want.\"","then":"He looks a little lost. \"I was hoping you'd have an answer.\""},{"text":"\"Someone who ticks most of your boxes, at least.\"","then":"He frowns. \"That sounds a lot like settling with extra steps.\""}],"why":"Naming genuinely good for you as the bar, not convenience, resets his search."}],"relearn":"You deserve a partner who's genuinely good for you, not just available."},
  {"id":"cb-953","cat":"choosing-well","type":"role-play","persona":"any","source":"hold your circle","hook":"Kavya has started saying your friend group is 'a bad influence' and wants you to see less of them.","setup":"Tonight she brings it up again, more directly.","steps":[{"prompt":"Kavya says: \"I really don't think you should hang out with them so much anymore.\"","options":[{"text":"\"My friends stay in my life. That won't change.\"","then":"She frowns. \"I'm just looking out for you, you know.\"","best":true},{"text":"\"Okay, if it bothers you that much, I'll see them less.\"","then":"She relaxes, then adds that less should mean weekends too."},{"text":"\"They're not that bad once you get to know them.\"","then":"She shakes her head. \"I don't think I want to know them more.\""},{"text":"\"Fine, I'll stop seeing them.\"","then":"She smiles, and asks what you'll do with all that free time."}],"why":"Naming your friends as non-negotiable protects your life outside one relationship."},{"prompt":"She presses: \"Don't you want to spend that time with me instead?\"","options":[{"text":"\"I want both. Someone right for me won't make me choose.\"","then":"She goes quiet, like she wasn't expecting that answer.","best":true},{"text":"\"I guess we could just see how it naturally goes for now.\"","then":"She nods, satisfied, already assuming less time with them ahead."},{"text":"\"You're right. They've been taking up too much time.\"","then":"She smiles. \"Exactly. I'm glad you see it too.\""},{"text":"\"Are you saying I have to choose?\"","then":"She backs off slightly. \"I'm not saying that. Not exactly.\""}],"why":"Naming both as non-negotiable tests whether she'll respect that, or push again."},{"prompt":"A week later she says: \"Your friend Rohit's birthday clashes with my cousin's function. You're coming to the function, right?\"","options":[{"text":"\"I'll come to the function and see Rohit another day.\"","then":"She nods, pleased. \"Okay, good. That works.\"","best":true},{"text":"\"I'll skip Rohit's. Family functions matter more anyway.\"","then":"She smiles, but the earlier boundary quietly starts slipping."},{"text":"\"I already promised Rohit, so I'll skip the function.\"","then":"She looks hurt. \"So my family matters less, then?\""},{"text":"\"Can't you go to the function without me this once?\"","then":"She looks taken aback. \"I'd rather we went together, honestly.\""}],"why":"Choosing what's fair this time, not proving a point, keeps both sides real."},{"prompt":"A few days later Kavya says: \"Fine. I trust you. But if they ever say something bad about me, that's on you.\"","options":[{"text":"\"That's fair. And if you ever ask me to cut them off again, I'll say no.\"","then":"She pauses, then nods slowly. \"Okay. Deal, I suppose.\"","best":true},{"text":"\"They really wouldn't ever do that, so please don't worry about it at all.\"","then":"She shrugs. \"We'll see, I guess.\""},{"text":"\"Sure, whatever keeps the peace between us.\"","then":"She nods, though the actual boundary was never really named."},{"text":"\"You're being a bit much about this, honestly.\"","then":"She stiffens. \"I don't think I'm the one being unreasonable.\""}],"why":"Naming the boundary as one you'll hold again, not just this once, makes it real."}],"relearn":"A good partner doesn't ask you to cut off your friends; hold that boundary."},
  {"id":"cb-954","cat":"choosing-well","type":"role-play","persona":"any","source":"ask the real questions","hook":"Your families have arranged a meeting with Farah, and everyone's waiting for a quick answer.","setup":"The families step out to give you both a few minutes alone.","steps":[{"prompt":"Farah says: \"So, honestly, what do you want to know?\"","options":[{"text":"\"How you handle disagreements, and what you want from life.\"","then":"She looks surprised, then thoughtful. \"Nobody's asked me that yet.\"","best":true},{"text":"\"What kind of things do you enjoy doing?\"","then":"She lists a few hobbies easily, and the talk stays comfortable and light."},{"text":"\"Are you really okay with how our families are running this?\"","then":"She nods slowly. \"I guess so.\" Neither of you says much more."},{"text":"\"Are you okay with how our parents run these things?\"","then":"She shrugs. \"It's normal, isn't it?\" The real questions stay unasked."}],"why":"Values and conflict-style tell you far more than hobbies or going along with it."},{"prompt":"Farah adds: \"Can I share something? I go quiet when people disagree. What about you?\"","options":[{"text":"\"I'd rather talk it through. What about your career goals?\"","then":"She brightens slightly. \"I want to keep working after marriage. Okay with you?\"","best":true},{"text":"\"That's okay. I'm sure we'd manage fine somehow.\"","then":"She nods, though neither of you has said how you'd manage."},{"text":"\"I don't really fight, so it won't be an issue.\"","then":"She looks unconvinced. \"Everyone disagrees eventually, though.\""},{"text":"\"Let's not worry about that part yet. It's only our second meeting.\"","then":"She nods, and the conversation drifts back to safer topics."}],"why":"Naming your own style and asking about her goals keeps the talk mutual and real."},{"prompt":"She asks: \"Can I ask something honest? Are you doing this mainly for your parents?\"","options":[{"text":"\"No. I want this to be my choice too, so I'm asking.\"","then":"She relaxes visibly. \"Good. Me too, honestly. This actually helps.\"","best":true},{"text":"\"A bit, but I'm sure it'll work out either way.\"","then":"She looks unsettled, unsure how seriously to take this conversation now."},{"text":"\"Everyone does it for their parents, don't they?\"","then":"She frowns slightly. \"I was hoping it was more than that.\""},{"text":"\"Let's just see what our families decide.\"","then":"She nods, though something in her expression closes off."}],"why":"Naming this as your own choice, not just family's, is what makes the questions matter."}],"relearn":"You can ask about values, goals and conflict-style before deciding; that's how you read real fit."},
  {"id":"cb-955","cat":"choosing-well","type":"role-play","persona":"any","source":"ask for time","hook":"Right after meeting Aakash once, your Bua wants a yes before he 'gets away'.","setup":"She corners you the moment the guests leave.","steps":[{"prompt":"Bua says: \"He's a good catch, beta. Say yes now, before someone else does.\"","options":[{"text":"\"It's a lifelong choice. I want to talk to him properly first.\"","then":"She sighs. \"Time, time. Fine, but don't take too long.\"","best":true},{"text":"\"He did seem nice. I suppose I could say yes.\"","then":"She beams. \"Wonderful! I'll tell them right away.\""},{"text":"\"Fine, if you all think he's that good, I'll say yes right now.\"","then":"She claps her hands, delighted, and reaches for her phone."},{"text":"\"Why is everyone in such a hurry about this?\"","then":"She waves a hand. \"Good boys don't stay available long, beta.\""}],"why":"Naming it as a lifelong choice earns time a quick 'good catch' doesn't deserve to skip."},{"prompt":"Before anyone calls, your cousin Simran says: \"I said yes after one meeting, and I'm happy.\"","options":[{"text":"\"I'm glad that worked for you. I still want my own process.\"","then":"Simran shrugs. \"Fair enough. Everyone's different, I suppose.\"","best":true},{"text":"\"Maybe I really am just overthinking this, like you keep saying.\"","then":"Simran nods. \"Probably. It worked out fine for me.\""},{"text":"\"That's different, you just got lucky, honestly.\"","then":"Simran looks a little offended. \"Or maybe I just knew what I wanted.\""},{"text":"\"I guess if it worked for you, it'll work for me too.\"","then":"Bua brightens. \"See? Even Simran agrees. Say yes.\""}],"why":"Someone else's timeline being right for them doesn't make it the right one for you."},{"prompt":"Bua presses: \"What is there to even talk about? You liked him, he liked you.\"","options":[{"text":"\"Whether our values and goals really match.\"","then":"She pauses. \"That is... a fair point, actually.\"","best":true},{"text":"\"I just want to be sure, that's all.\"","then":"She nods, but presses again: \"Sure of what, exactly?\""},{"text":"\"I don't know. I just feel rushed by all this.\"","then":"She softens slightly. \"Alright, alright, no need to feel rushed.\""},{"text":"\"Maybe you're right. There's nothing more to know.\"","then":"She reaches for her phone, then stops: \"But you should be sure.\""}],"why":"Naming what the time is actually for makes it a real request, not just stalling."},{"prompt":"Bua asks: \"Fine. So how long, exactly, before you decide?\"","options":[{"text":"\"A couple of weeks, with a few honest conversations with him.\"","then":"She nods slowly. \"Alright. I'll tell them two weeks, then.\"","best":true},{"text":"\"Not too long, honestly, I just need a little more time than this.\"","then":"She looks unconvinced. \"That's not really an answer, beta.\""},{"text":"\"However long it takes, I suppose, honestly.\"","then":"She frowns. \"That could be forever. Give me something firmer.\""},{"text":"\"Let's just say one week to keep everyone happy.\"","then":"She agrees, though one week barely changes anything."}],"why":"A specific timeframe with a real purpose is easy for everyone to actually respect."}],"relearn":"You're allowed to ask for time and real conversations before choosing; never be rushed."},
  {"id":"cb-956","cat":"choosing-well","type":"role-play","persona":"any","source":"name the put-down","hook":"On your third date, Yash jokes, again, that you're 'hopeless' at your job.","setup":"He laughs, waiting for you to laugh too.","steps":[{"prompt":"Yash grins: \"Relax, I'm kidding. You know I'm kidding, right?\"","options":[{"text":"\"Those jokes put me down, and I don't like it.\"","then":"He blinks, caught off guard. \"Oh. I didn't realise it landed like that.\"","best":true},{"text":"\"Haha, yeah, I guess I am a bit useless.\"","then":"He laughs harder, pleased, and does it again a minute later."},{"text":"\"You're kind of mean, you know that?\"","then":"He shrugs. \"It's just banter, don't take it so seriously.\""},{"text":"\"Ha, sure, whatever you say. You're the funny one.\"","then":"He grins and files it away as something he can keep doing."}],"why":"Naming the pattern, not laughing along, is what actually changes what happens next."},{"prompt":"Later, Yash says: \"Was that joke too much? I can drop the work jokes.\"","options":[{"text":"\"Thanks. I just want us building each other up, not the opposite.\"","then":"He nods slowly. \"Fair. I'll actually watch that, then.\"","best":true},{"text":"\"It's fine, honestly, I probably overreacted about the whole thing anyway.\"","then":"He relaxes, and the earlier joke stops feeling like it mattered."},{"text":"\"You should already know not to say stuff like that.\"","then":"He frowns. \"Alright, no need to pile on now.\""},{"text":"\"Whatever, let's just order food.\"","then":"He shrugs and changes the subject, nothing really settled."}],"why":"Naming the standard you want, not just accepting the apology, makes it mean something."},{"prompt":"Later he slips again: \"Kidding aside, you really are hopeless with directions, though.\"","options":[{"text":"\"That's the pattern again. I need it to stop.\"","then":"He looks genuinely stung this time. \"You're right. I'm sorry, really.\"","best":true},{"text":"\"You said you'd stop doing that, remember?\"","then":"He shrugs. \"It's a different joke, though.\""},{"text":"\"I guess old habits die hard, huh.\"","then":"He laughs, relieved, and the pattern quietly continues."},{"text":"\"Maybe this isn't going to work out.\"","then":"He looks startled. \"Wait, over a joke? Come on.\""}],"why":"Naming the repeat plainly tests whether the first conversation actually meant anything."}],"relearn":"You can name a put-down for what it is; a partner who respects you doesn't belittle you for laughs."},
  {"id":"cb-957","cat":"choosing-well","type":"role-play","persona":"any","source":"wiser lens","hook":"Your friend Ayesha is gushing about Aryan, mostly his car and his family's status.","setup":"She scrolls through his photos, starry-eyed.","steps":[{"prompt":"Ayesha says: \"Look at him. And his family owns like three properties!\"","options":[{"text":"\"He looks great, sure. But how does he actually treat you?\"","then":"She pauses mid-scroll. \"Treat me? Fine, I guess. We've barely talked.\"","best":true},{"text":"\"Wow, that's impressive, good for you.\"","then":"She grins wider. \"Right? I can't believe my luck.\""},{"text":"\"Yeah, they're gorgeous and rich, what else even matters?\"","then":"She laughs. \"Exactly! That's what I keep saying!\""},{"text":"\"You could probably do better, honestly.\"","then":"She frowns. \"Better how? He's basically perfect on paper.\""}],"why":"Asking how he treats her redirects from status to what actually matters long-term."},{"prompt":"She admits: \"Okay, we've mostly just talked about his car and job, if I'm honest.\"","options":[{"text":"\"Maybe find out what he actually values next, not just what he has.\"","then":"She considers this. \"Huh. I don't actually know that about him yet.\"","best":true},{"text":"\"That's okay. I'm sure the two of us would somehow manage fine either way.\"","then":"She nods, relieved, and goes back to scrolling through photos."},{"text":"\"As long as he's generous, that's a good sign.\"","then":"She brightens. \"He did pay for everything on the first date.\""},{"text":"\"You'll figure the rest out eventually.\"","then":"She shrugs. \"Sure, I guess it'll sort itself out.\""}],"why":"Values and character take longer to surface than looks or spending; ask early anyway."},{"prompt":"Ayesha asks: \"Okay, so what should I actually ask him next time?\"","options":[{"text":"\"What matters to him, and how he handles a disagreement.\"","then":"She nods slowly. \"Okay. I'm actually a little nervous to ask that.\"","best":true},{"text":"\"Ask about his future plans, especially career-wise.\"","then":"She nods, though that's still closer to status than to values."},{"text":"\"You don't need to ask anything, just enjoy it.\"","then":"She relaxes, back to admiring the photos instead."},{"text":"\"Ask if his family will approve of you.\"","then":"She looks worried. \"Oh no, I hadn't even thought of that.\""}],"why":"Asking about values and conflict-handling reveals who he actually is."},{"prompt":"A week later, Ayesha says: \"Aryan told me his family's reputation matters most to him.\"","options":[{"text":"\"What did you make of that? Does it line up with what matters to you?\"","then":"She pauses. \"Honestly, I'm not totally sure it does.\"","best":true},{"text":"\"That sounds fine to me, honestly, reputation matters to most families anyway.\"","then":"She nods, relieved, and doesn't examine it further."},{"text":"\"At least he's honest about it, that's something.\"","then":"She shrugs. \"True, I guess that's something.\""},{"text":"\"Maybe don't read too much into one answer.\"","then":"She nods and goes back to planning the next date."}],"why":"Checking his answer against your own values is what the question was for."}],"relearn":"Encourage choosing on values and compatibility, not looks and status alone."},
  {"id":"cb-958","cat":"choosing-well","type":"role-play","persona":"Sneha","source":"don't lower standards","hook":"Your Masi says you should 'adjust your expectations' since you're getting older.","setup":"She says it kindly, but firmly.","steps":[{"prompt":"Masi says: \"At your age, beta, you can't be so choosy anymore.\"","options":[{"text":"\"My age doesn't change what I need. I'd rather choose well than quickly.\"","then":"She purses her lips. \"Choose well, choose well, meanwhile the years pass.\"","best":true},{"text":"\"You're right, maybe I should lower my expectations before it's too late.\"","then":"She nods approvingly. \"Finally, some sense. I'll find you some good matches.\""},{"text":"\"I'm not choosy. I just haven't met the right person.\"","then":"She sighs. \"That's what choosy people always say.\""},{"text":"\"Can we talk about something else, please?\"","then":"She shrugs. \"Fine, but the clock doesn't stop for anyone.\""}],"why":"Naming your standards as unchanged by age, plainly, resists being talked out of them."},{"prompt":"Your mother adds gently: \"She's just worried, beta. We all are, a little.\"","options":[{"text":"\"I know. I'm not against marrying. I just want it right, not rushed.\"","then":"Your mother nods slowly. \"That's fair. I worry more than I should, maybe.\"","best":true},{"text":"\"I understand the worry, and honestly maybe I am taking a bit too long.\"","then":"Masi jumps in. \"See, even she agrees. Let's not waste more time then.\""},{"text":"\"You shouldn't worry about things that aren't your business.\"","then":"Your mother looks hurt. \"It is my business. I'm your mother.\""},{"text":"\"Fine, set me up with whoever you think is good.\"","then":"Masi starts listing names, then asks what kind of person you'd even say yes to."}],"why":"Naming both truths, wanting it and wanting it right, answers the worry honestly."},{"prompt":"Masi asks, more pointed now: \"So what exactly are you waiting for, then?\"","options":[{"text":"\"Someone whose values actually match mine. That's worth the time.\"","then":"She's quiet for a second. \"That is a fair thing to wait for, I suppose.\"","best":true},{"text":"\"I suppose I'm waiting for someone who's basically perfect in every way.\"","then":"She scoffs. \"Nobody's perfect. You'll wait forever at that rate.\""},{"text":"\"I don't really know, honestly.\"","then":"She shakes her head. \"That's exactly the problem, beta.\""},{"text":"\"Whatever comes along next, I suppose.\"","then":"She brightens. \"Good, because I have someone in mind already.\""}],"why":"Naming values, not perfection, as the standard makes the wait sound reasonable."},{"prompt":"A week later, Masi calls again: \"I found someone perfect. When can you meet him?\"","options":[{"text":"\"I'm open to meeting him, on my own timeline, not from pressure.\"","then":"She laughs. \"Fine, fine, your timeline. I'll send his details anyway.\"","best":true},{"text":"\"Fine, I suppose I could meet him soon, just to make everyone happy.\"","then":"She's delighted and starts planning the meeting immediately."},{"text":"\"I already told you I'm not in a hurry.\"","then":"She sighs. \"I know, I know. I'm just trying to help.\""},{"text":"\"Tell her I said no to anyone for now.\"","then":"Your mother looks caught in the middle, unsure what to say."}],"why":"Staying open on your own terms, not from pressure, keeps the choice genuinely yours."}],"relearn":"Your age is not a reason to lower your standards; choosing well stays worth it at any age."},
  {"id":"cb-990","type":"strike-rewrite","persona":"any","source":"not a status upgrade","hook":"\"Getting married is the next box to tick after a job and a flat.\"","myth":{"un":"Marriage is just the next box to tick after a job and a flat.","re":"Commitment is a freely chosen partnership with a person, not a milestone you collect to look settled.","why":"You marry a person, not a checklist."},"relearn":"Commitment is choosing a person freely, not ticking the next life box.","cat":"commitment-clearly"},
  {"id":"cb-991","type":"strike-rewrite","persona":"any","source":"loneliness isn't cured by vows","hook":"\"Once I'm married I won't feel lonely anymore.\"","myth":{"un":"Once I'm married I won't feel lonely anymore.","re":"A partnership is built by two whole people; it eases loneliness only when you're already at home with yourself.","why":"A wedding doesn't fill an inner gap."},"relearn":"Marriage isn't a cure for loneliness; a partnership is built by two whole people.","cat":"commitment-clearly"},
  {"id":"cb-992","type":"strike-rewrite","persona":"Sneha","source":"no expiry date","hook":"\"If you're not married by thirty, your chance is basically gone.\"","myth":{"un":"If you're not married by thirty, your chance is basically gone.","re":"There's no expiry on choosing well; a thoughtful late choice beats a rushed early one.","why":"A good choice has no deadline."},"relearn":"Your timeline is your own; there's no expiry date on choosing a partner well.","cat":"commitment-clearly"},
  {"id":"cb-993","type":"strike-rewrite","persona":"any","source":"big talks before, not after","hook":"\"Sort the wedding first; we'll figure out money and kids once we're married.\"","myth":{"un":"Figure out money and children only after the wedding.","re":"Talk the big topics through honestly before you commit, not after the band is booked.","why":"It's far harder to align once you're already in."},"relearn":"Talk through the big topics honestly before you commit, not after.","cat":"commitment-clearly"},
  {"id":"cb-994","type":"strike-rewrite","persona":"any","source":"engagement is not a trap","hook":"\"We're engaged, so backing out now would be unthinkable, whatever I find.\"","myth":{"un":"Once engaged, backing out is unthinkable whatever you find.","re":"An engagement is a plan, not a cage; a clear no before the wedding spares two whole lives.","why":"Calling it off beats committing against your judgement."},"relearn":"An engagement isn't a cage; you can still say no if it isn't right.","cat":"commitment-clearly"},
  {"id":"cb-995","type":"strike-rewrite","persona":"any","source":"drift isn't a decision","hook":"\"We've been together years, so we may as well just get married.\"","myth":{"un":"We've been together years, so we may as well just get married.","re":"Years together is momentum, not a reason; commit because you actively choose this person and this work.","why":"Drifting in isn't the same as choosing."},"relearn":"Commit because you genuinely choose the person, not because you've drifted along.","cat":"commitment-clearly"},
  {"id":"cb-996","type":"strike-rewrite","persona":"any","source":"not to fix a rocky patch","hook":"\"We keep fighting, but marriage will make us take it seriously and settle down.\"","myth":{"un":"Marriage will make a fighting couple settle down.","re":"Commitment amplifies what's already there; an unresolved pattern usually gets louder, not quieter.","why":"A vow doesn't repair what you haven't."},"relearn":"Marriage isn't a fix for problems; commitment amplifies what's already there.","cat":"commitment-clearly"},
  {"id":"cb-997","type":"strike-rewrite","persona":"any","source":"the day vs the years","hook":"\"Pour everything into the perfect wedding; that's what the marriage is really about.\"","myth":{"un":"The perfect wedding is what the marriage is really about.","re":"A wedding is a day; the partnership is the years of work that follow it.","why":"The guests leave; the two of you stay."},"relearn":"A wedding is a day; the partnership is the ongoing work that follows.","cat":"commitment-clearly"},
  {"id":"cb-998","type":"strike-rewrite","persona":"any","source":"reasons matter","hook":"\"It doesn't matter why you marry, only that you do it in time.\"","myth":{"un":"It doesn't matter why you marry, only that you do it in time.","re":"Why you commit matters most: choosing the person is sound; fear of being alone or of 'log kya kahenge' is shaky.","why":"A shaky reason makes a shaky start."},"relearn":"Sound reasons to commit are choosing the person; social pressure and fear are shaky.","cat":"commitment-clearly"},
  {"id":"cb-999","type":"strike-rewrite","persona":"Sneha","source":"single is whole","hook":"\"You're incomplete until you're married.\"","myth":{"un":"You're incomplete until you're married.","re":"You're already a whole person; a partnership adds to a full life, it doesn't complete a half one.","why":"Two whole people make the strongest team."},"relearn":"You're already whole; a partnership adds to a full life, it doesn't complete you.","cat":"commitment-clearly"},
  {"id":"cb-1000","type":"strike-rewrite","persona":"any","source":"cold feet vs core doubt","hook":"\"Everyone has cold feet, so ignore every doubt and just go through with it.\"","myth":{"un":"Ignore every doubt and just go through with the wedding.","re":"Ordinary nerves pass; a persistent doubt about respect, safety or core values is worth pausing for.","why":"Some doubts are signals, not just nerves."},"relearn":"Some nerves are normal, but persistent doubts about core respect or values are worth heeding.","cat":"commitment-clearly"},
  {"id":"cb-1001","type":"strike-rewrite","persona":"any","source":"living the same life","hook":"\"A wedding proves how much you love each other.\"","myth":{"un":"A wedding proves how much you love each other.","re":"How you treat each other on an ordinary Tuesday shows the love far more than one big celebration.","why":"Love is shown in the daily, not the spectacle."},"relearn":"A wedding doesn't prove love; how you treat each other day to day does.","cat":"commitment-clearly"},
  {"id":"cb-1002","type":"strike-rewrite","persona":"Sneha","source":"happily unmarried","hook":"\"Choosing not to marry means you'll regret it and end up alone.\"","myth":{"un":"Choosing not to marry means regret and ending up alone.","re":"Not marrying is a full, valid life; a chosen single life isn't a failed married one.","why":"A whole life takes many shapes."},"relearn":"Not marrying is an equally valid path; a chosen single life is a full one.","cat":"commitment-clearly"},
  {"id":"cb-1003","type":"strike-rewrite","persona":"any","source":"a number isn't a reason","hook":"\"You're the right age, so any decent proposal is one you should accept.\"","myth":{"un":"You're the right age, so accept any decent proposal.","re":"Age is not a reason to commit; you commit when you actually choose this particular person.","why":"The right age and the right person aren't the same thing."},"relearn":"Commit when you choose the person, not because the calendar says it's time.","cat":"commitment-clearly"},
  {"id":"cb-1004","type":"strike-rewrite","persona":"Nisha","source":"having kids isn't the point","hook":"\"Just marry; you can sort out whether you both want children later.\"","myth":{"un":"Marry now and sort out whether you both want children later.","re":"Whether and when to have children is a big-topic talk to have honestly before you commit, not assume.","why":"It's too big to leave to chance."},"relearn":"Talk through whether and when to have children before you commit; don't assume.","cat":"commitment-clearly"},
  {"id":"cb-1005","type":"strike-rewrite","persona":"any","source":"theirs not yours","hook":"\"Your parents waited long enough; you owe it to them to marry now.\"","myth":{"un":"You owe it to your parents to marry now.","re":"Their wishes can be heard with love, but the choice and its timing are yours to make freely.","why":"You're the one who lives the marriage."},"relearn":"Hear family with love, but the choice to commit and its timing are freely yours.","cat":"commitment-clearly"},
  {"id":"cb-1006","type":"strike-rewrite","persona":"any","source":"clarity is the goal","hook":"\"A real commitment should feel one hundred percent certain, with zero questions left.\"","myth":{"un":"A real commitment feels totally certain with zero questions left.","re":"Clear-eyed commitment means you've talked the big things through and chosen freely, not that you feel no nerves at all.","why":"Clarity isn't the absence of all nerves."},"relearn":"Eyes-open commitment is choosing freely after the big talks, not feeling zero nerves.","cat":"commitment-clearly"},
  {"id":"cb-1007","cat":"commitment-clearly","type":"branch","persona":"any","source":"the ultimatum","hook":"Your partner says marry within two months, or the relationship is over.","steps":[{"prompt":"He lays out the ultimatum over dinner. What do you do?","options":[{"text":"Say clearly you need real time, not a deadline","then":"He's frustrated, but the words land. He goes quiet, thinking.","best":true},{"text":"Agree to the two months to keep him from leaving","then":"You feel a knot of panic instead of relief."},{"text":"Say it's over right then, to beat him to it","then":"You both go quiet, and neither of you says what you actually meant."},{"text":"Ask for a shorter deadline instead, as a compromise","then":"You've traded one clock for a smaller one, still not your own."}],"why":"Naming your need for real time answers the ultimatum without being rushed by it."},{"prompt":"The next day, he calls it a fair ask, since you've been together a while. What do you say?","options":[{"text":"That time together doesn't change what a big decision needs","then":"He goes quiet, and admits he hadn't thought of it that way.","best":true},{"text":"Agree the timeline is fair, since he has a point","then":"You start counting down a clock you never actually chose."},{"text":"Get angry that he's pushing you again after you asked for time","then":"The fight ends the conversation, without answering the real question."},{"text":"Say you'll try to speed up your own feelings","then":"You spend the next weeks chasing a feeling instead of examining it."}],"why":"Time together doesn't shrink what a big decision actually needs."},{"prompt":"A friend asks if you're going to make the deadline. What do you tell her?","options":[{"text":"That you won't let a deadline decide this for you","then":"She nods slowly, then asks what you actually want, deadline aside.","best":true},{"text":"That you probably will, just to keep the peace","then":"She looks worried, though she doesn't say so directly."},{"text":"That you're avoiding thinking about it entirely for now","then":"The deadline keeps ticking while you avoid the actual question."},{"text":"That he's right to expect an answer by now","then":"You talk yourself into his timeline instead of finding your own."}],"why":"Saying it plainly, even to a friend, keeps the deadline from quietly becoming your answer."},{"prompt":"As the two months near their end, what do you do?","options":[{"text":"Tell him plainly you'll decide when you're ready","then":"It's a hard conversation, and for the first time it feels honest.","best":true},{"text":"Say yes on the deadline, relieved to have it over with","then":"The relief doesn't last, and the doubts come back after."},{"text":"Let the deadline pass without saying anything","then":"The silence does the deciding, instead of either of you."},{"text":"Ask him to extend it by a few more weeks","then":"You've bought time, without actually claiming it as your own."}],"why":"A commitment made on your own timeline, not his clock, is the only one that's genuinely yours."}],"debrief":"A commitment made under a deadline isn't a free choice; you're allowed to need real time.","relearn":"Commit from free choice, not under an ultimatum or a clock."},
  {"id":"cb-1008","cat":"commitment-clearly","type":"branch","persona":"any","source":"the avoided money talk","hook":"The wedding date is set, and you've still never talked about how you'll handle money together.","steps":[{"prompt":"You're choosing wedding cards when joint accounts come up in passing. What do you do?","options":[{"text":"Pause the cards and actually talk it through properly","then":"It takes twenty minutes, and you both learn something new.","best":true},{"text":"Say you'll sort it out after the wedding","then":"You go back to the cards, relieved to skip it for now."},{"text":"Assume you'll just keep managing money as you always have","then":"Neither of you says what 'as you always have' actually means to the other."},{"text":"Let your parents' old arrangement be the default plan","then":"You copy a pattern neither of you actually chose together."}],"why":"Pausing to actually talk beats letting the topic slip past you again."},{"prompt":"A few days later, money comes up again over dinner. What do you lead with?","options":[{"text":"Asking how he thinks about saving, spending and shared costs","then":"He answers slowly, working it out loud for the first time himself.","best":true},{"text":"Telling him how you think it should work","then":"He agrees quickly, and you're not sure he means it."},{"text":"Suggesting you keep it vague, since love shouldn't be about money","then":"The vagueness feels easy tonight, and unresolved tomorrow."},{"text":"Asking what his family expects, rather than what he wants","then":"You learn his family's expectations, and still not his own."}],"why":"A curious question about his own thinking gets you a real answer, not just agreement."},{"prompt":"You land on a rough plan together. What do you do with it?","options":[{"text":"Agree to revisit it honestly once you're married","then":"You both feel more ready, having said the real numbers out loud.","best":true},{"text":"Treat the one talk as fully settled for good","then":"You relax, though a few real questions never quite got asked."},{"text":"Leave the details loose, trusting it'll work out","then":"The loose ends wait quietly for the first real bill to arrive."},{"text":"Let one of you take charge of it entirely","then":"It's simpler for now, and the other stays out of a shared decision."}],"why":"Treating money as an ongoing talk, not a single box ticked, is what eyes-open commitment means."}],"debrief":"Money is one of the big topics to talk through honestly before, not after, you commit.","relearn":"Talk through money honestly before you commit, not after."},
  {"id":"cb-1009","cat":"commitment-clearly","type":"branch","persona":"Sneha","source":"the relatives' chorus","hook":"At every function, a different relative has 'just the right boy' waiting to be introduced.","steps":[{"prompt":"Your chachi says she's already told a boy's family about you. What do you do?","options":[{"text":"Thank her warmly, and say you'll decide who you meet","then":"She's a little deflated, but nods and backs off for now.","best":true},{"text":"Let her go ahead, since saying no feels like too much effort","then":"A meeting gets arranged before you've agreed to anything."},{"text":"Get irritated and say you're done with the whole subject","then":"She looks hurt, and avoids you for the rest of the function."},{"text":"Agree just to end the conversation quickly","then":"She takes 'agree' as a green light to move fast."}],"why":"Warmth plus a clear line lets you keep the relationship without handing over the decision."},{"prompt":"At the next function, a second relative brings a different name entirely. What do you do?","options":[{"text":"Stay warm, and repeat that you're choosing your own pace","then":"He shrugs good naturedly and moves on to the snacks.","best":true},{"text":"Compare the two names out loud to seem interested","then":"Word spreads that you're 'considering options', which isn't quite true."},{"text":"Avoid that corner of the room for the rest of the evening","then":"You dodge the conversation, and the introductions keep coming anyway."},{"text":"Say yes to meeting both, just to keep everyone happy","then":"Your calendar fills with meetings you didn't actually choose."}],"why":"Staying consistent, function after function, is what actually holds your pace."},{"prompt":"Your mother privately asks if the constant pushing is getting to you. What do you tell her?","options":[{"text":"That it is, and you'd like her help holding the line","then":"She looks relieved you said it, and agrees to help field it.","best":true},{"text":"That it's fine, brushing off how it actually feels","then":"She takes your word for it, and the pressure keeps landing on you alone."},{"text":"That maybe you should just accept a match to end it","then":"She hears something you don't quite mean, and starts hoping."},{"text":"That she should tell everyone to stop, angrily","then":"She agrees, but the ask lands harsher than you meant it to."}],"why":"Asking for help holding the line means you're not carrying the pressure alone."},{"prompt":"By the next big family gathering, what's changed in how you handle it?","options":[{"text":"You answer warmly and firmly, every time","then":"The introductions slowly taper off, since nothing rattles you.","best":true},{"text":"You start skipping gatherings to avoid the topic","then":"You dodge the pressure, and miss the people you'd actually enjoy."},{"text":"You agree to 'just one meeting' to buy some peace","then":"One meeting quietly becomes the next expectation."},{"text":"You let the exhaustion show and stop responding at all","then":"The silence gets read as an opening, not a boundary."}],"why":"Steady warmth, held every time, is what finally slows the pushing down."}],"debrief":"Social pressure about being single is relentless; keeping your timeline yours is the wise move.","relearn":"Hold your own timeline; don't commit just to quiet the 'why single' questions."},
  {"id":"cb-1010","cat":"commitment-clearly","type":"branch","persona":"any","source":"fear of being alone","hook":"You're unsure about Aakash, but the thought of staying single scares you more than he does.","steps":[{"prompt":"He asks, gently, if you're ready to take things further. What do you do?","options":[{"text":"Notice the fear behind your 'yes' and pause","then":"You realise you've been answering the fear, not the actual question.","best":true},{"text":"Say yes quickly, before you can talk yourself out of it","then":"It feels settled for tonight, and unsettled again by morning."},{"text":"Say yes and decide the doubts will probably fade","then":"The doubts stay exactly where they were, just quieter."},{"text":"Avoid answering directly and change the subject","then":"The question waits, unanswered, for the next time he asks."}],"why":"Noticing what's actually driving your 'yes' is the first step to answering honestly."},{"prompt":"A friend asks what you actually like about him, specifically. What do you say?","options":[{"text":"That you're not fully sure yet, and you want to be","then":"She says that's worth figuring out before anything else.","best":true},{"text":"That he's better than being alone","then":"Hearing it out loud, you notice that isn't really an answer."},{"text":"That your family would be relieved","then":"You describe everyone's relief except your own."},{"text":"That it doesn't matter, since the timing feels right","then":"You skip the actual question again."}],"why":"Naming the uncertainty out loud is more honest than dressing it up as something else."},{"prompt":"He brings up moving forward again, patiently. What do you do?","options":[{"text":"Ask for real time to be sure this is about him, not the fear","then":"He's a little disappointed, and says he'd rather you were sure.","best":true},{"text":"Commit now, since waiting feels like losing him","then":"You gain an answer, and lose the chance to actually test it."},{"text":"Tell him you're scared of being alone, and leave it there","then":"He's kind about it, and the real question underneath stays open."},{"text":"Let him decide the timeline, since you can't seem to","then":"The choice moves forward without ever really becoming yours."}],"why":"Asking for time tests whether this is really about him, not just about not being alone."}],"debrief":"Fear of being alone is a shaky basis; a free choice of the person is the sound one.","relearn":"Fear of being alone is a shaky reason to commit; choose the person freely."},
  {"id":"cb-1011","cat":"commitment-clearly","type":"branch","persona":"any","source":"settling-down peer pressure","hook":"Three friends got engaged this year, and you feel like you're falling behind.","steps":[{"prompt":"A friend's engagement post pops up again on your phone. What do you do?","options":[{"text":"Notice the feeling, and ask yourself what you actually want","then":"You realise it's comparison talking, not a clear answer about your life.","best":true},{"text":"Message your partner to ask if you should speed things up","then":"He's confused, since nothing between you has actually changed."},{"text":"Scroll past quickly and try not to think about it","then":"The feeling doesn't leave. It just waits for the next post."},{"text":"Like the post and tell yourself you're happy for her","then":"You are, and the other feeling sits there too, unexamined."}],"why":"Naming the comparison for what it is keeps it from quietly becoming your answer."},{"prompt":"At a friend's engagement party, someone asks when you'll be next. What do you say?","options":[{"text":"That you're not choosing on anyone else's timeline","then":"She nods, and admits she sometimes wonders the same about her own pace.","best":true},{"text":"That you'll probably catch up soon","then":"You hear yourself promising a timeline you don't actually feel."},{"text":"That your relationship isn't as serious as theirs","then":"You compare your relationship instead of just describing it."},{"text":"That weddings are everywhere lately, dodging the question","then":"The question waits for you at the next party too."}],"why":"Saying it plainly protects your pace from becoming a race."},{"prompt":"Back home, you think about what you actually want next. What guides your answer?","options":[{"text":"Your own clarity about this relationship","then":"It's quieter than the comparison, and it feels more like yours.","best":true},{"text":"How many friends have already gotten there first","then":"You measure your life by a scoreboard that was never really the point."},{"text":"How it would look to everyone else by next year","then":"You picture an audience instead of picturing your actual life."},{"text":"Whatever decision would stop the comparing fastest","then":"The comparing quiets for a moment, then returns with the next post."}],"why":"Your own clarity about the person is what a sound commitment actually rests on."}],"debrief":"'Everyone my age is settling down' is a shaky reason; your clarity about the person is sound.","relearn":"Don't drift into commitment to match friends; choose on your own clarity."},
  {"id":"cb-1011b","cat":"commitment-clearly","type":"branch","persona":"any","source":"the big-five checklist","hook":"You're close to committing, but you've never discussed faith, or where you'd actually live.","steps":[{"prompt":"Wedding planning starts, and religious practice comes up for the first time. What do you do?","options":[{"text":"Ask openly how he practises now, and what he'd want later","then":"He answers honestly, some of it surprising you both.","best":true},{"text":"Assume you'll each keep doing your own thing quietly","then":"You both nod, without checking if that's actually workable."},{"text":"Say your way is obviously how it'll be","then":"He goes along with it, though you don't know if he means it."},{"text":"Skip it entirely, since religion feels too big to bring up right now","then":"The topic stays exactly where it was: unspoken."}],"why":"An open, curious question about faith gets you real answers instead of assumptions."},{"prompt":"Next, you realise you've never discussed where you'll actually live. What do you do?","options":[{"text":"Ask whether he pictures living with his parents or apart","then":"He admits he'd assumed you already knew the answer.","best":true},{"text":"Assume it's obviously with his family, as is common","then":"You build a picture neither of you has actually confirmed."},{"text":"Say you'll decide once you're married and see how it goes","then":"You commit to a plan with a blank where the answer should be."},{"text":"Let your own family's preference quietly decide it","then":"One family's comfort settles a question that's really about you two."}],"why":"Asking directly about where you'll live surfaces a plan you'd otherwise both just assume."},{"prompt":"A relative asks if you've 'sorted the practical things'. What do you say?","options":[{"text":"That you're working through them honestly, one by one","then":"She seems satisfied, and you realise you actually mean it.","best":true},{"text":"Yes, to avoid a longer conversation","then":"A few of the practical things are still quietly unsorted."},{"text":"That those things usually sort themselves out after marriage","then":"You repeat a comforting idea neither of you has tested."},{"text":"That it's private, and change the subject","then":"The question is dodged, though it wasn't really unfair to ask."}],"why":"Saying honestly where things stand keeps the big talks real, not just performed."},{"prompt":"As the wedding date nears, what do you do about these conversations?","options":[{"text":"Note where you still don't fully agree, and keep talking","then":"Naming the gaps honestly feels steadier than pretending they've closed.","best":true},{"text":"Decide it's close enough and move on to the wedding","then":"The gaps stay open, folded under the wedding's momentum."},{"text":"Let the unresolved parts wait until you're living it","then":"You commit to sorting it out later, with no clearer plan than before."},{"text":"Assume love will smooth over whatever's left","then":"You lean on hope for the parts that actually needed a plan."}],"why":"Naming what's still unresolved keeps the commitment honest instead of just comfortable."}],"debrief":"Money, children, roles, values and home are the big talks to have honestly before you commit.","relearn":"Talk the big topics through honestly before you commit, not after."},
  {"id":"cb-1012","cat":"commitment-clearly","type":"branch","persona":"any","source":"a persistent gut doubt","hook":"You're engaged to Suresh, but a quiet doubt about how he treats you in front of others won't settle.","steps":[{"prompt":"At a dinner with friends, he brushes off your opinion again, lightly. What do you do?","options":[{"text":"Notice this as the same doubt returning, not new nerves","then":"You realise this has actually happened several times before.","best":true},{"text":"Let it go, since it's a small thing at a nice dinner","then":"You file it away as nothing, the same as every time before."},{"text":"Snap back at him in front of everyone","then":"The table goes tense, and the actual pattern goes unnamed."},{"text":"Decide you're being far too oversensitive before a big wedding","then":"You talk yourself out of noticing what you actually noticed."}],"why":"Recognising it as a returning pattern, not nerves, is what lets you actually weigh it."},{"prompt":"Later, alone, you bring it up carefully. What do you say?","options":[{"text":"That you've noticed a pattern of feeling dismissed","then":"He's quiet, then asks you to give him a real example.","best":true},{"text":"That tonight bothered you a little, leaving it vague","then":"He apologises for tonight, and the pattern stays unnamed."},{"text":"That you're probably just stressed about the wedding","then":"You hand him an excuse that isn't actually true."},{"text":"Nothing, deciding it's not worth a fight so close to the wedding","then":"The doubt stays exactly where it was, unspoken again."}],"why":"Naming the pattern plainly, with an example, gives him a real chance to hear it."},{"prompt":"A week later it happens again at a family dinner, and afterwards he apologises. What do you focus on?","options":[{"text":"Whether he actually changes it, not just how sorry he sounds","then":"You watch closely over the next weeks, and start to get a real answer.","best":true},{"text":"Accepting the apology and considering it resolved","then":"The relief feels good, and the pattern gets a chance to repeat."},{"text":"Deciding the wedding is too close to reconsider anything now","then":"You let the timeline decide instead of the actual pattern."},{"text":"Downplaying it so he doesn't feel too bad","then":"He relaxes before anything's actually been tested."}],"why":"Watching what actually changes, not just the apology, tells you if the doubt is answered."}],"debrief":"Ordinary nerves pass; a persistent doubt about core respect is a signal worth pausing for.","relearn":"Take a persistent doubt about core respect seriously before committing."},
  {"id":"cb-1013","cat":"commitment-clearly","type":"branch","persona":"any","source":"commitment to escape home","hook":"Home has felt suffocating for years, and marrying Ishaan feels like the fastest way out.","steps":[{"prompt":"He proposes, warm and hopeful. What runs through your mind as you answer?","options":[{"text":"Whether you're choosing him, or just choosing to leave","then":"The question surprises you, and you realise you're not fully sure.","best":true},{"text":"Relief that you'll finally be out of the house","then":"The relief feels real, and it isn't quite about him."},{"text":"That saying yes now solves the most urgent problem","then":"You solve today's problem, without asking the bigger question."},{"text":"That any way out is better than staying","then":"You accept the exit without checking whether it's the right one."}],"why":"Separating the urge to leave from the choice of him is what makes the choice honest."},{"prompt":"A friend asks what you love about him, specifically. What do you say?","options":[{"text":"That you're honestly not sure yet, separate from wanting out","then":"She says that's worth being honest with yourself about first.","best":true},{"text":"That he's kind, and that's more than enough given everything at home","then":"You measure him against your home, instead of on his own terms."},{"text":"That it doesn't matter, since leaving is what matters most","then":"You skip the question again, and it waits underneath."},{"text":"That your family would finally stop interfering","then":"You describe your family's exit, not your own reason to say yes."}],"why":"Being honest that you're unsure is more useful than an answer that's really about home."},{"prompt":"You start looking into what else could actually change your situation. What do you consider?","options":[{"text":"Other paths out, like work, moving out or a trusted relative","then":"It's harder than one quick yes, and it's actually yours to choose.","best":true},{"text":"Nothing else, since marriage is the fastest option available","then":"You close off paths you haven't actually tried."},{"text":"Whether things at home might just improve on their own","then":"You wait on a change you can't really count on."},{"text":"Whether Ishaan would mind if you explained your real reason","then":"You consider telling him, without asking what you actually want."}],"why":"Finding another way out frees the decision about him from the pressure to escape."},{"prompt":"Ishaan gently asks if you've thought more about his proposal. What do you do?","options":[{"text":"Take real time to know if you'd choose him for himself","then":"It's slower, and for the first time the choice feels like your own.","best":true},{"text":"Say yes anyway, since he's a genuinely good option","then":"You gain an exit, and still haven't answered the real question."},{"text":"Say no to him and to any way out entirely, exhausted by it all","then":"You're back where you started, no closer to either answer."},{"text":"Let the easier path decide for you","then":"The decision gets made by circumstance, not by you."}],"why":"Real time to choose him for himself is what makes it a commitment, not just an exit."}],"debrief":"Marrying as an escape route is shaky; a partner is chosen for who they are, not as an exit.","relearn":"Marrying to escape something is a shaky reason; choose the person for their own sake."},
  {"id":"cb-1014","cat":"commitment-clearly","type":"branch","persona":"any","source":"slowing a fast match","hook":"Both families want your wedding date fixed within weeks, though you've barely spoken to him properly.","steps":[{"prompt":"Your father says the astrologer found a good date next month. What do you do?","options":[{"text":"Ask for more time before any date gets fixed","then":"Your father pauses, then says he'll ask the astrologer for options later.","best":true},{"text":"Agree, since the date sounds auspicious","then":"The date gets fixed before you've had a real conversation with him."},{"text":"Object to fixing a date at all, upset by the rush","then":"The room tenses, and no one hears the actual ask underneath it."},{"text":"Say you'll go along with whatever both families prefer","then":"The decision moves ahead entirely in other people's hands."}],"why":"Asking for time, without needing a bigger fight, protects the choice from the rush."},{"prompt":"You get a rare hour alone with him before the next family meeting. What do you do with it?","options":[{"text":"Ask real questions about his values and what he wants","then":"You learn more in that hour than in every family meeting combined.","best":true},{"text":"Talk mostly about the wedding logistics","then":"You leave knowing the guest list, and little about him."},{"text":"Stay quiet, unsure what's appropriate to ask this early","then":"The hour passes, and you're back to square one."},{"text":"Ask him whether he thinks the date works for him","then":"He agrees easily, more concerned with the timeline than with talking."}],"why":"Using the rare time to ask real questions gets you more than logistics ever will."},{"prompt":"The families gather again, eager to lock the date in. What do you do?","options":[{"text":"Say plainly you both need a bit more time to talk","then":"There's a pause, then relief in his eyes too, at hearing it said.","best":true},{"text":"Let the date get fixed, since delaying feels awkward now","then":"The date is set, and the conversations you needed still haven't happened."},{"text":"Ask him to be the one to raise it, so it isn't just you","then":"He hesitates, unsure it's his place either, and the moment passes."},{"text":"Go along, deciding you'll get to know him after the wedding","then":"You commit to learning about him only after it's already decided."}],"why":"Naming the need for time together keeps the choice informed, not just fast."}],"debrief":"You can respectfully slow a fast process so the choice is genuinely informed and free.","relearn":"Ask for time and real conversations before a date is fixed; don't be rushed."},
  {"id":"cb-1015","cat":"commitment-clearly","type":"branch","persona":"any","source":"the sunk-cost wedding","hook":"Deposits are paid and the cards are printed, but something you've learned about him lately won't sit right.","steps":[{"prompt":"You overhear him speak sharply to a waiter, the same way he did last month. What do you do?","options":[{"text":"Actually let yourself register it, instead of brushing past it","then":"It joins a small, growing list you've been avoiding looking at directly.","best":true},{"text":"Decide it's just stress from wedding planning","then":"You hand him an excuse the pattern doesn't really support."},{"text":"Say something sharp back to make a point","then":"The moment turns into a small fight about tone, not the pattern."},{"text":"Laugh it off in front of the waiter to smooth things over","then":"The discomfort gets folded away instead of looked at."}],"why":"Letting yourself actually notice the pattern is the first honest step."},{"prompt":"That night, you think about the wedding cards already sitting at home. What do you do?","options":[{"text":"Remind yourself the cards don't have to decide this","then":"It's a strange relief, realising the paper isn't the real question.","best":true},{"text":"Feel locked in, since so much is already arranged","then":"The arrangements start doing the deciding instead of you."},{"text":"Add up the money spent so far as a reason to continue","then":"The number gets louder than the actual doubt underneath it."},{"text":"Decide it's too late to even think about this properly","then":"You stop yourself before really looking at what's bothering you."}],"why":"The cards and deposits are sunk costs. They were never the actual question."},{"prompt":"You mention the waiter moment to a close friend. What does she help you see?","options":[{"text":"That the pattern matters more than how far along things are","then":"Saying it to her, the doubt finally feels like something real to act on.","best":true},{"text":"That every wedding has last-minute nerves","then":"You fold a real concern into a category it doesn't belong in."},{"text":"That it's normal to want to back out before any wedding","then":"You get comfort, without actually naming what's specifically wrong."},{"text":"That you should just ask his friends if he's always like that","then":"You gather more opinions, and still haven't said anything to him."}],"why":"Naming it to someone you trust turns a vague doubt into something you can act on."},{"prompt":"The pattern keeps bothering you as the date nears. What do you do?","options":[{"text":"Name the moments and ask if he sees the pattern too","then":"He's defensive at first, then quiet, turning it over seriously.","best":true},{"text":"Ask if he's just stressed and leave it at that","then":"He says yes, relieved, and the pattern goes unnamed again."},{"text":"Tell him you're having doubts, without saying why","then":"He's hurt and confused, with nothing concrete to actually respond to."},{"text":"Decide not to say anything, this close to the date","then":"The conversation that might have changed things never happens."}],"why":"Naming the specific pattern directly gives him a real chance to respond to it."},{"prompt":"With the wedding just weeks away, what do you do?","options":[{"text":"Trust what you've seen over what's already paid for","then":"It's the hardest conversation of your life, and it's honestly yours.","best":true},{"text":"Go ahead, since calling it off now feels unthinkable","then":"You commit against your own judgement, for reasons that aren't really about him."},{"text":"Postpone without explaining why, to buy more time","then":"You delay the decision, without actually making it."},{"text":"Let his defensiveness settle the question for you","then":"You let his reaction decide something only you can actually decide."}],"why":"What you've actually seen matters more than what's already been spent."}],"debrief":"Sunk costs aren't a reason to commit; a no before the wedding is far cheaper than after.","relearn":"Money already spent isn't a reason to commit; you can still say no."},
  {"id":"cb-1016","cat":"commitment-clearly","type":"branch","persona":"Aditya","source":"committing on your own terms","hook":"You want to commit fully to your partner, but no template around you quite fits your life.","steps":[{"prompt":"A friend asks what your 'version of marriage' will actually look like. What do you say?","options":[{"text":"That you and your partner are still working that out together","then":"She's curious rather than confused, and asks what you've figured out so far.","best":true},{"text":"That you'll just wait until it's legally simple","then":"You describe a plan that depends on something outside your control."},{"text":"That you'll probably just skip defining it at all","then":"The lack of definition starts to feel less like freedom and more like avoidance."},{"text":"That it'll look exactly like your parents' marriage, adapted","then":"You reach for a template that was never quite built for you."}],"why":"Working it out together, rather than waiting on a template, is what makes it genuinely yours."},{"prompt":"You and your partner sit down to actually talk it through. What do you focus on?","options":[{"text":"What commitment and care actually look like for you two","then":"You end up with something neither of you had quite pictured, and it fits.","best":true},{"text":"What would be easiest to explain to your families","then":"You build a version aimed at everyone except you two."},{"text":"Whether to just wait for the law to catch up first","then":"You put your own plans on a timeline you don't control."},{"text":"Copying the nearest wedding you've both been to","then":"It looks familiar, and doesn't quite feel like yours."}],"why":"Focusing on what care and commitment mean to you two builds something that actually fits."},{"prompt":"You're ready to name what you've built to people who matter to you. What do you say?","options":[{"text":"State clearly what you've chosen and why it's real to you","then":"Saying it plainly, you realise how sure of it you actually are.","best":true},{"text":"Downplay it so it's easier for others to accept","then":"It's easier for them, and smaller than what you actually built."},{"text":"Avoid naming it directly, letting people assume what they like","then":"People fill the gap with their own guesses, not your actual answer."},{"text":"Wait for a more 'official' moment to say anything","then":"You keep waiting for a moment that was never going to arrive on its own."}],"why":"Naming it clearly is what makes a freely chosen commitment feel real, to you and to others."}],"debrief":"Commitment is a free, clear choice; many valid forms of partnership rest on the same foundations.","relearn":"Commit on terms true to you both; many valid forms of partnership are equally real."},
  {"id":"cb-1017","cat":"commitment-clearly","type":"branch","persona":"any","source":"the rebound rush","hook":"Six weeks after a hard breakup, you're already talking marriage with Tanvi.","steps":[{"prompt":"She asks, half joking, if you're moving fast because of the breakup. What do you do?","options":[{"text":"Consider the question honestly instead of brushing it off","then":"You realise you don't fully know the answer yourself yet.","best":true},{"text":"Say no immediately, a little too fast","then":"The quick denial doesn't quite convince either of you."},{"text":"Say the breakup is exactly why you know what you want now","then":"You mistake urgency for clarity, without checking the difference."},{"text":"Change the subject, uncomfortable with where it's going","then":"The real question sits there, unexamined, under the joke."}],"why":"Actually sitting with the question is more honest than brushing past it."},{"prompt":"A friend gently points out how fast things have moved. What do you tell her?","options":[{"text":"That you're going to slow down and actually think about it","then":"She looks relieved, and asks what slowing down would look like.","best":true},{"text":"That when you know, you know","then":"You repeat a line that skips the actual thinking."},{"text":"That she doesn't understand how right this feels","then":"You defend the pace instead of examining it."},{"text":"That you're scared to be alone again after the breakup","then":"You name the fear, and still haven't looked at whether it's driving this."}],"why":"Naming that you'll slow down protects the choice from being made by momentum alone."},{"prompt":"With a little distance and time, what do you check before moving forward with Tanvi?","options":[{"text":"Whether you're choosing her clearly, not just filling a gap","then":"The answer takes longer to reach, and it feels more solid once you do.","best":true},{"text":"Whether the relationship still feels as intense as it did","then":"Intensity answers a different question than the one that actually matters."},{"text":"Whether enough time has technically passed since the breakup","then":"You check a calendar instead of checking yourself."},{"text":"Whether she's still as keen as she was at the start","then":"You look for reassurance outside yourself instead of clarity within it."}],"why":"Checking whether you're choosing her clearly, not filling a gap, is what makes it sound."}],"debrief":"Rushing to commit to feel settled is shaky; a clear choice of the person is sound.","relearn":"Don't rush commitment to feel settled; choose freely once you're steady."},
  {"id":"cb-1018","cat":"commitment-clearly","type":"branch","persona":"any","source":"deciding whether, not just when","hook":"Everyone keeps asking when you and your partner will marry, and you haven't decided whether you want to.","steps":[{"prompt":"Your partner casually mentions a wedding season that would 'work well'. What do you do?","options":[{"text":"Say gently that you're still deciding whether, not just when","then":"He looks surprised, then says he hadn't realised that was still open.","best":true},{"text":"Go along with the season, to avoid an awkward conversation","then":"You've quietly agreed to a when, skipping the whether."},{"text":"Change the subject and hope it comes up naturally later","then":"The real question keeps getting postponed instead of asked."},{"text":"Say a season sounds fine, since you'll probably marry eventually","then":"'Probably' quietly turns into a plan neither of you actually chose."}],"why":"Naming that whether is still open protects it from being skipped by a when."},{"prompt":"A friend asks if you're excited about getting married soon. What do you tell her?","options":[{"text":"That you're honestly still working out if you want to at all","then":"She's surprised, then says that's a fair thing to actually sit with.","best":true},{"text":"That you're excited, performing more certainty than you actually feel","then":"You hear yourself say something you're not sure is true."},{"text":"That it's complicated, and leave it there","then":"You dodge the real question, and it waits for the next person who asks."},{"text":"That you'll figure out how you feel once it's closer","then":"You postpone a question that doesn't actually need the wedding to be close."}],"why":"Being honest that you're still deciding is more useful than performing certainty."},{"prompt":"Your partner asks directly if something's holding you back. What do you say?","options":[{"text":"That you need to know you want marriage, not just him","then":"It's a hard, honest conversation, and he says he'd rather have it now.","best":true},{"text":"That nothing's wrong, to avoid worrying him","then":"You reassure him with something that isn't quite true."},{"text":"That the timing just feels off for now","then":"You name a symptom, and the actual question stays unexamined."},{"text":"That you're sure about him, so the rest will follow","then":"You skip past the whether, hoping the when will answer it instead."}],"why":"Naming what you actually need to know keeps the real question from hiding behind a feeling."},{"prompt":"Your family asks again at dinner when the wedding will be. What do you do next?","options":[{"text":"Take real time to actually answer whether, before any when","then":"It's slower than everyone around you would like, and it's honestly yours.","best":true},{"text":"Set a date anyway, hoping certainty arrives before it does","then":"The date approaches faster than the answer does."},{"text":"Let the constant asking make the decision for you","then":"You arrive at a yes that was never fully your own."},{"text":"Avoid the topic until someone forces the question again","then":"The whether stays open, just quieter for now."}],"why":"Taking real time to answer whether is what makes any eventual when actually yours."}],"debrief":"Whether to commit is as valid a question as when; both are yours to answer freely.","relearn":"You get to decide whether to commit, not only when; both are your free choice."},
  {"id":"cb-1019","cat":"commitment-clearly","type":"branch","persona":"any","source":"a wedding budget vs a marriage","hook":"Your families are pouring savings into a huge wedding, though you'd both rather keep it small.","steps":[{"prompt":"Your mother shows you a venue that costs far more than you're comfortable with. What do you do?","options":[{"text":"Say plainly that you'd rather put less into one day","then":"She's taken aback, then asks what you'd rather do instead.","best":true},{"text":"Go along with the venue to avoid disappointing her","then":"The budget grows, carrying a wedding neither of you quite wanted."},{"text":"Agree in front of her, planning to raise it again later","then":"The booking moves ahead before you raise it again."},{"text":"Say nothing, since it's not really your money being spent","then":"You let a decision that will shape your day pass you by."}],"why":"Saying plainly what you'd rather do opens a real conversation instead of quiet resentment."},{"prompt":"Your partner mentions he's also uneasy about the growing cost. What do you do together?","options":[{"text":"Talk to both families about scaling the day back together","then":"It's an awkward conversation, and it opens the door to an actual compromise.","best":true},{"text":"Let each of you raise it separately with your own family","then":"Two half conversations happen, and neither family hears the full picture."},{"text":"Decide to just endure it, since it's one day","then":"You spend the day managing an event instead of enjoying it."},{"text":"Quietly plan a smaller celebration on the side","then":"You solve it privately, without ever actually naming it to your families."}],"why":"Raising it together, as a couple, carries more weight than two separate conversations."},{"prompt":"As the big day nears, what do you two keep coming back to?","options":[{"text":"What you're building together, past this one day","then":"The scale of the wedding starts mattering less than it did at the start.","best":true},{"text":"Whether the wedding will impress people enough","then":"You measure the day by an audience instead of by yourselves."},{"text":"Getting through the day without any family conflict","then":"You survive the day, and the bigger question stays unexamined."},{"text":"How much is left in the budget","then":"The numbers stay the loudest thing in the room."}],"why":"Centring what you're building together keeps the day in its place: one day, not the marriage."}],"debrief":"A wedding is a day; what you're really choosing is years of partnership, not a spectacle.","relearn":"Centre the partnership you're building, not the size of the wedding."},
  {"id":"cb-1020","cat":"commitment-clearly","type":"branch","persona":"Sneha","source":"the 'last chance' framing","hook":"A relative calls this proposal your 'last good chance' and says you have to grab it now.","steps":[{"prompt":"She lays out the warning at a family lunch, watching for your reaction. What do you do?","options":[{"text":"Say calmly you'll judge him on merit, not a deadline","then":"She looks unconvinced, but doesn't push further right then.","best":true},{"text":"Feel the panic set in and nod along","then":"The fear starts doing the deciding instead of you."},{"text":"Argue that 'last chance' talk is unfair, loudly","then":"The lunch turns tense, and the actual match gets lost in the argument."},{"text":"Agree to move quickly, just to be safe","then":"You speed up a decision that hasn't actually been made yet."}],"why":"Naming that you'll judge him on merit, not a deadline, protects the decision from fear."},{"prompt":"You meet the match himself. What do you pay attention to?","options":[{"text":"Whether he actually fits what you're looking for","then":"You notice things you'd have rushed past under pressure.","best":true},{"text":"Whether he seems like the last option you'll get","then":"You measure him against a fear instead of against yourself."},{"text":"How relieved your relative would be if you said yes","then":"You picture her relief instead of picturing your own life."},{"text":"How quickly you could reasonably say yes","then":"Speed becomes the question, instead of fit."}],"why":"Paying attention to actual fit, not scarcity, is what a sound choice is built on."},{"prompt":"Your relative asks again if you're 'finally convinced'. What do you tell her?","options":[{"text":"That you're weighing him on merit, in your own time","then":"She sighs, though something in your calm seems to land.","best":true},{"text":"That the pressure is working, a little","then":"You admit ground to a fear that was never really about him."},{"text":"That you'll decide fast, to end her asking","then":"The fast decision answers her, more than it answers you."},{"text":"That you don't know, avoiding the real question","then":"The scarcity story fills the space where your own answer should be."}],"why":"Repeating that you're weighing him on merit keeps the scarcity story from becoming your answer."},{"prompt":"With the 'last chance' talk still ringing in your ears, how do you actually decide?","options":[{"text":"On whether he's genuinely right for you, nothing else","then":"Whatever you decide, it's finally an answer that's actually yours.","best":true},{"text":"On how rare a good proposal like this might be","then":"You decide based on scarcity instead of on him."},{"text":"On avoiding regret if this really might be the very last one","then":"Fear of missing out quietly makes the choice for you."},{"text":"On what would finally stop the family pressure","then":"The pressure ends, and it isn't clear the choice was ever really yours."}],"why":"Deciding on whether he's actually right for you is the only basis that holds up over time."}],"debrief":"There's no expiry on choosing well; 'last chance' pressure is a shaky basis to commit.","relearn":"Reject 'last chance' pressure; choose freely on the person, not from scarcity."},
  {"id":"cb-1021","cat":"commitment-clearly","type":"branch","persona":"any","source":"renegotiating an old promise","hook":"Years ago you promised your parents you'd marry by thirty, and that birthday is weeks away.","steps":[{"prompt":"Your mother reminds you, gently, of the promise you made at twenty. What do you do?","options":[{"text":"Say you need to choose freely now, not by an old promise","then":"She's quiet, then admits she'd forgotten how young you were when you said it.","best":true},{"text":"Say you'll keep the promise no matter what","then":"You commit to honouring a deadline instead of a decision."},{"text":"Get defensive about being reminded of it at all, again","then":"The conversation turns into a fight about the reminder, not the choice."},{"text":"Promise to sort it out before the birthday","then":"You add a new deadline on top of the old one."}],"why":"Naming that the choice needs to be yours now, not then, is what actually honours it."},{"prompt":"A friend asks if you actually still want what you wanted at twenty. What do you say?","options":[{"text":"That you're not sure, and that matters more than the promise","then":"She says that sounds like something worth actually answering.","best":true},{"text":"That a promise is a promise, whatever you want now","then":"You let an old promise outrank what you actually feel today."},{"text":"That it doesn't really matter what you want now, at this age","then":"You hand your own answer over to a decision you made years ago."},{"text":"That you're too old to still be figuring this out","then":"You judge the uncertainty instead of actually sitting with it."}],"why":"Admitting you're unsure matters more than defending an old promise you made at twenty."},{"prompt":"Your birthday approaches, and your parents ask what's changed. What do you tell them?","options":[{"text":"That this deserves fresh thought now","then":"They're surprised, then say that's fair, if a little disappointing.","best":true},{"text":"That nothing's changed, hoping to avoid the conversation","then":"You dodge a conversation that was always going to come due."},{"text":"That you'll try to meet someone before the date","then":"You chase a deadline instead of a real answer."},{"text":"That the promise was a mistake to make in the first place","then":"You dismiss the old promise instead of actually renegotiating it."}],"why":"Saying the choice deserves fresh thought now is more honest than avoiding the question."},{"prompt":"The birthday comes and goes. What matters now?","options":[{"text":"That you'll choose freely when you're actually ready","then":"It's uncomfortable to let the old date pass, and it's honestly yours.","best":true},{"text":"Finding someone quickly to still technically keep the promise","then":"You meet the letter of an old promise, missing its actual point."},{"text":"Feeling like you've failed a promise you made years ago","then":"You carry guilt for outgrowing a decision made at twenty."},{"text":"Letting your parents' disappointment set the next deadline","then":"One deadline quietly gets replaced by another, still not yours."}],"why":"Choosing freely when you're ready is what the promise was always meant to protect."}],"debrief":"A promise made to a calendar years ago isn't a reason to commit before you're ready.","relearn":"An old timeline isn't a reason to commit; choose freely when you're truly ready."},
  {"id":"cb-1022","cat":"commitment-clearly","type":"branch","persona":"any","source":"a quiet drift into 'us'","hook":"You and your partner have been sliding toward marriage for months, without ever actually deciding it.","steps":[{"prompt":"Someone mentions your 'upcoming wedding' as if it's already settled. What do you do?","options":[{"text":"Notice that it was never actually decided out loud","then":"The realisation catches you off guard: you'd assumed it too.","best":true},{"text":"Go along with it, since it's basically true anyway","then":"The assumption hardens further, still unspoken between you two."},{"text":"Correct them sharply, embarrassed","then":"The correction lands awkwardly, without actually starting the real talk."},{"text":"Laugh and change the subject","then":"The moment passes, and so does the chance to name it."}],"why":"Noticing the unspoken assumption is what lets you actually examine it."},{"prompt":"That evening, you mention it to your partner. What do you say?","options":[{"text":"That you want to actually decide this together, out loud","then":"He pauses, then admits he'd been assuming too, not deciding.","best":true},{"text":"That people keep assuming, so maybe you should just go with it","then":"You let an assumption stand in for an actual choice."},{"text":"Nothing, since it feels too big to bring up suddenly","then":"The drift continues, one more day unexamined."},{"text":"That you guess you're getting married then","then":"You agree to something neither of you has actually chosen yet."}],"why":"Naming it out loud turns a silent drift into something you can actually choose."},{"prompt":"You sit down to talk it through properly. What matters most in that conversation?","options":[{"text":"Both of you saying clearly that this is what you choose","then":"Saying it out loud together feels different from where you'd drifted to.","best":true},{"text":"Agreeing quickly so the momentum isn't disrupted","then":"You keep the momentum, and skip the actual choosing."},{"text":"Letting whoever feels more certain decide for both of you","then":"One of you carries a decision that was meant to be shared."},{"text":"Deciding the drift has basically already decided it","then":"You let inertia stand in for a choice neither of you made."}],"why":"A commitment spoken clearly, by both of you, is what makes it a real choice, not a drift."}],"debrief":"Commitment works best as a clear, spoken choice, not a drift you never quite decided.","relearn":"Make commitment a conscious, spoken choice, not a drift."},
  {"id":"cb-1023","type":"sort","persona":"any","source":"reasons to commit, sorted","hook":"Sort: a sound reason to commit, or a shaky one?","items":[{"id":"a","text":"You've talked the big topics through"},{"id":"b","text":"Everyone keeps asking when"},{"id":"c","text":"You genuinely choose this person"},{"id":"d","text":"You're scared of being alone"},{"id":"e","text":"You respect how they treat you"},{"id":"f","text":"You want to look settled to relatives"}],"bins":[{"id":"sound","label":"Sound","valence":"pos"},{"id":"shaky","label":"Shaky","valence":"neg"}],"key":{"a":"sound","b":"shaky","c":"sound","d":"shaky","e":"sound","f":"shaky"},"relearn":"Choosing the person, talking things through and mutual respect are sound; pressure and fear are shaky.","cat":"commitment-clearly"},
  {"id":"cb-1024","type":"sort","persona":"any","source":"free choice vs pressure","hook":"Sort: a free choice to commit, or pressure to?","items":[{"id":"a","text":"You decide together in your own time"},{"id":"b","text":"An ultimatum: now or never"},{"id":"c","text":"You both feel ready and clear"},{"id":"d","text":"Relatives set the date for you"},{"id":"e","text":"You can still say not yet"},{"id":"f","text":"You're told it's too late to wait"}],"bins":[{"id":"free","label":"Free choice","valence":"pos"},{"id":"pressure","label":"Pressure","valence":"neg"}],"key":{"a":"free","b":"pressure","c":"free","d":"pressure","e":"free","f":"pressure"},"relearn":"Deciding together, feeling ready and keeping a way to say 'not yet' is free; ultimatums and set dates are pressure.","cat":"commitment-clearly"},
  {"id":"cb-1025","type":"sort","persona":"any","source":"a big talk vs skip it","hook":"Sort: a big topic to talk through before committing, or a wedding-day detail?","items":[{"id":"a","text":"How you'll share money"},{"id":"b","text":"What colour the cards are"},{"id":"c","text":"Whether and when to have children"},{"id":"d","text":"Which DJ to book"},{"id":"e","text":"How you'll handle each other's families"},{"id":"f","text":"The seating plan"}],"bins":[{"id":"talk","label":"Talk it through","valence":"pos"},{"id":"detail","label":"Wedding detail","valence":"neutral"}],"key":{"a":"talk","b":"detail","c":"talk","d":"detail","e":"talk","f":"detail"},"relearn":"Money, children and families are big topics to talk through before committing; cards and seating are just the wedding day.","cat":"commitment-clearly"},
  {"id":"cb-1026","type":"sort","persona":"any","source":"about the marriage vs the wedding","hook":"Sort: about building the marriage, or just about the wedding day?","items":[{"id":"a","text":"Agreeing how you'll repair after fights"},{"id":"b","text":"Choosing the mandap decor"},{"id":"c","text":"Aligning on money and goals"},{"id":"d","text":"Picking the menu"},{"id":"e","text":"Naming how you'll share the load"},{"id":"f","text":"Finalising the guest list"}],"bins":[{"id":"marriage","label":"The marriage","valence":"pos"},{"id":"wedding","label":"The wedding day","valence":"neutral"}],"key":{"a":"marriage","b":"wedding","c":"marriage","d":"wedding","e":"marriage","f":"wedding"},"relearn":"Repair, money, goals and sharing the load build the marriage; decor and menus are just one day.","cat":"commitment-clearly"},
  {"id":"cb-1027","type":"sort","persona":"any","source":"nerves vs real doubt","hook":"Sort: ordinary pre-commitment nerves, or a doubt worth heeding?","items":[{"id":"a","text":"Butterflies about a big life change"},{"id":"b","text":"They belittle you when angry"},{"id":"c","text":"Nervous about a big speech"},{"id":"d","text":"You can't be honest without fear"},{"id":"e","text":"Excited-anxious about the future"},{"id":"f","text":"Your core values clearly clash"}],"bins":[{"id":"nerves","label":"Ordinary nerves","valence":"neutral"},{"id":"heed","label":"Heed it","valence":"uhoh"}],"key":{"a":"nerves","b":"heed","c":"nerves","d":"heed","e":"nerves","f":"heed"},"relearn":"Butterflies and big-change jitters are ordinary nerves; belittling, fear and clashing core values are doubts worth heeding.","cat":"commitment-clearly"},
  {"id":"cb-1028","type":"sort","persona":"Sneha","source":"timeline: yours vs theirs","hook":"Sort: a reason that's genuinely yours, or one borrowed from others?","items":[{"id":"a","text":"You feel ready and you've chosen them"},{"id":"b","text":"Everyone your age is settling down"},{"id":"c","text":"You've talked the future through"},{"id":"d","text":"Relatives keep asking 'when'"},{"id":"e","text":"You respect and trust this person"},{"id":"f","text":"You'd look behind if you waited"}],"bins":[{"id":"yours","label":"Genuinely yours","valence":"pos"},{"id":"borrowed","label":"Borrowed pressure","valence":"neg"}],"key":{"a":"yours","b":"borrowed","c":"yours","d":"borrowed","e":"yours","f":"borrowed"},"relearn":"Feeling ready, choosing the person and respect are genuinely yours; 'everyone's settling' and 'looking behind' are borrowed pressure.","cat":"commitment-clearly"},
  {"id":"cb-1029","type":"sort","persona":"any","source":"completes me vs adds to me","hook":"Sort: marriage as completing you, or as adding to a whole life?","items":[{"id":"a","text":"Two whole people choosing to team up"},{"id":"b","text":"A vow to finally fix your loneliness"},{"id":"c","text":"A partner who joins a full life"},{"id":"d","text":"Someone to fill what's missing in you"},{"id":"e","text":"Sharing a life you already own"},{"id":"f","text":"Marriage as the cure for your problems"}],"bins":[{"id":"adds","label":"Adds to you","valence":"pos"},{"id":"completes","label":"'Completes' you","valence":"neg"}],"key":{"a":"adds","b":"completes","c":"adds","d":"completes","e":"adds","f":"completes"},"relearn":"A partnership is two whole people adding to full lives; it isn't a cure that completes a half person.","cat":"commitment-clearly"},
  {"id":"cb-1030","type":"sort","persona":"any","source":"eyes-open prep vs eyes-shut","hook":"Sort: eyes-open preparation to commit, or eyes-shut?","items":[{"id":"a","text":"Discussing how you'll handle conflict"},{"id":"b","text":"Assuming you already agree on everything"},{"id":"c","text":"Meeting each other's real daily life"},{"id":"d","text":"Avoiding any awkward question"},{"id":"e","text":"Naming your hopes and dealbreakers"},{"id":"f","text":"Hoping the hard stuff won't come up"}],"bins":[{"id":"open","label":"Eyes open","valence":"pos"},{"id":"shut","label":"Eyes shut","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"relearn":"Discussing conflict, naming dealbreakers and meeting real life is eyes-open; assuming and avoiding is eyes-shut.","cat":"commitment-clearly"},
  {"id":"cb-1031","cat":"commitment-clearly","type":"choose","persona":"any","source":"whole on your own","hook":"Sunita is filling in her matrimonial profile and pauses on why she wants to marry.","prompt":"Which of these treat marriage as a missing piece?","options":[{"text":"I'll finally feel whole once settled","fits":true,"note":"A partnership adds to a full life; it was never the missing half of you."},{"text":"A wedding will finally make me feel enough","fits":true,"note":"Feeling enough is built in yourself; a ring can't supply it."},{"text":"Being married will prove I'm lovable","fits":true,"note":"Being loved is lovely, but your worth was never waiting on a wedding."},{"text":"I'd like company for the ordinary days","fits":false,"note":"Wanting company is a healthy wish; it doesn't mean you feel incomplete."},{"text":"I want someone to share festivals with","fits":false,"note":"Wanting to share good things with someone is a healthy hope, not neediness."},{"text":"I want to build a family of my own","fits":false,"note":"Wanting a family is a hope for the future, not a sign you're incomplete."}],"relearn":"You're already whole, and a good partnership adds to that rather than completing it."},
  {"id":"cb-1032","cat":"commitment-clearly","type":"choose","persona":"any","source":"a day vs the years","hook":"Kavita is picturing life with Jatin beyond the wedding day itself.","prompt":"Which is closest to real married life?","options":[{"text":"Some evenings are quiet and a bit boring","fits":true,"note":"Ordinary, uneventful evenings are most of married life, and that's fine."},{"text":"They split chores and admin between them","fits":true,"note":"Sharing the everyday tasks is what the years are actually made of."},{"text":"They disagree sometimes and work it out","fits":true,"note":"Working through disagreement, not avoiding it, is what long partnerships do."},{"text":"She'll never feel lonely again","fits":false,"note":"Marriage doesn't erase loneliness; that still needs tending on its own."},{"text":"They'll agree on almost everything","fits":false,"note":"Two whole people will disagree sometimes; that's not a bad sign."},{"text":"Every evening feels like date night","fits":false,"note":"Lovely when it happens, but most evenings are ordinary, and that's fine."}],"relearn":"A wedding is one day; what you're choosing is years of ordinary partnership."},
  {"id":"cb-1033","cat":"commitment-clearly","type":"choose","persona":"any","source":"why, not just when","hook":"Aakash is thinking through what actually matters before he decides about Mitali.","prompt":"Which questions matter most here?","options":[{"text":"Do I freely choose her, with no pressure?","fits":true,"note":"This is the question that makes a commitment sound, whatever else is true."},{"text":"Can I picture our ordinary days together?","fits":true,"note":"The daily, unglamorous years are what he's really choosing, so this matters."},{"text":"Do we want the same things from this life?","fits":true,"note":"Shared expectations for the years ahead matter more than how the day looks."},{"text":"Is this the right age to get married?","fits":false,"note":"An age on a calendar says nothing about whether she's right for him."},{"text":"Will our horoscopes line up well?","fits":false,"note":"Families may value a horoscope match, but it can't tell him if he freely chooses her."},{"text":"Can we get through hard times together?","fits":true,"note":"How two people weather hard times matters far more than timing."}],"relearn":"Whether you freely choose this person matters more than when you commit."},
  {"id":"cb-1034","cat":"commitment-clearly","type":"choose","persona":"any","source":"your own pace","hook":"Ritika just watched another college friend get engaged online.","prompt":"Which thoughts actually help here?","options":[{"text":"I can be glad for her and fine myself","fits":true,"note":"Celebrating a friend doesn't mean her timeline has to become yours."},{"text":"A good choice has no deadline","fits":true,"note":"Choosing well doesn't come with an expiry date, whatever the calendar says."},{"text":"I'll feel better once I'm engaged too","fits":false,"note":"Getting engaged to ease a worry puts the worry in charge of the choice."},{"text":"I'm falling behind everyone","fits":false,"note":"There's no race here, so 'behind' isn't really the right word for this."},{"text":"I should just say yes to someone","fits":false,"note":"Saying yes to end the worry, rather than to the person, rarely goes well."},{"text":"Everyone my age is already settled","fits":false,"note":"What others are doing says nothing about what's right for you, right now."}],"relearn":"Your timeline is your own; there's no race and no expiry on choosing well."},
  {"id":"cb-1035","cat":"commitment-clearly","type":"choose","persona":"any","source":"no pressure either way","hook":"Juhi married last year, Nazia is waiting, and Sanjay says he'll never marry.","prompt":"Which are fair things to say about them?","options":[{"text":"Each of them chose their own path","fits":true,"note":"Married, waiting or not marrying, each path is fully theirs to choose."},{"text":"Waiting is a choice, not a delay","fits":true,"note":"Nazia is choosing her timing; she isn't stuck."},{"text":"Sanjay's choice deserves the same respect","fits":true,"note":"Not marrying is as complete a life choice as the other two."},{"text":"He'll come around eventually","fits":false,"note":"Assuming he'll change his mind doesn't respect what he's actually chosen."},{"text":"She just hasn't met the right one yet","fits":false,"note":"Waiting doesn't mean something is missing; it can simply be her pace."},{"text":"Juhi just did what was expected of her","fits":false,"note":"Juhi chose this too; assuming she just complied overlooks her own choice."}],"relearn":"Commit, wait or never marry, each path is equally valid and worth respecting."},
  {"id":"cb-1036","cat":"commitment-clearly","type":"choose","persona":"any","source":"talk before you leap","hook":"Riddhi and Mehak want to talk through the big things before they get engaged.","prompt":"Which make that talk an honest one?","options":[{"text":"Picking a calm time, not a rushed one","fits":true,"note":"A calm moment makes it easier to say what actually matters to each of you."},{"text":"Asking what the other truly wants","fits":true,"note":"Asking, not assuming, is how they find out what the other really needs."},{"text":"Naming their own non-negotiables clearly","fits":true,"note":"Stating a limit plainly is part of an honest talk, not rudeness."},{"text":"Agreeing to everything to keep it smooth","fits":false,"note":"Agreeing just to avoid friction hides what someone actually wants."},{"text":"Waiting until after the engagement","fits":false,"note":"Big questions are easier to raise before, not after, the decision is made."},{"text":"Listening without jumping in","fits":true,"note":"Letting the other finish is how the real answer gets heard."}],"relearn":"Talking the big things through honestly is what makes a commitment eyes-open."},
  {"id":"cb-1037","type":"reflect","persona":"any","source":"nerves vs signal","hook":"Nerves before a big step are normal. A doubt about respect or safety is different.","prompt":"What would help you tell the two apart?","options":["Talking it over with someone I trust","Noticing if the doubt keeps coming back","Watching how I'm treated when we disagree","Giving myself more time to decide"],"affirm":"Any of these helps; a doubt about how you're treated deserves a pause, and you're allowed to take one.","relearn":"Ordinary nerves pass; a doubt about respect or safety is worth pausing for.","cat":"commitment-clearly"},
  {"id":"cb-1038","cat":"commitment-clearly","type":"choose","persona":"any","source":"freely chosen","hook":"Bhavna is about to answer Harsh's proposal and wants the yes to be fully hers.","prompt":"Which of these are pressure, not a real reason?","options":[{"text":"She's the last of her friends unmarried","fits":true,"note":"Being the last one left is social pressure, not a reason on its own."},{"text":"Her parents already told the relatives","fits":true,"note":"Other people's announcements can push a yes before she's sure herself."},{"text":"They've been together so long it feels expected","fits":true,"note":"Drifting into a yes because it seems next isn't the same as choosing it."},{"text":"She feels calm picturing their years ahead","fits":false,"note":"Feeling steady about the future is a sign of readiness, not pressure."},{"text":"She trusts him with the hard days","fits":false,"note":"Trust built over hard days is a genuine reason, not outside pressure."},{"text":"They've talked the big things through","fits":false,"note":"Having the hard talks first is a real reason to feel ready."}],"relearn":"The strongest yes is freely chosen, not squeezed out by pressure or drift."},
  {"id":"cb-1039","cat":"commitment-clearly","type":"choose","persona":"any","source":"two whole people","hook":"Deepak and Swati argue about money almost every week and hope the wedding will settle it.","prompt":"Which would actually help them now?","options":[{"text":"Naming what they're really arguing about","fits":true,"note":"Naming the real issue is a first step a wedding date can't take for them."},{"text":"Agreeing how they'll split money decisions","fits":true,"note":"A clear, agreed system solves more than any date on a calendar."},{"text":"Setting a calm time to talk about money","fits":true,"note":"A planned, calm talk goes better than a fight in the moment."},{"text":"Noticing this fight repeats and asking why","fits":true,"note":"Spotting the pattern is what lets them actually change it, not just repeat it."},{"text":"Setting the wedding date sooner","fits":false,"note":"A date on the calendar doesn't resolve what they argue about weekly."},{"text":"Deciding a baby will bring them closer","fits":false,"note":"A baby brings joy and new pressures; it can't settle an old argument."}],"relearn":"Marriage doesn't cure a recurring problem; working on it together is what helps."},
  {"id":"cb-1040","cat":"commitment-clearly","type":"choose","persona":"any","source":"renewed daily","hook":"Neelam and Prakash have been married two years and counting.","prompt":"Which commitments get made again and again?","options":[{"text":"Being honest even when it's awkward","fits":true,"note":"Choosing honesty in an awkward moment is a commitment renewed right then."},{"text":"Taking his fair share of the load","fits":true,"note":"Carrying an equal share is a choice repeated daily, not signed once."},{"text":"Staying curious about who she's becoming","fits":true,"note":"People change, so choosing to keep knowing her is an ongoing commitment."},{"text":"Owning a mistake without excuses","fits":true,"note":"Taking responsibility, each time, is part of what keeps a partnership steady."},{"text":"Signing the marriage register","fits":false,"note":"Signing a register happens once; it isn't what holds the years together."},{"text":"Moving into their first home","fits":false,"note":"A big step, but it happens once; the daily choosing comes after."}],"relearn":"Commitment is a choice you keep making daily, not a one-time signature."},
  {"id":"cb-1041","cat":"commitment-clearly","type":"choose","persona":"any","source":"tuning out the chorus","hook":"Gauri's relatives ask her, at every single function, when the wedding is.","prompt":"What does she actually owe them?","options":[{"text":"Basic courtesy","fits":true,"note":"Courtesy costs her little and keeps her own dignity intact."},{"text":"Respect, without more detail","fits":true,"note":"She can be respectful without opening up her private reasons."},{"text":"A specific date","fits":false,"note":"She owes them warmth, not a deadline she hasn't chosen yet."},{"text":"Her private reasons for waiting","fits":false,"note":"Her reasons are hers to keep, even while she stays polite."},{"text":"A promise to hurry up","fits":false,"note":"A hurry-up promise borrows someone else's timeline, not her own."},{"text":"An answer every time they ask","fits":false,"note":"Courtesy doesn't mean discussing it at every function; she can change the subject."}],"relearn":"Hear the 'when?' chorus with grace, and keep the decision your own."},
  {"id":"cb-1042","cat":"commitment-clearly","type":"choose","persona":"any","source":"choosing whether","hook":"Over chai, Zainab's friend asks whether she even wants to marry, and Zainab isn't sure.","prompt":"Which questions are fair to ask yourself?","options":[{"text":"Do I actually want this life?","fits":true,"note":"Whether you want it at all is as fair a question as when you'll have it."},{"text":"Am I choosing this, or just going along?","fits":true,"note":"Noticing whether you're choosing or drifting is a fair, honest question."},{"text":"What do I want, apart from what family wants?","fits":true,"note":"Separating your own wish from family hopes is a fair, honest question."},{"text":"Is it too late for me now?","fits":false,"note":"There's no expiry on choosing well, so this question borrows someone else's fear."},{"text":"How soon can I catch up to my friends?","fits":false,"note":"Their timeline was never yours to catch up to."},{"text":"What will relatives think if I wait?","fits":false,"note":"Other people's opinions aren't a fair test of your own choice."}],"relearn":"Whether to commit is as valid a question as when, and both are yours to answer."},
  {"id":"cb-1043","type":"spot","persona":"any","source":"reasons that assume a yes","hook":"Spot the two shaky reasons to commit (catch the pressure, not the free choice).","scene":[{"id":"a","text":"You freely choose this person","trick":false},{"id":"b","text":"Everyone your age is settling down","trick":true},{"id":"c","text":"You've talked the big things through","trick":false},{"id":"d","text":"You're scared of being left alone","trick":true},{"id":"e","text":"You respect how they treat you","trick":false}],"why":"'Everyone's settling down' and 'scared of being alone' are shaky, pressure-and-fear reasons; the rest are sound, free ones.","relearn":"Choosing the person and talking things through is sound; peer pressure and fear of being alone are shaky.","cat":"commitment-clearly"},
  {"id":"cb-1044","type":"spot","persona":"any","source":"pressure lines that assume a yes","hook":"Spot the two lines that pressure you into commitment (catch the coercion, not the support).","scene":[{"id":"a","text":"\"Take all the time you need to be sure.\"","trick":false},{"id":"b","text":"\"It's now or you'll regret it forever.\"","trick":true},{"id":"c","text":"\"We can talk anything through first.\"","trick":false},{"id":"d","text":"\"Say yes or everyone will judge you.\"","trick":true},{"id":"e","text":"\"There's no rush; it's your call.\"","trick":false}],"why":"'Now or regret it' and 'say yes or be judged' pressure you toward a yes; the others leave the choice freely yours.","relearn":"Commitment should be a free choice; lines that rush or shame you into a yes are pressure.","cat":"commitment-clearly"},
  {"id":"cb-1045","type":"spot","persona":"any","source":"completes-me myths","hook":"Spot the two 'marriage will fix it' myths (catch the false promises).","scene":[{"id":"a","text":"A partnership is two whole people","trick":false},{"id":"b","text":"Marriage will cure my loneliness","trick":true},{"id":"c","text":"Commitment amplifies what's already there","trick":false},{"id":"d","text":"A wedding will fix our constant fights","trick":true},{"id":"e","text":"I'm a whole person before any vow","trick":false}],"why":"'Cure my loneliness' and 'fix our fights' are false promises; marriage amplifies what's there rather than curing it.","relearn":"Marriage isn't a cure for loneliness or conflict; a partnership is built by two whole people.","cat":"commitment-clearly"},
  {"id":"cb-1046","type":"spot","persona":"any","source":"wedding as the finish line","hook":"Spot the two lines that treat the wedding as the finish line.","scene":[{"id":"a","text":"The partnership is the work after the day","trick":false},{"id":"b","text":"Once the wedding's done, it's all sorted","trick":true},{"id":"c","text":"We'll keep choosing each other daily","trick":false},{"id":"d","text":"A perfect wedding proves the marriage","trick":true},{"id":"e","text":"A wedding is one day among many years","trick":false}],"why":"'Once the wedding's done it's sorted' and 'a wedding proves the marriage' treat the day as the finish; the partnership is the real work.","relearn":"A wedding is a day; the partnership that follows is the ongoing work.","cat":"commitment-clearly"},
  {"id":"cb-1047","type":"spot","persona":"any","source":"shaky timeline reasons","hook":"Spot the two timeline traps that aren't really your reason (catch the borrowed pressure).","scene":[{"id":"a","text":"You feel genuinely ready","trick":false},{"id":"b","text":"You'll be 'too old' if you wait","trick":true},{"id":"c","text":"You've chosen this person clearly","trick":false},{"id":"d","text":"This is your 'last good chance'","trick":true},{"id":"e","text":"You trust how they treat you","trick":false}],"why":"'Too old if you wait' and 'last good chance' are scarcity pressure, not reasons; readiness and a clear choice are.","relearn":"There's no expiry on choosing well; 'too old' and 'last chance' are pressure, not reasons.","cat":"commitment-clearly"},
  {"id":"cb-1048","type":"spot","persona":"any","source":"doubts to heed before committing","hook":"Spot the two doubts worth heeding before committing (catch the red flags, not the ordinary nerves).","scene":[{"id":"a","text":"Butterflies about a big life change","trick":false},{"id":"b","text":"They belittle you when they're angry","trick":true},{"id":"c","text":"Nervous excitement about the future","trick":false},{"id":"d","text":"You can't be honest with them without fear","trick":true},{"id":"e","text":"Mild jitters about the ceremony","trick":false}],"why":"Belittling and not being able to be honest without fear are doubts worth heeding; butterflies and jitters are ordinary nerves.","relearn":"Ordinary nerves pass; doubts about disrespect or fear before committing are worth heeding.","cat":"commitment-clearly"},
  {"id":"cb-1049","type":"spot","persona":"any","source":"drift vs decision","hook":"Spot the two signs you're drifting rather than choosing (catch the default, not the decision).","scene":[{"id":"a","text":"You both actively chose this together","trick":false},{"id":"b","text":"You're marrying because it's just easier","trick":true},{"id":"c","text":"You've talked it through and feel clear","trick":false},{"id":"d","text":"You never really decided, it just happened","trick":true},{"id":"e","text":"You can each say why you chose this","trick":false}],"why":"'It's just easier' and 'never really decided' are drift; actively choosing and being able to say why is a real decision.","relearn":"Commitment works best as a clear, spoken choice, not a drift you never decided.","cat":"commitment-clearly"},
  {"id":"cb-1050","type":"spot","persona":"any","source":"escaping into marriage","hook":"Spot the two reasons that use marriage as an escape (catch the shaky exit, not the sound choice).","scene":[{"id":"a","text":"You respect and want to build with them","trick":false},{"id":"b","text":"You mainly want out of a hard home","trick":true},{"id":"c","text":"You've chosen them for who they are","trick":false},{"id":"d","text":"You want to stop feeling lonely fast","trick":true},{"id":"e","text":"You feel like an equal with them","trick":false}],"why":"Marrying to escape home or loneliness is a shaky exit; choosing the person for who they are is sound.","relearn":"Marrying to escape something is shaky; choose the person for their own sake.","cat":"commitment-clearly"},
  {"id":"cb-1051","cat":"commitment-clearly","type":"role-play","persona":"Sneha","source":"answering 'when's your turn'","hook":"At your cousin's wedding, your Chachi corners you near the buffet.","setup":"She's smiling, but she's waiting for a real answer.","steps":[{"prompt":"Chachi asks: \"So? When's your turn, beta? You're not getting any younger.\"","options":[{"text":"\"I'll choose when it's genuinely right for me, not on anyone's deadline.\"","then":"She laughs. \"Fair enough, fair enough. Just don't wait forever.\"","best":true},{"text":"\"You're right. I should probably hurry up and just pick someone soon.\"","then":"She beams. \"That's the spirit! I know a few good boys, actually.\""},{"text":"\"There's no one right now, that's all.\"","then":"She tuts. \"No one? A girl like you? You must be too picky.\""},{"text":"\"Can we not talk about this at a wedding, please?\"","then":"She laughs. \"Where else would we talk about it?\""}],"why":"Naming your own timeline, warmly, answers the question without handing it over."},{"prompt":"Chachi gestures at the couple: \"Don't you want what they have?\"","options":[{"text":"\"Maybe someday, when it's right, not because it's their turn.\"","then":"She softens. \"Okay, that's a nicer way to put it, I suppose.\"","best":true},{"text":"\"I do want that, and honestly seeing them makes me feel behind.\"","then":"She nods sympathetically. \"There, see, so why wait any longer?\""},{"text":"\"Weddings aren't really my thing, I guess.\"","then":"She looks confused. \"Then why did you come?\""},{"text":"\"Sure, I want that too, obviously.\"","then":"She brightens. \"So let's find you someone, then!\""}],"why":"Wanting it on your own terms, not out of comparison, keeps the choice actually yours."},{"prompt":"Chachi asks, softer now: \"So what would make it feel right, for you?\"","options":[{"text":"\"Meeting someone whose values fit mine, not just meeting a deadline.\"","then":"She nods slowly. \"Fair enough. I'll stop pushing, for today.\"","best":true},{"text":"\"I suppose whenever the right person happens to come along on their own.\"","then":"She smiles. \"Well, let me help that along a little, hm?\""},{"text":"\"I don't know. I haven't really thought about it.\"","then":"She shakes her head. \"You should think about it, beta.\""},{"text":"\"Whatever finally gets everyone to stop asking.\"","then":"She laughs. \"Fair, but that could be a while yet.\""}],"why":"Naming values as the real marker, not timing, answers her without giving up your pace."}],"relearn":"You can answer the 'when' question warmly and still keep your timeline your own."},
  {"id":"cb-1052","cat":"commitment-clearly","type":"role-play","persona":"any","source":"needing time before the date","hook":"Both families want to fix your wedding date with Nikhil this weekend, at the temple visit.","setup":"Your father asks you directly before anyone else arrives.","steps":[{"prompt":"Your father asks: \"Shall we fix the date this weekend, then?\"","options":[{"text":"\"I want this to be a real choice, so I need a bit more time first.\"","then":"He studies you. \"Time for what? Has something happened?\"","best":true},{"text":"\"Fine, fix the date. I don't really want to make a fuss about it.\"","then":"He nods, relieved, and reaches for his phone to call the priest."},{"text":"\"Whatever's convenient for everyone else is fine.\"","then":"He smiles. \"Good, then this weekend it is.\""},{"text":"\"Why is everyone in such a rush suddenly?\"","then":"He shrugs. \"The good dates get taken fast, that's all.\""}],"why":"Naming it as needing a real choice, not just avoiding fuss, protects the decision."},{"prompt":"Before he calls anyone, he pauses: \"You seem unsure. Has something happened between you two?\"","options":[{"text":"\"No, nothing's wrong. I want us to talk a few big things through first.\"","then":"He relaxes slightly. \"Oh, good. Take the time you need, then.\"","best":true},{"text":"\"Nothing's really wrong. I just have a slightly uneasy feeling about all this lately.\"","then":"He frowns. \"An uneasy feeling? That's not nothing, beta.\""},{"text":"\"Nothing's wrong. I'm just being difficult, ignore me.\"","then":"He looks unconvinced but doesn't push further today."},{"text":"\"It's fine. Let's just fix the date and move on.\"","then":"He nods and calls out to the priest waiting outside."}],"why":"Naming it as wanting real talks, not doubt, reassures him without losing the time."},{"prompt":"Nikhil's mother joins in: \"The good dates this year are filling up fast, you know.\"","options":[{"text":"\"I understand, and I still need a little more time before we fix one.\"","then":"She exchanges a look with your father, then nods. \"Alright. Soon, though.\"","best":true},{"text":"\"I know, I know, maybe we should just take whatever date is open.\"","then":"She smiles, relieved, and starts listing the remaining open dates."},{"text":"\"That's not really my problem to solve.\"","then":"She looks taken aback. \"I was only trying to help.\""},{"text":"\"Let's just pick the soonest one and be done with it.\"","then":"She brightens and immediately starts checking her calendar."}],"why":"Holding the same request under new pressure shows it was a real need, not a mood."}],"relearn":"You can respectfully ask for more time before a date is fixed; commitment should be unrushed."},
  {"id":"cb-1053","cat":"commitment-clearly","type":"role-play","persona":"any","source":"opening the big-topics talk","hook":"You and Rahul are getting close to engaged, and you realise you've never discussed money or kids.","setup":"One evening, you bring it up directly.","steps":[{"prompt":"Rahul asks: \"Why now? We're happy, isn't that enough?\"","options":[{"text":"\"Before we commit, can we talk money, kids and sharing the load?\"","then":"He pauses, then nods slowly. \"Yeah. Actually, yeah, we should.\"","best":true},{"text":"\"Let's just commit first and figure all of that out later, together.\"","then":"He relaxes. \"Sounds good to me. Let's not overthink it.\""},{"text":"\"I just need to know we're compatible on paper too.\"","then":"He frowns slightly. \"On paper? That sounds cold, honestly.\""},{"text":"\"Forget it, it's probably nothing.\"","then":"He looks relieved and changes the subject to dinner plans."}],"why":"Naming the real topics now, not after, is what eyes-open commitment looks like."},{"prompt":"Later that week, Rahul brings it up himself: \"Kids. Where do you stand?\"","options":[{"text":"\"Honestly, I think I want kids someday. Where are you on it?\"","then":"He smiles a little. \"Same, but not for a few years.\" The talk opens up.","best":true},{"text":"\"You go first. I don't want to say the wrong thing.\"","then":"He hesitates. \"That makes it harder for me too, though.\""},{"text":"\"Whatever you want is fine with me.\"","then":"He looks uncertain. \"That's not really an answer, though.\""},{"text":"\"Let's skip that one. It's too heavy for tonight.\"","then":"He nods, and the topic gets quietly shelved again."}],"why":"Sharing your honest view and asking his makes it a real exchange."},{"prompt":"Rahul asks: \"And money and roles, how do you picture that working?\"","options":[{"text":"\"Shared and fair, worked out together, not assumed by either side.\"","then":"He nods. \"I like that. Let's actually write some of this down.\"","best":true},{"text":"\"However it naturally works out once we're actually living together.\"","then":"He shrugs. \"Sure, I guess we'll figure it out when we get there.\""},{"text":"\"You handle the money, and I'll handle the house, like most people.\"","then":"He pauses. \"Is that actually what you want, though?\""},{"text":"\"I haven't thought about it, honestly.\"","then":"He looks a little unsettled. \"Maybe we should, before we commit.\""}],"why":"Naming shared and fair, worked out together, turns vague hopes into a real plan."}],"relearn":"Open the big-topics talk before you commit, not after; that's eyes-open commitment."},
  {"id":"cb-1054","cat":"commitment-clearly","type":"role-play","persona":"any","source":"naming a real doubt","hook":"You've had a nagging doubt about how you and Kunal handle conflict, and it won't settle.","setup":"One quiet evening, you decide to finally say something.","steps":[{"prompt":"Kunal asks: \"You've seemed distracted lately. Everything okay?\"","options":[{"text":"\"Something about how we handle conflict worries me. Can we talk?\"","then":"He sets down his phone. \"Okay. I'd rather know than guess. Tell me.\"","best":true},{"text":"\"It's nothing major, just a small thing I've been turning over.\"","then":"He nods slowly. \"Okay, but you can tell me, even the small things.\""},{"text":"\"Never mind. I'll just push it down, it's fine.\"","then":"He looks unconvinced. \"You sure? You've seemed off for days.\""},{"text":"\"I'm just tired, that's all it is.\"","then":"He accepts it, though the distracted feeling doesn't go anywhere."}],"why":"Naming the specific worry, conflict, gives him something real to respond to."},{"prompt":"Kunal asks: \"Is it about how we argue? Tell me what's bothering you.\"","options":[{"text":"\"When we disagree, you go quiet for days instead of talking.\"","then":"He winces. \"That's fair. I do shut down. I hate that about myself.\"","best":true},{"text":"\"I don't know exactly, just a bad feeling whenever we argue.\"","then":"He looks puzzled. \"A bad feeling isn't much to go on, though.\""},{"text":"\"You always make everything my fault when we fight.\"","then":"He stiffens. \"That's not true. That's really not fair.\""},{"text":"\"It doesn't matter, I probably imagined it.\"","then":"He looks relieved, and the actual pattern goes unexamined."}],"why":"Naming the specific pattern, not a vague feeling, makes it something to work on."},{"prompt":"He asks: \"When we disagree, what do you need from me?\"","options":[{"text":"\"For us to agree on a way back to each other, even mid-disagreement.\"","then":"He thinks about it. \"Like a signal, maybe, that we're not actually done?\"","best":true},{"text":"\"I need you to just not go quiet, even though I know that's hard.\"","then":"He nods, though the actual how of that stays a little unclear."},{"text":"\"I need you to be different, honestly. That's the real problem.\"","then":"He looks hurt. \"That's a lot to ask someone to just be.\""},{"text":"\"I don't know, maybe it's not really fixable.\"","then":"He goes quiet for a while, then tries one more idea."}],"why":"Asking for a shared way back, not a personality change, makes the ask workable."},{"prompt":"Kunal offers: \"What if I promise to say 'I need a minute' instead of going silent?\"","options":[{"text":"\"That would help a lot. Let's actually try it next time.\"","then":"He looks relieved. \"Okay. Let's really try it. I want this to work.\"","best":true},{"text":"\"Maybe, we'll see if that actually works when it really counts.\"","then":"He nods, though it's unclear if either of you will remember it later."},{"text":"\"We'll see if you actually follow through this time.\"","then":"He looks stung. \"I'm trying here. That stings a bit.\""},{"text":"\"Sure, whatever. Let's just stop talking about this now.\"","then":"He nods. The talk ends there, though he remembers the idea."}],"why":"Agreeing to try the concrete plan turns the doubt into shared work."},{"prompt":"Weeks later, a small disagreement starts, and he catches himself: \"I need a minute, actually.\"","options":[{"text":"\"Okay. I'll be here when you're ready to come back.\"","then":"He returns minutes later, calmer. \"Okay. Let's actually finish this now.\"","best":true},{"text":"\"Fine, but don't take forever about it this time, okay?\"","then":"He nods, a little tense, and steps away for a bit."},{"text":"\"See, this is exactly what I was worried about.\"","then":"He pauses. \"I'm trying something different, though. Give it a chance.\""},{"text":"\"Whatever, I'm done talking about this anyway.\"","then":"He looks disappointed, and the new habit doesn't get its first real try."}],"why":"Letting the new habit actually work, in the moment, is how the doubt resolves."}],"relearn":"Name a persistent doubt before committing; pushing it down isn't the same as resolving it."},
  {"id":"cb-1055","cat":"commitment-clearly","type":"role-play","persona":"any","source":"declining an ultimatum","hook":"Varun says if you don't set a wedding date by month's end, he's walking away.","setup":"He says it flatly, arms crossed, waiting.","steps":[{"prompt":"Varun says: \"Set a date by the end of the month, or I'm done. Simple as that.\"","options":[{"text":"\"I won't commit under a deadline. It's a free choice or not at all.\"","then":"He looks taken aback. \"So that's a no, then? Just like that?\"","best":true},{"text":"\"Okay, let's just set a date then, so you don't actually leave.\"","then":"He relaxes a little, then admits he's not sure you mean it."},{"text":"\"Fine, whatever, pick a date yourself.\"","then":"He blinks. \"You don't even want to choose it together?\""},{"text":"\"You can't be serious right now.\"","then":"He shrugs. \"I'm dead serious. Your choice.\""}],"why":"Naming the ultimatum itself as the problem refuses to let fear pick the date."},{"prompt":"He softens slightly: \"I just need to know you're actually serious about us.\"","options":[{"text":"\"I am serious. That's separate from being pushed by a deadline.\"","then":"He pauses. \"Those can be separate things, I guess. Hadn't thought of it that way.\"","best":true},{"text":"\"I'll prove I'm serious by giving you a date, if that's what it takes.\"","then":"He nods, satisfied, though the ultimatum itself never gets addressed."},{"text":"\"If you have to ask, maybe you already know the answer.\"","then":"He looks stung. \"That's a harsh way to put it.\""},{"text":"\"I don't need to prove anything to you.\"","then":"He crosses his arms tighter. \"Feels like you're avoiding the question.\""}],"why":"Naming seriousness and deadlines as different things answers the real worry."},{"prompt":"Varun asks: \"So how do we decide on a timeline, then?\"","options":[{"text":"\"We build one together, not one you hand me.\"","then":"He considers this. \"Okay. That's actually fair, I think.\"","best":true},{"text":"\"I suppose we could talk about some kind of rough timeline sometime soon, maybe.\"","then":"He looks unsatisfied. \"That's pretty vague, honestly.\""},{"text":"\"I don't really believe in timelines for this kind of thing.\"","then":"He frowns. \"That's convenient, given the circumstances.\""},{"text":"\"Let's not set one. We'll just see what happens.\"","then":"He looks unconvinced this settles anything at all."}],"why":"Offering a shared timeline, not none, meets the worry without the ultimatum."},{"prompt":"He asks quietly: \"Does that mean you do want this, eventually, with me?\"","options":[{"text":"\"Yes, genuinely. I just need it to be my choice, not a threat.\"","then":"He exhales. \"Okay. I hear that. I'm sorry I framed it that way.\"","best":true},{"text":"\"I think so, probably, as long as things keep going okay.\"","then":"He nods, though the answer leaves him more unsettled than before."},{"text":"\"I don't know anymore, honestly, after that ultimatum.\"","then":"He looks stricken. \"So I might have just ruined this.\""},{"text":"\"Ask me again when you're not threatening to leave.\"","then":"He nods slowly, chastened, and the conversation ends there for now."}],"why":"Naming a genuine yes, on your own terms, separates real commitment from a threat."}],"relearn":"Commitment under an ultimatum isn't free; you can decline a deadline-or-else."},
  {"id":"cb-1056","cat":"commitment-clearly","type":"role-play","persona":"Sneha","source":"choosing not to right now","hook":"Your friend Ritu, freshly engaged, asks why you're 'holding back' from getting serious.","setup":"She means it kindly.","steps":[{"prompt":"Ritu asks: \"So really, why are you holding back? You could easily find someone.\"","options":[{"text":"\"I'm not holding back. Not marrying now is a real choice.\"","then":"She blinks. \"Oh. I didn't think of it that way, honestly.\"","best":true},{"text":"\"I guess there's probably something wrong with me for waiting.\"","then":"She rushes to reassure you, but the doubt lingers anyway."},{"text":"\"I just haven't found the right person yet, that's all.\"","then":"She nods. \"Right, well, hopefully soon then.\""},{"text":"\"Marriage isn't that important to me anyway.\"","then":"She looks surprised. \"Really? I thought everyone wanted that eventually.\""}],"why":"Naming it as a choice, not a lack, refuses the frame that something is missing."},{"prompt":"Ritu asks: \"But don't you worry you'll regret waiting too long?\"","options":[{"text":"\"I'd regret marrying on a timeline more than I'd regret waiting.\"","then":"She considers this. \"Huh. I never really thought about it like that.\"","best":true},{"text":"\"Sometimes, yeah, especially when everyone seems to be settling down.\"","then":"She nods sympathetically, and the worry sits there, unresolved."},{"text":"\"Regret is for people who don't know what they want.\"","then":"She looks a little stung. \"I know what I want, for the record.\""},{"text":"\"Maybe, who knows, we'll see.\"","then":"She shrugs, and the question quietly hangs in the air."}],"why":"Naming the bigger risk, a rushed choice, reframes waiting as the safer path."},{"prompt":"She asks, gently now: \"So what would make you feel ready, then?\"","options":[{"text":"\"Meeting someone whose values genuinely fit mine. No deadline.\"","then":"She smiles. \"That's actually a really thoughtful way to see it.\"","best":true},{"text":"\"Whenever I stop feeling like everyone's waiting on me to decide.\"","then":"She nods, though that's still about the pressure, not about you."},{"text":"\"I don't know, maybe I'll never feel ready.\"","then":"She looks concerned. \"That sounds like a sad way to think about it.\""},{"text":"\"Whenever my parents stop asking, probably.\"","then":"She laughs. \"Fair, though that might be never.\""}],"why":"Naming your own real marker, values fitting, keeps the choice about you."}],"relearn":"Not marrying right now is a valid, full choice; you don't owe an apology for it."},
  {"id":"cb-1057","cat":"commitment-clearly","type":"role-play","persona":"any","source":"re-centring the marriage","hook":"Aditi has spent every evening this month on venue comparisons and hasn't mentioned much else.","setup":"Tonight she shows you yet another venue with a huge price tag.","steps":[{"prompt":"Aditi asks: \"Isn't this place perfect? We just have to have it.\"","options":[{"text":"\"It looks lovely. Can we also talk about the years after?\"","then":"She looks up, surprised. \"The years after? I mean, sure, I guess.\"","best":true},{"text":"\"Sure, the wedding is what really counts. Let's book it.\"","then":"She grins and immediately starts filling out the booking form."},{"text":"\"That's way too expensive. We can't afford it.\"","then":"She deflates. \"You always shoot down everything I like.\""},{"text":"\"Whatever you want, I don't really mind either way.\"","then":"She nods, already scrolling to the next expensive option."}],"why":"Naming the years after redirects the focus without dismissing her excitement."},{"prompt":"Aditi asks, a little defensive: \"What else is there to plan? It's our one big day.\"","options":[{"text":"\"The marriage. That's the part that actually lasts.\"","then":"She's quiet for a second. \"I hadn't really thought about it that way.\"","best":true},{"text":"\"Our budget. I'd rather not go into debt over one day.\"","then":"She frowns. \"So this is about money, not about us?\""},{"text":"\"Nothing. Forget I said anything.\"","then":"She goes back to the venue photos, but seems distracted."},{"text":"\"You're being a bit obsessive about this, honestly.\"","then":"She looks hurt. \"I'm just trying to plan a nice day.\""}],"why":"Naming the marriage as the lasting part reframes the day without shaming her."},{"prompt":"She asks quietly: \"Do you think I've been ignoring us, planning all this?\"","options":[{"text":"\"A little, yeah. Let's plan the marriage with the same care.\"","then":"She nods slowly. \"Okay. Let's actually do that, starting this week.\"","best":true},{"text":"\"Not really, I think you've just been excited about the details.\"","then":"She looks relieved, though the actual imbalance stays where it was."},{"text":"\"Yes, honestly, it's all you talk about anymore.\"","then":"She looks stung. \"Okay. I didn't realise it was that bad.\""},{"text":"\"I don't know, maybe.\"","then":"She nods, unsure what to do with an answer that vague."}],"why":"Naming it honestly, then offering a shared plan, makes the imbalance fixable."}],"relearn":"A wedding is a day; centring the partnership you'll build matters more than the show."},
  {"id":"cb-1058","cat":"commitment-clearly","type":"role-play","persona":"any","source":"slowing a rebound rush","hook":"Barely a month after your breakup, Tarun is already talking about moving in together.","setup":"Tonight he brings it up again, excited.","steps":[{"prompt":"Tarun says: \"Why wait? Let's just move in, make it official already.\"","options":[{"text":"\"I want to choose this clearly, not rush in to feel less unsettled.\"","then":"He pauses, thinking about it.","best":true},{"text":"\"Let's just lock it in fast, so I can finally feel okay again.\"","then":"He grins, delighted, and starts looking up moving companies immediately."},{"text":"\"Sure, why not, let's just do it.\"","then":"He cheers, already planning, while your own doubt stays quietly unsaid."},{"text":"\"You're moving way too fast for me.\"","then":"He looks stung. \"I thought this is what you wanted too.\""}],"why":"Naming the real reason for pausing, clarity not distance, keeps this honest."},{"prompt":"Later, Tarun asks quietly: \"Is some of this about your ex?\"","options":[{"text":"\"It's about me needing to feel steady before I commit to anyone.\"","then":"He softens. \"Okay. That actually makes sense. Take your time.\"","best":true},{"text":"\"No, not at all. I've just had a whole lot going on with work lately.\"","then":"He nods, though he can tell there's more to it."},{"text":"\"Maybe a little, I don't know.\"","then":"He looks hurt. \"That's not really what I wanted to hear.\""},{"text":"\"Why does it matter what it's about?\"","then":"He frowns. \"It matters because I want to understand you.\""}],"why":"Naming your own steadiness as the issue, not him, keeps the reason clear."},{"prompt":"He asks: \"So what would help you feel ready, then?\"","options":[{"text":"\"Time, and choosing this because it's right, not to fill a gap.\"","then":"He nods slowly. \"Okay. I can actually wait for that, if it's real.\"","best":true},{"text":"\"Maybe just a few more weeks of us being good together first.\"","then":"He agrees, though the timeline is really just a guess dressed as a plan."},{"text":"\"I don't know, maybe nothing will really help.\"","then":"He looks worried. \"That sounds like you're not sure about us at all.\""},{"text":"\"Just stop asking about it and give me space.\"","then":"He nods, hurt, and the conversation ends there, unresolved."}],"why":"Naming time and clear reasons, not a gap to fill, protects the choice."}],"relearn":"Don't rush commitment to soothe a breakup; choose clearly once you're steady."},
  {"id":"cb-1059","type":"match","persona":"any","source":"sound vs shaky reasons matched","hook":"Match each reason to commit to whether it's sound or shaky.","relearn":"Choosing the person and talking things through are sound; pressure and fear are shaky reasons.","pairs":[{"left":"You freely choose this person","right":"Sound reason"},{"left":"You've talked the big things through","right":"A solid base"},{"left":"Everyone your age is settling down","right":"Shaky reason"},{"left":"You're scared of being alone","right":"Fear, not choice"},{"left":"Relatives keep asking when","right":"Outside pressure"}],"cat":"commitment-clearly"},
  {"id":"cb-1060","type":"match","persona":"any","source":"myth to truth, commitment","hook":"Match the commitment myth to the truth that replaces it.","relearn":"Marriage doesn't complete you, fix problems or finish at the wedding; it's two whole people, eyes open.","pairs":[{"left":"\"Marriage will complete me\"","right":"Two whole people team up"},{"left":"\"A wedding is the finish line\"","right":"The partnership is the work"},{"left":"\"Marriage fixes our problems\"","right":"It amplifies what's there"},{"left":"\"Commit because of my age\"","right":"Your readiness, not the calendar"},{"left":"\"Just drift into it\"","right":"Make it a clear choice"}],"cat":"commitment-clearly"},
  {"id":"cb-1061","type":"match","persona":"any","source":"big topic to why it matters","hook":"Match each big topic to talk through before committing to why it matters.","relearn":"Money, children, roles and family talks before committing avoid the biggest surprises later.","pairs":[{"left":"Money","right":"How you'll share it"},{"left":"Children","right":"Whether and when"},{"left":"Roles","right":"Who does what fairly"},{"left":"Families","right":"How you'll handle both"},{"left":"Values","right":"Where you align"}],"cat":"commitment-clearly"},
  {"id":"cb-1062","type":"match","persona":"any","source":"pressure line to free reply","hook":"Match each pressure line to a calm, free-choice reply.","relearn":"You can meet pressure to commit with a warm reply that keeps the choice freely yours.","pairs":[{"left":"\"It's now or never\"","right":"\"I won't decide on a clock\""},{"left":"\"Everyone's married already\"","right":"\"Their pace isn't mine\""},{"left":"\"You're getting too old\"","right":"\"There's no expiry on choosing well\""},{"left":"\"What will people say?\"","right":"\"This is my life to shape\""},{"left":"\"Just say yes\"","right":"\"I need real time first\""}],"cat":"commitment-clearly"},
  {"id":"cb-1063","type":"match","persona":"Sneha","source":"timeline pressures to the truth","hook":"Match each timeline pressure to the truth that defuses it.","relearn":"Timeline pressures aren't reasons; your pace is your own and there's no expiry on choosing well.","pairs":[{"left":"\"Settle down before thirty\"","right":"No deadline on a good choice"},{"left":"\"This is your last chance\"","right":"Scarcity isn't a reason"},{"left":"\"Don't be left behind\"","right":"Others' pace isn't yours"},{"left":"\"You're running out of time\"","right":"Your timeline is your own"},{"left":"\"It's just expected\"","right":"Expectation isn't consent"}],"cat":"commitment-clearly"},
  {"id":"cb-1064","type":"match","persona":"any","source":"nerves vs heed it matched","hook":"Match each feeling before committing to what it's telling you.","relearn":"Butterflies and jitters are ordinary; disrespect, fear and clashing core values are worth heeding.","pairs":[{"left":"Butterflies about a big change","right":"Excitement mixed with nerves"},{"left":"Stage fright before the day","right":"Worry about being watched"},{"left":"They belittle you when angry","right":"Respect is missing"},{"left":"You can't be honest without fear","right":"It isn't safe to speak up"},{"left":"Your core values clash","right":"You want different lives"}],"cat":"commitment-clearly"},
  {"id":"cb-1065","type":"match","persona":"any","source":"the wedding vs the marriage","hook":"Match each piece of wedding planning to the marriage skill it quietly tests.","relearn":"Planning a wedding together is early practice in the skills a marriage runs on.","pairs":[{"left":"Agreeing on a budget","right":"Handling money together"},{"left":"Balancing both families' wishes","right":"Setting kind boundaries"},{"left":"Splitting the planning tasks","right":"Sharing the load fairly"},{"left":"Settling a disagreement over guests","right":"Repairing after conflict"},{"left":"Keeping time for each other in the rush","right":"Protecting your closeness"}],"cat":"commitment-clearly"},
  {"id":"cb-1066","type":"match","persona":"any","source":"free choice vs pressure matched","hook":"Match each situation to what is really happening.","relearn":"Deciding together in your own time is free; ultimatums, set dates and shame are pressure.","pairs":[{"left":"You both want it and said so","right":"A choice you both own"},{"left":"You can still say not yet","right":"Room to wait"},{"left":"An ultimatum: now or over","right":"A threat to end it"},{"left":"Relatives fix the date","right":"Others deciding for you"},{"left":"Shamed into a yes","right":"Guilt doing the choosing"}],"cat":"commitment-clearly"},
  {"id":"cb-1080","type":"strike-rewrite","hook":"\"In an arranged match, the elders decide and you just go along.\"","myth":{"un":"In an arranged match, the elders decide and you just go along.","re":"Family can introduce and suggest, but the yes or no is yours to give.","why":"It's your marriage to live, so it's your call to make."},"relearn":"In an arranged match you still hold the right to decide and to take your time.","persona":"any","source":"your call","cat":"love-and-arranged"},
  {"id":"cb-1081","type":"strike-rewrite","hook":"\"Saying no to a proposed match disrespects your parents.\"","myth":{"un":"Saying no to a proposed match disrespects your parents.","re":"Declining a match isn't disrespect; it's using the consent that's yours on any path.","why":"Respecting elders and choosing for yourself can both be true at once."},"relearn":"You can decline a match with respect; consent is yours on any path.","persona":"any","source":"decline with respect","cat":"love-and-arranged"},
  {"id":"cb-1082","type":"strike-rewrite","hook":"\"A love marriage is more real than an arranged one.\"","myth":{"un":"A love marriage is more real than an arranged one.","re":"Neither path is more real; both stand on values, compatibility, communication and consent.","why":"What makes a marriage real is the work two people put in, not how they met."},"relearn":"Love and arranged marriages are equally real; both rest on the same foundations.","persona":"any","source":"both real","cat":"love-and-arranged"},
  {"id":"cb-1083","type":"strike-rewrite","hook":"\"In an arranged process there's no time to actually get to know them.\"","myth":{"un":"An arranged process leaves no time to actually get to know someone.","re":"You can ask for time and real conversations before you decide; nobody should rush you.","why":"A few honest talks tell you more than a single meeting or a photo."},"relearn":"In an arranged process, ask for time and real conversations before deciding.","persona":"any","source":"ask for time","cat":"love-and-arranged"},
  {"id":"cb-1084","type":"strike-rewrite","hook":"\"If the families have agreed, the couple's yes is just a formality.\"","myth":{"un":"Once the families agree, the couple's yes is just a formality.","re":"The couple's consent isn't a formality; their own judgement should lead the decision.","why":"Two families can bless a match, but only the couple can consent to it."},"relearn":"Family can be respected, but the couple's own judgement and consent should lead.","persona":"any","source":"not a formality","cat":"love-and-arranged"},
  {"id":"cb-1085","type":"strike-rewrite","hook":"\"A queer couple can't have a real marriage or family.\"","myth":{"un":"A queer couple can't have a real marriage or family.","re":"Many valid forms of partnership and family are real and rest on the same foundations.","why":"Love, respect and commitment make a family, not a single template."},"relearn":"Many valid forms of partnership and family are real and built on the same foundations.","persona":"Aditya","source":"every family is real","cat":"love-and-arranged"},
  {"id":"cb-1086","type":"strike-rewrite","hook":"\"In an arranged match, looks and the photo are what matter most.\"","myth":{"un":"In an arranged match, looks and the photo matter most.","re":"Goals, conflict style and values reveal real fit far better than a photo does.","why":"A photo can't tell you how someone handles a hard day together."},"relearn":"Asking about goals, conflict style and values reveals real fit in a match.","persona":"any","source":"beyond the photo","cat":"love-and-arranged"},
  {"id":"cb-1087","type":"strike-rewrite","hook":"\"Once a date is fixed, backing out is impossible.\"","myth":{"un":"Once a date is fixed, backing out is impossible.","re":"Your consent stays required right up to the day; you can change your mind.","why":"A fixed date doesn't cancel your right to choose freely."},"relearn":"Your consent is required throughout; a fixed date doesn't remove your right to choose.","persona":"any","source":"you can still choose","cat":"love-and-arranged"},
  {"id":"cb-1088","type":"strike-rewrite","hook":"\"An arranged match skips compatibility, so don't bother checking it.\"","myth":{"un":"An arranged match skips compatibility, so there's no point checking it.","re":"Compatibility matters on every path; check shared values and goals before you commit.","why":"How you'll handle money, family and conflict together is worth knowing either way."},"relearn":"Love and arranged marriages need the same foundations; check compatibility on both.","persona":"any","source":"check compatibility","cat":"love-and-arranged"},
  {"id":"cb-1089","type":"strike-rewrite","hook":"\"Being pressured into a wedding is just how it is; nothing to be done.\"","myth":{"un":"Being pressured into a wedding is just how it is; nothing can be done.","re":"A marriage needs your free yes; being forced is never okay, and help exists.","why":"Coercion isn't tradition, and you don't have to carry it alone."},"relearn":"Forced marriage is never okay; your consent is required, and help exists (181, 1098, 112).","persona":"any","source":"help exists","cat":"love-and-arranged"},
  {"id":"cb-1090","cat":"love-and-arranged","type":"branch","persona":"any","source":"no same-day yes","hook":"Your family has arranged a first meeting today, and wants your answer by dinner.","steps":[{"prompt":"Before the meeting even starts, your aunt says they'll want to know tonight. What do you do?","options":[{"text":"Say you'll meet him, but you won't decide tonight","then":"She's a little surprised, then nods and lets it go.","best":true},{"text":"Agree to decide tonight, to avoid an argument beforehand","then":"You walk into the meeting already boxed into a deadline."},{"text":"Say you don't even want to meet him under this pressure","then":"Your aunt talks you into going anyway, and you walk in tense."},{"text":"Ask your parents to decide tonight on your behalf","then":"You hand your first real look at him over to someone else's read."}],"why":"Separating meeting him from deciding on him protects your judgement from the deadline."},{"prompt":"The meeting itself goes fine, pleasant but brief. What do you do as it wraps up?","options":[{"text":"Ask him directly if he'd also like more time to talk properly","then":"He looks relieved, and says he was hoping someone would ask.","best":true},{"text":"Smile and say nothing at all, waiting to see what happens next","then":"The families move to decide for you both instead."},{"text":"Say yes on the spot, since the meeting went smoothly","then":"You agree to something built on one brief, pleasant hour."},{"text":"Avoid answering by leaving the room early","then":"You dodge the pressure, and also dodge the actual conversation."}],"why":"Asking if he wants more time too turns a rushed yes into an actual conversation."},{"prompt":"Back home, your family asks for tonight's answer as promised. What do you say?","options":[{"text":"That you need a proper talk with him before deciding","then":"There's a pause, then your father says that's a reasonable ask.","best":true},{"text":"A quick yes, since he seemed nice enough","then":"You answer the deadline, more than the actual question."},{"text":"A quick no, to avoid the pressure of deciding at all","then":"Your father asks you to talk to him properly once before the no is final."},{"text":"That you'll decide by tomorrow instead","then":"You've only moved the same rushed deadline by a day."}],"why":"Naming the need for a proper talk is a reasonable ask, not a refusal."},{"prompt":"A few days later, after a real conversation with him, what guides your actual answer?","options":[{"text":"What you learned about him in that longer talk","then":"Whatever you decide, it's based on him, not on one rushed evening.","best":true},{"text":"How much your family already likes him","then":"You lean on their read, instead of building your own."},{"text":"How awkward it would be to back out now, after meeting twice","then":"Discomfort about backing out quietly becomes your reason to continue."},{"text":"How the first meeting felt in the moment","then":"One brief hour ends up outweighing the fuller conversation after."}],"why":"Basing the answer on what you actually learned is what makes it a real yes or no."}],"debrief":"You can meet, weigh it, and ask for time; a real yes or no follows real talk.","relearn":"In an arranged process, ask for time and real conversations before deciding."},
  {"id":"cb-1091","cat":"love-and-arranged","type":"branch","persona":"any","source":"red flags count","hook":"In your second arranged meeting, Rakesh brushes off every opinion you offer as if it doesn't count.","steps":[{"prompt":"You mention wanting to keep working after marriage, and he waves it off. What do you do?","options":[{"text":"Register that as a real answer about how he sees you","then":"You realise this is the second time today he's done exactly this.","best":true},{"text":"Let it slide, since it's only the second meeting","then":"You collect one more moment you're quietly choosing not to count."},{"text":"Argue your point harder to make him take it seriously","then":"He humours you, without actually changing how he's listening."},{"text":"Stay quiet for the rest of the meeting","then":"The meeting ends smoothly, and the dismissal goes unexamined."}],"why":"Naming the dismissal as a real answer, not a mood, is what lets you actually see the pattern."},{"prompt":"Afterwards, your mother says he seems like a strong, confident match. What do you tell her?","options":[{"text":"That he dismissed everything you said, and it matters","then":"She's quiet, then asks you to tell her more about what happened.","best":true},{"text":"That he seems fine, agreeing with her read","then":"You let her impression stand in for your own."},{"text":"That you're not sure, without saying why","then":"The real reason for your hesitation stays unnamed."},{"text":"That his kind of confidence is probably normal at first meetings","then":"You relabel the dismissal as a trait instead of a flag."}],"why":"Saying plainly what you noticed keeps it from being smoothed over by someone else's impression."},{"prompt":"The families ask if you'd like a third meeting. What do you decide?","options":[{"text":"Decline, since the pattern already told you enough","then":"There's a pause, then your family accepts it without much fuss.","best":true},{"text":"Agree to one more meeting to be completely sure","then":"The same dismissiveness shows up again, right on schedule."},{"text":"Say yes, since two meetings feels too early to judge","then":"You override what you've already clearly noticed."},{"text":"Leave the decision to your parents","then":"The choice moves ahead without your read of him counted in it."}],"why":"A pattern you've already seen twice is enough information to act on."}],"debrief":"Red flags count on any path; how someone treats you now is information you can act on.","relearn":"Take red flags seriously in an arranged match; you can always say no."},
  {"id":"cb-1092","cat":"love-and-arranged","type":"branch","persona":"Sneha","source":"age is not a reason","hook":"Relatives say you're 'getting old' and should just accept whichever proposal comes next.","steps":[{"prompt":"A new biodata arrives, and your aunt says you can't afford to be choosy anymore. What do you do?","options":[{"text":"Say you'll still judge this one on its own merit","then":"Your aunt sighs, but agrees to let you actually meet him first.","best":true},{"text":"Agree that you should just accept this one","then":"You start the process already leaning toward yes, age deciding for you."},{"text":"Refuse to even look at the biodata, tired of the topic","then":"Your family sets up the meeting anyway, and you arrive knowing nothing about him."},{"text":"Ask her to just decide, since you're exhausted by choosing","then":"The decision moves into her hands instead of yours."}],"why":"Insisting on your own merit test, age or not, keeps the choice actually yours."},{"prompt":"You meet this new match. Older relatives ask if you'll finally say yes this time. What do you do?","options":[{"text":"Judge him the same way you would any match, carefully","then":"You notice things, good and not so good, same as always.","best":true},{"text":"Lower your usual standards, given your age","then":"You excuse things you wouldn't have excused before."},{"text":"Say yes quickly, relieved to finally end the search","then":"The relief is about the search ending, not really about him."},{"text":"Compare him only to how many proposals you've had","then":"You measure him against a number instead of against yourself."}],"why":"Judging him the same careful way as always keeps age from lowering your standard."},{"prompt":"Your relatives ask what's taking so long to decide. What do you tell them?","options":[{"text":"That you're deciding on fit, the same as always, age aside","then":"They're a little impatient, but they hear you mean it.","best":true},{"text":"That you're worried this really might be your last chance","then":"You let a fear about age lead instead of your own judgement."},{"text":"That you'll say yes soon, to stop the questions","then":"You aim the decision at ending the pressure, not at him."},{"text":"That age is making this harder than it should be","then":"You blame the clock for a decision that's still actually yours to make."}],"why":"Naming that fit still leads, age aside, is what keeps pressure from becoming your reason."}],"debrief":"Age and pressure aren't reasons to marry; choose the person and the fit, on your timeline.","relearn":"Commit when you genuinely choose the person, not from pressure or age."},
  {"id":"cb-1093","cat":"love-and-arranged","type":"branch","persona":"any","source":"big talks first","hook":"Your parents are pleased with a match, but you haven't yet asked him the big questions yourself.","steps":[{"prompt":"Your father says the families have already discussed everything important. What do you do?","options":[{"text":"Say you'd still like to ask him yourself, directly","then":"Your father is a little surprised, then agrees it makes sense.","best":true},{"text":"Trust that the families covered what matters","then":"You move ahead on secondhand answers to questions that are actually yours."},{"text":"Say you don't need to ask anything more","then":"You skip past questions you'll likely wish you'd asked."},{"text":"Ask a cousin to quietly find out from his side instead","then":"You get someone else's version of answers that should come from him."}],"why":"Asking to hear it from him yourself gets you answers, not just secondhand approval."},{"prompt":"You get a call with him arranged. What do you bring up first?","options":[{"text":"How he pictures handling money and roles in a marriage","then":"He's thoughtful, admitting he hadn't been asked that directly before.","best":true},{"text":"Whether the families are getting along well","then":"You learn about the families, and still not about him."},{"text":"Small talk, saving the bigger questions for later","then":"The call ends pleasant and light, and the real questions wait."},{"text":"Whether he's happy with how things are proceeding","then":"He says yes easily, and you learn little about what 'this' means to him."}],"why":"Asking directly about money and roles gets you his own thinking, not the families' summary."},{"prompt":"On the next call, you ask about children. What do you notice in his answer?","options":[{"text":"Whether his answer is actually his own, not just expected","then":"You can tell he's genuinely thought about it, not just reciting a line.","best":true},{"text":"Whether it matches what your family would want to hear","then":"You measure his answer against your family, not against yourselves."},{"text":"How quickly and confidently he answers","then":"Confidence tells you less than the actual answer does."},{"text":"Whether the topic feels too early to bring up at all","then":"You let a useful question go unasked, deemed too soon."}],"why":"Noticing whether an answer is genuinely his shows you more than how confidently it's said."},{"prompt":"As the process moves toward a decision, what do you do with what you've learned?","options":[{"text":"Weigh his actual answers alongside your family's approval","then":"You bring both into the decision, instead of relying on just one.","best":true},{"text":"Let your family's approval settle it, since the answers were fine","then":"The answers you worked to get end up mattering less than expected."},{"text":"Decide the questions themselves were the important part, answers aside","then":"You credit yourself for asking, without really using what you learned."},{"text":"Move ahead regardless, since the process is already this far along","then":"The momentum decides, more than anything he actually said."}],"why":"Weighing his actual answers alongside family approval keeps your own judgement in the decision."}],"debrief":"Talk the big things through before you commit on any path; that's how you find real fit.","relearn":"Talk through the big topics honestly before you commit, on any path."},
  {"id":"cb-1094","cat":"love-and-arranged","type":"branch","persona":"any","source":"free yes","hook":"A relative insists forcing this wedding through is fine, since it's 'for your own good'.","steps":[{"prompt":"She says it again, kindly but firmly, expecting you to simply agree. What do you do?","options":[{"text":"Say plainly that your consent is still required","then":"She looks taken aback, unused to being told no this directly.","best":true},{"text":"Stay quiet, hoping the pressure passes on its own","then":"Your silence gets treated as agreement, and plans move ahead."},{"text":"Pretend to agree, planning to object again some other day","then":"The 'agreement' gets repeated to others as settled fact."},{"text":"Shout that no one is listening to you","then":"The outburst gets dismissed as nerves, not heard as a real no."}],"why":"Naming that your consent is required, plainly, is not disrespect. It's the truth."},{"prompt":"She says every family does this, and you'll understand once it's done. What do you do?","options":[{"text":"Repeat clearly that being forced is not okay","then":"She's quiet for a moment, unsettled by how sure you sound.","best":true},{"text":"Ask her to just explain her reasoning one more time","then":"You get another explanation, and no more room to actually say no."},{"text":"Say you'll think about what she said","then":"'Thinking about it' gets heard as you coming around."},{"text":"Go along, telling yourself she must know better","then":"You hand your own consent over to someone else's certainty."}],"why":"Repeating your no, calmly, keeps 'everyone does this' from becoming your answer."},{"prompt":"You decide to tell someone outside the immediate pressure. Who do you turn to?","options":[{"text":"A trusted person outside the house, and a helpline","then":"Someone listens without judgement and helps you understand your options.","best":true},{"text":"No one, managing it alone for now","then":"The pressure keeps building with no one else aware of it."},{"text":"A friend, asking them to just keep it quiet","then":"Your friend carries it alone too, unsure what to actually do."},{"text":"Social media, venting without naming specifics","then":"It gets your feelings out, without actually getting you help."}],"why":"Reaching a trusted person and a helpline is not your fault to need, and it works."},{"prompt":"The relative doubles down, saying the invitations are already going out. What do you do?","options":[{"text":"Hold your no, and tell the people helping you it's escalating","then":"They move faster to help, since you told them what's changing.","best":true},{"text":"Give in, since it feels too far along to stop now","then":"You feel too worn down to fight, and the people helping you step in anyway."},{"text":"Try to quietly slow it down without saying no directly","then":"The indirect approach doesn't actually stop what's already moving."},{"text":"Blame yourself for not stopping it sooner, when you had the chance","then":"You carry blame that was never yours to carry in the first place."}],"why":"Telling the people helping you what's changing keeps you supported, not alone in it."},{"prompt":"With help now involved, what matters most going forward?","options":[{"text":"That the marriage only happens if you freely choose it","then":"It's a hard, ongoing process, and for the first time it's led by your own consent.","best":true},{"text":"Getting the family back to being pleased with you","then":"You aim at peace in the house over your own free choice."},{"text":"Proving to relatives that you had good reasons","then":"You spend energy justifying yourself instead of holding your no."},{"text":"Moving past it all quickly so life can return to normal","then":"You rush past a decision that deserves real support and time."}],"why":"A marriage only works when it's freely chosen. That is what your consent protects."}],"debrief":"No one's claim of 'your own good' overrides your consent. Being forced is never your fault, and help exists.","relearn":"Forced marriage is never okay; your consent is required, and help exists (181, 1098, 112)."},
  {"id":"cb-1095","cat":"love-and-arranged","type":"branch","persona":"any","source":"values gap is real","hook":"You want children eventually; the match your family likes says clearly he doesn't.","steps":[{"prompt":"He mentions it plainly over tea, expecting it might be a dealbreaker. What do you do?","options":[{"text":"Treat it as a real gap worth taking seriously","then":"He looks relieved you didn't brush past something this big.","best":true},{"text":"Assume he might change his mind later","then":"You build a hope on something he's already told you plainly."},{"text":"Say it doesn't matter much at this stage","then":"You downplay something that will matter a great deal later."},{"text":"Change the subject, uncomfortable with the topic","then":"The disagreement stays exactly where it was, unresolved."}],"why":"Taking the gap seriously right away is what respects how much it will actually matter."},{"prompt":"Your family says everything else about the match looks so suitable. What do you do?","options":[{"text":"Say this particular gap still matters, whatever else fits","then":"They're a little surprised, then ask you to explain why it's not minor.","best":true},{"text":"Agree that the rest outweighs this one thing","then":"You let a long-term question get outvoted by shorter-term fit."},{"text":"Say you'll decide about having children after the wedding instead","then":"You postpone a disagreement that won't get easier to raise later."},{"text":"Say you'll probably be the one to compromise","then":"You quietly volunteer to give up what you actually want."}],"why":"Naming that this particular gap still counts keeps it from being outweighed by unrelated fit."},{"prompt":"You and he talk once more, honestly, about where you each stand. What matters most?","options":[{"text":"Whether either of you could genuinely live with this","then":"You both leave with a clearer, harder, more honest picture.","best":true},{"text":"Whether your families would be disappointed by a no","then":"You weigh other people's disappointment over your own actual answer."},{"text":"Whether you're overreacting to one disagreement","then":"You question your own read instead of weighing the actual gap."},{"text":"Whether love could make the difference not matter","then":"You lean on hope for a question that needs an honest answer."}],"why":"Asking what you could each genuinely live with is what an honest values gap actually needs."}],"debrief":"A genuine values mismatch matters on any path; weigh it before you commit, not after.","relearn":"Take a values mismatch seriously even when other things look suitable."},
  {"id":"cb-1096","cat":"love-and-arranged","type":"branch","persona":"Aditya","source":"real on its own terms","hook":"Your partner's family still calls your relationship 'a phase he's going through'.","steps":[{"prompt":"At a gathering, his mother introduces you as 'his friend', again. What do you do?","options":[{"text":"Talk to your partner later about naming the relationship","then":"He admits it stings him too, and he's grateful you brought it up.","best":true},{"text":"Correct her yourself, right there at the gathering","then":"The room goes tense, and it becomes about the moment, not the pattern."},{"text":"Let it go, since it's not really your family to correct","then":"The pattern continues, unspoken between you and your partner too."},{"text":"Avoid future gatherings with his family","then":"You avoid the discomfort, and the relationship stays undefined to them."}],"why":"Naming the pattern together first means you're building a response as a team, not alone."},{"prompt":"Your partner says his family keeps asking when 'this phase' will end. What do you do?","options":[{"text":"Ask how he wants to respond, and back whatever he decides","then":"He says he's ready to say it plainly, and feels less alone doing it.","best":true},{"text":"Tell him to just confront them himself","then":"You hand him a plan built for you, not for how he wants to handle his own family."},{"text":"Suggest waiting it out until they come around on their own","then":"The waiting stretches on, with the dismissal still unaddressed."},{"text":"Say it doesn't matter what they call it, as long as you know","then":"He says he still wants it named, even if you're at peace without it."}],"why":"Backing how he wants to respond respects that it's his family relationship to navigate too."},{"prompt":"Together, you decide how to describe your relationship going forward. What do you focus on?","options":[{"text":"Naming it clearly as the real partnership it is","then":"It takes a few tries, and it starts to land, a little more each time.","best":true},{"text":"Letting his family's framing stand, to keep the peace","then":"The peace holds, and so does the phrase 'his friend'."},{"text":"Matching how serious his family seems willing to accept","then":"You shrink the description to fit what's comfortable for them."},{"text":"Avoiding the topic with them entirely from now on","then":"The silence reads as agreement with a framing neither of you holds."}],"why":"Naming the relationship clearly and consistently is what makes its reality land over time."}],"debrief":"Many forms of partnership are real and rest on the same foundations of values, respect and consent.","relearn":"Build the partnership that's right for you two; many forms are valid."},
  {"id":"cb-1097","cat":"love-and-arranged","type":"branch","persona":"any","source":"talk before yes","hook":"Your family wants an answer from just his photo and bio, but you'd rather actually talk first.","steps":[{"prompt":"Your mother says the photo and bio already tell you enough. What do you do?","options":[{"text":"Ask to message and call him before deciding anything","then":"Your mother's unsure at first, then agrees it makes sense.","best":true},{"text":"Agree the bio covers what matters","then":"You move toward a decision built on paper, not on him."},{"text":"Say no outright, based on the photo alone","then":"Your mother asks you to message him once before deciding, and sends you his number."},{"text":"Ask a relative who's already met him to vouch instead too","then":"You collect someone else's impression instead of forming your own."}],"why":"Asking to talk first is what brings your own judgement into the decision."},{"prompt":"His family shares his number so you can talk before anything is fixed. What do you send first?","options":[{"text":"A question about what he's looking for in a partner","then":"He answers thoughtfully, and the conversation actually starts to flow.","best":true},{"text":"Small talk about the weather and pleasantries","then":"The chat stays polite and tells you almost nothing."},{"text":"A question about his job, salary and family background","then":"You learn his numbers, and little about the person behind them."},{"text":"Nothing yet, waiting for him to message first","then":"He messages first two days later, and the calls begin slowly."}],"why":"A real question gets you an actual sense of him, not just a polite exchange."},{"prompt":"After a few calls, your family asks if you've 'seen enough' to decide. What do you say?","options":[{"text":"That the calls are exactly how you're actually deciding","then":"They're pleased you're taking it seriously in your own way.","best":true},{"text":"That the photo was really what convinced you","then":"You credit the part that told you the least."},{"text":"That you're basically done talking now","then":"You cut short a process that was finally giving you something real."},{"text":"That you're honestly unsure the calls even matter that much at all","then":"You downplay the one thing that's actually been useful."}],"why":"Naming that the calls are the real basis keeps a photo from quietly deciding for you."},{"prompt":"Ready to give your answer, what does it rest on?","options":[{"text":"How he actually came across in those calls","then":"Whatever you decide, it's built on him, not on a photo.","best":true},{"text":"How good he looked in the photo","then":"You lean on the one thing you were trying to look past."},{"text":"How quickly the calls happened to go","then":"Speed answers a different question than fit does."},{"text":"What the family's first impression of the bio was","then":"Their first impression ends up outweighing your own conversations."}],"why":"Basing your answer on real conversations, not a photo, is what makes it genuinely yours."}],"debrief":"Meeting and talking honestly brings your judgement in; deciding on a photo skips it.","relearn":"Meeting and talking honestly brings judgement; deciding on a photo skips it."},
  {"id":"cb-1098","cat":"love-and-arranged","type":"branch","persona":"any","source":"rush is a flag","hook":"The matchmaker warns that a good proposal like this one 'won't wait around'.","steps":[{"prompt":"She says other families are already interested, so you should move fast. What do you do?","options":[{"text":"Say plainly you'll take the time you need","then":"She's a little put off, but the pressure in her voice eases slightly.","best":true},{"text":"Speed up your side of things to not lose the match","then":"You let someone else's urgency set your own pace."},{"text":"Back out entirely, annoyed by the pressure tactic","then":"You lose the chance to actually judge the match on its own terms."},{"text":"Ask her to handle the rest of the process for you","then":"You hand the pacing, and the decision, over to her instead."}],"why":"Naming that your pace is yours to set is what actually answers the rush."},{"prompt":"A relative repeats that good matches don't come around twice. What do you tell them?","options":[{"text":"That a match worth having can handle you taking real time","then":"They pause, then admit that's actually a fair point.","best":true},{"text":"That they might be right, and you should hurry","then":"You let urgency stand in for your own judgement."},{"text":"That you'll decide today to put the worry to rest","then":"You answer the anxiety, more than the actual question."},{"text":"That you honestly don't care if it's lost, out of frustration","then":"You react to the pressure instead of actually weighing the match."}],"why":"Pointing out that a real match can handle time reframes urgency as the flag it is."},{"prompt":"With the pressure still in the air, how do you actually move through the process?","options":[{"text":"At your own pace, with the talks you need","then":"The rush eases as you keep, calmly, not being rushed by it.","best":true},{"text":"Faster than you'd like, just to be safe","then":"You move on someone else's clock, unsure it was ever yours to keep."},{"text":"By avoiding the topic until it resolves itself","then":"Avoidance doesn't slow the pressure. It just delays your own answer."},{"text":"By deciding quickly so the anxiety stops","then":"The anxiety stops, and so does your chance to actually judge the match."}],"why":"Keeping your own pace, calmly and consistently, is what a match worth having can withstand."}],"debrief":"A match worth having can handle your taking time; rush-pressure is a reason to slow down.","relearn":"In an arranged process you can ask for time; never be rushed."},
  {"id":"cb-1099","cat":"love-and-arranged","type":"branch","persona":"any","source":"couple leads","hook":"Your aunt insists that once the elders decide, what the couple thinks 'doesn't really matter'.","steps":[{"prompt":"She says it plainly at a planning meeting, expecting agreement. What do you do?","options":[{"text":"Say respectfully that your judgement leads this choice","then":"The room goes quiet for a moment, then moves on, point made.","best":true},{"text":"Nod along to avoid an awkward scene in front of everyone","then":"The room takes your silence as agreement with her framing."},{"text":"Argue that elders should have no say at all","then":"The meeting turns into a fight about authority instead of the actual match."},{"text":"Leave the room rather than respond","then":"The comment stands unanswered, and later gets repeated as settled."}],"why":"Naming that your own judgement leads is respectful and clear, without needing a fight."},{"prompt":"Later, your parents ask if you're comfortable letting them handle the rest. What do you say?","options":[{"text":"That you value their help, and still want the final say","then":"They agree, glad you said it plainly rather than staying unsure.","best":true},{"text":"That they should just decide, since they know best","then":"You hand over the decision along with the planning."},{"text":"That you don't trust them to handle any of it","then":"You reject their help instead of simply keeping your own say."},{"text":"That it's fine either way","then":"The vagueness leaves the actual answer unclear to everyone, including you."}],"why":"Saying you want the final say, warmly, keeps consent yours without rejecting their help."},{"prompt":"The match himself asks how decisions get made in your family. What do you tell him?","options":[{"text":"That family is respected, and the two of you still decide","then":"He relaxes, saying he was hoping you'd both actually be asked.","best":true},{"text":"That elders usually decide, and you go along","then":"You describe a process that leaves your own voice out of it."},{"text":"That it varies a lot, without saying where you personally stand","then":"You leave the actual answer for him to guess."},{"text":"That you're not sure how much weight your opinion carries","then":"You hand him an uncertain answer about your own role in this."}],"why":"Telling him plainly that you both decide sets the tone for how you'll decide together."}],"debrief":"Family involvement can be respected, but the couple's own judgement and consent should lead.","relearn":"Family can be respected, but the couple's judgement and consent should lead."},
  {"id":"cb-1100","cat":"love-and-arranged","type":"branch","persona":"any","source":"back her choice","hook":"Your friend Meher confides that her family is pushing a wedding she clearly doesn't want.","steps":[{"prompt":"She tells you quietly that she doesn't know how to say no. What do you do?","options":[{"text":"Tell her the choice is hers to make","then":"She looks relieved just to hear someone say it plainly.","best":true},{"text":"Tell her to just go along with it for now","then":"She hears 'adjust' from you too, on top of everyone else."},{"text":"Say you'll talk to her family yourself","then":"Meher feels it's now out of her hands entirely, in a different way."},{"text":"Change the subject, unsure what to say","then":"She's left carrying it alone, a little more than before."}],"why":"Telling her plainly it's her choice is more useful than staying quiet to avoid discomfort."},{"prompt":"She says her family keeps telling her it's for her own good. What do you say?","options":[{"text":"That no one's 'good' can override her own consent","then":"She holds onto that sentence, repeating it back to herself later.","best":true},{"text":"That families usually do know best, generally","then":"You hand her a general rule that doesn't fit what she just told you."},{"text":"That she should just tell them very clearly to stop","then":"You give advice that skips how hard and risky that feels for her."},{"text":"That it'll probably blow over on its own","then":"You minimise pressure that isn't actually going away by itself."}],"why":"Naming that no one's 'good' overrides her consent gives her words to hold onto."},{"prompt":"She asks if you think she's overreacting. What do you tell her?","options":[{"text":"That it isn't her fault, and her feelings make sense","then":"She tears up, saying she needed to hear that from someone.","best":true},{"text":"That it's probably not as serious as it feels right now","then":"She hears her real fear dismissed as an overreaction."},{"text":"That she should try to see her family's side more","then":"You ask her to carry more of the weight than she already is."},{"text":"That everyone feels pressure before a wedding","then":"You flatten what she's describing into ordinary nerves."}],"why":"Saying it's not her fault answers the fear under the question she actually asked."},{"prompt":"You ask if she's told anyone else. What do you help her do next?","options":[{"text":"Point her to a helpline and a trusted adult outside home","then":"She writes the number down, hands shaking a little, and thanks you.","best":true},{"text":"Suggest she wait a few weeks and see how things unfold","then":"The pressure keeps building while she waits it out alone."},{"text":"Offer to post about it online to build support","then":"It gets attention, without getting her any real, direct help."},{"text":"Say you'll keep her secret and do nothing more","then":"You carry the secret with her, and she's still without real support."}],"why":"A helpline and a trusted adult give her real options, not just sympathy."},{"prompt":"In the weeks after, how do you stay involved as her friend?","options":[{"text":"Check in regularly and keep backing her right to choose","then":"She tells you later that knowing someone was steady beside her mattered.","best":true},{"text":"Step back, assuming she has it handled now","then":"She's left to carry the rest of it more alone than you realised."},{"text":"Push her to make a final decision quickly","then":"You add your own pressure onto everything she's already carrying."},{"text":"Avoid bringing it up again at all, to not stir things further","then":"The silence between you leaves her wondering if you still remember."}],"why":"Staying steadily involved is what actually backs her choice, past the first conversation."}],"debrief":"Encourage friends to choose on their own consent; being forced is never okay, and help exists.","relearn":"Forced marriage is never okay; your consent is required, and help exists (181, 1098, 112)."},
  {"id":"cb-1101","cat":"love-and-arranged","type":"branch","persona":"any","source":"paper isn't fit","hook":"On paper, Naina ticks every box your family wanted, but conversation with her never quite flows.","steps":[{"prompt":"After a third stilted meeting, your mother asks what's holding you back. What do you do?","options":[{"text":"Say honestly that the connection just isn't there yet","then":"Your mother's surprised, since the match looks perfect on paper.","best":true},{"text":"Say nothing's wrong, since you can't name a reason","then":"You leave the real issue unnamed, even to yourself."},{"text":"Blame nerves for how the meetings have gone","then":"You explain away something that might be telling you more."},{"text":"Agree to move forward, since the boxes are all ticked","then":"You let the paperwork outvote what the meetings actually felt like."}],"why":"Saying honestly that the connection isn't there is more useful than explaining it away."},{"prompt":"A friend asks what the meetings with her have actually felt like. What do you tell her?","options":[{"text":"That the conversation just never really flows between you","then":"Saying it plainly, you realise how much that's actually been bothering you.","best":true},{"text":"That everything about her is impressive on paper","then":"You describe the resume again, not the actual meetings."},{"text":"That it'll probably improve once you know each other better","then":"You hope forward instead of naming what's true right now."},{"text":"That you're not sure it's fair to expect instant chemistry","then":"You lower the bar before you've really tested it."}],"why":"Naming what the meetings actually felt like tells you more than the paper ever could."},{"prompt":"The families ask if you're ready to move to the next stage. What do you decide?","options":[{"text":"Ask for one more honest, unstructured conversation first","then":"It goes much the same as before, and you finally have your answer.","best":true},{"text":"Say yes, trusting the fit will grow naturally later","then":"You commit to a hope instead of to what you've actually experienced."},{"text":"Say no immediately, without explaining to anyone why","then":"You close the process without giving the honest reason room to be heard."},{"text":"Ask your family to decide, since you can't quite explain it","then":"The decision moves ahead without the one thing you actually noticed."}],"why":"One more honest conversation tests the connection directly, instead of just hoping for it."}],"debrief":"Suitability on paper isn't the same as fit; you're allowed to weigh how you actually connect.","relearn":"Suitable on paper isn't fit; weigh how you actually connect before deciding."},
  {"id":"cb-1102","cat":"love-and-arranged","type":"branch","persona":"Aditya","source":"same foundations","hook":"You and your partner realise you've never actually talked roles and money, assuming it's 'a married-couple thing'.","steps":[{"prompt":"A friend, recently married, mentions the money talk she had with her husband. What do you do?","options":[{"text":"Realise you and your partner should have that same talk","then":"You bring it up that night, and he agrees it's overdue.","best":true},{"text":"Assume your relationship doesn't need that kind of talk","then":"You skip a conversation that would actually help you both."},{"text":"Feel a little envious of how clear-cut it sounds for her","then":"You compare your path to hers instead of starting your own talk."},{"text":"Decide it's too early in your relationship for that","then":"You wait for a 'right time' that isn't clearly coming."}],"why":"Realising the same big talks apply to you too is what starts the conversation you need."},{"prompt":"You sit down together to talk money. What do you focus on?","options":[{"text":"How you'll each contribute and decide together","then":"You land on something practical that actually fits how you both live.","best":true},{"text":"Whichever of you earns more taking the lead","then":"One of you ends up deciding more than either of you intended."},{"text":"Keeping things loosely undefined for now, to stay flexible","then":"The vagueness feels fine tonight, and murky at the next bill."},{"text":"What a married couple would typically do","then":"You reach for a template that was never quite built with you in mind."}],"why":"Naming a specific, practical plan for money is what makes it real, not just talked about."},{"prompt":"Next, you talk about roles at home. What matters most in that conversation?","options":[{"text":"What feels fair to each of you, without defaulting to a script","then":"You both name things you'd been quietly assuming the other would handle.","best":true},{"text":"Splitting things exactly down the middle by category","then":"The neat split doesn't quite match how you each actually want to live."},{"text":"Letting whoever's more organised take charge","then":"One of you ends up carrying more, simply by default."},{"text":"Avoiding the topic entirely, since you get along fine day to day","then":"The ease today leaves the actual division of work undiscussed."}],"why":"Naming what feels fair, instead of defaulting to a script, builds roles that actually fit you both."},{"prompt":"As you look ahead to married life, how do you feel about these conversations?","options":[{"text":"Steadier, with a plan that's your own","then":"It feels like the foundation of a partnership you actually chose.","best":true},{"text":"Relieved just to have it over with","then":"The relief covers a few things you didn't quite finish deciding."},{"text":"Unsure it was even necessary, in hindsight","then":"You doubt a conversation that quietly did real work."},{"text":"Ready to leave the details loose from here","then":"You step back from a plan you'd only just finished building."}],"why":"Feeling steadier is what a genuinely built, not borrowed, foundation actually gives you."}],"debrief":"Every partnership rests on the same foundations; the big talks belong on every path.","relearn":"Every form of partnership rests on the same foundations; have the big talks."},
  {"id":"cb-1103","cat":"love-and-arranged","type":"branch","persona":"any","source":"a freely-chosen yes","hook":"After two honest meetings with Devika, you feel genuinely ready to say yes.","steps":[{"prompt":"Your family asks if you're ready to move forward. What do you do?","options":[{"text":"Say yes clearly, and that it's your own choice","then":"Your family is glad, and glad to hear you say it's genuinely yours.","best":true},{"text":"Say yes, but credit the families for making it easy","then":"The yes gets framed as everyone else's success more than your own."},{"text":"Hesitate, even though you feel sure, out of habit","then":"Your hesitation reads as doubt you don't actually have."},{"text":"Wait for Devika to say yes first, to be safe","then":"You delay a clear answer that was actually already yours to give."}],"why":"Saying clearly that it's your own choice is what makes a yes actually count as consent."},{"prompt":"A friend asks what made you sure, after only two meetings. What do you tell her?","options":[{"text":"That the conversations were honest, and that convinced you","then":"She nods, saying that sounds like a real reason, not just a fast one.","best":true},{"text":"That two meetings felt like plenty of time, generally","then":"You defend the number instead of naming what actually convinced you."},{"text":"That your family's excitement made the decision easier","then":"You credit their enthusiasm over your own actual reasons."},{"text":"That you didn't want to seem difficult by waiting longer","then":"You explain the yes with something that isn't really why you said it."}],"why":"Naming the honest conversations as your real reason keeps the yes grounded in something true."},{"prompt":"Before the families move ahead, you and Devika get a last private moment. What do you say?","options":[{"text":"That you're choosing this freely, and ask if she is too","then":"She says yes, just as clearly, and you both mean it.","best":true},{"text":"That you assume she feels the same, without asking","then":"You move forward on an assumption instead of hearing it from her."},{"text":"That the families are happy, so it must be right","then":"You lean on everyone else's happiness instead of checking your own."},{"text":"Nothing personal, leaving it to the formal process","then":"A genuinely personal moment passes by unused."}],"why":"Asking her directly makes sure the yes is freely chosen on both sides, not just assumed."}],"debrief":"A real yes is freely chosen after real conversations; that's consent leading on any path.","relearn":"Consent is essential on any path; a real yes is yours to give freely."},
  {"id":"cb-1104","type":"match","hook":"Match each question to what it reveals about a possible match.","relearn":"Asking about goals, conflict style and values reveals real fit.","pairs":[{"left":"\"Where do you see your life in ten years?\"","right":"Long-term goals"},{"left":"\"How do you handle a serious disagreement?\"","right":"Conflict style"},{"left":"\"What matters most to you in a home?\"","right":"Core values"},{"left":"\"How would we split money and chores?\"","right":"Fairness expectations"},{"left":"\"How involved would both families be?\"","right":"Family boundaries"}],"persona":"any","source":"questions reveal fit","cat":"love-and-arranged"},
  {"id":"cb-1105","type":"match","hook":"Match each move to what it shows you about a possible match.","relearn":"Honest talks, shared values and time reveal fit; a photo or deadline reveals little.","pairs":[{"left":"Talking honestly over a few meetings","right":"How you communicate"},{"left":"Comparing what you each care about","right":"Whether your values fit"},{"left":"Asking for time before deciding","right":"That you're choosing freely"},{"left":"Saying yes off one photo","right":"Almost nothing real"},{"left":"Letting a deadline force the call","right":"Only that you felt rushed"}],"persona":"any","source":"what each move shows","cat":"love-and-arranged"},
  {"id":"cb-1106","type":"match","hook":"Match each phrase to what it does to the couple's consent.","relearn":"Suggesting and giving time respects consent; rushing, forcing or silencing overrides it.","pairs":[{"left":"\"Take your time to decide.\"","right":"Respects consent"},{"left":"\"Meet and see how you feel.\"","right":"Invites their judgement"},{"left":"\"We suggested; you two choose.\"","right":"Leaves the choice with them"},{"left":"\"You'll marry whether you like it or not.\"","right":"Forces past their no"},{"left":"\"Your opinion doesn't count here.\"","right":"Silences their voice"}],"persona":"any","source":"respect vs override","cat":"love-and-arranged"},
  {"id":"cb-1107","type":"match","hook":"Match each route to who it helps with a coercion or marriage problem.","relearn":"Forced-marriage routes are 181, 1091, 112; a couples counsellor helps a struggling marriage.","pairs":[{"left":"Women Helpline","right":"181"},{"left":"Women in distress","right":"1091"},{"left":"Emergency","right":"112"},{"left":"Childline","right":"1098"},{"left":"Struggling partnership","right":"A couples counsellor"}],"persona":"any","source":"help routes","cat":"love-and-arranged"},
  {"id":"cb-1108","type":"match","hook":"Match each foundation to why both love and arranged paths need it.","relearn":"Both paths rest on values, communication, consent and compatibility.","pairs":[{"left":"Shared values","right":"Keeps you aligned long-term"},{"left":"Honest communication","right":"Lets you repair after conflict"},{"left":"Free consent","right":"Makes the choice truly yours"},{"left":"Practical compatibility","right":"Helps daily life fit together"},{"left":"Mutual respect","right":"Holds the bond under stress"}],"persona":"any","source":"same foundations","cat":"love-and-arranged"},
  {"id":"cb-1109","type":"match","hook":"Match each reason to commit with what kind of reason it is.","relearn":"Choosing the person after real talks is sound; pressure, age or fear is shaky.","pairs":[{"left":"\"We've talked the big things through.\"","right":"Sound: eyes-open"},{"left":"\"I genuinely choose this person.\"","right":"Sound: free choice"},{"left":"\"Everyone my age is settling down.\"","right":"Shaky: timeline pressure"},{"left":"\"I'm scared of being alone.\"","right":"Shaky: fear of loneliness"},{"left":"\"Relatives will stop asking.\"","right":"Shaky: social pressure"}],"persona":"any","source":"sound vs shaky","cat":"love-and-arranged"},
  {"id":"cb-1110","type":"match","hook":"Match each kind of family input to what it does for the couple.","relearn":"Suggesting and welcoming supports the couple; deciding for them or forcing overreaches.","pairs":[{"left":"Suggesting someone to meet","right":"Opens a door"},{"left":"Welcoming your chosen partner","right":"Backs your choice"},{"left":"Giving you time to decide","right":"Respects your pace"},{"left":"Deciding the answer for you","right":"Takes over the choice"},{"left":"Forcing a date past your no","right":"Overrides your consent"}],"persona":"any","source":"support vs overreach","cat":"love-and-arranged"},
  {"id":"cb-1111","cat":"love-and-arranged","type":"role-play","persona":"any","source":"ask for real talks","hook":"Your mother has a match ready, Vidya, and wants your answer before guests arrive tonight.","setup":"She shows you the biodata, eager for a yes.","steps":[{"prompt":"Your mother asks: \"So? Isn't she lovely? Should I tell them yes tonight?\"","options":[{"text":"\"I'm glad you found her. I'd like a couple of real talks first.\"","then":"She pauses. \"Talks? I suppose that's reasonable, actually.\"","best":true},{"text":"\"Sure, if everyone thinks she's right, let's just say yes tonight.\"","then":"She beams and picks up the phone, then hesitates."},{"text":"\"I don't even know her, how can I say yes?\"","then":"She sighs. \"That's what the talks are for, later. Just say yes for now.\""},{"text":"\"Why is everyone in such a rush about this?\"","then":"She shrugs. \"Good families don't wait around forever, beta.\""}],"why":"Naming real talks as the next step, not a yes, keeps the pace actually yours."},{"prompt":"Before calling anyone back, she asks: \"What is there to even talk about? The families agree.\"","options":[{"text":"\"Whether we actually get along and want the same things.\"","then":"She considers this. \"I suppose that matters more than I gave it credit for.\"","best":true},{"text":"\"I just want to feel a little more sure before anything's decided.\"","then":"She nods, but presses: \"Sure of what, exactly, beta?\""},{"text":"\"The families agreeing doesn't mean much to me, honestly.\"","then":"She looks wounded. \"It means everything to this family.\""},{"text":"\"Fine, maybe there's nothing more to know.\"","then":"She reaches for her phone, then pauses: \"Are you sure, though?\""}],"why":"Naming what the talks are actually for makes the request concrete, not stalling."},{"prompt":"Your mother asks: \"Alright. How many talks, and how long will this take?\"","options":[{"text":"\"A couple of real conversations, over the next two or three weeks.\"","then":"She nods. \"Alright, I can tell them that much. Not too long, then.\"","best":true},{"text":"\"I'm not totally sure yet, maybe just a little longer than usual.\"","then":"She looks uneasy. \"That's hard to tell them, but alright, I suppose.\""},{"text":"\"However long it naturally takes, I guess.\"","then":"She frowns. \"That's not something I can tell them, beta.\""},{"text":"\"Let's just say one conversation should be enough.\"","then":"She agrees, though one talk barely tells you anything real."}],"why":"A clear number and timeframe turns the request into something everyone can plan around."},{"prompt":"Your mother says, phone in hand: \"Vidya's family is asking to finalise everything within the week.\"","options":[{"text":"\"Let's tell them the same plan: a couple of real talks, then we'll see.\"","then":"She nods and repeats it into the phone. \"Alright. They've agreed to wait.\"","best":true},{"text":"\"Maybe we should just speed things up a little to keep them happy.\"","then":"She relays a faster timeline, and your earlier request quietly shrinks."},{"text":"\"Tell them to stop rushing. It's honestly getting annoying now.\"","then":"She hesitates on the phone, unsure how to soften that for them."},{"text":"\"Just tell them whatever gets them to stop calling.\"","then":"She sighs and makes a vague promise she isn't sure she can keep."}],"why":"Holding the same plan under new pressure shows it was a real request, not a mood."}],"relearn":"You can warmly ask for real conversations before deciding on a match."},
  {"id":"cb-1112","cat":"love-and-arranged","type":"role-play","persona":"any","source":"respectful no","hook":"After meeting the family once, your Tau says declining now would shame everyone.","setup":"He says it sternly, expecting you to back down.","steps":[{"prompt":"Tau says: \"You cannot say no now. It will shame this whole family.\"","options":[{"text":"\"I respect you, but this isn't the right fit. That's my answer.\"","then":"He frowns hard, but says nothing more for a moment.","best":true},{"text":"\"I'm so sorry, maybe I should just accept it to avoid trouble.\"","then":"He nods, satisfied, and starts planning the next steps immediately."},{"text":"\"Fine, I'll do it, if it keeps the peace.\"","then":"He relaxes. \"Good. That's the sensible choice, beta.\""},{"text":"\"Since when do I need your permission to say no?\"","then":"He stiffens. \"Since your choices affect this whole family.\""}],"why":"Naming your answer as final, with respect, doesn't leave it open to pressure."},{"prompt":"Tau presses: \"If you say no, what will I even tell them? It would embarrass me.\"","options":[{"text":"\"Tell them honestly it wasn't the right match. That's the truth.\"","then":"He sighs heavily. \"The truth. Fine. I suppose that's something.\"","best":true},{"text":"\"Tell them whatever softens it. I don't mind what you say to them.\"","then":"He nods, already composing a softer story about your no."},{"text":"\"That's your problem to handle, not mine.\"","then":"He looks furious. \"You are unbelievably selfish, you know that?\""},{"text":"\"Tell them I said yes, and I'll deal with it later somehow.\"","then":"He hesitates: \"And when you back out later?\""}],"why":"Offering the honest reason protects you without asking him to lie for you."},{"prompt":"Tau says, quieter now: \"This family has never had a refusal like this before.\"","options":[{"text":"\"Then I suppose I'm the first. My consent is still mine to give.\"","then":"He's quiet for a long moment. \"I hadn't thought of it quite that way.\"","best":true},{"text":"\"I know, and I do feel bad about breaking that pattern first.\"","then":"He nods, and the guilt sits there, unaddressed and heavy."},{"text":"\"That's not really my concern, honestly.\"","then":"He looks stung. \"It should be. This is still your family.\""},{"text":"\"Maybe I should have just said yes to avoid all this.\"","then":"He brightens slightly. \"It's not too late to reconsider, you know.\""}],"why":"Naming consent as yours, even as a first, holds the boundary without shame."},{"prompt":"Later, your mother asks quietly: \"Are you alright? Tau can be harsh.\"","options":[{"text":"\"I'm okay. I just need my decision respected, even if it's hard for him.\"","then":"She squeezes your hand. \"It is. I respect it too, for what that's worth.\"","best":true},{"text":"\"I'm fine, I suppose, though I do still feel a little guilty about the whole thing.\"","then":"She nods gently. \"You don't need to feel guilty for choosing, you know.\""},{"text":"\"Can you talk to him for me, smooth things over?\"","then":"She hesitates. \"I can try, though he doesn't always listen to me either.\""},{"text":"\"Honestly, I'm dreading the next family gathering already.\"","then":"She looks concerned. \"Don't let him make you dread your own family.\""}],"why":"Naming respect as what you need, plainly, turns private guilt into shared support."}],"relearn":"You can decline a match with respect; your consent is yours to give."},
  {"id":"cb-1113","cat":"love-and-arranged","type":"role-play","persona":"Sneha","source":"own timeline","hook":"Your parents have a growing stack of biodata on the dining table.","setup":"She lays another on the table, hopeful.","steps":[{"prompt":"Your mother asks: \"Why haven't you settled down? This one seems perfect.\"","options":[{"text":"\"I'll commit when I choose someone, not to match a timeline.\"","then":"She sighs. \"I just want to see you happy and settled, that's all.\"","best":true},{"text":"\"I'm working on it. These things just take some time, Ma.\"","then":"She nods, half-satisfied, and adds another biodata to the pile anyway."},{"text":"\"I don't know. I guess I'm just bad at this.\"","then":"She looks concerned. \"Bad at it? There's nothing wrong with you.\""},{"text":"\"Stop bringing me these, I'm not interested.\"","then":"She looks hurt. \"I'm only trying to help you, you know.\""}],"why":"Naming choosing, not a deadline, as your standard answers her without shutting her out."},{"prompt":"She asks: \"But don't you want to be happy and settled, like your cousins?\"","options":[{"text":"\"I do want that, when it's genuinely right, not on their timeline.\"","then":"She pauses. \"Their timeline, hm. I suppose that's a fair point.\"","best":true},{"text":"\"I do, and seeing them settled makes me feel a bit behind, honestly.\"","then":"She nods sympathetically. \"There, see, so why not just try harder, then?\""},{"text":"\"Happiness doesn't really need a husband, Ma.\"","then":"She looks wounded. \"I didn't say it did. I just want good things for you.\""},{"text":"\"Sure, I want that too, I suppose.\"","then":"She brightens. \"So let's actually look at these properly, then!\""}],"why":"Wanting it on your own timeline, not comparison, keeps the choice genuinely yours."},{"prompt":"Your mother asks, softer: \"So how will you even know when it's right?\"","options":[{"text":"\"When someone's values actually fit mine. That's the real marker.\"","then":"She nods slowly. \"That's actually a good way to think about it, beta.\"","best":true},{"text":"\"I suppose I'll just know somehow when the right one shows up.\"","then":"She smiles. \"Well, let these help that along a little, hm?\""},{"text":"\"I don't know. I haven't really thought about it.\"","then":"She shakes her head. \"You should think about it, you know.\""},{"text":"\"Whenever everyone finally stops asking me this.\"","then":"She laughs softly. \"Fair, though that could be a while yet.\""}],"why":"Naming values as the marker, not timing or family opinion, protects your pace."}],"relearn":"Your timeline is your own; commit when you choose the person, not the deadline."},
  {"id":"cb-1114","cat":"love-and-arranged","type":"role-play","persona":"any","source":"ask real questions","hook":"Your families have arranged a meeting with Devika, and small talk is running dry.","setup":"The families step away, leaving cold tea.","steps":[{"prompt":"Devika says: \"So... nice weather we're having?\"","options":[{"text":"\"Can I actually ask something real? How do you handle a disagreement?\"","then":"She laughs, relieved. \"Please. Yes. I get quiet, honestly, then think it over.\"","best":true},{"text":"\"Sure, lovely weather, and this tea is nice too, isn't it?\"","then":"She nods, and the conversation stays pleasant and completely surface-level."},{"text":"\"I suppose our families have covered the important stuff already.\"","then":"She shrugs. \"I guess so.\" Neither of you says much more."},{"text":"\"Are you nervous too? This is a bit strange, right?\"","then":"She laughs. \"A little.\" The real questions stay unasked, though."}],"why":"Naming a real question breaks the small talk and actually tests compatibility."},{"prompt":"Devika asks: \"Fair, your turn then. What about money, how do you see that working?\"","options":[{"text":"\"Shared and openly discussed, not assumed by either side.\"","then":"She nods, pleased. \"That's exactly how I'd want it too, honestly.\"","best":true},{"text":"\"I haven't really thought that far ahead yet, if I'm honest.\"","then":"She nods, though neither of you actually says where you stand."},{"text":"\"Whoever earns more should probably decide, I'd think.\"","then":"She pauses. \"Hm. I'm not sure I agree with that, actually.\""},{"text":"\"Let's not talk money, it feels a bit too soon.\"","then":"She nods, though the question quietly stays unanswered."}],"why":"Naming shared and open, plainly, tests real compatibility on something that matters."},{"prompt":"Devika asks: \"One more, if that's okay. What about family, how involved would they be?\"","options":[{"text":"\"Respected, but us as a couple making the final calls together.\"","then":"She smiles. \"That's exactly the balance I'm hoping for too.\"","best":true},{"text":"\"However involved they want to be, I suppose, since they know best.\"","then":"She looks uncertain, unsure how much say she'd actually have."},{"text":"\"Very involved, family comes first in everything, always.\"","then":"She hesitates. \"Always? Even over what we'd decide together?\""},{"text":"\"Not involved at all, honestly, that's between us.\"","then":"She looks surprised. \"Not at all? That feels like a lot to shut out.\""}],"why":"Naming respected but not overriding names a real, workable balance."}],"relearn":"Asking about goals, conflict style and values reveals real fit in a match."},
  {"id":"cb-1115","cat":"love-and-arranged","type":"role-play","persona":"Aditya","source":"it's real","hook":"Your Chachi posts in the family group that your partnership with Dev 'isn't real'.","setup":"Everyone can see it, parents included.","steps":[{"prompt":"Chachi writes in the group: \"Let's be honest, two men can't have a real marriage.\"","options":[{"text":"\"Our marriage is real. It rests on the same love as anyone's.\"","then":"The group goes quiet a moment, then your cousin sends a supportive reply.","best":true},{"text":"\"I don't think this needs debating in a family group chat.\"","then":"Chachi repeats her point, undeterred, and the message stays unanswered."},{"text":"\"Maybe she has a point, in a way.\"","then":"Your father sends a concerned message, unsure if you actually mean that."},{"text":"\"Can everyone please just stop replying to this.\"","then":"The group goes quiet, but Chachi's message stays there, unanswered."}],"why":"Naming your family as real, plainly and publicly, meets the dismissal in the open."},{"prompt":"She writes again: \"No offence, but marriage means a husband and a wife.\"","options":[{"text":"\"None taken, and we're just two equal partners, like any couple.\"","then":"She doesn't reply, but your mother sends a heart in response instead.","best":true},{"text":"\"That's a fairly narrow way to define it, honestly, but okay.\"","then":"Chachi replies defensively, and the thread turns tense for a while."},{"text":"\"I guess I do handle more of the traditional roles, if that helps.\"","then":"She replies \"There, see!\" pleased that it fits her framing."},{"text":"\"Does the wording really matter that much?\"","then":"She replies: \"It matters to me. Words matter.\""}],"why":"Naming equal partnership, not roles, corrects the frame without matching her tone."},{"prompt":"Later, your father calls privately and asks: \"Are you doing alright, after all that?\"","options":[{"text":"\"I'm okay. Her view isn't the only one in this family.\"","then":"He's quiet a moment. \"It isn't. Not to your mother or me, either.\"","best":true},{"text":"\"I'm used to comments like that by now, so it's honestly fine.\"","then":"He sounds sad. \"You shouldn't have to be used to it, though.\""},{"text":"\"Can you ask her to stop posting things like that?\"","then":"He sighs. \"I can try. She doesn't always listen, even to me.\""},{"text":"\"Honestly, I might just leave that group chat.\"","then":"He sounds concerned. \"I don't want you to feel pushed out.\""}],"why":"Naming it plainly to someone on your side turns a public hurt into shared ground."}],"relearn":"Your partnership is real and built on the same foundations as any; hold that with dignity."},
  {"id":"cb-1116","cat":"love-and-arranged","type":"role-play","persona":"any","source":"name the coercion","hook":"Your family has set a wedding date with a man you've never agreed to marry.","setup":"Tonight your father calls you into the living room.","steps":[{"prompt":"Your father says: \"The priest is booked. Next month, it's decided.\"","options":[{"text":"\"I haven't agreed to this. We need to stop and talk.\"","then":"He frowns. \"There's nothing to talk about. It's already decided.\"","best":true},{"text":"\"I guess it's already decided, then.\"","then":"He nods, but notices your face and stays a moment longer."},{"text":"\"Fine, let's just do it. I'll figure it out somehow.\"","then":"He hears the flatness in your voice and frowns."},{"text":"\"Maybe it won't be so bad, I don't know.\"","then":"He hears the doubt and sits back down."}],"why":"Naming your lack of consent plainly, out loud, is the first real step toward help."},{"prompt":"Your father says, firmer: \"Every family does this. You'll come around.\"","options":[{"text":"\"No one can force a marriage. I need help, not more pressure.\"","then":"He looks startled by the word help, and for once says nothing back.","best":true},{"text":"\"Maybe you're right. I'll come around eventually.\"","then":"He relaxes and leaves the room, certain the matter is settled."},{"text":"\"Fine, I'll go through with all of it, just to keep the peace for now.\"","then":"He nods, pleased, and tells your mother it's settled."},{"text":"\"I don't have a choice here anyway, do I.\"","then":"He shrugs. \"Exactly. So let's not make this harder than it needs to be.\""}],"why":"Naming it as forced and asking for help changes what happens next; none of this is your fault."},{"prompt":"Later that night, you message your cousin Alia, who asks: \"Hey, you okay? You went quiet in the chat.\"","options":[{"text":"\"Not really. I'm being pushed into a wedding I haven't agreed to.\"","then":"She replies fast: \"Okay, that's serious. Let's figure out what to do, now.\"","best":true},{"text":"\"I'm fine. Just tired after the whole family dinner.\"","then":"She sends a heart emoji and logs off, none the wiser."},{"text":"\"Family stuff. It's complicated, so just forget I went quiet.\"","then":"She offers to listen if you ever want to talk, then moves on."},{"text":"\"I probably just have to go through with it.\"","then":"She hesitates. \"That doesn't sound like nothing. Are you sure?\""}],"why":"Naming it plainly to someone you trust turns a private fear into something to act on."},{"prompt":"Alia says: \"I heard they're fixing a date. If you're not okay with it, want help finding someone to call?\"","options":[{"text":"\"Yes, please. I don't know who to call, but I need help.\"","then":"She stays on the phone with you while you look up the numbers together.","best":true},{"text":"\"Maybe, let me think about it a bit more first.\"","then":"She agrees to wait, but sends you the numbers anyway, just in case."},{"text":"\"I can handle it myself. I don't want to be a burden.\"","then":"She says gently: \"You're not a burden. Please let me help.\""},{"text":"\"It's fine. I was probably overreacting earlier.\"","then":"She sounds unconvinced and looks up the numbers anyway."}],"why":"Accepting help, and naming that you need it, is the safe next step, not a burden."},{"prompt":"Alia reads aloud: \"There's Women Helpline 181, or 112 for emergency. Which one?\"","options":[{"text":"\"181. I want to talk about my options right now.\"","then":"The call connects. A calm voice says: \"You reached out. Let's talk.\"","best":true},{"text":"\"None of them, maybe I should just wait and see.\"","then":"Alia stays close, gently keeping the numbers ready for whenever you're ready."},{"text":"\"I don't know, this all feels too big.\"","then":"Alia says softly: \"It is big. That's exactly why we call. I'm right here.\""},{"text":"\"Let's just try talking to my father again instead.\"","then":"Alia nods. \"We can, but let's have help lined up either way.\""}],"why":"Calling 181 turns fear into a concrete next step, with someone on your side."}],"relearn":"Being forced is never your fault; your consent is required, and help exists (181, 1098, 112)."},
  {"id":"cb-1117","cat":"love-and-arranged","type":"role-play","persona":"any","source":"insist on talks","hook":"The other family wants to finalise everything without you and Rhea ever talking.","setup":"Your mother relays the request.","steps":[{"prompt":"Your mother says: \"They want to skip ahead, the families know each other well.\"","options":[{"text":"\"I'd still like a couple of real conversations with her first.\"","then":"Your mother nods. \"That's fair. I'll tell them. Should be no issue.\"","best":true},{"text":"\"If the families know each other that well, that's probably enough.\"","then":"She relays it, but Rhea's family asks if you two want to meet first."},{"text":"\"Whatever's easiest, I really don't mind either way.\"","then":"She says it's settled, and they ask if you'd like to meet Rhea anyway."},{"text":"\"Isn't that a bit unusual, skipping that part?\"","then":"She shrugs. \"Maybe, but it happens. Up to you, though.\""}],"why":"Naming the talks as something that matters to you keeps your judgement in it."},{"prompt":"She adds: \"They did say it might seem forward, meeting one-on-one so soon.\"","options":[{"text":"\"That's alright. Honest talks matter more than moving fast.\"","then":"Your mother relays it, and to her surprise, the other family agrees easily.","best":true},{"text":"\"Maybe they're right. It could look a little strange to everyone.\"","then":"Your mother nods, and quietly lets the idea drop instead."},{"text":"\"Fine, let's not make it awkward for anyone then.\"","then":"She looks relieved, and the plan moves ahead without you meeting Rhea."},{"text":"\"Tell them I don't care what it looks like.\"","then":"She hesitates. \"I'll say it more gently than that, alright?\""}],"why":"Choosing honest talks over appearances keeps the decision grounded in something real."},{"prompt":"A week later, Rhea calls: \"Hi. I thought we should talk before anything's final.\"","options":[{"text":"\"Me too. I wanted us to know each other before anything's decided.\"","then":"She laughs, relieved. \"Same, honestly. Where do we even start?\"","best":true},{"text":"\"Yeah, it seemed like the sensible thing to do, given everything.\"","then":"She laughs politely, though the conversation stays a little formal."},{"text":"\"Honestly, our families probably know best anyway.\"","then":"She sounds surprised. \"Oh. I thought you wanted to talk, though?\""},{"text":"\"I don't really know what to say now that we're on the phone.\"","then":"She laughs. \"Me neither. Let's just start somewhere, I guess.\""}],"why":"Naming why the talks matter to you sets an honest, equal tone for the conversation."}],"relearn":"Meeting and talking honestly brings your judgement in; you're allowed to ask for it."},
  {"id":"cb-1118","type":"reflect","hook":"On any path, love or arranged, the yes or no is yours to give, in your own time.","prompt":"What helps you feel sure a yes is really yours?","options":["Having time to think it over","Knowing I could say no","Talking it through with them","Hearing my own voice, not just others'"],"affirm":"On any path, your consent and your timeline are genuinely your own.","relearn":"On any path, your consent and your timeline are your own.","persona":"any","source":"yours to give","cat":"love-and-arranged"},
  {"id":"cb-1119","cat":"love-and-arranged","type":"choose","persona":"any","source":"same things","hook":"Gurpreet's marriage was arranged, and his best friend's began with falling in love.","prompt":"What does every good marriage need?","options":[{"text":"Shared values about the big things","fits":true,"note":"Whatever the start, aligned values are what marriages run on."},{"text":"Honest conversations, even hard ones","fits":true,"note":"Every path needs real talk, not just harmony on the surface."},{"text":"Respect for each other as equals","fits":true,"note":"Respect has to be there no matter how the couple met."},{"text":"Ongoing consent, not just a first yes","fits":true,"note":"Choosing each other keeps mattering long after the wedding."},{"text":"Falling in love before the wedding","fits":false,"note":"Lovely for many, though it isn't what a marriage runs on later."},{"text":"Families arranging the introduction","fits":false,"note":"A fine way to meet, but it isn't what keeps a marriage strong."}],"relearn":"Love and arranged marriages both need the same foundations to work."},
  {"id":"cb-1120","cat":"love-and-arranged","type":"choose","persona":"any","source":"time isn't rude","hook":"Rashmi's family showed her a proposal, and she wants a little more time before deciding.","prompt":"What's a fair way for her to ask for time?","options":[{"text":"Telling them she needs a few more weeks","fits":true,"note":"Naming a clear amount of time is direct and fair to everyone."},{"text":"Saying plainly she isn't sure yet","fits":true,"note":"Honesty about not being ready is a completely fair answer."},{"text":"Asking to meet him again before deciding","fits":true,"note":"More meetings give her what she needs to decide, and that's a fair ask."},{"text":"Avoiding the topic when it comes up","fits":false,"note":"Dodging it leaves everyone guessing, including her."},{"text":"Saying yes now and hoping it works out","fits":false,"note":"A yes said to buy time isn't the answer she means."},{"text":"Letting her parents decide for her","fits":false,"note":"That hands away a decision that's hers to make."}],"relearn":"Asking for time in an arranged process is choosing well, not being rude."},
  {"id":"cb-1121","cat":"love-and-arranged","type":"choose","persona":"any","source":"paper vs person","hook":"Mohit's parents found a biodata that ticks every box he listed.","prompt":"What does he still need to find out?","options":[{"text":"Whether they make each other laugh","fits":true,"note":"No biodata can show whether two people enjoy each other."},{"text":"How they handle a disagreement","fits":true,"note":"Paper can't show how someone behaves when things get tense."},{"text":"What she hopes married life looks like","fits":true,"note":"Her hopes for daily life together aren't on any form."},{"text":"Her salary","fits":false,"note":"That's already on the biodata, and it won't tell him whether they get along."},{"text":"Her height","fits":false,"note":"Already on paper, and it says nothing about fit."},{"text":"Her educational qualifications","fits":false,"note":"Already known from the biodata; degrees say little about daily life together."}],"relearn":"Suitable on paper isn't the same as fit; you're allowed to look deeper."},
  {"id":"cb-1122","cat":"love-and-arranged","type":"choose","persona":"Sneha","source":"single is valid","hook":"Sneha is in her thirties, and relatives keep asking why she still hasn't married.","prompt":"What's actually true about her life?","options":[{"text":"She can be happy exactly as she is","fits":true,"note":"Happiness isn't waiting on a wedding; it's available now."},{"text":"Being single isn't a problem to fix","fits":true,"note":"Single is a full way to live, not something that needs solving."},{"text":"She must care only about her career","fits":false,"note":"That's a guess about her reasons, not a fact about her life."},{"text":"She's being too picky","fits":false,"note":"A common jibe, but wanting the right fit isn't a flaw."},{"text":"She'll regret it one day","fits":false,"note":"That's a fear others project onto her, not a fact about her life."},{"text":"Her real life starts at the wedding","fits":false,"note":"Her life is already real, married or not."}],"relearn":"Not marrying, or not yet, is a fully valid choice."},
  {"id":"cb-1123","type":"reflect","hook":"Your partnership counts, whether or not the law and relatives have caught up.","prompt":"What makes a partnership feel real to you?","options":["The care we show each other","The life we build day to day","Friends who welcome us","Knowing we chose each other"],"affirm":"Many valid forms of partnership and family are real, on the same foundations as any.","relearn":"Many valid forms of partnership and family are real and equal.","persona":"Aditya","source":"it counts","cat":"love-and-arranged"},
  {"id":"cb-1124","cat":"love-and-arranged","type":"choose","persona":"any","source":"deciding is yours","hook":"Farhan and Zara's families are excited about the match and keen to help things along.","prompt":"Which of these respects their decision?","options":[{"text":"Families sharing their honest opinion","fits":true,"note":"Sharing a view is welcome as long as the choice stays theirs."},{"text":"Families waiting to hear their answer","fits":true,"note":"Waiting for their answer is what respecting the decision looks like."},{"text":"Families blessing whatever they choose","fits":true,"note":"Support that doesn't depend on the answer leaves the choice with them."},{"text":"Families fixing the wedding date already","fits":false,"note":"That skips past a yes the couple hasn't given yet."},{"text":"Families telling them this is the one","fits":false,"note":"Meant kindly, but it nudges the decision instead of leaving it to them."},{"text":"Families announcing it to relatives","fits":false,"note":"Telling everyone before the couple decides puts pressure on their answer."}],"relearn":"Family can be respected; the couple's own judgement and consent should lead."},
  {"id":"cb-1125","cat":"love-and-arranged","type":"choose","persona":"any","source":"meeting isn't marrying","hook":"Priya agreed to meet Nitin again after their first introduction.","prompt":"What has she actually said yes to?","options":[{"text":"One more conversation with him","fits":true,"note":"That's exactly what she agreed to, nothing more yet."},{"text":"Getting to know him a little more","fits":true,"note":"A second meeting is for learning more, not for deciding everything."},{"text":"Marrying him","fits":false,"note":"That's a much bigger yes than the one she's actually given."},{"text":"Getting engaged","fits":false,"note":"An engagement is a separate step she hasn't agreed to."},{"text":"Her family announcing it","fits":false,"note":"Telling relatives is way ahead of what she's said yes to."},{"text":"Ending the search for anyone else","fits":false,"note":"One more meeting doesn't mean she's decided to stop looking."}],"relearn":"Agreeing to meet again is a separate yes from agreeing to marry."},
  {"id":"cb-1126","cat":"love-and-arranged","type":"choose","persona":"any","source":"kind to ask","hook":"Neha and Imran are getting to know each other in their first few meetings.","prompt":"Which questions are kind to ask early?","options":[{"text":"How do you want to handle money?","fits":true,"note":"A fair, practical question that helps both of them plan ahead."},{"text":"Do you want children, and when?","fits":true,"note":"Talking honestly about children early helps them both see clearly."},{"text":"Where do you picture us living?","fits":true,"note":"Where and with whom they'd live is a big, fair thing to know early."},{"text":"How much do your parents own?","fits":false,"note":"That's about family wealth, not about the two of them."},{"text":"Will you give up your job after marriage?","fits":false,"note":"It assumes an answer about someone else's career instead of asking what they want."},{"text":"Can you promise you'll never change?","fits":false,"note":"Sounds romantic, but everyone grows, so the promise sets them both up to fail."}],"relearn":"Asking about goals, money and values early is kind, not unromantic."},
  {"id":"cb-1127","cat":"love-and-arranged","type":"choose","persona":"any","source":"two whole people","hook":"Rekha is close to saying yes to Aman, and wants to be sure it's really her choice.","prompt":"What does choosing him freely look like?","options":[{"text":"Wanting this, not just accepting it","fits":true,"note":"Genuinely wanting it is different from simply going along."},{"text":"Knowing she could still say no","fits":true,"note":"A real yes needs a real no sitting right beside it."},{"text":"Seeing him for who he really is","fits":true,"note":"Choosing the real person, not an idea of him, is part of a free choice."},{"text":"Her parents approving of him","fits":false,"note":"Their approval is nice, but it isn't the same as her wanting it."},{"text":"Feeling she should decide by now","fits":false,"note":"Pressure to hurry isn't the same as being ready."},{"text":"Having time to think it over","fits":true,"note":"A choice made without a rush is easier to call her own."}],"relearn":"On any path, the aim is two whole people choosing each other freely."},
  {"id":"cb-1128","type":"sort","hook":"Sort each line: respects the couple's consent, or overrides it?","items":[{"id":"a","text":"\"Meet and see how you feel.\""},{"id":"b","text":"\"Take all the time you need.\""},{"id":"c","text":"\"We suggested; you two decide.\""},{"id":"d","text":"\"You'll marry whether you like it or not.\""},{"id":"e","text":"\"Your opinion doesn't count here.\""},{"id":"f","text":"\"It's fixed; backing out isn't allowed.\""}],"bins":[{"id":"respects","label":"Respects consent","valence":"pos"},{"id":"overrides","label":"Overrides consent","valence":"neg"}],"key":{"a":"respects","b":"respects","c":"respects","d":"overrides","e":"overrides","f":"overrides"},"relearn":"Suggesting and giving time respects the couple; forcing or silencing them overrides consent.","persona":"any","source":"respect vs override","cat":"love-and-arranged"},
  {"id":"cb-1129","type":"sort","hook":"Sort each reason to commit: sound, or shaky?","items":[{"id":"a","text":"\"I genuinely choose this person.\""},{"id":"b","text":"\"We've talked the big things through.\""},{"id":"c","text":"\"We agree on values and conflict.\""},{"id":"d","text":"\"Everyone my age is settling down.\""},{"id":"e","text":"\"I'm scared of being alone.\""},{"id":"f","text":"\"Relatives will finally stop asking.\""}],"bins":[{"id":"sound","label":"Sound reason","valence":"pos"},{"id":"shaky","label":"Shaky reason","valence":"neg"}],"key":{"a":"sound","b":"sound","c":"sound","d":"shaky","e":"shaky","f":"shaky"},"relearn":"Choosing the person after real talks is sound; pressure, age and fear-of-alone are shaky.","persona":"any","source":"sound vs shaky","cat":"love-and-arranged"},
  {"id":"cb-1130","type":"sort","hook":"Sort each move in a match: brings real judgement, or skips it?","items":[{"id":"a","text":"Talking honestly over a few meetings"},{"id":"b","text":"Checking how your values line up"},{"id":"c","text":"Asking the big questions early"},{"id":"d","text":"Saying yes off a single photo"},{"id":"e","text":"Letting a deadline force the call"},{"id":"f","text":"Skipping every awkward topic"}],"bins":[{"id":"brings","label":"Brings judgement","valence":"pos"},{"id":"skips","label":"Skips judgement","valence":"neg"}],"key":{"a":"brings","b":"brings","c":"brings","d":"skips","e":"skips","f":"skips"},"relearn":"Meeting, talking and checking values brings judgement; deciding on a photo or deadline skips it.","persona":"any","source":"judgement vs skipping","cat":"love-and-arranged"},
  {"id":"cb-1131","type":"sort","hook":"Sort each foundation: needed on both love and arranged paths, or not a true foundation?","items":[{"id":"a","text":"Shared values"},{"id":"b","text":"Honest communication"},{"id":"c","text":"Free consent"},{"id":"d","text":"Matching the photo's looks"},{"id":"e","text":"Speed of the decision"},{"id":"f","text":"How much money was spent"}],"bins":[{"id":"foundation","label":"True foundation","valence":"pos"},{"id":"notreal","label":"Not a foundation","valence":"neg"}],"key":{"a":"foundation","b":"foundation","c":"foundation","d":"notreal","e":"notreal","f":"notreal"},"relearn":"Values, communication and consent are real foundations; looks, speed and spend are not.","persona":"any","source":"true foundations","cat":"love-and-arranged"},
  {"id":"cb-1132","type":"sort","hook":"Sort each family act: healthy support, or overreach into the couple's choice?","items":[{"id":"a","text":"Suggesting someone to meet"},{"id":"b","text":"Welcoming your chosen partner"},{"id":"c","text":"Giving you time to decide"},{"id":"d","text":"Deciding the answer for you"},{"id":"e","text":"Forcing a date past your no"},{"id":"f","text":"Silencing your questions"}],"bins":[{"id":"support","label":"Healthy support","valence":"pos"},{"id":"overreach","label":"Overreach","valence":"neg"}],"key":{"a":"support","b":"support","c":"support","d":"overreach","e":"overreach","f":"overreach"},"relearn":"Suggesting, welcoming and giving time supports the couple; deciding or forcing is overreach.","persona":"any","source":"support vs overreach","cat":"love-and-arranged"},
  {"id":"cb-1133","type":"sort","hook":"Sort each line a partner says in a match: green flag, or red flag?","items":[{"id":"a","text":"\"Take your time; no rush from me.\""},{"id":"b","text":"\"Let's talk about how we'd handle money.\""},{"id":"c","text":"\"I want to know what you actually think.\""},{"id":"d","text":"\"Your friends are a waste of your time.\""},{"id":"e","text":"\"You'll do as I say once we marry.\""},{"id":"f","text":"\"I'll decide; you don't need to.\""}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"green","c":"green","d":"red","e":"red","f":"red"},"relearn":"Patience, openness and respect are green flags; control and contempt are red flags, on any path.","persona":"any","source":"green vs red","cat":"love-and-arranged"},
  {"id":"cb-1134","type":"sort","hook":"Sort each statement about consent and timing: true, or a myth to strike?","items":[{"id":"a","text":"You can ask for time before deciding."},{"id":"b","text":"Your yes is required on every path."},{"id":"c","text":"You can change your mind before the day."},{"id":"d","text":"An arranged match means no consent."},{"id":"e","text":"Once families agree, your yes is a formality."},{"id":"f","text":"A fixed date cancels your right to choose."}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth to strike","valence":"neg"}],"key":{"a":"true","b":"true","c":"true","d":"myth","e":"myth","f":"myth"},"relearn":"Time, your required yes and the freedom to change your mind are true; the rest are myths.","persona":"any","source":"true vs myth","cat":"love-and-arranged"},
  {"id":"cb-1135","type":"spot","hook":"Spot the two lines that override the couple's consent.","scene":[{"id":"a","text":"\"Take your time before you decide.\"","trick":false},{"id":"b","text":"\"You'll marry whoever we pick, end of story.\"","trick":true},{"id":"c","text":"\"Meet a few times first.\"","trick":false},{"id":"d","text":"\"Your opinion doesn't matter once we decide.\"","trick":true},{"id":"e","text":"\"We suggested; the choice is yours.\"","trick":false}],"why":"Both caught lines force or silence the couple; consent must lead on any path.","relearn":"Consent must lead on any path; forcing or silencing the couple overrides it.","persona":"any","source":"catch the coercion","cat":"love-and-arranged"},
  {"id":"cb-1136","type":"spot","hook":"Spot the two red-flag lines a prospect might say in a match.","scene":[{"id":"a","text":"\"I'd love to hear what you think.\"","trick":false},{"id":"b","text":"\"After we marry, you'll quit your friends.\"","trick":true},{"id":"c","text":"\"Let's talk through the big topics.\"","trick":false},{"id":"d","text":"\"Once you're mine, you'll do as I say.\"","trick":true},{"id":"e","text":"\"No rush; take your time deciding.\"","trick":false}],"why":"The caught lines show control and contempt, red flags worth declining over, on any path.","relearn":"Control and contempt are red flags worth declining over, on any path.","persona":"any","source":"catch the red flags","cat":"love-and-arranged"},
  {"id":"cb-1137","type":"spot","hook":"Spot the two shaky reasons to say yes to a match.","scene":[{"id":"a","text":"\"I genuinely choose this person.\"","trick":false},{"id":"b","text":"\"I'm just scared of being left alone.\"","trick":true},{"id":"c","text":"\"We've talked the big things through.\"","trick":false},{"id":"d","text":"\"Everyone my age is married already.\"","trick":true},{"id":"e","text":"\"We agree on values and goals.\"","trick":false}],"why":"Fear-of-alone and 'everyone my age' are shaky reasons; choose the person, not the pressure.","relearn":"Fear-of-alone and 'everyone my age' are shaky reasons; choose the person.","persona":"any","source":"catch the shaky reasons","cat":"love-and-arranged"},
  {"id":"cb-1138","type":"spot","hook":"Spot the two myths in this talk about arranged matches.","scene":[{"id":"a","text":"You can ask for time before deciding.","trick":false},{"id":"b","text":"An arranged match means you have no consent.","trick":true},{"id":"c","text":"Your yes is required on every path.","trick":false},{"id":"d","text":"Once families agree, your opinion is just a formality.","trick":true},{"id":"e","text":"You can change your mind before the day.","trick":false}],"why":"The caught lines deny consent; in any process the yes or no is genuinely yours.","relearn":"In any process the yes or no is genuinely yours; consent is never a formality.","persona":"any","source":"catch the myths","cat":"love-and-arranged"},
  {"id":"cb-1139","type":"spot","hook":"Spot the two lines that pressure or rush the decision.","scene":[{"id":"a","text":"\"A good match won't wait, so decide now.\"","trick":true},{"id":"b","text":"\"Take whatever time you need.\"","trick":false},{"id":"c","text":"\"We can talk again before you decide.\"","trick":false},{"id":"d","text":"\"Say yes tonight or lose your chance.\"","trick":true},{"id":"e","text":"\"There's no deadline on your answer.\"","trick":false}],"why":"The caught lines use rush and scarcity to push a yes; a real fit can wait for your decision.","relearn":"Rush and scarcity push a quick yes; a real fit can wait for your decision.","persona":"any","source":"catch the rush","cat":"love-and-arranged"},
  {"id":"cb-1140","type":"spot","hook":"Spot the two lines that dismiss a queer partnership as not real.","scene":[{"id":"a","text":"\"Your partnership is real and built on respect.\"","trick":false},{"id":"b","text":"\"That's a phase, not a real marriage.\"","trick":true},{"id":"c","text":"\"Many forms of family are valid.\"","trick":false},{"id":"d","text":"\"Two of you can't be a real family.\"","trick":true},{"id":"e","text":"\"Same love and respect as any family.\"","trick":false}],"why":"The caught lines erase a real partnership; many valid forms of family rest on the same foundations.","relearn":"Many valid forms of family are real and rest on the same foundations.","persona":"Aditya","source":"catch the dismissals","cat":"love-and-arranged"},
  {"id":"cb-1141","type":"spot","hook":"Spot the two lines that are forced-marriage coercion, not respect.","scene":[{"id":"a","text":"\"It's your choice whether to marry.\"","trick":false},{"id":"b","text":"\"You'll go through with it whether you agree or not.\"","trick":true},{"id":"c","text":"\"We'll support whatever you decide.\"","trick":false},{"id":"d","text":"\"Refuse and you're dead to this family.\"","trick":true},{"id":"e","text":"\"Take time; no one will force you.\"","trick":false}],"why":"The caught lines force a marriage; being coerced is never okay, and help exists (181, 1098, 112).","relearn":"Forced marriage is never okay; your consent is required, and help exists (181, 1098, 112).","persona":"any","source":"catch the coercion","cat":"love-and-arranged"},
  {"id":"cb-1142","type":"spot","hook":"Spot the two lines that wrongly treat love and arranged as unequal.","scene":[{"id":"a","text":"\"Both paths need values, talk and consent.\"","trick":false},{"id":"b","text":"\"A love marriage is more real than an arranged one.\"","trick":true},{"id":"c","text":"\"How you met matters less than what you build.\"","trick":false},{"id":"d","text":"\"Arranged means you skip compatibility.\"","trick":true},{"id":"e","text":"\"Same foundations hold up either path.\"","trick":false}],"why":"The caught lines rank one path over the other; both rest on the same foundations.","relearn":"Neither path outranks the other; both rest on the same foundations.","persona":"any","source":"catch the unequal claims","cat":"love-and-arranged"},
  {"id":"cb-1170","type":"strike-rewrite","persona":"any","source":"money talk","hook":"\"Splitting money fairly from day one kills the romance.\"","myth":{"un":"Splitting money fairly from day one kills the romance.","re":"Agreeing a fair money plan early removes a top source of fights and lets the closeness grow.","why":"Money clarity prevents the resentment that erodes warmth later."},"relearn":"Agreeing how money works fairly and early protects a partnership, it doesn't dampen it.","cat":"starting-strong"},
  {"id":"cb-1171","type":"strike-rewrite","persona":"any","source":"mental load","hook":"\"Running the home is naturally the wife's department.\"","myth":{"un":"Running the home is naturally the wife's department.","re":"Home and care work is shared work; defaulting it to one partner is a choice, not nature.","why":"The invisible load is real labour and starting it equal sets the long pattern."},"relearn":"Home and care work is shared from day one; it isn't naturally one partner's job.","cat":"starting-strong"},
  {"id":"cb-1172","type":"strike-rewrite","persona":"any","source":"in-law boundaries","hook":"\"Setting any boundary with in-laws means you don't respect elders.\"","myth":{"un":"Setting any boundary with in-laws means you don't respect elders.","re":"You can respect elders and still agree kind, clear limits as a couple-unit.","why":"Respect and healthy boundaries coexist; deciding them together protects the marriage."},"relearn":"Respecting elders and setting kind couple boundaries with in-laws can both be true.","cat":"starting-strong"},
  {"id":"cb-1173","type":"strike-rewrite","persona":"any","source":"roles by default","hook":"\"Once you're married the roles just sort themselves out.\"","myth":{"un":"Once you're married the roles just sort themselves out.","re":"Unnamed roles default to old gendered patterns; naming them early lets you choose fairly.","why":"What you don't decide on purpose, habit decides for you."},"relearn":"Name roles on purpose early; left unspoken they default to old gendered patterns.","cat":"starting-strong"},
  {"id":"cb-1174","type":"strike-rewrite","persona":"any","source":"early conflict habits","hook":"\"A couple who agrees how they'll fight isn't really in love.\"","myth":{"un":"A couple who agrees how they'll fight isn't really in love.","re":"Agreeing early how you'll handle disagreement is one of the strongest starts there is.","why":"Every couple disagrees; a shared repair habit is what keeps it from wounding."},"relearn":"Agreeing early how you'll handle conflict is a sign of a strong start, not a weak bond.","cat":"starting-strong"},
  {"id":"cb-1175","type":"strike-rewrite","persona":"any","source":"two incomes, two names","hook":"\"If he earns more, the big decisions should naturally be his.\"","myth":{"un":"If he earns more, the big decisions should naturally be his.","re":"An equal say isn't bought by a bigger salary; both partners decide the big things together.","why":"Tying voice to income builds in an imbalance you'll renegotiate painfully later."},"relearn":"A bigger income doesn't buy a bigger vote; big decisions stay shared.","cat":"starting-strong"},
  {"id":"cb-1176","type":"strike-rewrite","persona":"any","source":"talking kids early","hook":"\"Asking about kids before the wedding is putting the cart before the horse.\"","myth":{"un":"Asking about kids before the wedding is putting the cart before the horse.","re":"Whether and when to have children is too big to leave unspoken; talk it through before you commit.","why":"Assuming you agree on children is one of the most painful surprises to discover late."},"relearn":"Talk whether and when to have children honestly before committing; don't assume you agree.","cat":"starting-strong"},
  {"id":"cb-1177","cat":"starting-strong","type":"branch","persona":"Pooja","source":"mental load named","hook":"You've both moved in, and you're quietly doing all the planning, remembering and chasing.","steps":[{"prompt":"You realise you're the only one tracking the household's needs again. What do you do?","options":[{"text":"Keep carrying it silently to avoid a fuss","then":"The list in your head gets longer, and Karthik never sees it."},{"text":"Wait for him to notice on his own","then":"Another week passes with the noticing left entirely to you."},{"text":"Quietly resent him instead of speaking up","then":"The resentment sits there, doing nothing to change the load."},{"text":"Name the invisible load to Karthik","then":"Karthik looks up from his phone, surprised this is even a thing.","best":true}],"why":"Naming the load is the only way it becomes visible enough for him to actually share it."},{"prompt":"Karthik finally notices how much you're juggling and asks, surprised, what it all is. What do you do?","options":[{"text":"Let his surprise be the end of the conversation","then":"The conversation ends there, and the list stays yours."},{"text":"Apologise for making it a big deal","then":"Karthik reassures you, but nothing about the load actually changes."},{"text":"Exaggerate it to make sure he gets it","then":"Karthik looks unsure whether to believe the whole picture."},{"text":"Walk him through what the invisible work includes","then":"Karthik starts naming things he'd never have thought to list.","best":true}],"why":"Spelling out the actual tasks turns his surprise into something he can act on."},{"prompt":"He offers to help when you ask him to. What do you do?","options":[{"text":"Accept that as enough for now","then":"You're still the one remembering to ask, every single time."},{"text":"Thank him and keep managing it all yourself","then":"The offer stays an offer. The list stays yours."},{"text":"Stay silent, since an offer is something","then":"The asking itself quietly becomes one more task on your list."},{"text":"Ask to share the noticing, not just tasks","then":"Karthik pauses, then says he can actually try that.","best":true}],"why":"Sharing who notices and plans, not just who executes, is what actually lightens the load."},{"prompt":"A few weeks in, some of it has shifted back to you. What do you do?","options":[{"text":"Absorb it again rather than raise it twice","then":"The old pattern quietly creeps back in."},{"text":"Give up on the whole system","then":"Without the system, everything defaults back to you."},{"text":"Feel resentful without saying why","then":"Karthik has no idea anything's slipped."},{"text":"Name what's slipped back and reset together","then":"Karthik nods, and you both adjust the list again.","best":true}],"why":"Catching the slip and resetting together keeps the sharing real, not a one-time fix."}],"debrief":"The mental load is real work. Making it seen and shared early sets a fair pattern.","relearn":"Make the invisible load visible and share it. Carrying it silently breeds resentment."},
  {"id":"cb-1178","cat":"starting-strong","type":"branch","persona":"any","source":"leave plans","hook":"You're newly married, and a festival visit to both families clashes on the same dates.","steps":[{"prompt":"Both families ask you to confirm you're coming. What do you do?","options":[{"text":"Let each of you go to your own parents separately","then":"You spend the festival apart, each explaining the other's absence."},{"text":"Pick whichever family asked first","then":"The other family hears about it secondhand and feels it."},{"text":"Avoid answering either family","then":"Both families keep asking until you finally send a rushed plan."},{"text":"Plan it together and give one joint decision","then":"You and your partner agree on a plan before either family hears a word.","best":true}],"why":"Deciding together first means you present one answer instead of two competing ones."},{"prompt":"One family sounds disappointed by the plan. What do you do?","options":[{"text":"Change the plan on the spot to please them","then":"The joint decision you made together quietly unravels."},{"text":"Blame your partner's family for the clash","then":"Your partner hears their family described as the problem."},{"text":"Stop replying to avoid the discomfort","then":"The disappointment sits there, unaddressed, until the next call."},{"text":"Explain together why you chose this year's plan","then":"The disappointment doesn't vanish, but it's heard as a shared choice.","best":true}],"why":"Explaining the reasoning together keeps it a couple's decision, not one partner's fault."},{"prompt":"Next year the same clash is coming again. What do you do?","options":[{"text":"Let it default to whoever complained louder last time","then":"The plan gets decided by volume, not by fairness."},{"text":"Avoid planning until the last minute again","then":"You're scrambling again, right when you didn't need to be."},{"text":"Let each side assume they're getting this year","then":"Both families are surprised, for opposite reasons."},{"text":"Decide together again, maybe alternating fairly","then":"The conversation this time takes ten minutes, not an evening.","best":true}],"why":"Deciding together each year, with a fair pattern like alternating, keeps it from being refought."}],"debrief":"Face differing family expectations as one couple-unit with a shared decision.","relearn":"Decide together as a couple. Don't let each family pull you apart."},
  {"id":"cb-1179","cat":"starting-strong","type":"branch","persona":"Karthik","source":"money systems","hook":"You and Pooja earn very differently and haven't agreed how to handle shared expenses.","steps":[{"prompt":"A shared bill comes up, and it's awkward who pays. What do you do?","options":[{"text":"Let whoever earns more just quietly cover it all","then":"The bill gets paid, and so does a pattern neither of you chose."},{"text":"Split everything exactly in half regardless of income","then":"Pooja does the maths and looks uneasy about what that half actually costs her."},{"text":"Avoid shared expenses altogether","then":"You both end up paying for things separately, awkwardly, every time."},{"text":"Suggest sitting down to agree a fair system","then":"Pooja looks relieved someone finally said it out loud.","best":true}],"why":"A system you agree on together beats an awkward guess every time a bill appears."},{"prompt":"Pooja asks what \"fair\" means when incomes differ. What do you say?","options":[{"text":"Whoever earns more should just decide","then":"Pooja goes along with it, though it's clearly not what she meant by fair."},{"text":"Split it however avoids an argument today","then":"It works today, and solves nothing for next month."},{"text":"Wait and see how it feels over time","then":"Without a system, it just feels uneven, quietly, every month."},{"text":"A split proportional to what you each earn","then":"Pooja nods. It finally accounts for the actual gap between you.","best":true}],"why":"A proportional split shares the burden fairly instead of pretending the incomes are equal."},{"prompt":"She also wants to know she can spend some money without asking. What do you do?","options":[{"text":"Say all spending should be discussed together","then":"Pooja starts feeling like she needs permission for a coffee."},{"text":"Say you'll decide the big purchases","then":"Pooja notices the decisions keep landing on your side."},{"text":"Insist on tracking every rupee jointly","then":"The system starts feeling more like surveillance than partnership."},{"text":"Agree you'll each keep some money of your own","then":"Pooja relaxes. The plan finally has room for her own choices.","best":true}],"why":"Keeping some individual autonomy alongside the shared system respects both of you as adults."},{"prompt":"A few months in, your incomes shift. What do you do?","options":[{"text":"Keep the old split regardless","then":"The system slowly stops matching what's actually fair anymore."},{"text":"Let resentment build instead of adjusting","then":"Neither of you says anything, but both of you notice."},{"text":"Let whoever earns more take over the decisions","then":"The system you built together quietly becomes one person's call."},{"text":"Revisit the system together to keep it fair","then":"You update the split in one short conversation.","best":true}],"why":"Treating the system as something to revisit keeps it fair as your incomes actually change."}],"debrief":"Agree a fair, transparent money system early. Don't let one partner control it all.","relearn":"Agree a fair money system early. Don't default control to the higher earner."},
  {"id":"cb-1180","cat":"starting-strong","type":"branch","persona":"Sneha","source":"surnames & identity","hook":"Family assumes Sneha will drop her name and career focus after the wedding.","steps":[{"prompt":"The topic comes up at a family function. What does Sneha do?","options":[{"text":"Go along with the assumption to avoid friction","then":"The family nods, satisfied, while something in Sneha sinks a little."},{"text":"Avoid the conversation entirely","then":"The assumption stands, simply because no one corrected it."},{"text":"Apologise for wanting to keep them","then":"Sneha ends up defending a choice she shouldn't have to justify."},{"text":"Say plainly her name and work are her choice","then":"The room goes a little quiet, but Sneha's said exactly what she means.","best":true}],"why":"Saying it plainly puts the choice where it belongs, with her, instead of left to assumption."},{"prompt":"Varun is asked what he thinks. What should he do?","options":[{"text":"Let the family's assumption stand unchallenged","then":"Sneha is left to argue her own choice alone."},{"text":"Stay neutral so as not to take sides","then":"His silence reads as agreement with the assumption, not neutrality."},{"text":"Suggest she reconsider to keep the peace","then":"Sneha hears her own partner ask her to shrink for the room."},{"text":"Back her choice clearly in front of them","then":"The family hears it from both of them now, not just Sneha.","best":true}],"why":"Backing her choice out loud turns it from her lone stance into the couple's shared one."},{"prompt":"A relative brings it up again weeks later. What do they do?","options":[{"text":"Revisit and re-decide from scratch each time","then":"Every mention reopens a decision that was already made."},{"text":"Get defensive at being asked again","then":"The relative backs off, but the tension lingers in the room."},{"text":"Quietly start second-guessing it","then":"A settled choice starts to feel unsettled again, for no real reason."},{"text":"Calmly repeat the choice they made together","then":"It takes one sentence this time, and then the topic moves on.","best":true}],"why":"Repeating a choice you've already made together, calmly, closes the door without a fight."}],"debrief":"Decide identity and work choices on purpose together. Don't lose yourself to a default.","relearn":"Make name and career choices on purpose together. Don't erase yourself by default."},
  {"id":"cb-1181","cat":"starting-strong","type":"branch","persona":"any","source":"chores baseline","hook":"Week one of living together: dishes, cleaning and cooking are all landing on one of you.","steps":[{"prompt":"You notice the pattern by day four. What do you do?","options":[{"text":"Let it settle and assume it'll balance out later","then":"Day five looks exactly like day four."},{"text":"Keep doing it all so the space stays nice","then":"The house stays tidy, and so does the imbalance."},{"text":"Say nothing and hope your partner notices","then":"Your partner doesn't notice, because nothing's actually said."},{"text":"Pause and split the running of the home fairly now","then":"Your partner looks a little sheepish, like they'd assumed you didn't mind.","best":true}],"why":"Setting a fair split now is far easier than unwinding a habit once it's hardened."},{"prompt":"By the weekend your partner notices too, and asks how you should divide it. What do you suggest?","options":[{"text":"Whoever has more free time that day","then":"You end up renegotiating the split most days."},{"text":"Guessing as you go and sorting it out when it gets messy","then":"Some days nothing gets covered, and some days you both do the same thing."},{"text":"Whoever asks first each time","then":"Asking first becomes its own small chore."},{"text":"Splitting by what each of you doesn't mind doing","then":"You end up with a list that neither of you dreads.","best":true}],"why":"Splitting by preference, not guesswork, makes the system one you'll both actually keep."},{"prompt":"A week in, one task keeps getting missed. What do you do?","options":[{"text":"Quietly pick it up yourself again","then":"The list looks fine on paper. It isn't, in practice."},{"text":"Let it slide since it's \"just one thing\"","then":"One missed thing quietly becomes a habit."},{"text":"Get annoyed but say nothing","then":"Your partner has no idea anything's wrong."},{"text":"Name it and adjust who owns it","then":"You swap that one task, and it sticks this time.","best":true}],"why":"Naming the gap and reassigning it keeps the system fair instead of letting it slide."}],"debrief":"Split the running of the home fairly from week one. Don't wait for it to \"balance out.\"","relearn":"Agree a fair share of home work early. An unfair default rarely balances itself later."},
  {"id":"cb-1182","cat":"starting-strong","type":"branch","persona":"Nisha","source":"big-topics checklist","hook":"You're about to commit to Rohit but haven't talked money, children, work cities or caring for parents.","steps":[{"prompt":"You realise how much you haven't actually discussed. What do you do?","options":[{"text":"Assume love will sort the details out","then":"You both feel closer, and just as unprepared as before."},{"text":"Wait until after the wedding when there's less to plan","then":"You plan to wait, until Rohit's mother asks about your joint account plans."},{"text":"Ask a relative what usually gets discussed","then":"You get a list of customs, not what you and Rohit actually think."},{"text":"Sit down and start working through the big topics honestly","then":"Rohit looks relieved someone finally said it out loud.","best":true}],"why":"Working through the big topics honestly, before committing, means fewer surprises later."},{"prompt":"Money comes up first. What do you ask?","options":[{"text":"How much he earns, exactly, and what he spends on","then":"Rohit answers, but how you'll actually manage money together stays unasked."},{"text":"Whether he'll just handle the finances","then":"Rohit assumes that means he decides alone from here."},{"text":"Nothing, since money talk feels awkward","then":"The awkwardness stays exactly where it was, just postponed."},{"text":"How he thinks about saving and shared money","then":"Rohit shares a plan he's clearly thought about before.","best":true}],"why":"Asking how he thinks about money reveals more than a number ever could."},{"prompt":"Next you raise children. What do you ask?","options":[{"text":"Whether he assumes you'll want kids soon","then":"Rohit answers what he thinks you want, not what he actually wants."},{"text":"Whether his parents expect grandchildren","then":"You learn about his parents' hopes, not his own."},{"text":"Nothing, you'll cross that bridge later","then":"The bridge stays right where it was, uncrossed."},{"text":"What he actually thinks, if and when","then":"Rohit takes a real moment to answer, instead of a quick one.","best":true}],"why":"Asking what he actually thinks, not what's expected of him, gets you his real answer."},{"prompt":"Work cities comes up, since his job could relocate him. What do you ask?","options":[{"text":"Whether you're expected to just follow","then":"Rohit hesitates, unsure if that's really what you're asking for."},{"text":"Whether his career should just come first","then":"Rohit answers carefully, sensing it's a loaded question."},{"text":"Nothing, you'll figure it out if it happens","then":"If it happens, you'll be figuring it out with no plan at all."},{"text":"How you'd decide a move together","then":"Rohit relaxes, glad it's framed as a \"we\" question.","best":true}],"why":"Asking how you'd decide together, not who wins, sets up a real process for later."},{"prompt":"Last, caring for ageing parents on both sides. What do you ask?","options":[{"text":"Whether that's \"his side's\" job to handle","then":"Rohit isn't sure that's a fair question to answer alone."},{"text":"Whether you'll deal with it when it comes up","then":"When it comes up, there'll be no plan waiting for you."},{"text":"Nothing, it's too far off to plan","then":"Far off arrives faster than either of you expects."},{"text":"How you'd plan to support both families together","then":"Rohit says no one's ever asked him that so plainly before.","best":true}],"why":"Planning for both families together, on purpose, avoids it defaulting to one person later."}],"debrief":"Talk money, children, careers and elder care honestly before committing. Don't assume.","relearn":"Discuss the big topics honestly before commitment. Love alone won't sort hidden mismatches."},
  {"id":"cb-1183","cat":"starting-strong","type":"branch","persona":"any","source":"first repair habit","hook":"Your first real fight as a couple is winding down, and nothing's been resolved.","steps":[{"prompt":"The tension is still in the room. What do you do?","options":[{"text":"Sweep it under the rug and hope it doesn't recur","then":"You both go quiet, and the actual issue stays untouched."},{"text":"Keep arguing until someone gives in","then":"Someone gives in, tired rather than actually convinced."},{"text":"Go to bed without a word","then":"You lie there awake, replaying it instead of resting."},{"text":"Agree how you'll cool down and repair","then":"You both breathe out, like there's finally a plan for this.","best":true}],"why":"Agreeing on a repair plan while it's fresh builds a habit you'll both use again."},{"prompt":"The next morning, you both agree you need a plan for fights like this. What should it include?","options":[{"text":"An unspoken rule to never bring it up again","then":"The topic goes underground instead of getting solved."},{"text":"Whoever apologises first","then":"Whoever's more tired ends up carrying the apology alone."},{"text":"Avoiding this topic forever","then":"The plan avoids the fight, not the thing the fight was about."},{"text":"A fixed time to come back and talk once calmer","then":"You pick a time, and it feels less like an open wound now.","best":true}],"why":"A fixed time to return to it turns cooling down into an actual plan, not an avoidance."},{"prompt":"The next disagreement starts to heat up. What do you do?","options":[{"text":"Forget the plan and let it spiral","then":"It plays out exactly like the fight before this one."},{"text":"Wait for your partner to remember it first","then":"You both wait, and the moment slips past unused."},{"text":"Let this one go unresolved too","then":"The pile of unresolved fights gets one item bigger."},{"text":"Use the cool-down-and-repair habit you agreed","then":"It's calmer this time, mostly because you both know what comes next.","best":true}],"why":"Using the habit you built the first time is what makes it an actual habit, not a one-off."}],"debrief":"Build a cool-down-and-repair habit from the first conflict. Don't sweep fights under the rug.","relearn":"Set a repair habit early. Unresolved fights swept aside pile into resentment."},
  {"id":"cb-1184","cat":"starting-strong","type":"branch","persona":"any","source":"both careers count","hook":"A job offer means relocating, and only your partner's career is being treated as the one that matters.","steps":[{"prompt":"The offer comes up at dinner. What do you do?","options":[{"text":"Assume you'll just follow since that's \"normal\"","then":"The evening moves to logistics, and your own career quietly drops out of it."},{"text":"Decline to discuss it and let them decide","then":"Your partner is left making a decision that affects you both, alone."},{"text":"Agree immediately to keep things easy","then":"It's easy tonight, and you notice the cost of that later."},{"text":"Say both careers deserve a real look here","then":"Your partner pauses, like they hadn't fully considered that side of it.","best":true}],"why":"Naming that both careers matter is what gets the decision actually weighed, not assumed."},{"prompt":"Before replying to the offer, your partner asks how you two should decide. What do you suggest?","options":[{"text":"Whoever's offer is bigger automatically wins","then":"The bigger number decides, and your reasons never really get heard."},{"text":"Deciding based on what your families would think","then":"You end up optimising for approval instead of your actual lives."},{"text":"Flipping a coin since it's too hard","then":"The coin decides something you'll both be living with for years."},{"text":"Listing what each of you would gain and lose","then":"The list makes it clear this isn't as one-sided as it first looked.","best":true}],"why":"Laying out what each of you would actually gain and lose makes the trade-offs visible."},{"prompt":"The numbers turn out close. What do you do?","options":[{"text":"Default to your partner's job since that's familiar","then":"Familiar wins, not necessarily better."},{"text":"Let whoever's more stressed about it decide","then":"The decision goes to whoever argues hardest, not whoever's right for you both."},{"text":"Pick whichever's easier to explain to family","then":"You optimise the explanation instead of the actual choice."},{"text":"Keep talking until you reach a decision you both want","then":"It takes another evening, but you land somewhere you both mean.","best":true}],"why":"Talking until you both genuinely agree beats defaulting to whichever's easier to justify."},{"prompt":"A similar decision comes up again in a few years. What do you do?","options":[{"text":"Assume the old default this time","then":"The habit from last time quietly takes over again."},{"text":"Let this one go to whoever's more tired of arguing","then":"Exhaustion decides, not the actual weighing."},{"text":"Decide one of you always gets the final say now","then":"One person's career quietly becomes the permanent priority."},{"text":"Revisit it together the same honest way","then":"It's faster this time. You already know how to do this part.","best":true}],"why":"Using the same honest process again keeps both careers counting, not just the first time."}],"debrief":"Treat both partners' careers as equally real. Decide moves together, not by default.","relearn":"Both careers count. Weigh a relocation together rather than defaulting to one partner's."},
  {"id":"cb-1185","cat":"starting-strong","type":"branch","persona":"any","source":"early expectations talk","hook":"You each carry unspoken pictures of \"how married life should be\" and haven't compared them.","steps":[{"prompt":"A small disagreement reveals you imagined things differently. What do you do?","options":[{"text":"Stay quiet and hope your pictures already match","then":"You both keep assuming, and the mismatch stays hidden."},{"text":"Insist your version is the right one","then":"Your partner goes quiet instead of actually agreeing."},{"text":"Assume it'll sort itself out later","then":"Later arrives, and so does the same disagreement, bigger."},{"text":"Share your picture openly and ask about theirs","then":"Your partner actually pulls up a chair for this one.","best":true}],"why":"Comparing your pictures out loud is the only way to find out where they actually differ."},{"prompt":"A few expectations turn out to differ more than you thought. What do you do?","options":[{"text":"Pretend it doesn't bother you, since you're already engaged","then":"It bothers you anyway, just quietly now instead of openly."},{"text":"Decide you're simply incompatible","then":"One real difference gets treated like the whole relationship."},{"text":"Let it go unaddressed to keep the peace","then":"The peace holds today, and the mismatch waits for tomorrow."},{"text":"Talk through where you differ and why it matters","then":"You both start to see why the other pictured it that way.","best":true}],"why":"Talking through the why behind a difference, not just the difference, is what closes the gap."},{"prompt":"A few months into marriage, your pictures of daily life shift again. What do you do?","options":[{"text":"Assume it's settled forever now","then":"Life changes, and the settled version quietly stops fitting."},{"text":"Stop discussing it since it's \"sorted\"","then":"The next shift catches you both off guard."},{"text":"Let whoever adjusts more just keep adjusting","then":"One of you keeps bending, and it stops feeling fair."},{"text":"Check back in as life actually changes things","then":"A year later, the small check-in still feels easy to have.","best":true}],"why":"Treating it as something to revisit keeps your shared picture accurate as life changes."}],"debrief":"Share your expectations of married life early. Don't assume your pictures already match.","relearn":"Name your expectations early. Unspoken pictures collide later if never compared."},
  {"id":"cb-1186","cat":"starting-strong","type":"branch","persona":"any","source":"privacy & space","hook":"Married now, family expects full access to your home, phones and weekends, always.","steps":[{"prompt":"A relative walks in unannounced again. What do you do?","options":[{"text":"Give up all privacy to be seen as a \"good\" couple","then":"The visits keep coming, and so does the feeling of never being off duty."},{"text":"Snap at the relative in the moment","then":"The relative leaves hurt, and the real issue is still unaddressed."},{"text":"Avoid the issue since it feels rude to raise","then":"The unannounced visits become the unspoken norm."},{"text":"Agree as a couple what privacy you'll keep","then":"You and your partner draft a plan before the next visit happens.","best":true}],"why":"Deciding your privacy together first means you're acting from a plan, not reacting each time."},{"prompt":"The next weekend, you both decide family needs to hear about privacy. What do you do?","options":[{"text":"Let your partner handle it alone","then":"Your partner carries the awkward conversation, and the weight, by themselves."},{"text":"Avoid the topic until someone's upset again","then":"The boundary exists only in your heads, not out loud yet."},{"text":"Promise to \"figure something out\" vaguely","then":"The vague promise changes nothing about next weekend."},{"text":"Explain it together, kindly and clearly","then":"Family hears it once, from both of you, and it's clear.","best":true}],"why":"Explaining the boundary together, kindly, makes it a shared decision, not one person's rule."},{"prompt":"At the next visit, a relative walks in unannounced again. What do you do?","options":[{"text":"Cave to avoid an awkward moment","then":"The boundary quietly stops meaning anything."},{"text":"Blame your partner if family reacts badly","then":"Your partner is left defending a boundary you both agreed to, alone."},{"text":"Decide boundaries were a bad idea","then":"You're back to no plan at all, and the old pattern returns."},{"text":"Hold the boundary together as agreed","then":"It's a little awkward, and it holds, together.","best":true}],"why":"Holding it together, even when it's tested, is what makes a boundary actually real."}],"debrief":"Agree what privacy and space you keep as a couple. Togetherness shouldn't erase it.","relearn":"Set healthy privacy and space as a couple early. Don't surrender it to look \"good.\""},
  {"id":"cb-1187","cat":"starting-strong","type":"branch","persona":"Sneha","source":"fair festivals & fasts","hook":"Tradition expects Sneha to do all the festival cooking and fasting solo while Varun relaxes.","steps":[{"prompt":"Festival prep starts again this year. What does Sneha do?","options":[{"text":"Accept it silently because \"that's how it's done\"","then":"The kitchen fills up, and so does a feeling she doesn't say out loud."},{"text":"Quietly resent Varun through the whole thing","then":"The festival passes, and so does the resentment, unspoken."},{"text":"Cancel the festival plans out of frustration","then":"The frustration is real, and the festival isn't really the problem."},{"text":"Raise it and ask to share the festival work","then":"Varun looks a little caught off guard, then actually listens.","best":true}],"why":"Raising it directly is what actually opens the chance for the work to be shared."},{"prompt":"Varun says he's never really thought about it. What does he do?","options":[{"text":"Say the women in his family always handled it","then":"Sneha hears her own effort explained away as tradition."},{"text":"Offer to help once and expect thanks for it","then":"Sneha ends up managing his one-time help along with everything else."},{"text":"Agree in the moment and forget by the next festival","then":"The agreement doesn't survive past this conversation."},{"text":"Ask what sharing it could actually look like","then":"They end up with a rough plan for who does what this year.","best":true}],"why":"Asking what sharing could look like turns good intentions into an actual plan."},{"prompt":"The next festival arrives. What do they do?","options":[{"text":"Fall back into the old solo pattern","then":"Sneha is back in the kitchen alone, and the plan goes unmentioned."},{"text":"Split it unevenly again without discussing it","then":"It looks shared on paper, and doesn't feel that way to Sneha."},{"text":"Skip the festival to avoid the issue","then":"Avoiding the festival avoids the conversation too."},{"text":"Share the work the way they planned","then":"The kitchen has both of them in it this time.","best":true}],"why":"Actually using the plan they made is what turns a good conversation into a real change."}],"debrief":"Share festival and ritual work as a couple. Don't let \"how it's done\" assign it to one.","relearn":"Share the festival and ritual load. Tradition isn't a reason for one partner to carry it all."},
  {"id":"cb-1188","cat":"starting-strong","type":"branch","persona":"Aditya","source":"joint vs solo decisions","hook":"Kabir's parents are deciding your home, money and timeline for you both, without asking.","steps":[{"prompt":"They announce another decision made on your behalf. What do you do?","options":[{"text":"Let it stand to keep the peace","then":"The peace holds, and so does a decision neither of you actually made."},{"text":"Argue loudly in front of the family","then":"The room tenses, and the actual issue gets lost in the noise."},{"text":"Quietly resent it and say nothing to anyone","then":"Kabir has no idea anything's bothering you."},{"text":"Kindly reclaim the choice as yours and Kabir's","then":"Kabir glances at you, surprised, then nods along.","best":true}],"why":"Reclaiming it kindly, together, puts the choice back where it belongs without a scene."},{"prompt":"Kabir's parents push back, saying they only want to help. What do you do?","options":[{"text":"Back down and let them keep deciding for you both","then":"The help keeps arriving as decisions you never asked for."},{"text":"Tell them to stop helping altogether","then":"The relationship gets frostier, and the actual issue stays unresolved."},{"text":"Let Kabir handle it alone this time","then":"Kabir is left explaining a boundary that's supposed to be both of yours."},{"text":"Thank them, and say you'll decide together","then":"His parents look unsure, but hear that it's coming from both of you.","best":true}],"why":"Thanking them keeps the relationship warm while the explanation sets the actual boundary."},{"prompt":"You and Kabir sit down to actually decide. What do you do?","options":[{"text":"Let whoever feels strongest about it choose","then":"One of you ends up carrying a decision the other never fully agreed to."},{"text":"Split decisions arbitrarily to be fair","then":"Fair on paper doesn't always mean either of you is happy with the result."},{"text":"Default to what his parents originally wanted","then":"You're back where you started, just with extra steps."},{"text":"Talk it through until you both agree","then":"It takes longer, and you both actually mean the answer you land on.","best":true}],"why":"Talking until you both genuinely agree is what makes it the couple's decision, not a guess."},{"prompt":"A new decision comes up with the family again. What do you do?","options":[{"text":"Revert to letting them decide like before","then":"The old pattern is easier to fall into than either of you expects."},{"text":"Avoid the family until it passes","then":"The decision gets made without you anyway, just later."},{"text":"Let Kabir's parents and you both weigh in equally as deciders","then":"The choice ends up split between three voices instead of two."},{"text":"Lead with the couple's judgement again","then":"It's quicker this time. You've done this part before.","best":true}],"why":"Leading with your own judgement again is what keeps it a pattern, not a one-time win."}],"debrief":"Let the couple's judgement lead the big choices, kindly. Don't outsource them all.","relearn":"The couple's own judgement should lead big decisions, kindly, not be handed to elders."},
  {"id":"cb-1189","cat":"starting-strong","type":"branch","persona":"Pooja","source":"time for friends","hook":"Marriage is making you both drop your own friendships to be a \"proper\" couple.","steps":[{"prompt":"You realise you haven't seen your own friends in weeks. What do you do?","options":[{"text":"Cut them off further since you're \"married now\"","then":"The group chat goes quieter, and so does a part of you."},{"text":"Wait for Karthik to notice and suggest it first","then":"Weeks pass, until Karthik mentions he misses his own friends."},{"text":"Feel guilty and say nothing","then":"The guilt sits there, doing nothing to fix the actual gap."},{"text":"Agree with Karthik you'll each keep your own friends","then":"Karthik looks relieved, like he'd been missing his own friends too.","best":true}],"why":"Agreeing on it together makes keeping your friendships a shared plan, not a guilty secret."},{"prompt":"Karthik asks how much time apart feels right. What do you say?","options":[{"text":"Whatever feels easiest to agree to right now","then":"The vague answer means neither of you actually plans for it."},{"text":"None, really, since you're a couple now","then":"Karthik goes along with it, though you can tell he doesn't quite mean it."},{"text":"Whatever he wants, to avoid conflict","then":"The plan ends up shaped entirely around his answer, not yours."},{"text":"Something specific you can both commit to","then":"You land on a rough number that fits both your weeks.","best":true}],"why":"A specific answer is one you can actually plan around, not just agree to and forget."},{"prompt":"A friend's plan clashes with couple time one weekend. What do you do?","options":[{"text":"Cancel on your friend automatically, without a second thought","then":"The plan you agreed on starts to feel like it doesn't really count."},{"text":"Feel too guilty to enjoy it","then":"You're there with your friend, and half your mind is still at home."},{"text":"Quietly resent whichever you choose","then":"Either way, the resentment follows you into the evening."},{"text":"Go, since the space you agreed on matters too","then":"You come home lighter, and Karthik asks how your friend's doing.","best":true}],"why":"Using the space you agreed on is what makes the agreement mean something, not just sound good."}],"debrief":"Keep your own friendships and space. Build \"us\" without erasing \"me.\"","relearn":"A strong \"us\" keeps room for each \"me.\" Don't drop your own friends to prove you're a couple."},
  {"id":"cb-1190","cat":"starting-strong","type":"branch","persona":"any","source":"caring for parents","hook":"You haven't discussed how you'll both support ageing parents on either side.","steps":[{"prompt":"A parent's health scare makes the question urgent. What do you do?","options":[{"text":"Assume the daughter-in-law will absorb it all","then":"The assumption quietly decides who's carrying this, before you've even talked."},{"text":"Wait until it becomes a bigger crisis","then":"The crisis arrives anyway, now with no plan waiting for it."},{"text":"Let whichever side's parent it is handle it alone","then":"One of you is suddenly doing this without the other's support."},{"text":"Sit down together and plan elder care fairly","then":"You both bring worries neither of you had said out loud yet.","best":true}],"why":"Planning together, before it's urgent, means neither of you carries it alone by default."},{"prompt":"A week later, the family asks what support you two can offer. What do you include?","options":[{"text":"Only your side's parents for now","then":"The plan quietly leaves out half the people who'll need it."},{"text":"Whichever side asks first","then":"The plan ends up shaped by whoever spoke up, not by fairness."},{"text":"A vague plan to \"help out\" without specifics","then":"When the moment comes, \"help out\" doesn't tell either of you what to do."},{"text":"Both families' needs from the start","then":"The plan covers people on both sides, not just one.","best":true}],"why":"Including both families from the start is what makes the plan actually fair, not one-sided."},{"prompt":"Money for care becomes part of the conversation. What do you do?","options":[{"text":"Assume one side will just cover it","then":"One of you starts quietly carrying a cost the other never discussed."},{"text":"Avoid the topic since it feels awkward","then":"The awkwardness stays, and so does the unanswered question."},{"text":"Let whoever has more quietly cover it and resent it","then":"The resentment grows exactly where the silence was."},{"text":"Agree a fair way to share the cost","then":"You land on a split that accounts for what you each can actually give.","best":true}],"why":"Agreeing the cost split openly avoids one partner quietly carrying it and resenting it later."},{"prompt":"A year later, needs on one side change. What do you do?","options":[{"text":"Stick rigidly to the old plan","then":"The old plan starts to strain against the new reality."},{"text":"Let it default back to one partner","then":"The fairness you built starts quietly slipping away."},{"text":"Assume it'll work itself out","then":"Nothing works itself out. It just waits for someone to notice."},{"text":"Revisit the plan together","then":"You update the plan in one evening, and it fits again.","best":true}],"why":"Treating the plan as adjustable keeps it fair as each family's needs actually change."}],"debrief":"Plan elder care fairly and together early. Don't default it to the daughter-in-law.","relearn":"Plan support for ageing parents fairly and together. Don't default care to one partner."},
  {"id":"cb-1191","cat":"starting-strong","type":"branch","persona":"any","source":"honest money history","hook":"You each have loans or savings the other doesn't fully know about yet.","steps":[{"prompt":"The topic of combining finances comes up. What do you do?","options":[{"text":"Hide the debts and deal with it after marriage","then":"You keep yours hidden for now, and it weighs on you whenever money comes up."},{"text":"Mention it only if directly asked","then":"It never quite comes up, so it never quite gets said."},{"text":"Wait until it becomes unavoidable","then":"Unavoidable arrives at the worst possible moment."},{"text":"Lay out your real money picture honestly now","then":"Your partner exhales, like they'd been waiting for someone to go first.","best":true}],"why":"Laying it out honestly now means you commit on the truth, not a surprise later."},{"prompt":"Before the wedding, your partner mentions a loan you didn't know about. What do you do?","options":[{"text":"React with shock and judgment before they finish","then":"Your partner regrets being honest almost immediately."},{"text":"Pretend it doesn't change anything at all","then":"The pretending doesn't make the numbers any different."},{"text":"Quietly worry without saying so","then":"The worry sits there, doing nothing but grow."},{"text":"Thank them for being honest and calmly ask more","then":"The conversation gets easier once neither of you is bracing for a reaction.","best":true}],"why":"Meeting honesty with calm keeps the door open for the rest of the conversation you still need."},{"prompt":"The loan payments start to bite. What do you suggest?","options":[{"text":"One of you just absorbs it alone","then":"It's called shared finances, and it doesn't quite feel that way yet."},{"text":"Ignore it since love will sort it out","then":"Love doesn't send the reminder emails. The debt does."},{"text":"Blame past decisions instead of planning forward","then":"The blame changes the mood, and nothing about the balance."},{"text":"A shared plan to pay it down together","then":"You both know exactly what happens next month, and the month after.","best":true}],"why":"A shared plan turns the debt into something you're solving together, not one person's problem."},{"prompt":"Months later, a big new expense lands on top of the loan. What do you do?","options":[{"text":"Quietly cover it without saying anything","then":"The plan on paper stops matching what's actually happening."},{"text":"Blame each other's spending and stop budgeting","then":"Without a plan, you're back to guessing."},{"text":"Let one partner absorb the change alone","then":"The sharing you built starts quietly slipping to one side again."},{"text":"Talk it through and plan for it together","then":"You tweak one number, and the plan holds.","best":true}],"why":"Adjusting the plan together keeps it working instead of letting one surprise break it."}],"debrief":"Share your honest money picture, including loans, before committing. Don't hide it.","relearn":"Be honest about loans and savings before commitment. Hidden money shocks erode trust early."},
  {"id":"cb-1192","cat":"starting-strong","type":"branch","persona":"any","source":"saying the quiet part","hook":"Something about how you'll live together is bothering you, but you're scared to raise it.","steps":[{"prompt":"It crosses your mind again while you're together. What do you do?","options":[{"text":"Bottle it up so you don't seem difficult","then":"It stays exactly where it was: inside you, unsaid."},{"text":"Wait for a \"perfect\" moment that never comes","then":"The perfect moment keeps not arriving, and neither does the conversation."},{"text":"Hint at it and hope they guess","then":"Your partner picks up that something's off, but not what."},{"text":"Raise it gently now with an \"I feel\" opener","then":"Your partner puts down what they're doing to actually listen.","best":true}],"why":"An \"I feel\" opener names the problem without attacking, so your partner can actually hear it."},{"prompt":"Later, your partner asks if something's been on your mind. What do you do?","options":[{"text":"Downplay it and say it's nothing, really","then":"The real size of it gets lost in the downplaying."},{"text":"Mention something smaller instead","then":"Your partner responds to the smaller thing, not the actual worry."},{"text":"Turn it back and ask what they think first","then":"You learn their view, and yours still hasn't been said."},{"text":"Explain it honestly, even though it's uncomfortable","then":"It's an awkward minute, and then it's said, and that's a relief.","best":true}],"why":"Explaining it fully, even when it's uncomfortable, is what actually gets it heard."},{"prompt":"A similar worry comes up again another week. What do you do?","options":[{"text":"Assume raising the last one used up your chances","then":"This one goes quiet the way the first one almost did."},{"text":"Decide it's not worth mentioning twice","then":"Two small worries stay unsaid instead of one."},{"text":"Wait to see if it goes away alone","then":"It doesn't go away. It just waits with you."},{"text":"Raise this one too, the same honest way","then":"It's a little easier this time. You've done it before.","best":true}],"why":"Using the same honest approach again is what turns one brave moment into an actual habit."}],"debrief":"Raise worries early and gently with an \"I felt\" opener. Bottling them isn't a strong start.","relearn":"Name worries early and kindly. Bottling them to seem easy lets small things grow large."},
  {"id":"cb-1193","cat":"starting-strong","type":"branch","persona":"any","source":"wedding vs marriage focus","hook":"All the energy is going into the wedding day, and the marriage talks keep getting postponed.","steps":[{"prompt":"Another planning session eats the whole evening. What do you do?","options":[{"text":"Pour it all into the function and figure \"us\" out later","then":"The guest list grows by ten names. The marriage talk shrinks by one more evening."},{"text":"Cancel the wedding talk to force a change","then":"The wedding planning still has to happen somehow, just later and rushed."},{"text":"Assume the marriage talks aren't that urgent","then":"Nothing about them becomes urgent. They just keep waiting quietly."},{"text":"Carve out time for the real partnership conversations too","then":"Your partner looks surprised, then relieved, that you said it.","best":true}],"why":"Making room for the partnership talks now stops the wedding from crowding out the marriage."},{"prompt":"Partner says there's no room left this week. What do you suggest?","options":[{"text":"Dropping it until after the wedding","then":"After the wedding arrives, and so does a new reason to postpone."},{"text":"Insisting on the full talk anyway","then":"You both end up too tired for the conversation to actually land."},{"text":"Letting the wedding win this week too","then":"This week becomes last week's habit, again."},{"text":"One short, focused conversation instead","then":"Twenty minutes turns out to be enough to actually say something real.","best":true}],"why":"A short, focused conversation fits into a busy week in a way a big one never will."},{"prompt":"The wedding is two weeks away, and the marriage talks still feel unfinished. What do you do next?","options":[{"text":"Consider the topic closed now","then":"The next thing that needs saying waits for an opening that doesn't come."},{"text":"Go back to only wedding logistics","then":"The one good conversation stays a one-off."},{"text":"Assume momentum will carry it without effort","then":"The momentum fades by the time the next busy week hits."},{"text":"Schedule a short talk before the day","then":"It's already on the calendar before either of you can forget.","best":true}],"why":"Scheduling the next one keeps the habit going instead of leaving it to chance."},{"prompt":"The wedding is a week away, and everyone's stressed. What do you do?","options":[{"text":"Drop the partnership talks entirely till after","then":"The last stretch before the wedding becomes the longest gap yet."},{"text":"Blame the wedding for the pressure","then":"The blame is fair, and it doesn't get the conversation back."},{"text":"Assume you can catch up once it's over","then":"Once it's over, a different kind of busy takes its place."},{"text":"Protect a brief check-in amid the chaos","then":"It's five minutes, and it's enough to feel like a team again.","best":true}],"why":"Protecting even a brief check-in keeps the partnership from disappearing into wedding week."}],"debrief":"A wedding is a day. Protecting time for the marriage itself is what sets you up to last.","relearn":"Don't let the wedding crowd out the marriage talks. The day passes, the partnership stays."},
  {"id":"cb-1194","cat":"starting-strong","type":"branch","persona":"Karthik","source":"equal from day one statement","hook":"You want to set the tone with Pooja, but worry naming \"equal partnership\" out loud sounds too formal.","steps":[{"prompt":"You're planning your first weeks together. What do you do?","options":[{"text":"Hope your actions alone will make it obvious","then":"Pooja notices the effort, but not the intention behind it."},{"text":"Wait for Pooja to bring it up first","then":"Neither of you says it, so neither of you has actually agreed to it."},{"text":"Mention it jokingly so it doesn't feel too serious","then":"Pooja laughs along, unsure if you actually meant it."},{"text":"Say plainly that you want to build this as equals","then":"Pooja looks at you for a second, then smiles like she means it too.","best":true}],"why":"Saying the intention out loud puts it on the table instead of leaving it silently inferred."},{"prompt":"A week in, Pooja asks what an equal partnership would mean for you two, day to day. What do you do?","options":[{"text":"Say it'll just naturally work out","then":"\"Naturally\" turns out to mean whoever notices first, again."},{"text":"Say she should tell you whenever something's unfair","then":"The whole job of noticing unfairness lands back on her."},{"text":"Change the subject, since it feels too formal","then":"The big thing stays a nice sentence, without a next step."},{"text":"Give one or two concrete examples of what equal looks like","then":"Pooja nods. It sounds less like a slogan now and more like a plan.","best":true}],"why":"Concrete examples turn the intention into something you can both actually act on."},{"prompt":"A relative later jokes that you'll \"come around\" to the usual way. What do you do?","options":[{"text":"Laugh along and let the comment stand","then":"The joke lands as more true than either of you meant it to."},{"text":"Get defensive with the relative","then":"The relative backs off, and the mood turns a little frosty."},{"text":"Quietly wonder if the relative has a point","then":"A comment meant as a joke starts to plant a small doubt."},{"text":"Calmly restate what you and Pooja agreed","then":"It takes one sentence, and the joke doesn't land twice.","best":true}],"why":"Restating what you've already agreed, calmly, holds the line without starting a fight."}],"debrief":"Name the intention to build as equals early. Don't leave it to be silently inferred.","relearn":"Say the intention to be equals out loud early. Unspoken intentions get read as the old default."},
  {"id":"cb-1195","cat":"starting-strong","type":"role-play","persona":"any","source":"equal tone","hook":"You and Meera just got the keys to your first home together, boxes everywhere.","setup":"She starts unpacking the kitchen, humming to herself.","steps":[{"prompt":"Meera says: \"I'll just handle the kitchen setup. You figure out the rest?\"","options":[{"text":"\"Let's actually plan this together, as equals, from day one.\"","then":"She pauses, boxes in hand. \"Oh, good point. Where do we even start?\"","best":true},{"text":"\"Sure, we'll probably just figure it all out naturally as we go.\"","then":"She shrugs and keeps unpacking alone, and a pattern quietly starts."},{"text":"\"Sounds good, kitchens are more your thing anyway.\"","then":"She laughs, but something about \"your thing\" doesn't sit quite right."},{"text":"\"Whatever's fastest, I don't really mind.\"","then":"She nods and keeps going alone, boxes stacking up around her."}],"why":"Naming a shared plan now stops default roles setting in box by box."},{"prompt":"That weekend, Meera asks: \"How should we split the house stuff fairly?\"","options":[{"text":"\"Let's list every task, then split by what we each prefer.\"","then":"She grins. \"I actually love organising lists. Let's do that now.\"","best":true},{"text":"\"Whatever feels natural to each of us, I suppose, in the moment.\"","then":"She nods, though \"natural\" quietly starts looking like old habits."},{"text":"\"You handle inside stuff. I'll handle outside stuff.\"","then":"She pauses. \"Isn't that just the usual split, though?\""},{"text":"\"Let's not overthink unpacking boxes.\"","then":"She shrugs and goes back to sorting the kitchen alone."}],"why":"Splitting by preference, named out loud, keeps old defaults from choosing for you."},{"prompt":"Later, Meera's mother visits and says: \"Beta, you shouldn't make him do kitchen things.\"","options":[{"text":"\"We're sharing everything equally. That's how we're building this.\"","then":"Her mother blinks, then shrugs. \"Well, it's your house, I suppose.\"","best":true},{"text":"\"He offered, honestly, so I didn't think much of it at the time.\"","then":"Her mother looks unconvinced but doesn't push the point further."},{"text":"\"You're right, let me take over the kitchen instead.\"","then":"Meera glances over, surprised, but doesn't say anything."},{"text":"\"That's a bit old-fashioned, don't you think, Aunty?\"","then":"Her mother bristles slightly. \"I'm just saying what I know.\""}],"why":"Naming the shared plan out loud, even to family, protects it from slipping back."}],"relearn":"Name the intention to build as equals early; don't leave roles to default."},
  {"id":"cb-1196","cat":"starting-strong","type":"role-play","persona":"any","source":"money openness","hook":"Wedding costs are piling up, and you two have never mapped out finances.","setup":"Tonight, the caterer's quote arrives, bigger than planned.","steps":[{"prompt":"Siddharth says: \"This is more than I thought. We'll manage somehow, I guess.\"","options":[{"text":"\"Can we map out how we'll handle money fairly, together?\"","then":"He exhales. \"Yeah. Honestly, I've been avoiding that conversation.\"","best":true},{"text":"\"Let's just avoid the topic and hope it works itself out.\"","then":"He nods, but the next morning brings up the accounts himself."},{"text":"\"You handle the budget. You're better with numbers.\"","then":"He looks uneasy. \"I don't want to do this alone, though.\""},{"text":"\"We'll figure it out, no need to worry.\"","then":"He nods, though the worry doesn't actually go anywhere."}],"why":"Naming a real, fair plan turns a scary bill into something you face together."},{"prompt":"Siddharth asks: \"Okay. Separate savings, joint account, or what, once we're married?\"","options":[{"text":"\"Let's lay out both our incomes and debts first, then decide.\"","then":"He nods slowly. \"Fair. I haven't even told you about my loan yet.\"","best":true},{"text":"\"Whatever's simplest to manage day to day, once we're married.\"","then":"He shrugs. \"Simplest for who, though? We should think about that.\""},{"text":"\"Joint account, obviously, once we're married that's normal.\"","then":"He pauses. \"Maybe, but can we actually think it through first?\""},{"text":"\"Let's just decide after the wedding, less to worry about now.\"","then":"He nods, though the bill from tonight is still sitting there unpaid."}],"why":"Looking at the real numbers first grounds the decision in facts, not guesses."},{"prompt":"He admits: \"I've actually got a student loan I haven't really mentioned.\"","options":[{"text":"\"Thank you for saying that. Let's plan around it together.\"","then":"He looks relieved. \"Okay. That's a weight off, actually telling you.\"","best":true},{"text":"\"That's fine, I guess. We'll deal with it whenever it comes up.\"","then":"He nods, though the loan stays a vague worry instead of a plan."},{"text":"\"Why didn't you tell me that sooner?\"","then":"He looks stung. \"I was scared of exactly this reaction, honestly.\""},{"text":"\"That's your debt, so that's your problem to handle.\"","then":"He goes quiet, and the openness from before closes off."}],"why":"Meeting honesty with a plan, not judgement, is what makes openness worth it."},{"prompt":"A few days later, Siddharth asks: \"Should we also tell our families how we're splitting things?\"","options":[{"text":"\"Only what we're both comfortable sharing. It's our plan.\"","then":"He nods. \"Agreed. Some of this can just stay between us.\"","best":true},{"text":"\"Sure, let's just tell them everything. It's probably easier.\"","then":"He hesitates, but goes along, and the plan starts feeling less private."},{"text":"\"Why would that matter to anyone else, honestly?\"","then":"He shrugs. \"Fair, I guess. Just thought I'd ask.\""},{"text":"\"Tell your family whatever you want. I don't really mind.\"","then":"He nods, though it's unclear if that's actually true for you."}],"why":"Deciding together what stays private keeps the plan a shared one, not a public one."}],"relearn":"Open an honest, fair money conversation early; avoiding it isn't a strong start."},
  {"id":"cb-1197","cat":"starting-strong","type":"role-play","persona":"any","source":"sharing home work","hook":"Three weeks into living together, you realise you're doing nearly all the cooking and cleaning.","setup":"Tonight, doing dishes alone again, you decide to say something.","steps":[{"prompt":"Vikas calls from the couch: \"Need any help in there?\"","options":[{"text":"\"Actually, yes. I'm doing most of this. Can we split it fairly?\"","then":"He comes in, surprised. \"Oh. I didn't realise it was this lopsided.\"","best":true},{"text":"\"It's fine. I've basically got a system going at this point.\"","then":"He calls back \"Okay, cool\" and stays on the couch, relieved."},{"text":"\"No, I've got it, like always.\"","then":"He relaxes back into the couch, and the pattern continues unnoticed."},{"text":"\"You could offer without being asked, you know.\"","then":"He calls back \"Sorry!\" but doesn't actually get up to help."}],"why":"Naming the imbalance plainly, with an \"I\" opener, is what resets it."},{"prompt":"The next night, Vikas notices the sink again and asks: \"How should we split this stuff?\"","options":[{"text":"\"Let's list it all out and each take clear, fair pieces.\"","then":"He grabs a notepad. \"Good idea, let's see what 'all of it' even is.\"","best":true},{"text":"\"Whatever you're comfortable with, I don't want to make this a whole thing.\"","then":"He nods vaguely, and the actual split stays undefined."},{"text":"\"You do the outside stuff. I'll keep doing the inside.\"","then":"He pauses. \"Isn't that just what's already happening, though?\""},{"text":"\"Just help out more when you notice something.\"","then":"He nods, though \"when I notice\" turns out to be pretty rarely."}],"why":"A clear, listed split, not vague goodwill, is what actually changes the pattern."},{"prompt":"A week later, dishes pile up again, and Vikas says: \"Sorry, I forgot it was my turn.\"","options":[{"text":"\"It's okay. Can we put the list somewhere we'll both actually see it?\"","then":"He nods. \"Let's stick it on the fridge tonight, so neither forgets.\"","best":true},{"text":"\"It's fine. I'll just do it this once since I'm already in here.\"","then":"He looks relieved, and \"just this once\" quietly becomes the pattern."},{"text":"\"You always forget your turn, honestly.\"","then":"He looks defensive. \"I said sorry. It won't happen every time.\""},{"text":"\"Forget the list, it's clearly not working anyway.\"","then":"He shrugs, and the chores start drifting back toward you again."}],"why":"Fixing the system, not just forgiving the slip, is what makes the split hold."}],"relearn":"Raise an unfair home-work split early with an 'I' opener; sharing it is a strong start."},
  {"id":"cb-1198","cat":"starting-strong","type":"role-play","persona":"any","source":"in-law boundary, kindly","hook":"Your mother-in-law has already picked the curtains and furniture for your new bedroom.","setup":"She proudly shows you both the plan, expecting approval.","steps":[{"prompt":"She asks: \"Don't you love it? I picked everything myself.\"","options":[{"text":"\"It's thoughtful. For our room though, we'd like to decide together.\"","then":"She looks surprised, then a little wounded. \"Oh. I just wanted to help.\"","best":true},{"text":"\"It's lovely. Let's just go with whatever you've already picked.\"","then":"She beams. Your partner looks at you, surprised you gave in so fast."},{"text":"\"I actually hate all of this, to be honest.\"","then":"She looks hurt. \"I spent weeks on this, you know.\""},{"text":"\"Whatever makes you happy, Aunty.\"","then":"She smiles, but your partner quietly says you should both have a say."}],"why":"Naming appreciation and the boundary together keeps both respect and limits true."},{"prompt":"Your partner's father adds: \"She just wants to help. Let her have this one.\"","options":[{"text":"\"We love that she wants to help. This one, we'd like to choose.\"","then":"He nods slowly. \"Fair enough. We'll let you two decide, then.\"","best":true},{"text":"\"I suppose it's not worth a whole disagreement over curtains.\"","then":"He smiles, relieved, though she noticed the pause before you agreed."},{"text":"\"It's our room, not really anyone else's decision.\"","then":"He looks taken aback. \"We were only trying to help, you know.\""},{"text":"\"Fine, let her have this one, like you said.\"","then":"He relaxes, and the pattern quietly repeats with the next room too."}],"why":"Naming love and the limit together, in one breath, keeps the boundary kind."},{"prompt":"Later, your mother-in-law asks quietly: \"Did I do something wrong?\"","options":[{"text":"\"Not at all. We just want some choices to be ours, as a couple.\"","then":"She nods slowly. \"I understand. I'll ask next time, I promise.\"","best":true},{"text":"\"No, no, it's honestly fine. You didn't do anything wrong at all, really.\"","then":"She looks relieved, though the actual boundary never really lands."},{"text":"\"Kind of, yeah, it did feel like a lot.\"","then":"She looks stricken. \"Oh no. I only ever meant to help.\""},{"text":"\"Don't worry about it. We'll just go with your plan.\"","then":"She brightens, and the earlier boundary quietly disappears."}],"why":"Naming the boundary again, warmly, makes it a lasting habit, not one stand."},{"prompt":"Weeks later, she calls before buying anything for the guest room: \"Would this colour work for you two?\"","options":[{"text":"\"That means a lot that you asked. Let's pick it together.\"","then":"She sounds pleased. \"Good. I wanted to get it right this time.\"","best":true},{"text":"\"Oh, you really didn't have to check with us about something so small.\"","then":"She sounds a little unsure whether checking in was even wanted."},{"text":"\"Whatever you think is best, Aunty, like before.\"","then":"She hesitates, then goes with her own plan again anyway."},{"text":"\"Honestly, we don't really care about the guest room.\"","then":"She sounds deflated. \"Oh. Alright, I'll just decide then.\""}],"why":"Welcoming her asking first shows the boundary became a habit, not one hard talk."}],"relearn":"Set kind in-law boundaries as a couple-unit; respect and limits can both be true."},
  {"id":"cb-1199","cat":"starting-strong","type":"role-play","persona":"any","source":"talking kids","hook":"You and Arnav are talking marriage seriously, but have never actually discussed children.","setup":"Tonight, a friend's baby announcement comes up over dinner.","steps":[{"prompt":"Arnav says: \"Everyone's having kids lately, huh. Wild.\"","options":[{"text":"\"Before we commit, can we talk about if and when we'd want kids?\"","then":"He sets down his fork. \"Good idea, actually. I've been wondering too.\"","best":true},{"text":"\"I guess we probably already agree on that, so we're fine.\"","then":"He nods vaguely, though neither of you has actually said anything."},{"text":"\"Kids are years away. Let's not worry about any of that now.\"","then":"He shrugs. \"Sure, I guess we'll cross that bridge later.\""},{"text":"\"I assume you want kids too, right?\"","then":"He pauses. \"I mean, maybe? I hadn't really said that out loud.\""}],"why":"Naming the real question now, not assuming, is what makes it an honest choice."},{"prompt":"Later that week, Arnav says: \"About kids. I'm honestly not sure yet. Is that a problem?\"","options":[{"text":"\"Not a problem. I'd rather know that now than assume later.\"","then":"He relaxes. \"Okay, good. I was worried you'd want an answer today.\"","best":true},{"text":"\"I mean, I sort of need you to be sure before we go any further.\"","then":"He tenses. \"That feels like pressure, not a real conversation.\""},{"text":"\"That's fine. We'll figure it out eventually.\"","then":"He nods, though the actual uncertainty just gets quietly shelved."},{"text":"\"You should probably decide that before we get engaged.\"","then":"He looks anxious. \"Decide it just like that, on a deadline?\""}],"why":"Making room for 'not sure yet' keeps the conversation honest instead of forced."},{"prompt":"He asks: \"What if we still don't agree by the time we're actually engaged?\"","options":[{"text":"\"Then we keep talking, honestly, until we actually know together.\"","then":"He nods slowly. \"Okay. I can work with that. Let's keep checking in.\"","best":true},{"text":"\"I suppose whoever feels more strongly should probably decide.\"","then":"He looks uneasy. \"That doesn't feel fair to either of us, really.\""},{"text":"\"Then maybe we're not actually right for each other.\"","then":"He looks startled. \"That escalated fast, over a maybe.\""},{"text":"\"We'll just deal with it when it actually comes up.\"","then":"He nods, though the question stays exactly where it started."}],"why":"Committing to keep talking, not to a forced answer, respects where you both are."}],"relearn":"Talk whether and when to have children honestly before committing; don't assume you agree."},
  {"id":"cb-1200","cat":"starting-strong","type":"role-play","persona":"any","source":"both careers","hook":"Rajiv got a great offer in Bangalore, the same week you got shortlisted here.","setup":"He brings up packing boxes before you've discussed it.","steps":[{"prompt":"Rajiv says: \"This Bangalore offer's huge. We should start planning the move.\"","options":[{"text":"\"Both our careers matter. Let's weigh this together.\"","then":"He pauses. \"Oh, I didn't realise you had something going too.\"","best":true},{"text":"\"Sure, your offer's clearly the bigger opportunity.\"","then":"He nods, already looking up moving companies online."},{"text":"\"Whatever's best for your career, I'll adjust.\"","then":"He smiles, relieved, and starts planning without a second thought."},{"text":"\"You didn't even ask what I've got going on.\"","then":"He looks caught out. \"You're right. Tell me?\""}],"why":"Naming both careers as equally real puts the decision on fair footing."},{"prompt":"Later, Rajiv notices you've gone quiet and asks: \"What's happening on your end?\"","options":[{"text":"\"I've been shortlisted for a role here I'm genuinely excited about.\"","then":"He looks surprised. \"I had no idea. Okay, this actually changes things.\"","best":true},{"text":"\"Nothing major, just some interviews, nothing worth changing plans over.\"","then":"He nods, but the next day asks you about the shortlist again."},{"text":"\"It doesn't matter, your offer's better anyway.\"","then":"He frowns. \"That's not really for you to decide alone, is it?\""},{"text":"\"Forget it, I'll just look for something in Bangalore.\"","then":"He hesitates. \"Are you sure? That sounds like you're giving something up.\""}],"why":"Naming your own opportunity plainly gives the decision something real to weigh."},{"prompt":"He asks: \"So how do we actually decide, then, fairly?\"","options":[{"text":"\"Weigh both offers honestly, and choose based on both our futures.\"","then":"He nods. \"Okay. Let's actually sit down and compare, properly.\"","best":true},{"text":"\"Whichever one pays more should probably be the deciding factor.\"","then":"He hesitates. \"Is that really what matters most here, though?\""},{"text":"\"You already basically decided, so let's just go with yours.\"","then":"He looks uneasy. \"I don't want it to be like that, honestly.\""},{"text":"\"Let's just flip a coin. It's too hard to decide otherwise.\"","then":"He laughs, unsure if you're serious, and the real talk stalls."}],"why":"Weighing both futures honestly is what makes the decision actually shared."},{"prompt":"A few days later, Rajiv says: \"I made a list comparing both offers.\"","options":[{"text":"\"Let's go through it together and decide as a team.\"","then":"He nods, pleased. \"That's what I was hoping you'd say.\"","best":true},{"text":"\"Just tell me what the list says and I'll go with whatever it shows.\"","then":"He hesitates. \"I'd rather we look at it together, honestly.\""},{"text":"\"I trust your judgement, just decide for both of us.\"","then":"He looks uneasy. \"I don't want to be the one deciding alone, though.\""},{"text":"\"Let's not look at it today, I'm not in the mood.\"","then":"He nods, though the decision just keeps waiting in limbo."}],"why":"Going through the comparison together keeps the decision genuinely shared."}],"relearn":"Treat both partners' careers as equally real and decide moves together."},
  {"id":"cb-1201","cat":"starting-strong","type":"role-play","persona":"any","source":"naming the mental load","hook":"A month into living together, you're the one remembering every bill and plan.","setup":"Tonight, you're making a list again while he watches TV.","steps":[{"prompt":"He glances over: \"What are you writing? Another list?\"","options":[{"text":"\"Yeah. I'm doing all the remembering for us. Can we share that?\"","then":"He mutes the TV. \"Wait, really? I didn't realise that was all on you.\"","best":true},{"text":"\"Just our schedule, it's honestly not a big deal, don't worry.\"","then":"He nods and turns the TV back up, and the list keeps growing regardless."},{"text":"\"Nothing, just keeping track of things, like always.\"","then":"He shrugs and goes back to watching, unaware anything's off."},{"text":"\"You'd know if you ever looked at the calendar yourself.\"","then":"He looks stung. \"That's a bit harsh, don't you think?\""}],"why":"Naming the invisible work plainly is the only way it becomes visible enough to share."},{"prompt":"The next day, he finds the list and asks: \"How could I help carry some of this?\"","options":[{"text":"\"You take ownership of noticing some things too, not just doing tasks.\"","then":"He nods slowly. \"That's fair. I've been waiting to be told, huh.\"","best":true},{"text":"\"Just help me out more when I ask, that would already be something.\"","then":"He agrees easily, though the remembering itself stays entirely on you."},{"text":"\"I don't know, just pay more attention, I guess.\"","then":"He looks unsure what that actually means day to day."},{"text":"\"Forget it, it's probably easier if I just keep doing it.\"","then":"He relaxes, relieved, and the load quietly stays exactly where it was."}],"why":"Asking him to notice, not just execute, is what actually shares the invisible part."},{"prompt":"A week later, he says: \"I remembered the electricity bill today, by the way.\"","options":[{"text":"\"That means a lot. That's exactly the noticing I meant.\"","then":"He looks pleased. \"Okay. I want to actually keep this up, not just today.\"","best":true},{"text":"\"Only the one thing though, there's honestly a lot more than that.\"","then":"He deflates slightly. \"Right. I guess I've still got a way to go.\""},{"text":"\"Finally, only took a month.\"","then":"He winces. \"I said I'm trying. Give me a bit of credit here.\""},{"text":"\"Good, now do that for everything else too.\"","then":"He nods, a little overwhelmed by the sudden size of the ask."}],"why":"Naming the small win specifically encourages the habit, not just raises the bar."}],"relearn":"Name the mental load and share it; making it visible early is a strong start."},
  {"id":"cb-1202","cat":"starting-strong","type":"role-play","persona":"any","source":"repair after a fight","hook":"You and Dhruv just had your first real fight, over something small that spiralled.","setup":"It's been quiet for twenty minutes since it ended.","steps":[{"prompt":"Dhruv finally says: \"That got pretty heated. Sorry, kind of.\"","options":[{"text":"\"It did. Can we figure out how we cool off and actually repair?\"","then":"He nods slowly. \"Yeah. I don't want every fight to end like that.\"","best":true},{"text":"\"It's fine. Let's just pretend that whole thing never happened.\"","then":"He agrees, relieved, though the same thing will likely happen again."},{"text":"\"You were the one who got heated, not me.\"","then":"He bristles. \"I wasn't the only one raising my voice, though.\""},{"text":"\"Let's just not talk about it.\"","then":"He nods, and the room stays quiet a while longer."}],"why":"Naming a repair habit now, not just moving on, softens the next fight."},{"prompt":"Later that night, Dhruv asks: \"What should we do differently next time?\"","options":[{"text":"\"Take a real break when it gets heated, then come back on purpose.\"","then":"He nods. \"I like that. A real break, not just storming off.\"","best":true},{"text":"\"I don't know, maybe just try to stay a bit calmer in the moment.\"","then":"He nods, though \"stay calmer\" isn't really a plan either of you can use."},{"text":"\"You should just learn to control your temper.\"","then":"He looks defensive. \"This isn't only about my temper, though.\""},{"text":"\"Let's just avoid the topics that set us off.\"","then":"He looks unsure. \"Forever? That feels like avoiding the real problem.\""}],"why":"A real break with a plan to return beats vague promises to just be calmer."},{"prompt":"Weeks later, a new argument heats up, and Dhruv says: \"I need a break before I say something I regret.\"","options":[{"text":"\"Okay. Let's take it, and come back to finish this properly.\"","then":"He nods and steps out, returning minutes later, calmer, ready to talk.","best":true},{"text":"\"Fine, but don't take forever about it this time around.\"","then":"He nods, a little tense, and the break feels more like a punishment."},{"text":"\"We don't have time for breaks right now.\"","then":"He looks frustrated. \"This is exactly what we said we'd do, though.\""},{"text":"\"Sure, take all the time you need. I don't even care anymore.\"","then":"He pauses, hurt, unsure if that's really what you mean."}],"why":"Actually using the break, without resentment, is how the new habit sticks."},{"prompt":"A month later, Dhruv asks: \"Have our fights been any better lately, do you think?\"","options":[{"text":"\"Some are. The breaks help when we come back and repair.\"","then":"He smiles. \"Good. Let's keep doing it, even when it feels unnecessary.\"","best":true},{"text":"\"Maybe, I guess, though I haven't really been keeping track much.\"","then":"He nods, though neither of you names what's actually been working."},{"text":"\"I hadn't really noticed, honestly.\"","then":"He looks a little deflated that you hadn't clocked the change."},{"text":"\"Let's not jinx it by talking about it.\"","then":"He laughs, though the habit stays a little unspoken and fragile."}],"why":"Naming what's working keeps you both intentionally choosing to keep doing it."}],"relearn":"Build a cool-down-and-repair habit early; coming back to repair starts a partnership strong."},
  {"id":"cb-1203","cat":"starting-strong","type":"role-play","persona":"any","source":"equal say on big things","hook":"Karan's promotion means he earns much more now, and he's started deciding things solo.","setup":"Tonight he mentions he's already picked an apartment.","steps":[{"prompt":"Karan says: \"I found us a great new apartment. I'll sign the lease Friday.\"","options":[{"text":"\"Wait, that's a big decision. Shouldn't we choose it together?\"","then":"He pauses. \"I guess I just figured, since I'm covering more of it now.\"","best":true},{"text":"\"If you're paying more of it, I suppose it makes sense you'd choose.\"","then":"He nods, relieved, and goes ahead with signing it Friday as planned."},{"text":"\"Sure, whatever you think is best.\"","then":"He smiles and moves ahead, taking your agreement at face value."},{"text":"\"You've been deciding a lot lately, actually.\"","then":"He looks surprised. \"Have I? I didn't really notice that.\""}],"why":"Naming it as a shared decision, plainly, stops income from becoming the vote."},{"prompt":"Later, Karan notices you're quiet and asks: \"Is this about the money? I didn't mean it like that.\"","options":[{"text":"\"It's about big calls staying ours, whoever earns more.\"","then":"He nods slowly. \"Okay. I hear that. I didn't mean to just take over.\"","best":true},{"text":"\"Kind of, yeah. You've changed since the promotion.\"","then":"He looks hurt. \"That's not fair. I'm the same person.\""},{"text":"\"No, it's fine, forget I said anything.\"","then":"He relaxes, but it stays on his mind for days."},{"text":"\"Yes, it's exactly about the money, obviously.\"","then":"He stiffens. \"That's not really fair, I'm trying here.\""}],"why":"Naming the principle, equal say regardless of income, is clearer than naming money."},{"prompt":"He asks, thinking it over: \"So how did I even end up deciding things alone?\"","options":[{"text":"\"I think we both let 'you earn more' quietly become 'you decide more'.\"","then":"He nods slowly. \"Yeah. That's exactly what happened, isn't it.\"","best":true},{"text":"\"Honestly, I probably should have said something sooner than this.\"","then":"He nods, though the actual pattern still isn't named clearly."},{"text":"\"You just started doing it, I didn't really have a say.\"","then":"He looks defensive. \"That's not fair, I never excluded you on purpose.\""},{"text":"\"I don't know, it just happened gradually, I guess.\"","then":"He shrugs, and the pattern stays a bit vague and unaddressed."}],"why":"Naming exactly how income quietly became authority makes the pattern fixable."},{"prompt":"Karan offers: \"What if we agree: anything big, we decide together, no matter who's paying?\"","options":[{"text":"\"Yes. Let's name what counts as 'big' so we both know.\"","then":"He nods. \"Good idea. Apartments, big purchases, anything like that.\"","best":true},{"text":"\"Sure, we'll figure out what's big as we go along.\"","then":"He agrees, though \"big\" stays vague enough to slip past you again later."},{"text":"\"Let's just say everything, to be safe.\"","then":"He hesitates. \"Everything? Even small day-to-day stuff?\""},{"text":"\"I trust you to know what counts as big.\"","then":"He looks unsure. \"I'd rather we actually agreed on that together.\""}],"why":"Naming the actual scope of 'big' makes the agreement usable, not just nice words."},{"prompt":"Weeks later, Karan says: \"There's a big investment opportunity. I want to run it by you properly first.\"","options":[{"text":"\"Thank you for bringing it to me. Let's go through it together.\"","then":"He smiles. \"That's the whole point, right? Let's actually look at it now.\"","best":true},{"text":"\"You clearly understand this stuff better, so you should decide.\"","then":"He hesitates. \"I'd rather we looked at it together, like we agreed.\""},{"text":"\"Do whatever you think is right, I trust your judgement.\"","then":"He pauses. \"I don't want to be the one deciding alone again, though.\""},{"text":"\"I'm too busy to look at this properly right now.\"","then":"He nods, though the old pattern threatens to quietly creep back."}],"why":"Actually showing up for the big decision is how the equal-say agreement holds."}],"relearn":"Big decisions stay shared; a bigger income doesn't buy a bigger vote."},
  {"id":"cb-1204","type":"spot","persona":"any","source":"strong-start red flags","hook":"Spot the two red flags in how this couple is starting out.","scene":[{"id":"a","text":"They talk money and roles openly","trick":false},{"id":"b","text":"One partner avoids every hard topic","trick":true},{"id":"c","text":"They agree how they'll handle conflict","trick":false},{"id":"d","text":"Chores quietly default to one person","trick":true},{"id":"e","text":"Both careers are taken seriously","trick":false}],"why":"Avoiding hard topics and defaulting chores to one person are the weak-start red flags.","relearn":"A strong start talks openly and shares the load; avoiding topics and defaulting roles are red flags.","cat":"starting-strong"},
  {"id":"cb-1205","type":"spot","persona":"any","source":"equality red flags","hook":"Spot the two lines that build in imbalance from day one.","scene":[{"id":"a","text":"\"Let's split chores and decisions\"","trick":false},{"id":"b","text":"\"The home is your department now\"","trick":true},{"id":"c","text":"\"Both our careers matter\"","trick":false},{"id":"d","text":"\"I earn more, so I decide\"","trick":true},{"id":"e","text":"\"Big calls, we make together\"","trick":false}],"why":"Assigning the home to one partner and tying decisions to income are the imbalance red flags.","relearn":"Sharing chores, careers and decisions builds equality; 'your department' and 'I decide' build imbalance.","cat":"starting-strong"},
  {"id":"cb-1206","type":"spot","persona":"any","source":"mental-load red flags","hook":"Spot the two signs the invisible load is being dumped on one partner.","scene":[{"id":"a","text":"They plan and remember together","trick":false},{"id":"b","text":"One silently tracks every chore and date","trick":true},{"id":"c","text":"\"Just tell me what to do\" every time","trick":true},{"id":"d","text":"They share who-does-what openly","trick":false},{"id":"e","text":"Both notice when something needs doing","trick":false}],"why":"One person silently tracking everything, and 'just tell me' offloading, dump the mental load on one.","relearn":"Sharing the noticing and planning splits the mental load; silent tracking and 'just tell me' dump it on one.","cat":"starting-strong"},
  {"id":"cb-1207","type":"spot","persona":"any","source":"money red flags","hook":"Spot the two unhealthy money moves as a couple starts out.","scene":[{"id":"a","text":"They agree a fair, open money plan","trick":false},{"id":"b","text":"One hides debts from the other","trick":true},{"id":"c","text":"The higher earner controls it all secretly","trick":true},{"id":"d","text":"Both keep some personal autonomy","trick":false},{"id":"e","text":"They talk spending honestly","trick":false}],"why":"Hiding debts and one partner secretly controlling all the money are the red flags.","relearn":"Open, fair money with some autonomy is healthy; hidden debts and secret control are red flags.","cat":"starting-strong"},
  {"id":"cb-1242","type":"spot","persona":"any","source":"in-law red flags","hook":"Spot the two unhealthy ways this couple handles family expectations.","scene":[{"id":"a","text":"They decide together, then tell both families","trick":false},{"id":"b","text":"Each is pulled to their own parents alone","trick":true},{"id":"c","text":"One family's way always simply wins","trick":true},{"id":"d","text":"They set kind, clear boundaries as a couple","trick":false},{"id":"e","text":"They respect elders and still choose together","trick":false}],"why":"Being pulled apart and letting one family always win are the red flags for a couple-unit.","relearn":"Facing family as a united couple-unit is strong; being split or one side always winning are red flags.","cat":"starting-strong"},
  {"id":"cb-1208","type":"spot","persona":"any","source":"repair red flags","hook":"Spot the two habits that will hurt this couple's early conflicts.","scene":[{"id":"a","text":"They cool off, then circle back to repair","trick":false},{"id":"b","text":"They sweep every fight under the rug","trick":true},{"id":"c","text":"They keep score of old wins and losses","trick":true},{"id":"d","text":"They use 'I felt...' not 'you never...'","trick":false},{"id":"e","text":"They say sorry and mean it","trick":false}],"why":"Sweeping fights aside and keeping score are the habits that erode a young partnership.","relearn":"Repair and 'I felt...' build a partnership; sweeping fights aside and scorekeeping are red flags.","cat":"starting-strong"},
  {"id":"cb-1209","type":"spot","persona":"any","source":"'me' inside 'us' red flags","hook":"Spot the two signs 'us' is starting to erase 'me'.","scene":[{"id":"a","text":"They each keep their own friends","trick":false},{"id":"b","text":"One gives up everything they loved","trick":true},{"id":"c","text":"They cut off all outside friendships","trick":true},{"id":"d","text":"They support each other's growth","trick":false},{"id":"e","text":"They keep their own interests too","trick":false}],"why":"Giving up everything you love and cutting off all friends are the signs 'us' is erasing 'me'.","relearn":"Healthy 'us' keeps room for each 'me'; giving up everything and cutting off friends are red flags.","cat":"starting-strong"},
  {"id":"cb-1210","type":"spot","persona":"any","source":"fair-festival red flags","hook":"Spot the two unfair defaults around festivals and rituals.","scene":[{"id":"a","text":"They share the festival cooking","trick":false},{"id":"b","text":"She fasts and cooks alone while he relaxes","trick":true},{"id":"c","text":"All ritual work falls to the new bride","trick":true},{"id":"d","text":"They plan celebrations together","trick":false},{"id":"e","text":"They split the prep and the cleanup","trick":false}],"why":"One partner doing all the fasting, cooking and ritual work alone are the unfair-default red flags.","relearn":"Sharing festival and ritual work is fair; dumping it all on the bride is an unfair-default red flag.","cat":"starting-strong"},
  {"id":"cb-1211","type":"spot","persona":"any","source":"expectations red flags","hook":"Spot the two ways this couple is mishandling unspoken expectations.","scene":[{"id":"a","text":"They compare their hopes for married life","trick":false},{"id":"b","text":"Each assumes the other already agrees","trick":true},{"id":"c","text":"They stay quiet to avoid any friction","trick":true},{"id":"d","text":"They name where their pictures differ","trick":false},{"id":"e","text":"They ask instead of guessing","trick":false}],"why":"Assuming agreement and staying silent to dodge friction are the unspoken-expectation red flags.","relearn":"Naming and comparing expectations is strong; assuming agreement and silence to avoid friction are red flags.","cat":"starting-strong"},
  {"id":"cb-1212","type":"spot","persona":"any","source":"privacy red flags","hook":"Spot the two signs this couple has no healthy space of its own.","scene":[{"id":"a","text":"They agree what privacy they'll keep","trick":false},{"id":"b","text":"Family expects full access to phones always","trick":true},{"id":"c","text":"They surrender all space to seem 'good'","trick":true},{"id":"d","text":"They protect some couple time","trick":false},{"id":"e","text":"They keep healthy limits, kindly","trick":false}],"why":"Full family access to phones and surrendering all space to look agreeable are the red flags.","relearn":"A couple needs healthy space; full-access demands and surrendering all privacy are red flags.","cat":"starting-strong"},
  {"id":"cb-1213","type":"spot","persona":"any","source":"elder-care red flags","hook":"Spot the two unfair ways elder-care is being handled.","scene":[{"id":"a","text":"They plan care for both sides together","trick":false},{"id":"b","text":"They assume the daughter-in-law absorbs it all","trick":true},{"id":"c","text":"Only one side's parents are even discussed","trick":true},{"id":"d","text":"They agree a fair, shared plan early","trick":false},{"id":"e","text":"Both partners stay responsible","trick":false}],"why":"Dumping care on the daughter-in-law and ignoring one side's parents are the unfair red flags.","relearn":"Fair, shared elder-care planning is strong; dumping it on one partner or ignoring one side are red flags.","cat":"starting-strong"},
  {"id":"cb-1214","type":"spot","persona":"any","source":"wedding-vs-marriage red flags","hook":"Spot the two signs the day is crowding out the marriage.","scene":[{"id":"a","text":"They make time for partnership talks too","trick":false},{"id":"b","text":"All energy goes to the function only","trick":true},{"id":"c","text":"The wedding is treated as the finish line","trick":true},{"id":"d","text":"They invest in 'us', not just the day","trick":false},{"id":"e","text":"They keep talking the big topics","trick":false}],"why":"Pouring everything into the function and treating the wedding as the finish line are the red flags.","relearn":"A wedding is a day; investing only in the function and calling it the finish line are red flags.","cat":"starting-strong"},
  {"id":"cb-1215","type":"spot","persona":"any","source":"honesty red flags","hook":"Spot the two honesty red flags as this couple gets serious.","scene":[{"id":"a","text":"They share their real money picture","trick":false},{"id":"b","text":"One hides a big decision they've made","trick":true},{"id":"c","text":"They downplay things to avoid the talk","trick":true},{"id":"d","text":"They raise worries with 'I feel...'","trick":false},{"id":"e","text":"They tell each other the hard truths kindly","trick":false}],"why":"Hiding a big decision and downplaying things to dodge the talk are the honesty red flags.","relearn":"Honesty and 'I feel...' build a strong start; hiding decisions and downplaying to dodge talks are red flags.","cat":"starting-strong"},
  {"id":"cb-1216","type":"spot","persona":"any","source":"first-week red flags","hook":"Spot the two weak-start moves in this couple's first weeks together.","scene":[{"id":"a","text":"They set a fair chore baseline early","trick":false},{"id":"b","text":"They let an unfair habit just 'settle'","trick":true},{"id":"c","text":"They postpone every awkward conversation","trick":true},{"id":"d","text":"They agree how they'll handle conflict","trick":false},{"id":"e","text":"They name roles on purpose, together","trick":false}],"why":"Letting an unfair habit settle and postponing every awkward talk are the weak-start red flags.","relearn":"Early fair baselines and naming roles start strong; letting habits 'settle' and dodging talks are red flags.","cat":"starting-strong"},
  {"id":"cb-1217","type":"sort","persona":"Karthik","source":"equality-from-start","hook":"Sort: builds equality from day one, or builds in imbalance?","items":[{"id":"a","text":"Sharing chores and decisions"},{"id":"b","text":"One person does all the housework"},{"id":"c","text":"Both careers taken seriously"},{"id":"d","text":"One partner's plans always come first"},{"id":"e","text":"Splitting the mental load"},{"id":"f","text":"The higher earner decides everything"}],"bins":[{"id":"equal","label":"Builds equality","valence":"pos"},{"id":"imbalance","label":"Builds imbalance","valence":"neg"}],"key":{"a":"equal","b":"imbalance","c":"equal","d":"imbalance","e":"equal","f":"imbalance"},"relearn":"Sharing chores, careers, decisions and the mental load builds equality; one-sided defaults build imbalance.","cat":"starting-strong"},
  {"id":"cb-1218","type":"sort","persona":"any","source":"strong-vs-shaky-start","hook":"Sort: a strong start to a partnership, or a shaky one?","items":[{"id":"a","text":"Talking money and roles openly"},{"id":"b","text":"Avoiding every hard topic"},{"id":"c","text":"Agreeing how you'll repair after fights"},{"id":"d","text":"Assuming love sorts the details"},{"id":"e","text":"Naming expectations early"},{"id":"f","text":"Hoping your pictures already match"}],"bins":[{"id":"strong","label":"Strong start","valence":"pos"},{"id":"shaky","label":"Shaky start","valence":"neg"}],"key":{"a":"strong","b":"shaky","c":"strong","d":"shaky","e":"strong","f":"shaky"},"relearn":"Talking openly, agreeing repair and naming expectations start strong; avoiding and assuming start shaky.","cat":"starting-strong"},
  {"id":"cb-1219","type":"sort","persona":"Nisha","source":"talk-early-or-avoid","hook":"Sort: a conversation worth having early, or one people wrongly skip?","items":[{"id":"a","text":"Whether and when to have children"},{"id":"b","text":"Nothing, just see what happens"},{"id":"c","text":"How money will work between you"},{"id":"d","text":"Dodging anything that causes friction"},{"id":"e","text":"How you'll share elder-care"},{"id":"f","text":"Staying silent to seem easy-going"}],"bins":[{"id":"have","label":"Talk it early","valence":"pos"},{"id":"skip","label":"Skip / avoid","valence":"neg"}],"key":{"a":"have","b":"skip","c":"have","d":"skip","e":"have","f":"skip"},"relearn":"Children, money and elder-care are worth talking early; avoiding friction by avoiding topics isn't a strong start.","cat":"starting-strong"},
  {"id":"cb-1220","type":"sort","persona":"Pooja","source":"us-and-me","hook":"Sort: keeps room for both 'us' and 'me', or erases 'me'?","items":[{"id":"a","text":"Each still sees their own friends"},{"id":"b","text":"One gives up everything they loved"},{"id":"c","text":"Supporting each other's growth"},{"id":"d","text":"Cutting off all outside friendships"},{"id":"e","text":"Holding on to your own interests too"},{"id":"f","text":"Losing yourself entirely in the other"}],"bins":[{"id":"both","label":"Keeps us and me","valence":"pos"},{"id":"erase","label":"Erases me","valence":"neg"}],"key":{"a":"both","b":"erase","c":"both","d":"erase","e":"both","f":"erase"},"relearn":"Keeping your friends, interests and growth holds both 'us' and 'me'; giving up everything erases 'me'.","cat":"starting-strong"},
  {"id":"cb-1221","type":"sort","persona":"Pooja","source":"sharing-the-load","hook":"Sort: fairly shared work, or dumped on one partner?","items":[{"id":"a","text":"Both plan and remember things"},{"id":"b","text":"She silently tracks every chore"},{"id":"c","text":"They split cooking and cleaning"},{"id":"d","text":"All ritual work falls to the bride"},{"id":"e","text":"Both notice what needs doing"},{"id":"f","text":"One carries the whole mental load"}],"bins":[{"id":"shared","label":"Fairly shared","valence":"pos"},{"id":"dumped","label":"Dumped on one","valence":"neg"}],"key":{"a":"shared","b":"dumped","c":"shared","d":"dumped","e":"shared","f":"dumped"},"relearn":"Both planning, noticing and splitting work is fair; silent tracking and dumping rituals on one isn't.","cat":"starting-strong"},
  {"id":"cb-1222","type":"sort","persona":"Karthik","source":"money-footing","hook":"Sort: a sound way to start money together, or a shaky one?","items":[{"id":"a","text":"A fair, open shared plan"},{"id":"b","text":"One hides debts from the other"},{"id":"c","text":"Both keep some personal autonomy"},{"id":"d","text":"The higher earner secretly controls it"},{"id":"e","text":"Talking spending honestly"},{"id":"f","text":"Avoiding the money talk entirely"}],"bins":[{"id":"sound","label":"Sound footing","valence":"pos"},{"id":"shaky","label":"Shaky footing","valence":"neg"}],"key":{"a":"sound","b":"shaky","c":"sound","d":"shaky","e":"sound","f":"shaky"},"relearn":"An open, fair plan with autonomy and honesty starts money sound; hiding, secret control and avoidance are shaky.","cat":"starting-strong"},
  {"id":"cb-1223","type":"sort","persona":"any","source":"couple-unit-on-family","hook":"Sort: facing family as a couple-unit, or being pulled apart?","items":[{"id":"a","text":"Deciding together, then telling both families"},{"id":"b","text":"Each siding with their own parents alone"},{"id":"c","text":"Kind boundaries agreed between the two of you"},{"id":"d","text":"One family's way always simply wins"},{"id":"e","text":"Respecting elders and still choosing together"},{"id":"f","text":"Letting elders decide everything for you"}],"bins":[{"id":"united","label":"Couple-unit","valence":"pos"},{"id":"split","label":"Pulled apart","valence":"neg"}],"key":{"a":"united","b":"split","c":"united","d":"split","e":"united","f":"split"},"relearn":"Deciding together with kind boundaries faces family as a unit; being pulled apart or overruled splits you.","cat":"starting-strong"},
  {"id":"cb-1224","type":"sort","persona":"any","source":"reasons-to-talk-early","hook":"Sort: a strong reason to talk it through early, or a shaky excuse to skip it?","items":[{"id":"a","text":"\"Better to know before we commit\""},{"id":"b","text":"\"Bringing it up seems unromantic\""},{"id":"c","text":"\"We should start on the same page\""},{"id":"d","text":"\"Talking about it might cause a fight\""},{"id":"e","text":"\"Surprises later hurt more\""},{"id":"f","text":"\"Love will sort it out anyway\""}],"bins":[{"id":"sound","label":"Strong reason","valence":"pos"},{"id":"shaky","label":"Shaky reason","valence":"neg"}],"key":{"a":"sound","b":"shaky","c":"sound","d":"shaky","e":"sound","f":"shaky"},"relearn":"Knowing before you commit and starting aligned are strong reasons; 'unromantic' or 'love sorts it' are shaky.","cat":"starting-strong"},
  {"id":"cb-1225","type":"sort","persona":"any","source":"how-to-raise-it","hook":"Sort: a strong way to raise a hard topic, or a weak one?","items":[{"id":"a","text":"\"I feel stretched; can we share this?\""},{"id":"b","text":"\"You never help with anything\""},{"id":"c","text":"\"Can we figure this out together?\""},{"id":"d","text":"Staying silent and stewing"},{"id":"e","text":"\"Here's what I need; what do you need?\""},{"id":"f","text":"\"Fine, I'll just do it all myself\""}],"bins":[{"id":"good","label":"Strong opener","valence":"pos"},{"id":"poor","label":"Weak opener","valence":"neg"}],"key":{"a":"good","b":"poor","c":"good","d":"poor","e":"good","f":"poor"},"relearn":"'I feel...' and 'let's figure it out together' raise issues well; 'you never...', silence and martyrdom don't.","cat":"starting-strong"},
  {"id":"cb-1226","type":"reflect","persona":"any","source":"equal-start-reflection","hook":"There's no wrong answer here, just your own honest start.","prompt":"What's one habit you'd want set as equal from day one?","options":["Sharing the housework","Both careers mattering","Deciding money together","Splitting the mental load"],"affirm":"Any of these is a strong place to start, and naming it out loud makes it real.","ask":"What would that habit look like in a normal week?","deeper":"How could you bring it up with a partner?","relearn":"Naming an equality habit you want from day one is a strong, honest start.","cat":"starting-strong"},
  {"id":"cb-1227","type":"reflect","persona":"any","source":"hard-topic-reflection","hook":"No right answer, just notice what's true for you.","prompt":"Which early conversation feels hardest for you to start?","options":["Money","Children","Family boundaries","Sharing the load"],"affirm":"Whichever you picked, naming the hard one is the first step to having it.","ask":"What makes that one feel hard to start?","deeper":"What is one small way you could open it?","relearn":"Noticing which early talk feels hardest is the first step to actually having it.","cat":"starting-strong"},
  {"id":"cb-1228","type":"reflect","persona":"any","source":"me-inside-us-reflection","hook":"There's no wrong choice, just what keeps you whole.","prompt":"What's one part of 'you' you want to keep as you build 'us'?","options":["A friendship","A hobby or passion","Your own goals","Your own quiet time"],"affirm":"Keeping that part of you is exactly how a healthy 'us' stays strong.","ask":"What does that part of you give you?","deeper":"How could a partner help you keep it?","relearn":"Holding on to a piece of 'me' is how 'us' stays healthy, not selfish.","cat":"starting-strong"},
  {"id":"cb-1229","type":"reflect","persona":"any","source":"tone-setting-reflection","hook":"No marks here, just your own intention.","prompt":"What tone do you most want to set in your first months together?","options":["Honesty","Fairness","Kindness in conflict","Respect for each other's space"],"affirm":"Whatever you chose, naming the tone you want helps you live it.","ask":"What would that tone look like on a hard day?","deeper":"What might a partner want the tone to be, and why?","relearn":"Naming the tone you want to set early helps you actually build it.","cat":"starting-strong"},
  {"id":"cb-1230","type":"reflect","persona":"any","source":"fair-share-reflection","hook":"There's no wrong answer, just your honest picture.","prompt":"What does a fair share of the home work look like to you?","options":["Splitting by task","Splitting by time","Trading off by week","Whatever's fair for both"],"affirm":"There's no single right split; what matters is that it feels fair to you both.","ask":"What makes that split feel fair to you?","deeper":"How might a partner see it differently?","relearn":"A fair share is whatever both partners agree feels fair, not a fixed formula.","cat":"starting-strong"},
  {"id":"cb-1231","type":"reflect","persona":"any","source":"repair-style-reflection","hook":"No wrong answer, just what helps you reconnect.","prompt":"After a fight, what helps you come back and repair?","options":["A little space first","Talking it out soon","A small kind gesture","Saying sorry plainly"],"affirm":"Any of these can work; knowing your repair style helps you use it on purpose.","ask":"What does that give you after a fight?","deeper":"What might a partner need to repair, and how would you find out?","relearn":"Knowing what helps you repair after a fight lets you reconnect on purpose.","cat":"starting-strong"},
  {"id":"cb-1232","type":"reflect","persona":"any","source":"family-boundary-reflection","hook":"There's no wrong answer, just what feels right for you two.","prompt":"What's one boundary you'd want to agree on with family early?","options":["Some couple-only decisions","A bit of privacy","Festival plans shared fairly","Time just for you two"],"affirm":"Whatever you chose, agreeing it together as a couple is the strong part.","ask":"What would that boundary protect for you two?","deeper":"How could you raise it kindly with family?","relearn":"Agreeing a kind family boundary together as a couple is a strong, respectful start.","cat":"starting-strong"},
  {"id":"cb-1233","type":"reflect","persona":"any","source":"why-talk-early-reflection","hook":"No marks, just your own reason.","prompt":"Why might talking the big topics early matter to you?","options":["Fewer surprises later","Starting on the same page","Building real trust","Feeling like a team"],"affirm":"Whatever your reason, it's a good one, and it's worth acting on.","ask":"What would talking early change for you?","deeper":"What might make someone put these talks off?","relearn":"Your own reason to talk the big topics early is worth naming and acting on.","cat":"starting-strong"},
  {"id":"cb-1234","type":"match","persona":"any","source":"topic-to-why","hook":"Match each early topic to why it's worth talking through.","pairs":[{"left":"Money","right":"Avoid surprises and resentment later"},{"left":"Children","right":"Too big to assume you agree on"},{"left":"Roles at home","right":"Choose them, don't default by gender"},{"left":"Family boundaries","right":"Face expectations as a couple-unit"},{"left":"Conflict","right":"Agree how you'll repair in advance"}],"relearn":"Money, children, roles, family and conflict are all worth talking through early, each for its own reason.","cat":"starting-strong"},
  {"id":"cb-1235","type":"match","persona":"any","source":"weak-to-strong","hook":"Match each weak-start move to its stronger version.","pairs":[{"left":"Avoid hard topics","right":"Raise them early and kindly"},{"left":"Default chores to one","right":"Split the home work fairly"},{"left":"\"You never help\"","right":"\"I feel stretched; can we share?\""},{"left":"Hide debts","right":"Share your honest money picture"},{"left":"Sweep fights aside","right":"Cool off, then repair"}],"relearn":"Every weak-start move has a stronger version: raise it early, share fairly, use 'I feel...', be honest, repair.","cat":"starting-strong"},
  {"id":"cb-1236","type":"match","persona":"any","source":"statement-to-value","hook":"Match each thing a partner says to the value it shows.","pairs":[{"left":"\"Let's decide money together\"","right":"Fairness"},{"left":"\"I felt hurt when...\"","right":"Honest, non-blaming repair"},{"left":"\"Both our careers count\"","right":"Equality"},{"left":"\"Let's agree limits with family\"","right":"Healthy boundaries"},{"left":"\"Keep your own friends too\"","right":"Room for 'me' in 'us'"}],"relearn":"Fair money, 'I felt...' repair, equal careers, family limits and keeping friends each show a strong-start value.","cat":"starting-strong"},
  {"id":"cb-1237","type":"match","persona":"any","source":"load-to-share","hook":"Match each bit of invisible work to the visible chore it leads to.","pairs":[{"left":"Remembering birthdays","right":"Buying and sending the gift"},{"left":"Planning the week's meals","right":"Doing the grocery run"},{"left":"Noticing the gas cylinder is low","right":"Booking the refill"},{"left":"Tracking the school calendar","right":"Packing the right bag each day"},{"left":"Keeping elders' medicines stocked","right":"The pharmacy trip"}],"relearn":"Every visible chore starts with invisible work, like noticing and remembering, and both partners can carry it.","cat":"starting-strong"},
  {"id":"cb-1238","type":"match","persona":"any","source":"worry-to-opener","hook":"Match each worry to a kind way to open the conversation.","pairs":[{"left":"Chores feel unfair","right":"\"Can we re-split the home work?\""},{"left":"Unsure about kids","right":"\"Can we talk if and when?\""},{"left":"Spending feels one-sided","right":"\"Let's map money together\""},{"left":"In-laws expect too much","right":"\"Let's set limits as a couple\""},{"left":"A small upset is festering","right":"\"I felt hurt when...\""}],"relearn":"Every worry has a kind opener; naming it gently early beats bottling it until it bursts.","cat":"starting-strong"},
  {"id":"cb-1239","type":"match","persona":"any","source":"path-to-need","hook":"Match each early choice to the right route or person for support.","pairs":[{"left":"Feeling forced toward marriage","right":"Women Helpline 181"},{"left":"Immediate danger at home","right":"Emergency 112"},{"left":"A woman in distress, alone","right":"1091"},{"left":"Want to talk it through first","right":"A trusted counsellor"},{"left":"Someone under 18 being married off","right":"Childline 1098"}],"relearn":"Real routes exist: 181, 112, 1091, Childline 1098 and a counsellor each fit a different early need.","cat":"starting-strong"},
  {"id":"cb-1240","type":"match","persona":"any","source":"myth-to-truth","hook":"Match each starting-out myth to the truth that replaces it.","pairs":[{"left":"\"Money talk is unromantic\"","right":"It's how you start strong"},{"left":"\"Roles sort themselves out\"","right":"Name them on purpose"},{"left":"\"Home is the wife's job\"","right":"Care work is shared work"},{"left":"\"Wedding is the finish line\"","right":"A day; the marriage is the work"},{"left":"\"Earning more means deciding\"","right":"Big calls stay shared"}],"relearn":"Each starting myth has a truth: money talk starts strong, roles are chosen, care is shared, the marriage is the work.","cat":"starting-strong"},
  {"id":"cb-1241","type":"match","persona":"any","source":"habit-to-payoff","hook":"Match each early habit to what it builds over time.","pairs":[{"left":"Repairing after fights","right":"A partnership that lasts"},{"left":"Appreciating out loud","right":"A warmer bond"},{"left":"Sharing the load","right":"Fairness that holds"},{"left":"Keeping your own self","right":"Two whole people"},{"left":"Talking the big topics","right":"Fewer painful surprises"}],"relearn":"Repair, appreciation, sharing, keeping yourself and talking early each build a stronger partnership over time.","cat":"starting-strong"},
  {"id":"cb-1260","cat":"tools-and-help","type":"match","persona":"any","source":"tool to job","relearn":"Each partnership skill fits a job: repair for ruptures, appreciation for the bond, check-ins to stay close.","hook":"Match the partnership skill to the job it does.","pairs":[{"left":"A sincere repair","right":"Mends a rupture"},{"left":"Spoken appreciation","right":"Feeds the bond"},{"left":"A weekly check-in","right":"Catches small things early"},{"left":"An 'I felt...' opener","right":"Raises a hard topic safely"},{"left":"A money conversation","right":"Avoids painful surprises"}]},
  {"id":"cb-1261","cat":"tools-and-help","type":"match","persona":"Saxena","source":"when to use what","relearn":"A counsellor builds skills, a trusted friend gives perspective, a helpline answers coercion or danger.","hook":"Match the situation to the right kind of help.","pairs":[{"left":"You both want to communicate better","right":"A couples counsellor"},{"left":"You need an outside perspective","right":"A trusted friend or elder"},{"left":"You're being coerced to marry","right":"Women Helpline 181"},{"left":"Immediate danger at home","right":"Emergency 112"},{"left":"A minor is being married off","right":"Childline 1098"}]},
  {"id":"cb-1262","cat":"tools-and-help","type":"match","persona":"any","source":"'I' vs 'you'","relearn":"An 'I felt' opener invites repair; a 'you always' attack invites defence; name the need, not the flaw.","hook":"Match the way of raising a problem to what it tends to spark.","pairs":[{"left":"\"I felt unheard\"","right":"A conversation"},{"left":"\"You never listen\"","right":"Defensiveness"},{"left":"\"Can we figure this out?\"","right":"Teamwork"},{"left":"\"This is all your fault\"","right":"A standoff"},{"left":"\"Here's what I need\"","right":"A clear ask"}]},
  {"id":"cb-1263","cat":"tools-and-help","type":"match","persona":"Pooja","source":"naming the mental load","relearn":"Noticing what needs doing, remembering, and planning is invisible work; naming it lets it be shared, not thanked.","hook":"Pooja carries the household planning. Match each response to what it does.","pairs":[{"left":"He thanks her for carrying it","right":"Kind, but nothing changes"},{"left":"They split the planning, not just tasks","right":"The load actually gets lighter"},{"left":"He waits to be asked each time","right":"She still does the remembering"},{"left":"They keep a shared list","right":"Both can see what's needed"},{"left":"They review the week together on Sunday","right":"Fewer last-minute scrambles"}]},
  {"id":"cb-1264","cat":"tools-and-help","type":"match","persona":"any","source":"question to fit","relearn":"Good questions reveal goals, conflict style, money attitudes and family expectations: the things that shape fit.","hook":"Match the question to what it reveals about fit.","pairs":[{"left":"\"What do you want from life?\"","right":"Shared goals"},{"left":"\"How do you handle a fight?\"","right":"Conflict style"},{"left":"\"How should money work?\"","right":"Attitudes to spending"},{"left":"\"What role does family play?\"","right":"Expectations of relatives"},{"left":"\"Do you want children?\"","right":"A big life choice"}]},
  {"id":"cb-1265","cat":"tools-and-help","type":"match","persona":"any","source":"green vs red flag","relearn":"Owning mistakes, respecting boundaries and steadiness are green flags; control, contempt and love-bombing are red.","hook":"Match each behaviour to what it really shows.","pairs":[{"left":"Owns their mistakes","right":"Accountability"},{"left":"Respects your no","right":"Your limits matter to them"},{"left":"Tries to control who you see","right":"Cutting you off from friends"},{"left":"Treats you with contempt","right":"Looking down on you"},{"left":"Love-bombs then goes cold","right":"Keeping you off balance"}]},
  {"id":"cb-1266","cat":"tools-and-help","type":"match","persona":"any","source":"repair steps","relearn":"A real repair owns your part, names the hurt, makes it right and changes the pattern, not just 'sorry, moving on'.","hook":"Match the repair move to what it does.","pairs":[{"left":"\"I see I hurt you\"","right":"Owns your part"},{"left":"\"That must have stung\"","right":"Names their hurt"},{"left":"\"How can I make it right?\"","right":"Offers repair"},{"left":"\"I'll do this differently\"","right":"Changes the pattern"},{"left":"\"Whatever, let's move on\"","right":"Skips the repair"}]},
  {"id":"cb-1267","cat":"tools-and-help","type":"match","persona":"any","source":"reliable vs fragile","relearn":"Respect, communication and repair are reliable bases; sparks-only, status and 'they'll change' are fragile.","hook":"Match each basis to how sturdy it is.","pairs":[{"left":"Mutual respect","right":"A reliable base"},{"left":"Status and looks","right":"A fragile base"},{"left":"Good communication","right":"Built to last"},{"left":"Sparks alone","right":"Fades fast"},{"left":"Willingness to repair","right":"Weathers the storms"}]},
  {"id":"cb-1268","cat":"tools-and-help","type":"match","persona":"any","source":"talk before commit","relearn":"Money, children, roles and family boundaries are the big talks worth having before you commit, not after.","hook":"Match the topic to why you talk it through early.","pairs":[{"left":"Money","right":"Avoids surprise strain"},{"left":"Children","right":"A choice you must align on"},{"left":"Roles and chores","right":"Builds fairness in"},{"left":"Family boundaries","right":"Sets the couple-unit"},{"left":"Conflict style","right":"Predicts the daily peace"}]},
  {"id":"cb-1269","cat":"tools-and-help","type":"match","persona":"Sneha","source":"timeline pressure","relearn":"Your pace is yours; 'log kya kahenge', age and 'everyone's settling' are pressures, not reasons to commit.","hook":"Match the line you hear to what it really is.","pairs":[{"left":"\"Everyone your age is married\"","right":"Social pressure"},{"left":"\"What will people say?\"","right":"Just noise to tune out"},{"left":"\"I genuinely choose this person\"","right":"A sound reason"},{"left":"\"We've talked the big things through\"","right":"A solid foundation"},{"left":"\"I'm scared of being alone\"","right":"A shaky reason"}]},
  {"id":"cb-1270","cat":"tools-and-help","type":"match","persona":"Aditya","source":"every form is real","relearn":"Many forms of partnership rest on the same foundations of values, respect and consent; none is less real.","hook":"Every path rests on the same foundations. Match each one to what it looks like.","pairs":[{"left":"A love marriage","right":"Began by falling for each other"},{"left":"An arranged match","right":"Began with a family introduction"},{"left":"A same-gender partnership","right":"Two women, or two men, together"},{"left":"A long-term unmarried bond","right":"Committed without a wedding"},{"left":"Choosing not to marry","right":"A full life, just as it is"}]},
  {"id":"cb-1271","cat":"tools-and-help","type":"match","persona":"any","source":"skill to moment","relearn":"Each skill has its moment: listen when they're hurt, repair after a fight, check in when life gets busy.","hook":"Match the skill to the moment it's for.","pairs":[{"left":"Really listening","right":"When they're hurting"},{"left":"A repair attempt","right":"After a fight"},{"left":"A deliberate check-in","right":"When life gets busy"},{"left":"Setting a kind boundary","right":"With pushy family"},{"left":"Saying thank you out loud","right":"For everyday effort"}]},
  {"id":"cb-1272","cat":"tools-and-help","type":"match","persona":"any","source":"myth to truth 2","relearn":"Conflict is normal, doubts deserve a look, a partner can't be remade, and chemistry isn't compatibility.","hook":"Match the partnership myth to the truth.","pairs":[{"left":"\"Conflict means we're failing\"","right":"Every couple clashes sometimes"},{"left":"\"Doubts mean it's doomed\"","right":"Some nerves are normal"},{"left":"\"I'll change them later\"","right":"Choose them as they are"},{"left":"\"Chemistry is compatibility\"","right":"They're not the same"},{"left":"\"Love conquers all gaps\"","right":"Core fit still matters"}]},
  {"id":"cb-1273","cat":"tools-and-help","type":"match","persona":"Karthik","source":"sharing the load","relearn":"Sharing chores, decisions and both careers builds equality; defaulting it to one person builds imbalance.","hook":"Match the move to whether it builds equality.","pairs":[{"left":"Splitting chores fairly","right":"Builds equality"},{"left":"One person does it all","right":"Builds imbalance"},{"left":"Both careers taken seriously","right":"A fair partnership"},{"left":"Deciding together","right":"Shared power"},{"left":"\"Just tell me what to do\"","right":"Still her load to manage"}]},
  {"id":"cb-1274","cat":"tools-and-help","type":"match","persona":"any","source":"support to need","relearn":"Different troubles call for different help: skills from a counsellor, safety from a helpline, perspective from a friend.","hook":"Match the partnership trouble to the support that fits.","pairs":[{"left":"We keep having the same fight","right":"A couples counsellor"},{"left":"I feel unsafe at home","right":"Emergency 112"},{"left":"I'm being forced to marry","right":"Women Helpline 181"},{"left":"I just need to vent","right":"A trusted friend"},{"left":"I want to understand myself","right":"Personal therapy"}]},
  {"id":"cb-1275","cat":"tools-and-help","type":"match","persona":"any","source":"sign to read","relearn":"Feeling freer, more yourself and respected reads green; shrinking, walking on eggshells reads as a warning.","hook":"Match each feeling in a relationship to what may be behind it.","pairs":[{"left":"More yourself with them","right":"You don't have to perform"},{"left":"Freer to grow","right":"Your plans get support"},{"left":"Smaller and quieter","right":"Your voice is being squeezed out"},{"left":"Always managing their mood","right":"Their temper sets the rules"},{"left":"Respected in disagreements","right":"You can differ and stay close"}]},
  {"id":"cb-1276","cat":"tools-and-help","type":"match","persona":"any","source":"wedding vs marriage","relearn":"The wedding moments are lovely; their everyday versions are what a marriage runs on.","hook":"Match each wedding moment to the everyday version that matters more.","pairs":[{"left":"Saying the vows","right":"Keeping promises on ordinary days"},{"left":"Feeding each other sweets","right":"Cooking for each other on a tired night"},{"left":"Guests blessing the couple","right":"Friends who back you long after"},{"left":"Posing for the photos","right":"Being real with each other off camera"},{"left":"Dancing at the sangeet","right":"Having fun together years later"}]},
  {"id":"cb-1277","cat":"tools-and-help","type":"match","persona":"any","source":"boundary phrase","relearn":"Kind, clear boundaries with family protect the couple-unit without disrespect: name the need and the limit.","hook":"Match the kind boundary to what it protects.","pairs":[{"left":"\"We'll take a weekend just for us\"","right":"Time alone as a couple"},{"left":"\"We value your input, and we'll decide\"","right":"Respect with a limit"},{"left":"\"Let's talk privately before we answer\"","right":"A united reply"},{"left":"\"Please call before visiting\"","right":"Your home stays yours"},{"left":"\"We're not discussing children yet\"","right":"Your own timeline"}]},
  {"id":"cb-1278","cat":"tools-and-help","type":"match","persona":"any","source":"early habit to payoff","relearn":"Habits you build early set the pattern: open talk, fair sharing, repair and appreciation pay off for years.","hook":"Match the early habit to what it pays off as later.","pairs":[{"left":"Talking openly from day one","right":"Fewer buried resentments"},{"left":"Sharing the load fairly","right":"Lasting equality"},{"left":"Repairing small fights fast","right":"No pile-up"},{"left":"Appreciating out loud","right":"A warm bond"},{"left":"Protecting time together","right":"Staying connected"}]},
  {"id":"cb-1279","cat":"tools-and-help","type":"match","persona":"any","source":"consent in any path","relearn":"Consent means a real yes you could also say no to, with time, in a love match or an arranged one alike.","hook":"Match the consent move to what it secures.","pairs":[{"left":"Asking for time to decide","right":"No rushed answer"},{"left":"Real conversations first","right":"Knowing what you're agreeing to"},{"left":"Family respecting a refusal","right":"No one overriding you"},{"left":"Choosing, not being chosen for","right":"Your judgement leads"},{"left":"Changing your mind before the wedding","right":"A yes you can still take back"}]},
  {"id":"cb-1280","cat":"tools-and-help","type":"match","persona":"Nisha","source":"the children question","relearn":"Whether, when and how to have children is a choice to make together honestly, not to assume or be nagged into.","hook":"Match the children question to how to handle it.","pairs":[{"left":"\"Do we both want kids?\"","right":"Align before committing"},{"left":"\"When's the good news?\"","right":"Outside pressure to tune out"},{"left":"\"What if we differ?\"","right":"Talk it through honestly"},{"left":"\"Is not having kids okay?\"","right":"A fully valid choice"},{"left":"Assuming you agree","right":"A risky shortcut"}]},
  {"id":"cb-1281","cat":"tools-and-help","type":"match","persona":"any","source":"tool to feeling","relearn":"When you feel distant, turn toward; when hurt, repair; when grateful, say it; when stuck, get curious.","hook":"Match what you're feeling to the tool that fits.","pairs":[{"left":"Feeling distant","right":"Turn toward them"},{"left":"Feeling hurt","right":"Ask for a repair"},{"left":"Feeling grateful","right":"Say it out loud"},{"left":"Feeling stuck in a fight","right":"Get curious about the need"},{"left":"Feeling unheard","right":"Use an 'I felt' opener"}]},
  {"id":"cb-1282","cat":"tools-and-help","type":"match","persona":"any","source":"stance to action","relearn":"The game's values become actions: choose on values, share the load, respect every path, keep consent central.","hook":"Match the value to the action that lives it out.","pairs":[{"left":"Values over sparks","right":"Ask the real questions"},{"left":"Equality from day one","right":"Split the load fairly"},{"left":"Every path respected","right":"No pressure either way"},{"left":"Consent is central","right":"A free yes or no"},{"left":"Built, not just felt","right":"Do the daily work"}]},
  {"id":"cb-1283","cat":"tools-and-help","type":"role-play","persona":"Saxena","source":"suggest counselling","hook":"You've suggested couples counselling, and Amit looks stung by the idea.","setup":"He crosses his arms, clearly bracing for something bad.","steps":[{"prompt":"Amit says: \"So you think we're broken? Is that what this means?\"","options":[{"text":"\"Not broken. It's about getting even better at us, together.\"","then":"He relaxes slightly. \"Oh. I thought this meant something worse, honestly.\"","best":true},{"text":"\"No, nothing's wrong. I just thought it might be nice to try.\"","then":"He looks unconvinced. \"Then why bring it up out of nowhere like this?\""},{"text":"\"Well, we do argue a lot lately, so maybe.\"","then":"He looks hurt. \"So you do think something's wrong with us.\""},{"text":"\"Fine, forget it, clearly we don't need help.\"","then":"He relaxes, but a day later asks what counselling would even involve."}],"why":"Naming it as building better, not fixing broken, meets his fear without backing down."},{"prompt":"He asks, still unsure: \"Isn't counselling for couples who are basically failing, though?\"","options":[{"text":"\"No, plenty of strong couples use it just to get even stronger.\"","then":"He considers this. \"Huh. I genuinely didn't know that, actually.\"","best":true},{"text":"\"Maybe, but I don't think we're anywhere near that point yet.\"","then":"He looks reassured, but the actual reframe never really lands."},{"text":"\"Only really struggling couples need it, I suppose.\"","then":"He frowns. \"So we are struggling, then? Is that what you're saying?\""},{"text":"\"I don't really know how it works, honestly.\"","then":"He shrugs. \"Then maybe it's not worth trying, if neither of us knows.\""}],"why":"Naming that strong couples use it too removes the shame from the suggestion."},{"prompt":"Amit asks, softer now: \"Okay. What would we even talk about in there?\"","options":[{"text":"\"Whatever we want. Even just building our communication further.\"","then":"He nods slowly. \"Okay. That actually sounds manageable, not scary.\"","best":true},{"text":"\"I'm not totally sure. We'd probably figure that out together with them.\"","then":"He nods, though the uncertainty leaves him a little hesitant still."},{"text":"\"Probably all the ways you frustrate me, mostly.\"","then":"He stiffens. \"That doesn't sound like something I want to sign up for.\""},{"text":"\"I don't know, whatever comes up, I guess.\"","then":"He shrugs, still not quite convinced this is worth trying."}],"why":"Naming it as open and constructive, not a complaint session, makes it feel safe."}],"relearn":"You can suggest a counsellor as building better together, not as proof something's broken."},
  {"id":"cb-1284","cat":"tools-and-help","type":"role-play","persona":"Pooja","source":"share, don't thank","hook":"You've filled in the kids' school forms alone again, and Karthik notices.","setup":"Tonight, he says it again, pleased with himself.","steps":[{"prompt":"Karthik says: \"Hey, thanks for handling the school forms again. You're amazing.\"","options":[{"text":"\"I don't need thanks. I need us to share the noticing too.\"","then":"He pauses. \"Oh. I thought thanking you was the thoughtful thing to do.\"","best":true},{"text":"\"Thanks for noticing. That's honestly appreciated, at least.\"","then":"He smiles, satisfied, and the forms land on you again next term."},{"text":"\"It's fine. I don't mind handling it.\"","then":"He nods, relieved, and the pattern continues exactly as before."},{"text":"\"You're welcome, someone has to do it.\"","then":"He laughs. \"True enough.\" The actual imbalance stays unnamed."}],"why":"Naming shared noticing, not gratitude, is what actually changes the pattern."},{"prompt":"Karthik asks, a little puzzled: \"I always say thanks. Isn't that the same as helping?\"","options":[{"text":"\"Not quite. Noticing the form existed in the first place is the real work.\"","then":"He pauses. \"Huh. I never actually think about that part, honestly.\"","best":true},{"text":"\"I guess it's close enough, thanking me is still something, at least.\"","then":"He nods, relieved, and the noticing stays entirely on you either way."},{"text":"\"No, not even close, honestly.\"","then":"He looks defensive. \"Then what am I even supposed to do here?\""},{"text":"\"I don't know, maybe it doesn't matter that much.\"","then":"He shrugs, and the conversation quietly drops there."}],"why":"Naming the noticing as the real, invisible work makes the difference concrete."},{"prompt":"He asks: \"Okay, so what would you actually want me to notice, then?\"","options":[{"text":"\"Pick one whole area, like school forms, and own it completely.\"","then":"He nods. \"Okay, deal. School forms are mine from now on, fully.\"","best":true},{"text":"\"Just notice things more in general, I suppose, whenever you can.\"","then":"He nods, though \"in general\" doesn't really change much day to day."},{"text":"\"I'll just keep sending you reminders when things come up.\"","then":"He agrees, though that still leaves the noticing itself on you."},{"text":"\"Whatever's easiest for you, I don't want to overload you.\"","then":"He hesitates, and the actual ask stays a little too soft to stick."}],"why":"Owning a whole area, fully, is what turns 'helping' into actually sharing it."}],"relearn":"Ask for the load to be shared, not for thanks; fairness isn't a favour you should be grateful for."},
  {"id":"cb-1285","cat":"tools-and-help","type":"role-play","persona":"any","source":"ask for time","hook":"Your father calls you at work about the match the family likes.","setup":"You step into the stairwell to take the call properly.","steps":[{"prompt":"Your father says: \"Beta, I need to give them an answer by the weekend.\"","options":[{"text":"\"I value this, and I need more time and a few real talks first.\"","then":"He pauses. \"More time. Alright. I'll tell them it's not a no.\"","best":true},{"text":"\"Okay, fine. I'll just say yes. I don't want to hold things up.\"","then":"He sounds relieved and hangs up already planning next steps."},{"text":"\"Can't this wait until I'm home tonight?\"","then":"He sighs. \"They need to know soon, beta. It can't really wait.\""},{"text":"\"Just tell them whatever you think is right.\"","then":"He hesitates. \"I'd rather this one actually be your answer.\""}],"why":"Naming both value and a real need for time keeps the door open, unrushed."},{"prompt":"He calls back that evening: \"If you need more time, how much, realistically?\"","options":[{"text":"\"A couple of weeks, with two or three honest talks in that time.\"","then":"He considers it. \"That's reasonable. I'll tell them that much.\"","best":true},{"text":"\"I'm honestly not totally sure yet, maybe a bit longer than usual.\"","then":"He sounds uneasy. \"That's hard to give them, but alright, I suppose.\""},{"text":"\"However long it naturally takes, I guess.\"","then":"He sighs. \"That's not something I can tell them, beta.\""},{"text":"\"Let's just say a few days, to keep it simple.\"","then":"He agrees, though a few days barely allows for anything real."}],"why":"A specific timeframe with a real purpose is easy for your father to relay."},{"prompt":"Later that evening, he texts: \"They agreed. But please don't take too long, alright?\"","options":[{"text":"\"Thank you. I'll use the time well and let you know honestly.\"","then":"He replies with a thumbs up, and the pressure in the house eases a little.","best":true},{"text":"\"I'll try, though I honestly can't promise how long it'll take.\"","then":"He replies: \"Try your best, beta,\" still sounding a little uneasy."},{"text":"\"Don't worry. I'll rush it if I have to.\"","then":"He replies: \"You don't have to rush, just don't forget either.\""},{"text":"\"I said I need time, so please stop checking in.\"","then":"He goes quiet, and the reply doesn't come for a while."}],"why":"Thanking him while holding the timeline shows the request was genuine, not a delay."}],"relearn":"You can ask family for time and real conversations before deciding on a match, respectfully and clearly."},
  {"id":"cb-1286","cat":"tools-and-help","type":"role-play","persona":"any","source":"raise the money talk","hook":"Boxes are packed for your move-in with Ayaan, and money hasn't come up once.","setup":"Sorting through bills to forward, you decide to raise it.","steps":[{"prompt":"Ayaan asks: \"Should I just forward my bills to the new address?\"","options":[{"text":"\"Actually, can we plan how we'll handle money before moving in?\"","then":"He sets the bills down. \"Yeah, actually, we probably should do that.\"","best":true},{"text":"\"Sure, we'll figure the money out once we're settled in properly.\"","then":"He nods and keeps sorting, and the topic slides by unaddressed."},{"text":"\"I haven't really thought about money at all, honestly.\"","then":"He shrugs. \"Me neither. Let's just wing it, I guess.\""},{"text":"\"Just keep bills separate. That's easiest.\"","then":"He pauses. \"Is that actually the plan, or just what's easiest to say?\""}],"why":"Naming the real plan before moving in beats guessing once you're living together."},{"prompt":"On moving day, Ayaan asks: \"Shared expenses. How should we even split those?\"","options":[{"text":"\"Split by income, fairly, not automatically fifty-fifty.\"","then":"He nods. \"That actually makes sense. Let's work out the numbers.\"","best":true},{"text":"\"Fifty-fifty on everything, that's simplest and feels fair enough.\"","then":"He hesitates. \"Simplest, sure, but is it actually fair for both of us?\""},{"text":"\"Whoever earns more should just cover more, obviously.\"","then":"He pauses. \"I mean, maybe, but let's actually talk numbers first.\""},{"text":"\"Let's not do math, just split things as they come up.\"","then":"He looks unsure. \"That sounds like it could get messy fast.\""}],"why":"Splitting by income, named plainly, is fairer than assuming an even split works."},{"prompt":"He asks: \"What about savings, do we keep those separate too?\"","options":[{"text":"\"Separate savings, but a shared fund for our joint goals.\"","then":"He nods. \"I like that. Ours for us, mine and yours stay ours too.\"","best":true},{"text":"\"Whatever you're comfortable with, I don't have a strong preference.\"","then":"He nods, though the actual plan for savings stays a little unclear."},{"text":"\"Everything joint, once we're living together it's all shared.\"","then":"He pauses. \"That feels like a big jump before we've even moved in.\""},{"text":"\"Let's not plan that far ahead yet.\"","then":"He shrugs, and savings joins the list of things left undecided."}],"why":"Separate savings with a shared goal fund balances independence with 'us'."},{"prompt":"A week later, on moving day, Ayaan says: \"I set up a shared fund for our joint goals.\"","options":[{"text":"\"Thank you for doing that. Let's both add to it this week.\"","then":"He smiles. \"Already did my half. Your turn whenever works.\"","best":true},{"text":"\"Oh, nice, I'll get to my half whenever I remember to.\"","then":"He nods, though the fund sits half-empty for a while."},{"text":"\"Good, so I don't need to think about it anymore.\"","then":"He looks uncertain. \"It's still both of us adding to it, though.\""},{"text":"\"I'm sure it'll sort itself out eventually.\"","then":"He hesitates, unsure if the plan is actually going to hold."}],"why":"Following through together is what turns the plan into an actual shared habit."}],"relearn":"Open the money conversation early, calmly and openly, so you start on the same page."},
  {"id":"cb-1287","cat":"tools-and-help","type":"role-play","persona":"any","source":"decline a match kindly","hook":"After meeting Rohit twice, you know he's not right for you, but your mother is hopeful.","setup":"She asks eagerly the moment he leaves.","steps":[{"prompt":"Your mother asks: \"So? What do you think? He seemed wonderful.\"","options":[{"text":"\"I've thought hard. He's not right for me, so it's a no.\"","then":"She looks disappointed but nods. \"Alright. Can I ask what felt off?\"","best":true},{"text":"\"I guess I'll go along with it, since everyone likes him so much.\"","then":"She brightens, then catches your face: \"You don't look happy about it.\""},{"text":"\"He was fine, I suppose, if that's what everyone wants.\"","then":"She reaches for her phone, then stops: \"That didn't sound like a yes.\""},{"text":"\"I don't want to talk about it right now.\"","then":"She looks worried. \"That doesn't sound like a good sign, does it.\""}],"why":"A clear, respectful no protects your choice without hiding behind maybe."},{"prompt":"She asks: \"What felt off, exactly? He seemed so easy to talk to.\"","options":[{"text":"\"Our values on some big things just didn't line up, honestly.\"","then":"She nods slowly. \"That's fair. Better to know that now than later.\"","best":true},{"text":"\"I can't really explain it. It was just a feeling, nothing specific.\"","then":"She looks unconvinced. \"A feeling isn't much to go on, beta.\""},{"text":"\"Nothing specific, I just didn't feel it.\"","then":"She sighs. \"You never feel it with anyone lately.\""},{"text":"\"Does it matter? A no is a no.\"","then":"She looks hurt. \"I was only trying to understand, that's all.\""}],"why":"Naming the real reason, values, makes the no land as considered, not casual."},{"prompt":"Your mother asks: \"Are you sure? These proposals don't come along so easily.\"","options":[{"text":"\"I'm sure. I'd rather wait for right than settle for easy.\"","then":"She's quiet a moment, then nods. \"Alright. I trust your judgement, then.\"","best":true},{"text":"\"Maybe I'm being too fussy. Perhaps I should reconsider.\"","then":"She perks up. \"Should I tell them you'll think about it again?\""},{"text":"\"Convenient doesn't mean right, obviously.\"","then":"She looks stung. \"I wasn't saying it should be only about convenience.\""},{"text":"\"Fine, maybe I'll give it another chance.\"","then":"She looks relieved, though your earlier certainty quietly gets undone."}],"why":"Choosing right over convenient, plainly, keeps the decision actually yours."}],"relearn":"You can decline a match honestly and kindly; saying no to a proposal is your right on any path."},
  {"id":"cb-1288","cat":"tools-and-help","type":"role-play","persona":"Karthik","source":"take on the noticing","hook":"Pooja says she's exhausted from managing every single household task alone.","setup":"You want to actually fix this, not just sympathise.","steps":[{"prompt":"Pooja says: \"I'm so tired of being the one who tracks everything.\"","options":[{"text":"\"Let me fully own groceries and bills, planning included.\"","then":"She looks surprised. \"Wait, really? The planning too, not just the doing?\"","best":true},{"text":"\"Sure, just make me a list and I'll do it, whatever you need.\"","then":"She sighs. \"That's still me doing the remembering, though.\""},{"text":"\"I do help out a lot already, though.\"","then":"She looks tired. \"Helping isn't the same as owning it, Karthik.\""},{"text":"\"Let's hire some help around the house instead.\"","then":"She pauses. \"That could work, but it doesn't fix us, though.\""}],"why":"Owning the planning, not just tasks on a list, is what 'help' was missing."},{"prompt":"Pooja asks, cautiously: \"Would you notice when we're low on things, without me saying?\"","options":[{"text":"\"Yes. I'll check and restock without you having to remind me.\"","then":"She exhales. \"Okay. That would genuinely change things for me.\"","best":true},{"text":"\"I'll try to notice more, though I can't promise I'll catch everything.\"","then":"She nods, cautiously, still bracing to have to remind him anyway."},{"text":"\"You can just text me when we're low on something.\"","then":"She looks deflated. \"That's still me doing the noticing, though.\""},{"text":"\"Let's just set a reminder app for groceries.\"","then":"She shrugs. \"Maybe, but who's setting that reminder each time?\""}],"why":"Noticing without being told is the actual shift from helping to owning."},{"prompt":"A week later, Pooja notices the fridge is stocked without her saying anything.","options":[{"text":"\"I checked yesterday and restocked. Didn't want to wait to be asked.\"","then":"She smiles, genuinely surprised. \"This is exactly what I meant, thank you.\"","best":true},{"text":"\"Yeah, I noticed and got some things, though I might have missed a few.\"","then":"She nods, pleased but still double-checking behind him out of habit."},{"text":"\"I got the essentials, you can check if anything's missing.\"","then":"She sighs. \"That's still asking me to keep tracking it, though.\""},{"text":"\"I did it today, don't get used to it.\"","then":"She laughs, unsure if that's a joke or a warning."}],"why":"Naming that you acted without being asked shows the ownership is sticking."},{"prompt":"A month in, Pooja says: \"Honestly, groceries have been on my mind a lot less this month.\"","options":[{"text":"\"That's the whole point, that it's fully off your plate now.\"","then":"She smiles. \"It really is. Thank you for actually following through.\"","best":true},{"text":"\"That's great, though let me know if I ever slip up on anything.\"","then":"She nods, though \"let me know\" quietly reopens the old habit."},{"text":"\"See, I told you I could handle it.\"","then":"She pauses. \"It's not really about proving that, though.\""},{"text":"\"I'm exhausted too, if I'm honest.\"","then":"She looks concerned. \"Is it too much? I don't want you resentful either.\""}],"why":"Naming it as fully hers to not think about anymore confirms the ownership held."}],"relearn":"Real sharing means taking on the noticing and planning, not waiting to be told what to do."},
  {"id":"cb-1289","cat":"tools-and-help","type":"role-play","persona":"any","source":"repair after you hurt them","hook":"You snapped at Zoya over something small this morning, and the distance since has been obvious.","setup":"That evening, you find her quieter than usual.","steps":[{"prompt":"Zoya says, a little flat: \"I'm fine. Just tired, I guess.\"","options":[{"text":"\"I'm sorry I snapped this morning. That wasn't fair. Can we talk?\"","then":"She looks up, surprised. \"Oh. Yeah. I'd like that, actually.\"","best":true},{"text":"\"You're being a bit too sensitive about this, honestly, let it go.\"","then":"She stiffens, then says quietly that it hurt more than you think."},{"text":"\"Sorry about earlier, anyway, what's for dinner?\"","then":"She pauses. \"That's it? That's the whole apology?\""},{"text":"\"I had a rough morning. That's all it was.\"","then":"She nods slowly, then looks up as if she wants to say more."}],"why":"Naming the snap and owning it, plainly, opens the door the flat mood is guarding."},{"prompt":"Zoya says: \"It just really stung, you know. More than usual.\"","options":[{"text":"\"I hear that. I'm sorry it landed that hard. That wasn't okay.\"","then":"She softens. \"Thank you for actually saying that, not just moving past it.\"","best":true},{"text":"\"I didn't mean it that harshly, you probably just took it wrong.\"","then":"She looks hurt. \"So this is my fault for how I took it?\""},{"text":"\"I said sorry already, what more do you want?\"","then":"She goes quiet again, the distance settling back in."},{"text":"\"You've said things that stung too, you know.\"","then":"She looks wounded. \"Is that really what this is about right now?\""}],"why":"Naming the sting as real, not explaining it away, is what makes the apology land."},{"prompt":"Later, once things are calmer, she asks quietly: \"How do we stop this from happening again?\"","options":[{"text":"\"I'll step back before I snap, and check in with you after.\"","then":"She nods. \"I'd really like that. Just knowing you're trying helps.\"","best":true},{"text":"\"I'll try to be in a better mood in general, going forward.\"","then":"She nods, though \"better mood\" isn't really a plan either of you can use."},{"text":"\"You could just not take things so personally.\"","then":"She looks stung again. \"That's kind of the opposite of an apology.\""},{"text":"\"I don't know, these things just happen sometimes.\"","then":"She sighs, unconvinced this will actually be any different next time."}],"why":"A concrete plan to catch yourself, not just good intentions, makes the repair real."}],"relearn":"A sincere repair owns your part, names their hurt, and offers to make it right."},
  {"id":"cb-1290","cat":"tools-and-help","type":"branch","persona":"any","source":"friend rushing in","hook":"Your friend Farhan is about to commit fast just to stop relatives asking \"when.\"","steps":[{"prompt":"Farhan tells you the wedding might happen within weeks. What do you do?","options":[{"text":"Tell him to hurry before it's \"too late\"","then":"Farhan nods, like the deadline is the only thing that matters now."},{"text":"Congratulate him and drop it","then":"Farhan moves on to logistics, then admits a day later that it all feels rushed."},{"text":"Tell him relatives will never stop asking anyway","then":"True or not, it doesn't give Farhan anything to actually decide with."},{"text":"Ask if he'd choose this with no clock ticking","then":"Farhan goes quiet, like the question caught him off guard.","best":true}],"why":"The question separates his own choice from the pressure, without telling him what to decide."},{"prompt":"He admits he hasn't really thought it through. What do you do?","options":[{"text":"Tell him it's too late to slow down now","then":"Farhan shrugs, like the decision's already out of his hands."},{"text":"Say relatives know best","then":"Farhan hands the decision further away from himself, not closer."},{"text":"Drop the subject to avoid awkwardness","then":"Farhan is left to think it through entirely alone."},{"text":"Help him name what's actually rushing him","then":"Farhan starts talking about the questions at home, not the relationship.","best":true}],"why":"Naming what's actually rushing him separates the real pressure from the actual decision."},{"prompt":"He says he's scared of disappointing his parents by waiting. What do you do?","options":[{"text":"Tell him their approval matters more than his doubts","then":"Farhan nods, and the doubts stay exactly where they were, just quieter."},{"text":"Agree he should just push through it","then":"Farhan takes that as permission to ignore what he actually feels."},{"text":"Stay quiet so you don't interfere","then":"Farhan is left carrying the fear by himself."},{"text":"Remind him this choice is his to make at his pace","then":"Farhan exhales, like someone finally said the thing he needed to hear.","best":true}],"why":"Reminding him it's his choice, at his pace, gives him permission the family pressure won't."}],"debrief":"A friend's best help is permission to choose on values and their own pace, not the timeline.","relearn":"Encourage a friend to weigh values and take their time, rather than rush to beat a timeline."},
  {"id":"cb-1291","cat":"tools-and-help","type":"branch","persona":"any","source":"friend ignoring red flags","hook":"Your friend Divya's partner is controlling, but she keeps excusing it.","steps":[{"prompt":"Divya mentions he read her messages again. What do you do?","options":[{"text":"Say nothing to keep the peace","then":"Divya changes the subject, and so do you."},{"text":"Tell her she has to leave him before it gets worse","then":"Divya gets defensive on his behalf, right in front of you."},{"text":"Judge her for allowing it","then":"Divya feels the judgment and says less next time."},{"text":"Name what you see with care, and stay close","then":"Divya goes quiet, like she's actually hearing it for the first time.","best":true}],"why":"Naming it with care, while staying on her side, helps her hear it without feeling attacked."},{"prompt":"Then she says he's just being protective. What do you do?","options":[{"text":"Drop it since she's upset","then":"The conversation ends, and so does the chance to say more today."},{"text":"Argue harder to convince her","then":"The more you push, the more she defends him instead of thinking."},{"text":"Agree with her to smooth things over","then":"Divya relaxes, and the actual worry goes right back underground."},{"text":"Ask what \"protective\" looks like","then":"Divya starts describing it, and hearing it out loud gives her pause.","best":true}],"why":"Asking her to describe it out loud lets her hear the pattern for herself, gently."},{"prompt":"Divya goes quiet for a while after that talk. What do you do?","options":[{"text":"Assume she doesn't want to hear from you again","then":"The distance grows, though she hasn't stopped thinking about your words."},{"text":"Corner her again for an answer","then":"Divya pulls back further instead of opening up."},{"text":"Tell others so they can convince her too","then":"Divya finds out, and now there's a second thing to feel cornered about."},{"text":"Keep the door open without pushing further","then":"You send one warm message, no pressure, and leave it there.","best":true}],"why":"Keeping the door open, without pushing, is what makes it safe for her to come back to you."},{"prompt":"Weeks later she reaches out, unsure what to do. What do you do?","options":[{"text":"Say you knew it all along","then":"Divya feels judged again, right when she finally reached out."},{"text":"Tell her exactly what to do, step by step","then":"Divya hears another person telling her what to decide."},{"text":"Remind her you warned her","then":"The reminder lands as blame, not help."},{"text":"Listen and help her think it through","then":"Divya starts to sound like herself again, working it out with you.","best":true}],"why":"Listening and helping her think it through respects that the choice is still hers to make."}],"debrief":"You can name a red flag with care and still leave the choice theirs. Silence helps no one.","relearn":"A caring friend names the red flags honestly while leaving the choice with their friend."},
  {"id":"cb-1292","cat":"tools-and-help","type":"branch","persona":"any","source":"friend facing coercion","hook":"A friend confides she's being forced into a marriage she doesn't want.","steps":[{"prompt":"She tells you, scared of how you'll react. What do you do?","options":[{"text":"Tell her to just adjust and keep family happy","then":"She hears that her fear matters less than the family's comfort."},{"text":"Ask if she's sure she's not overreacting","then":"She doubts herself for a moment, then quietly asks what she should do."},{"text":"Promise to keep it secret and do nothing else","then":"The secret stays safe. She's still exactly as alone as before."},{"text":"Believe her, and tell her it's not her fault","then":"Something in her shoulders drops, like she'd been braced for the opposite.","best":true}],"why":"Believing her, and saying it's not her fault, is what she needs to hear before anything else."},{"prompt":"She asks what she should actually do. What do you do?","options":[{"text":"Tell her to wait and see if it blows over","then":"Waiting doesn't slow down a date that's already being planned."},{"text":"Tell her to handle it alone so no one else finds out","then":"She's carrying this exactly the way she was before she told you."},{"text":"Suggest she just delay the date quietly","then":"A quiet delay buys a little time, and no real support."},{"text":"Share real help: Women Helpline 181, 1091, 112","then":"She writes the numbers down, like she didn't know this existed.","best":true}],"why":"Real routes to help give her actual options, not just sympathy."},{"prompt":"She's scared contacting anyone will make things worse at home. What do you do?","options":[{"text":"Back off and let her decide alone with no support","then":"She's left weighing an enormous decision by herself."},{"text":"Tell her she has no choice but to call right now","then":"The pressure just shifts from her family to you."},{"text":"Drop the subject so she isn't more scared","then":"The fear stays, and so does the silence around it."},{"text":"Offer to stay with her while she calls or reaches out","then":"She looks a little less alone with that offer on the table.","best":true}],"why":"Offering to be there while she reaches out turns a scary step into one she doesn't take alone."},{"prompt":"A few days later she asks if you'll still be there whatever she decides. What do you do?","options":[{"text":"Say only if she does what you'd do","then":"She hears that your support has a condition attached to it."},{"text":"Tell her she should have listened sooner","then":"She hears blame, right when she needed the opposite."},{"text":"Pull back since it's not your problem","then":"She's left with one less person in her corner."},{"text":"Say yes, and mean it","then":"She exhales, like that answer was the one she needed most.","best":true}],"why":"Staying, whatever she decides, is what makes your support real instead of conditional."}],"debrief":"Forced marriage is never her fault. Believe her and route her to help: 181, 1091, 112, or 1098.","relearn":"If a friend is forced to marry, point them to real help. It's never their fault, and routes exist."},
  {"id":"cb-1293","cat":"tools-and-help","type":"branch","persona":"any","source":"reach for a counsellor","hook":"You and your partner keep circling the same fight and feel stuck.","steps":[{"prompt":"It happens again for what feels like the tenth time. What do you do?","options":[{"text":"Keep grinding through it alone out of pride","then":"The tenth time looks a lot like the ninth."},{"text":"Decide the relationship must be failing","then":"One stuck pattern starts to feel like the whole relationship."},{"text":"Avoid each other for a few days","then":"The distance cools the fight, and the actual issue is still there."},{"text":"Suggest a couples counsellor together","then":"Your partner looks surprised, then quietly relieved someone said it.","best":true}],"why":"A counsellor gives you tools for the loop that trying harder alone hasn't broken."},{"prompt":"Your partner wonders aloud about counselling, then worries it means something's wrong. What do you do?","options":[{"text":"Drop the idea to avoid the conversation","then":"The tenth fight stays the last word on the subject."},{"text":"Insist something must be seriously broken","then":"The word \"broken\" makes the idea feel scarier than it needs to."},{"text":"Agree it's a bad sign and reconsider things","then":"A stuck pattern turns into a much bigger question than it needs to be."},{"text":"Explain counselling is for building better too","then":"Your partner relaxes a little, hearing it's not only for emergencies.","best":true}],"why":"Framing it as building better, not just crisis repair, makes it easier to actually say yes to."},{"prompt":"A month later, you both agree to try one counselling session. What do you do beforehand?","options":[{"text":"Go in assuming it'll fix everything at once","then":"One session can't carry that much weight, and you're disappointed fast."},{"text":"Cancel out of nerves","then":"The stuck pattern gets to keep running, uninterrupted."},{"text":"Go only to prove a point","then":"You spend the session defending yourself instead of listening."},{"text":"Go in ready to be honest and patient","then":"The first session feels like a start, not a verdict.","best":true}],"why":"Going in patient and honest gives the process room to actually help."}],"debrief":"Counselling is for building better, not only crises. Reaching out early is a strength.","relearn":"Reaching for a couples counsellor early is a strength, not an admission of failure."},
  {"id":"cb-1294","cat":"tools-and-help","type":"branch","persona":"Pooja","source":"mental load surfaces","hook":"You finally tell Karthik how much invisible planning you carry.","steps":[{"prompt":"He listens and thanks you warmly. What do you do next?","options":[{"text":"Accept the thanks and leave it there","then":"The thanks feels nice, and the planning is still all yours tomorrow."},{"text":"Assume things will change on their own now that you've said it","then":"Nothing changes, because nothing specific was actually agreed."},{"text":"Feel guilty for bringing it up at all","then":"The guilt does nothing except make it harder to raise next time."},{"text":"Say thanks is nice, but ask to split the planning","then":"Karthik pauses, then asks what that would actually look like.","best":true}],"why":"Asking to split the planning turns being thanked into something that actually changes the load."},{"prompt":"A week later, Karthik asks how he could take some of the planning off you. What do you do?","options":[{"text":"Say he should just figure it out himself","then":"Karthik isn't sure where to start, and neither of you moves forward."},{"text":"Say it's too complicated to explain","then":"The load stays exactly where it was, now with a sigh attached."},{"text":"Drop specifics and hope he gets it","then":"Hoping doesn't tell him which Tuesday needs remembering."},{"text":"Walk through one real example together","then":"Karthik starts to see what \"noticing\" actually involves.","best":true}],"why":"One real example makes the invisible work concrete enough for him to actually take on."},{"prompt":"A month later, some habits have shifted and some haven't. What do you do?","options":[{"text":"Stay quiet so you don't seem ungrateful","then":"The parts that slipped back stay exactly where they slipped."},{"text":"Go back to doing it all since it's easier","then":"Easier today costs you the progress you already made."},{"text":"Wait and see if it improves alone","then":"Alone, it settles back to where it started."},{"text":"Name what's working and what still needs work","then":"You both know exactly what to tweak instead of starting over.","best":true}],"why":"Naming what's working and what isn't keeps the change going, instead of letting it slip."}],"debrief":"Naming the mental load should lead to sharing it, not to being thanked for carrying it.","relearn":"When the invisible load is named, the fix is to share the planning, not to thank the person carrying it."},
  {"id":"cb-1295","cat":"tools-and-help","type":"branch","persona":"any","source":"wedding eclipses marriage","hook":"Wedding planning is consuming you both, and the real talks keep slipping.","steps":[{"prompt":"Another week passes on guest lists and decor. What do you do?","options":[{"text":"Pour everything into the perfect day and sort the rest later","then":"The day gets more perfect. The rest keeps waiting."},{"text":"Cancel wedding planning to force the issue","then":"Your partner panics about the vendors, and planning takes over even more."},{"text":"Assume there'll be time after the wedding","then":"After the wedding, a different kind of busy shows up instead."},{"text":"Protect time for the marriage talks too","then":"Your partner looks up from the guest list, like they'd been waiting for this.","best":true}],"why":"Protecting time for the marriage talks now means the wedding doesn't use up all of it."},{"prompt":"Partner says there's no time for \"another conversation\" right now. What do you do?","options":[{"text":"Drop it until after the wedding","then":"After the wedding arrives with its own new reasons to postpone."},{"text":"Insist on a long talk immediately","then":"You both end up too rushed for it to actually land."},{"text":"Give up and let the wedding take over","then":"The wedding takes over exactly the way you were trying to avoid."},{"text":"Suggest one short, specific talk instead","then":"Your partner agrees, relieved it's not the big talk they were dreading.","best":true}],"why":"A short, specific conversation is easier to say yes to than one big, vague one."},{"prompt":"With a week to go, the marriage talks still feel half done. What do you do?","options":[{"text":"Consider the topic closed for good now","then":"The next thing that needs saying waits for an opening that doesn't come."},{"text":"Go back to full wedding focus","then":"The good talk becomes a one-off instead of a pattern."},{"text":"Feel it's enough and stop planning talks entirely","then":"Enough today doesn't cover what comes up next month."},{"text":"Set a short check-in before the wedding","then":"It's already on the calendar, so it's harder to lose to the chaos.","best":true}],"why":"Setting the next check-in turns one good talk into a habit instead of a lucky exception."}],"debrief":"A wedding is a day. Protecting time for the marriage itself is what sets you up to last.","relearn":"Pour energy into the marriage skills, not only the wedding day. The day passes, the partnership remains."},
  {"id":"cb-1296","cat":"tools-and-help","type":"branch","persona":"any","source":"help a friend ask questions","hook":"A friend in an arranged process doesn't know what to ask the other person.","steps":[{"prompt":"Ishita asks what even matters in these meetings. What do you do?","options":[{"text":"Tell her looks and a good job are what matter","then":"Ishita nods, and walks in with nothing to actually learn about him."},{"text":"Tell her not to ask too much or she'll seem difficult","then":"Ishita holds back the very questions that would tell her something real."},{"text":"Tell her to just trust her gut in the moment","then":"Her gut has very little to actually go on."},{"text":"Help her list real questions to bring","then":"Ishita starts writing, like this is the first time someone's shown her how.","best":true}],"why":"Real, prepared questions give her something to actually judge fit by, not just a gut feeling."},{"prompt":"She wants a first question to open with. What do you suggest?","options":[{"text":"Something about his job and salary","then":"The number tells her plenty about his income, and nothing about him."},{"text":"Something about his family's expectations of her","then":"She learns what his family wants, before she's learned what he wants."},{"text":"Something safe that won't reveal much","then":"The meeting stays pleasant, and she leaves knowing about as much as she arrived with."},{"text":"Something about what he wants from life","then":"His answer gives her something real to actually weigh.","best":true}],"why":"Asking what he wants from life gets at values fast, instead of surface facts."},{"prompt":"She asks how to find out how he handles conflict. What do you suggest?","options":[{"text":"Ask his friends behind his back","then":"She gets someone else's version, filtered through their loyalty to him."},{"text":"Assume it'll show itself later","then":"Later, she's already invested, and the answer arrives without warning."},{"text":"Skip it since it feels too soon to ask something so personal","then":"The question that reveals the most gets left for after it matters most."},{"text":"Ask him how he handled a recent disagreement","then":"His answer tells her more than a dozen easier questions would.","best":true}],"why":"How someone handles conflict, asked directly, reveals more than almost anything else."},{"prompt":"She's nervous to bring up money and roles this early. What do you say?","options":[{"text":"Agree it's too early and to wait","then":"The easy questions get asked. The important ones get postponed again."},{"text":"Tell her his family will decide that anyway","then":"She stops thinking of it as something she gets a say in."},{"text":"Suggest she guess based on his job","then":"A guess based on his job tells her nothing about what he actually thinks."},{"text":"Remind her this is exactly the time to ask","then":"Ishita nods, like she needed the permission more than the question.","best":true}],"why":"This early conversation is exactly when honest answers about money and roles matter most."},{"prompt":"After the meeting she asks how she did. What do you tell her?","options":[{"text":"That she should have asked more personal questions","then":"Ishita leaves doubting a process that actually went well."},{"text":"That it only matters what his family thought","then":"Her own read on the meeting quietly stops counting."},{"text":"That she overthought a simple meeting","then":"The questions that gave her real answers get written off as overthinking."},{"text":"That asking real questions was exactly the point","then":"Ishita relaxes, like she's finally sure she did this right.","best":true}],"why":"Telling her the real questions were the point confirms she's judging fit the right way."}],"debrief":"In any match process, the right questions reveal real fit. Help a friend bring them.","relearn":"A friend can be coached to ask the real questions about goals, conflict, money and family in any match process."},
  {"id":"cb-1297","cat":"tools-and-help","type":"sort","persona":"Saxena","source":"right tool","relearn":"Skills for stuck-but-safe couples, helplines for coercion or danger, both are real routes to help.","hook":"Sort: who's this best taken to?","items":[{"id":"a","text":"We keep having the same fight"},{"id":"b","text":"I'm being forced to marry"},{"id":"c","text":"We want better communication"},{"id":"d","text":"I feel unsafe at home"},{"id":"e","text":"A minor is being married off"},{"id":"f","text":"We want to grow as a couple"}],"bins":[{"id":"counsellor","label":"A counsellor","valence":"neutral"},{"id":"helpline","label":"A helpline","valence":"tell"}],"key":{"a":"counsellor","b":"helpline","c":"counsellor","d":"helpline","e":"helpline","f":"counsellor"}},
  {"id":"cb-1298","cat":"tools-and-help","type":"sort","persona":"any","source":"green light vs warning","relearn":"Feeling respected, freer and like a team reads green; shrinking, walking on eggshells reads as a warning.","hook":"Sort: a green light, or a warning sign?","items":[{"id":"a","text":"You feel more yourself"},{"id":"b","text":"You walk on eggshells"},{"id":"c","text":"You feel like a team"},{"id":"d","text":"You shrink to keep the peace"},{"id":"e","text":"You're respected in fights"},{"id":"f","text":"You manage their every mood"}],"bins":[{"id":"green","label":"Green light","valence":"pos"},{"id":"warn","label":"Warning sign","valence":"uhoh"}],"key":{"a":"green","b":"warn","c":"green","d":"warn","e":"green","f":"warn"}},
  {"id":"cb-1299","cat":"tools-and-help","type":"sort","persona":"any","source":"skill vs not","relearn":"Repair, 'I' statements, appreciation and check-ins are partnership skills; silence and scorekeeping aren't.","hook":"Sort: a real partnership skill, or not?","items":[{"id":"a","text":"Making a sincere repair"},{"id":"b","text":"Keeping score of wrongs"},{"id":"c","text":"Using an 'I felt' opener"},{"id":"d","text":"Silent treatment till they cave"},{"id":"e","text":"Saying thank you out loud"},{"id":"f","text":"Bringing up old fights to win"}],"bins":[{"id":"skill","label":"A real skill","valence":"pos"},{"id":"notskill","label":"Not a skill","valence":"neg"}],"key":{"a":"skill","b":"notskill","c":"skill","d":"notskill","e":"skill","f":"notskill"}},
  {"id":"cb-1300","cat":"tools-and-help","type":"sort","persona":"Pooja","source":"sharing vs not","relearn":"Splitting the noticing and planning shares the load; being thanked or handed a list leaves it on one person.","hook":"Sort: this actually shares the load, or just looks like it?","items":[{"id":"a","text":"Owning groceries, planning included"},{"id":"b","text":"\"Just make me a list\""},{"id":"c","text":"Tracking the chores yourself too"},{"id":"d","text":"\"Thanks for doing it all\""},{"id":"e","text":"Deciding meals together"},{"id":"f","text":"Helping only when asked"}],"bins":[{"id":"shares","label":"Shares the load","valence":"pos"},{"id":"onhers","label":"Still on her","valence":"uhoh"}],"key":{"a":"shares","b":"onhers","c":"shares","d":"onhers","e":"shares","f":"onhers"}},
  {"id":"cb-1301","cat":"tools-and-help","type":"sort","persona":"any","source":"sound vs shaky help-seeking","relearn":"Reaching for help early and choosing freely is sound; suffering in silence or 'adjusting' to coercion isn't.","hook":"Sort: a sound move when things get hard, or a shaky one?","items":[{"id":"a","text":"Seeing a counsellor early"},{"id":"b","text":"Suffering in silence out of pride"},{"id":"c","text":"Telling a trusted person you're coerced"},{"id":"d","text":"\"Adjusting\" to a forced marriage"},{"id":"e","text":"Naming a problem honestly"},{"id":"f","text":"Hoping it fixes itself"}],"bins":[{"id":"sound","label":"Sound","valence":"pos"},{"id":"shaky","label":"Shaky","valence":"neg"}],"key":{"a":"sound","b":"shaky","c":"sound","d":"shaky","e":"sound","f":"shaky"}},
  {"id":"cb-1302","cat":"tools-and-help","type":"sort","persona":"any","source":"wedding vs marriage sort","relearn":"Venue and guests are the wedding day; money, repair and the mental load are the marriage that lasts.","hook":"Sort: a wedding-day task, or marriage work?","items":[{"id":"a","text":"Picking the venue"},{"id":"b","text":"Agreeing how money works"},{"id":"c","text":"The guest list"},{"id":"d","text":"How you'll repair fights"},{"id":"e","text":"The decorations"},{"id":"f","text":"Who carries the mental load"}],"bins":[{"id":"day","label":"The wedding day","valence":"neutral"},{"id":"marriage","label":"The marriage","valence":"pos"}],"key":{"a":"day","b":"marriage","c":"day","d":"marriage","e":"day","f":"marriage"}},
  {"id":"cb-1303","cat":"tools-and-help","type":"sort","persona":"any","source":"consent present vs absent","relearn":"Time to decide, real talks and a free no mean consent is present; being rushed or overridden means it's absent.","hook":"Sort: consent is present here, or absent?","items":[{"id":"a","text":"Given time to decide"},{"id":"b","text":"Rushed to say yes today"},{"id":"c","text":"Free to say no"},{"id":"d","text":"Your no is overridden"},{"id":"e","text":"Real conversations first"},{"id":"f","text":"Decided for you by others"}],"bins":[{"id":"present","label":"Consent present","valence":"pos"},{"id":"absent","label":"Consent absent","valence":"neg"}],"key":{"a":"present","b":"absent","c":"present","d":"absent","e":"present","f":"absent"}},
  {"id":"cb-1304","cat":"tools-and-help","type":"sort","persona":"any","source":"helps friend vs not","relearn":"Listening, naming flags with care and sharing real help supports a friend; shaming or 'just adjust' doesn't.","hook":"Sort: this helps a struggling friend, or doesn't?","items":[{"id":"a","text":"Listening without judging"},{"id":"b","text":"\"Just adjust and stay quiet\""},{"id":"c","text":"Sharing a real helpline"},{"id":"d","text":"Shaming their choices"},{"id":"e","text":"Naming a red flag kindly"},{"id":"f","text":"Spreading their secret around"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"hurts","label":"Doesn't help","valence":"neg"}],"key":{"a":"helps","b":"hurts","c":"helps","d":"hurts","e":"helps","f":"hurts"}},
  {"id":"cb-1305","cat":"tools-and-help","type":"sort","persona":"any","source":"reveals fit vs distracts","relearn":"Goals, conflict style, money values and family roles reveal fit; salary, car and looks distract from it.","hook":"Sort: reveals real fit, or a shiny distraction?","items":[{"id":"a","text":"How they handle a disagreement"},{"id":"b","text":"The size of their salary"},{"id":"c","text":"What they want from life"},{"id":"d","text":"How fancy their car is"},{"id":"e","text":"How they treat people with less power"},{"id":"f","text":"Their follower count"}],"bins":[{"id":"reveals","label":"Reveals fit","valence":"pos"},{"id":"distract","label":"Distraction","valence":"neutral"}],"key":{"a":"reveals","b":"distract","c":"reveals","d":"distract","e":"reveals","f":"distract"}},
  {"id":"cb-1306","cat":"tools-and-help","type":"spot","persona":"any","source":"spot the warning","relearn":"Walking on eggshells and managing their every mood are warnings; respect, freedom and teamwork are green.","hook":"Spot the two warning signs hiding among the green lights.","scene":[{"id":"a","text":"You feel respected in disagreements","trick":false},{"id":"b","text":"You walk on eggshells daily","trick":true},{"id":"c","text":"You feel free to be yourself","trick":false},{"id":"d","text":"You manage their every mood","trick":true},{"id":"e","text":"You feel like a team","trick":false}],"why":"Eggshells and managing their every mood are the warning signs; respect, freedom and teamwork are green."},
  {"id":"cb-1307","cat":"tools-and-help","type":"spot","persona":"Pooja","source":"spot the fake fix","relearn":"Being thanked or handed a list isn't sharing; sharing means owning the noticing and planning too.","hook":"Spot the two 'fixes' that still leave the mental load on one person.","scene":[{"id":"a","text":"He owns groceries, planning and all","trick":false},{"id":"b","text":"He thanks her for carrying it all","trick":true},{"id":"c","text":"They split the noticing too","trick":false},{"id":"d","text":"He helps only when handed a list","trick":true},{"id":"e","text":"They decide chores together","trick":false}],"why":"Thanks and 'give me a list' leave the planning on her; real sharing owns the noticing too."},
  {"id":"cb-1308","cat":"tools-and-help","type":"spot","persona":"any","source":"spot the shaky reason","relearn":"Fear of being alone and 'log kya kahenge' are shaky reasons; choosing the person freely is sound.","hook":"Spot the two shaky reasons to commit hiding among the sound ones.","scene":[{"id":"a","text":"You genuinely choose this person","trick":false},{"id":"b","text":"You're scared of being alone","trick":true},{"id":"c","text":"You've talked the big things through","trick":false},{"id":"d","text":"\"Log kya kahenge\" if you wait","trick":true},{"id":"e","text":"You both want the same life","trick":false}],"why":"Fear of being alone and 'what will people say' are shaky reasons; the rest are sound, free choices."},
  {"id":"cb-1309","cat":"tools-and-help","type":"spot","persona":"any","source":"spot the red flag","relearn":"Control and contempt are red flags; owning mistakes, respecting boundaries and steadiness are green.","hook":"Spot the two red flags hiding among the green flags.","scene":[{"id":"a","text":"They own their mistakes","trick":false},{"id":"b","text":"They try to control who you see","trick":true},{"id":"c","text":"They respect your boundaries","trick":false},{"id":"d","text":"They treat you with contempt","trick":true},{"id":"e","text":"They're steady under stress","trick":false}],"why":"Controlling who you see and contempt are the red flags; the rest are long-term green flags."},
  {"id":"cb-1310","cat":"tools-and-help","type":"spot","persona":"any","source":"spot the non-repair","relearn":"Brushing it off and blaming you back aren't repairs; owning it, naming the hurt and changing are.","hook":"Spot the two lines that look like an apology but aren't a real repair.","scene":[{"id":"a","text":"\"I see I hurt you, I'm sorry\"","trick":false},{"id":"b","text":"\"Whatever, let's just move on\"","trick":true},{"id":"c","text":"\"I'll do this differently next time\"","trick":false},{"id":"d","text":"\"You made me do it\"","trick":true},{"id":"e","text":"\"How can I make it right?\"","trick":false}],"why":"'Let's move on' and 'you made me' dodge repair; owning it, changing and asking to make it right are real."},
  {"id":"cb-1311","cat":"tools-and-help","type":"spot","persona":"any","source":"spot the bad help","relearn":"'Just adjust' and shaming aren't help; listening, naming flags kindly and sharing real routes are.","hook":"Spot the two responses to a struggling friend that don't actually help.","scene":[{"id":"a","text":"\"I believe you, that sounds hard\"","trick":false},{"id":"b","text":"\"Just adjust and keep quiet\"","trick":true},{"id":"c","text":"\"There's help: 181, 1091, 112\"","trick":false},{"id":"d","text":"\"It's your own fault, really\"","trick":true},{"id":"e","text":"\"I'm here whatever you decide\"","trick":false}],"why":"'Just adjust' and 'your own fault' aren't help; believing her and sharing real routes are."},
  {"id":"cb-1312","cat":"tools-and-help","type":"spot","persona":"any","source":"spot the distraction","relearn":"Salary and follower count distract; how they handle conflict and treat the less powerful reveal real fit.","hook":"Spot the two shiny distractions hiding among the things that reveal real fit.","scene":[{"id":"a","text":"How they handle a disagreement","trick":false},{"id":"b","text":"The size of their salary","trick":true},{"id":"c","text":"How they treat people with less power","trick":false},{"id":"d","text":"Their follower count","trick":true},{"id":"e","text":"Whether your life goals align","trick":false}],"why":"Salary and followers are distractions; conflict-handling, respect and aligned goals reveal real fit."},
  {"id":"cb-1313","cat":"tools-and-help","type":"choose","persona":"any","source":"counselling reframe 2","hook":"Naina and Ritu have been putting off talking to anyone about their rough patch.","prompt":"Which beliefs could be keeping them stuck?","options":[{"text":"Needing help means we've failed","fits":true,"note":"Treating help as failure is exactly what keeps people from asking."},{"text":"A good couple shouldn't need this","fits":true,"note":"Thinking a good couple wouldn't need this is what keeps many from trying."},{"text":"Family will think less of us","fits":true,"note":"Worry about what family will think stops many couples from asking."},{"text":"We should be able to fix it alone","fits":true,"note":"Believing it must be solved alone is what stops many from reaching out."},{"text":"We want to understand each other better","fits":false,"note":"That's a healthy reason to reach out, not a belief that holds anyone back."},{"text":"We'd rather sort this out early","fits":false,"note":"Wanting to catch it early is what helps couples ask sooner, not later."}],"relearn":"Asking for help means valuing the partnership enough to tend it."},
  {"id":"cb-1314","cat":"tools-and-help","type":"reflect","persona":"any","source":"your toolkit","relearn":"You already carry tools like listening, repair, 'I' statements and appreciation; the bond grows as you use them.","hook":"You've got a real toolkit now: repair, 'I' statements, check-ins and thanks.","prompt":"Which will you reach for first?","options":["Repair after fights","'I felt' openers","Regular check-ins","Saying thanks out loud"],"affirm":"Whichever you reach for, using your tools on purpose is how a good partnership quietly grows.","ask":"When might you reach for it first?","deeper":"Which tool might a partner reach for, and why?"},
  {"id":"cb-1315","cat":"tools-and-help","type":"reflect","persona":"any","source":"help isn't weakness","relearn":"Knowing where help lives, from a counsellor to a friend or a helpline, is part of building well.","hook":"Knowing where help lives is part of building well, not only a last resort.","prompt":"Which route would you most want to know about?","options":["A couples counsellor","A trusted friend or relative","A helpline for serious trouble","A support group"],"affirm":"Knowing any of these routes ahead of time is quiet strength, kept ready.","ask":"What makes that route feel right to you?","deeper":"What might stop someone from reaching out, and what could help?"},
  {"id":"cb-1316","cat":"tools-and-help","type":"reflect","persona":"any","source":"read your own gut","relearn":"Your own read on feeling respected, calm and yourself is a signal worth trusting.","hook":"How a relationship leaves you feeling is real information.","prompt":"After time together, which feeling matters most to you?","options":["Respected","More like myself","Calm, not on edge","Heard, even when we disagree"],"affirm":"Any of these is worth checking for; how you feel after time together is a signal you can trust.","ask":"What tells you that feeling is there?","deeper":"What might a friend notice first, and why?"},
  {"id":"cb-1317","cat":"tools-and-help","type":"choose","persona":"any","source":"no single timeline","hook":"A friend group swaps notes on what makes any relationship work well.","prompt":"Which of these helps, married or not?","options":[{"text":"Listening without planning your reply","fits":true,"note":"That skill helps any relationship, whatever the label on it."},{"text":"Saying sorry and meaning it","fits":true,"note":"Repair matters in any close relationship, married or not."},{"text":"Noticing when someone close is stressed","fits":true,"note":"Paying attention like this helps long before any wedding, and without one."},{"text":"Picking an auspicious date","fits":false,"note":"That's a task for a wedding, not a skill for the relationship."},{"text":"Choosing the guest list","fits":false,"note":"Only useful once there's a wedding to plan."},{"text":"Booking the banquet hall","fits":false,"note":"An event task, not something that helps two people get along."}],"relearn":"These tools work whether you marry now, later, or never."},
  {"id":"cb-1318","cat":"tools-and-help","type":"reflect","persona":"any","source":"help a friend","relearn":"Being the friend who listens, names a flag kindly, and knows the real routes can change someone's life.","hook":"A friend starts telling you that something feels wrong in their relationship.","prompt":"What could you do first?","options":["Listen without judging","Tell them I believe them","Ask what they need from me","Share where they can get help"],"affirm":"Any of these helps; listening without judging and knowing the routes makes you the friend who genuinely helps.","ask":"What would help you do that well?","deeper":"What might your friend need to hear most?"},
  {"id":"cb-1319","cat":"tools-and-help","type":"reflect","persona":"any","source":"wedding vs marriage reflect","relearn":"If you pour even half the wedding-day energy into the marriage itself, you start far stronger.","hook":"Imagine putting wedding-day energy into the marriage itself.","prompt":"What would you tend first?","options":["How we handle money","How we repair fights","How we share the load","How we stay close"],"affirm":"Tending the marriage, not just the day, is what lasts; any one you pick starts you strong.","ask":"What would tending that look like in your first year?","deeper":"What might a partner want to tend first, and why?"},
  {"id":"cb-1320","cat":"tools-and-help","type":"choose","persona":"Pooja","source":"seeing the invisible","hook":"Pooja realised she's the only one tracking what the house needs each week.","prompt":"What counts as the invisible work?","options":[{"text":"Remembering when the milk will run out","fits":true,"note":"Keeping track of what's needed before it runs out is real work."},{"text":"Noticing the school form is due soon","fits":true,"note":"Noticing what's coming up is work too, even if it's unseen."},{"text":"Planning what everyone will eat this week","fits":true,"note":"Deciding the meals ahead is thinking work that someone has to carry."},{"text":"Cooking the dinner","fits":false,"note":"A real task, but one that's seen, so it's easier to share."},{"text":"Carrying the shopping bags in","fits":false,"note":"Visible and physical, so it's easy to notice and share."},{"text":"Washing the dishes after dinner","fits":false,"note":"Another visible task, easy to see and take turns on."}],"relearn":"Once the mental load is named, it can finally be shared."},
  {"id":"cb-1321","cat":"tools-and-help","type":"reflect","persona":"any","source":"carry the toolkit forward","relearn":"Choose on values, build with care, commit freely, repair, and know where help lives: that's the whole kit.","hook":"A strong partnership leans on a few steady habits.","prompt":"Which feels most like yours already?","options":["Choose on values","Build with care","Commit freely","Know where help lives"],"affirm":"Carry that one, and you've got what it takes to choose and build a partnership that's truly yours.","ask":"Where have you seen that habit in your own life?","deeper":"Which habit would you like to grow next, and why?"},
  {"id":"cb-1322","cat":"tools-and-help","type":"strike-rewrite","persona":"Saxena","source":"counselling=broken","relearn":"Couples counselling is a tool for building better; many strong couples use it, not just broken ones.","hook":"\"Going to a couples counsellor means your marriage is broken.\"","myth":{"un":"Going to a couples counsellor means your marriage is broken.","re":"Counselling is a tool for building a stronger partnership; plenty of strong couples use it.","why":"You don't have to be breaking to want to get better."}},
  {"id":"cb-1323","cat":"tools-and-help","type":"strike-rewrite","persona":"Pooja","source":"helping=sharing","relearn":"Real sharing means owning the noticing and planning; 'helping when asked' still leaves the load on one person.","hook":"\"A husband who helps when asked is doing his fair share.\"","myth":{"un":"A husband who helps when asked is doing his fair share.","re":"Fair sharing means owning the noticing and planning too, not waiting to be told what to do.","why":"If she still tracks it all, the load is still hers."}},
  {"id":"cb-1324","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"ask=weakness","relearn":"Reaching for help from a counsellor, a friend or a helpline is a sign of strength and care, not weakness.","hook":"\"Needing outside help with a relationship is a sign of weakness.\"","myth":{"un":"Needing outside help with a relationship is a sign of weakness.","re":"Reaching for help from a counsellor, a trusted person or a helpline is strength and care, not weakness.","why":"Knowing when to ask is its own kind of wisdom."}},
  {"id":"cb-1325","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"love=no tools","relearn":"Even deep love needs real tools, like repair, 'I' statements and check-ins, to stay close over years.","hook":"\"If the love is real, you won't need 'techniques' or tools.\"","myth":{"un":"If the love is real, you won't need 'techniques' or tools.","re":"Even deep love uses real tools, like repair, 'I' statements and check-ins, to stay close over years.","why":"Skills are how good feeling becomes a lasting bond."}},
  {"id":"cb-1326","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"family=private always","relearn":"Forced marriage and abuse aren't 'private family matters' to endure; real help exists and it's never your fault.","hook":"\"Marriage troubles are private; you should never seek outside help.\"","myth":{"un":"Marriage troubles are private; you should never seek outside help.","re":"Coercion or abuse is never just 'private' to endure; help exists (181, 1091, 112) and it's not your fault.","why":"Safety and consent outrank keeping up appearances."}},
  {"id":"cb-1327","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"counsellor takes sides","relearn":"A good couples counsellor helps you both build skills and understand each other, not pick a winner.","hook":"\"A counsellor will just take my partner's side and judge us.\"","myth":{"un":"A counsellor will just take my partner's side and judge us.","re":"A good couples counsellor helps you both build skills and understand each other, not pick a winner.","why":"The aim is the partnership, not a verdict."}},
  {"id":"cb-1328","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"friend should fix it","relearn":"A good friend listens, names flags kindly and points to help; they can't and shouldn't fix the relationship for you.","hook":"\"A real friend would just tell me whether to leave or stay.\"","myth":{"un":"A real friend would just tell me whether to leave or stay.","re":"A good friend listens, names what they see and points to help; the choice stays yours.","why":"They can support the decision, not make it for you."}},
  {"id":"cb-1329","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"tools=manipulation","relearn":"Communication tools like 'I' statements and repair build honesty and closeness; they're not manipulation.","hook":"\"Using 'communication tricks' on your partner is just manipulation.\"","myth":{"un":"Using 'communication tricks' on your partner is just manipulation.","re":"Tools like 'I felt' openers and repair build honesty and closeness; they're the opposite of manipulation.","why":"They make you clearer and kinder, not sneakier."}},
  {"id":"cb-1350","cat":"what-it-takes","type":"strike-rewrite","hook":"\"A good partner just knows what you need without being told.\"","myth":{"un":"A good partner just knows what you need without being told.","re":"No one reads minds; naming what you need plainly is part of the work, not a sign of a weak bond.","why":"Spoken needs get met; hinted ones rarely do."},"relearn":"No one reads minds, so name what you need plainly; that's the work, not a sign of a weak bond.","persona":"any","source":"name your needs"},
  {"id":"cb-1351","cat":"what-it-takes","type":"strike-rewrite","hook":"\"Compromise means one of you always gives in.\"","myth":{"un":"Compromise means one of you always gives in.","re":"Real compromise looks for an option that respects both of you, not the same person caving every time.","why":"One person always caving is resentment in waiting."},"relearn":"Compromise finds an option that respects both of you; one person always caving builds resentment.","persona":"any","source":"fair compromise"},
  {"id":"cb-1352","cat":"what-it-takes","type":"strike-rewrite","hook":"\"If they really cared, they'd never upset you.\"","myth":{"un":"If they really cared, they'd never upset you.","re":"Even loving partners hurt each other sometimes; caring shows in how they own it and repair, not in never slipping.","why":"Repair, not perfection, is what holds."},"relearn":"Loving partners still slip; caring shows in owning it and repairing, not in never upsetting you.","persona":"any","source":"repair over perfection"},
  {"id":"cb-1353","cat":"what-it-takes","type":"strike-rewrite","hook":"\"Bringing up a problem just starts a fight, so stay quiet.\"","myth":{"un":"Bringing up a problem just starts a fight, so stay quiet.","re":"Unsaid problems don't vanish; they leak out as distance. Raised kindly and early, they're easier to solve.","why":"Silence stores up; honesty clears the air."},"relearn":"Unsaid problems leak out as distance; raise them kindly and early instead of staying quiet.","persona":"any","source":"don't store it up"},
  {"id":"cb-1354","cat":"what-it-takes","type":"strike-rewrite","hook":"\"Doing the chores you split is doing them 'a favour'.\"","myth":{"un":"Doing the chores you both agreed to split is doing your partner a favour.","re":"Shared work you agreed on is just your share, not a favour to be thanked for; it's how a team runs.","why":"A favour is extra; your share is baseline."},"relearn":"Your agreed share of the work isn't a favour to be thanked for; it's how a team runs.","persona":"Karthik","source":"share not favour"},
  {"id":"cb-1355","cat":"what-it-takes","type":"strike-rewrite","hook":"\"Keeping a tally of who did more keeps things fair.\"","myth":{"un":"Keeping a running tally of who did more keeps things fair.","re":"Scorekeeping turns a team into rivals; aiming to support each other beats counting who 'owes' whom.","why":"Tallies measure debt, not partnership."},"relearn":"Scorekeeping turns a team into rivals; support each other instead of counting who owes whom.","persona":"any","source":"stop scorekeeping"},
  {"id":"cb-1356","cat":"what-it-takes","type":"strike-rewrite","hook":"\"Spending time apart means you're drifting apart.\"","myth":{"un":"Spending time apart means you're drifting apart.","re":"Two whole people keep their own friends and interests; healthy space refills the bond, it doesn't drain it.","why":"Room to breathe makes the 'us' stronger."},"relearn":"Healthy space and your own interests refill the bond; togetherness needn't mean fusing into one.","persona":"any","source":"space is healthy"},
  {"id":"cb-1357","cat":"what-it-takes","type":"strike-rewrite","hook":"\"Saying sorry first means you've lost the argument.\"","myth":{"un":"Saying sorry first means you've lost the argument.","re":"Repairing first isn't losing; it's choosing the relationship over being right, and it takes more strength.","why":"You're on the same side, not opponents."},"relearn":"Repairing first isn't losing; it chooses the relationship over being right, and takes more strength.","persona":"any","source":"repair isn't losing"},
  {"id":"cb-1358","cat":"what-it-takes","type":"strike-rewrite","hook":"\"Big feelings should be handled alone so you don't burden them.\"","myth":{"un":"Big feelings should be handled alone so you don't burden your partner.","re":"Turning toward each other with hard feelings is the point of a partnership; shared weight is lighter, not a burden.","why":"Being let in is how trust deepens."},"relearn":"Turning toward each other with hard feelings deepens trust; shared weight is lighter, not a burden.","persona":"any","source":"turn toward"},
  {"id":"cb-1359","cat":"what-it-takes","type":"strike-rewrite","hook":"\"Once you're committed, you can stop making an effort.\"","myth":{"un":"Once you're committed, you can stop making an effort.","re":"Commitment is the start of the work, not the end of it; the small efforts are what keep a bond alive for years.","why":"Coasting is how warmth quietly fades."},"relearn":"Commitment starts the work, it doesn't end it; small ongoing efforts keep a bond alive.","persona":"any","source":"keep showing up"},
  {"id":"cb-1360","cat":"what-it-takes","type":"sort","hook":"Sort: builds the partnership, or erodes it?","items":[{"id":"a","text":"Saying thank you for the everyday things"},{"id":"b","text":"Bringing up an old wrong in every fight"},{"id":"c","text":"Checking in on how the other is really doing"},{"id":"d","text":"Going silent for days when upset"},{"id":"e","text":"Owning your share after a rough patch"},{"id":"f","text":"Letting small grudges quietly pile up"}],"bins":[{"id":"builds","label":"Builds it","valence":"pos"},{"id":"erodes","label":"Erodes it","valence":"neg"}],"key":{"a":"builds","b":"erodes","c":"builds","d":"erodes","e":"builds","f":"erodes"},"relearn":"Thanks, check-ins and owning your share build a partnership; old wrongs, silence and grudges erode it.","persona":"any","source":"builds vs erodes"},
  {"id":"cb-1361","cat":"what-it-takes","type":"sort","hook":"Sort: builds trust, or breaks it?","items":[{"id":"a","text":"Doing what you said you'd do"},{"id":"b","text":"Checking their phone behind their back"},{"id":"c","text":"Telling them a hard truth gently"},{"id":"d","text":"Repeating what they told you in confidence"},{"id":"e","text":"Showing up when you promised to"},{"id":"f","text":"Hiding a money worry from them"}],"bins":[{"id":"builds","label":"Builds trust","valence":"pos"},{"id":"breaks","label":"Breaks it","valence":"neg"}],"key":{"a":"builds","b":"breaks","c":"builds","d":"breaks","e":"builds","f":"breaks"},"relearn":"Reliability and honest gentleness build trust; snooping, breaking confidences and hiding things break it.","persona":"any","source":"trust day to day"},
  {"id":"cb-1362","cat":"what-it-takes","type":"sort","hook":"Sort: a way to raise an issue that lands, or one that wounds?","items":[{"id":"a","text":"\"I felt left out at the party.\""},{"id":"b","text":"\"You always ignore me.\""},{"id":"c","text":"\"I'd love more help with bedtime.\""},{"id":"d","text":"\"You never lift a finger here.\""},{"id":"e","text":"\"Can we figure this out together?\""},{"id":"f","text":"\"This is all your fault, as usual.\""}],"bins":[{"id":"lands","label":"Lands well","valence":"pos"},{"id":"wounds","label":"Wounds","valence":"neg"}],"key":{"a":"lands","b":"wounds","c":"lands","d":"wounds","e":"lands","f":"wounds"},"relearn":"\"I felt\" openers and joint problem-solving land; \"you always/never\" attacks and blame wound.","persona":"any","source":"how you raise it"},
  {"id":"cb-1363","cat":"what-it-takes","type":"sort","hook":"Sort: interdependence, or losing yourself?","items":[{"id":"a","text":"Keeping your own close friendships"},{"id":"b","text":"Dropping every hobby for theirs"},{"id":"c","text":"Backing each other's separate goals"},{"id":"d","text":"Needing permission for small things"},{"id":"e","text":"Two opinions you can both voice"},{"id":"f","text":"Hiding your real views to keep peace"}],"bins":[{"id":"inter","label":"Interdependence","valence":"pos"},{"id":"lost","label":"Losing yourself","valence":"neg"}],"key":{"a":"inter","b":"lost","c":"inter","d":"lost","e":"inter","f":"lost"},"relearn":"Own friendships, separate goals and your own voice are interdependence; dropping it all is losing yourself.","persona":"any","source":"us without erasing me"},
  {"id":"cb-1364","cat":"what-it-takes","type":"sort","hook":"Sort: keeps love alive over years, or lets it fade?","items":[{"id":"a","text":"Small daily rituals you share"},{"id":"b","text":"Assuming the spark runs itself"},{"id":"c","text":"Noticing and naming what you appreciate"},{"id":"d","text":"Treating each other as furniture"},{"id":"e","text":"Protecting time to actually talk"},{"id":"f","text":"Letting busyness eat every evening"}],"bins":[{"id":"alive","label":"Keeps it alive","valence":"pos"},{"id":"fade","label":"Lets it fade","valence":"neg"}],"key":{"a":"alive","b":"fade","c":"alive","d":"fade","e":"alive","f":"fade"},"relearn":"Shared rituals, naming appreciation and protected talk-time keep love alive; coasting lets it fade.","persona":"any","source":"keeping love alive"},
  {"id":"cb-1365","cat":"what-it-takes","type":"sort","hook":"Sort: handling a fight that repairs, or one that escalates?","items":[{"id":"a","text":"Taking a breather, then coming back"},{"id":"b","text":"Dragging in their family to score points"},{"id":"c","text":"Sticking to the actual issue"},{"id":"d","text":"Threatening to walk out for effect"},{"id":"e","text":"Saying \"help me understand\""},{"id":"f","text":"Mocking how they feel"}],"bins":[{"id":"repair","label":"Repairs","valence":"pos"},{"id":"escal","label":"Escalates","valence":"neg"}],"key":{"a":"repair","b":"escal","c":"repair","d":"escal","e":"repair","f":"escal"},"relearn":"A breather, staying on the issue and curiosity repair a fight; family-scoring, threats and mockery escalate it.","persona":"any","source":"fighting fair"},
  {"id":"cb-1366","cat":"what-it-takes","type":"sort","hook":"Sort: shares the mental load, or dumps it on one person?","items":[{"id":"a","text":"Tracking the chores without being asked"},{"id":"b","text":"Waiting to be handed a to-do list"},{"id":"c","text":"Remembering the kid's check-up without a reminder"},{"id":"d","text":"\"Just tell me what to do\" every time"},{"id":"e","text":"Owning a whole task end to end"},{"id":"f","text":"Calling your share a big 'help'"}],"bins":[{"id":"shared","label":"Shares the load","valence":"pos"},{"id":"dumped","label":"Dumps it","valence":"neg"}],"key":{"a":"shared","b":"dumped","c":"shared","d":"dumped","e":"shared","f":"dumped"},"relearn":"Tracking and owning tasks yourself shares the mental load; waiting to be managed dumps it on one person.","persona":"Pooja","source":"mental load"},
  {"id":"cb-1367","cat":"what-it-takes","type":"sort","hook":"Sort: a reliable habit, or a fragile one?","items":[{"id":"a","text":"Doing the small things you promise"},{"id":"b","text":"Big gestures, then long silences"},{"id":"c","text":"Showing up steadily on dull days"},{"id":"d","text":"Effort only when you want something"},{"id":"e","text":"Following through on plans you set"},{"id":"f","text":"Vanishing the moment it's inconvenient"}],"bins":[{"id":"reliable","label":"Reliable","valence":"pos"},{"id":"fragile","label":"Fragile","valence":"uhoh"}],"key":{"a":"reliable","b":"fragile","c":"reliable","d":"fragile","e":"reliable","f":"fragile"},"relearn":"Small kept promises and steady follow-through are reliable; grand gestures with silences are fragile.","persona":"any","source":"reliable vs fragile"},
  {"id":"cb-1368","cat":"what-it-takes","type":"sort","hook":"Sort: a real apology, or a fake one?","items":[{"id":"a","text":"\"I was wrong, and I'm sorry I hurt you.\""},{"id":"b","text":"\"Sorry you took it that way.\""},{"id":"c","text":"\"Here's what I'll do differently.\""},{"id":"d","text":"\"Sorry, but you started it.\""},{"id":"e","text":"Naming exactly what you got wrong"},{"id":"f","text":"A quick sorry to end the talk fast"}],"bins":[{"id":"real","label":"Real repair","valence":"pos"},{"id":"fake","label":"Fake one","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"Owning the wrong and naming what you'll change is real repair; \"sorry you felt that\" and excuses are fake.","persona":"any","source":"real vs fake apology"},
  {"id":"cb-1369","cat":"what-it-takes","type":"sort","hook":"Sort: feeling like a team, or feeling like opponents?","items":[{"id":"a","text":"\"It's us against the problem.\""},{"id":"b","text":"\"It's me against you.\""},{"id":"c","text":"Celebrating each other's wins"},{"id":"d","text":"Quietly hoping they slip up"},{"id":"e","text":"Planning the hard week together"},{"id":"f","text":"Withholding to make a point"}],"bins":[{"id":"team","label":"A team","valence":"pos"},{"id":"versus","label":"Opponents","valence":"neg"}],"key":{"a":"team","b":"versus","c":"team","d":"versus","e":"team","f":"versus"},"relearn":"\"Us vs the problem\", celebrating wins and planning together is teamwork; rivalry and withholding aren't.","persona":"any","source":"team vs opponents"},
  {"id":"cb-1370","cat":"what-it-takes","type":"sort","hook":"Sort: deepens connection, or quietly distances?","items":[{"id":"a","text":"Asking about their day and listening"},{"id":"b","text":"Scrolling while they talk"},{"id":"c","text":"Remembering what matters to them"},{"id":"d","text":"Forgetting things they told you twice"},{"id":"e","text":"Being curious about their inner world"},{"id":"f","text":"Assuming you already know them fully"}],"bins":[{"id":"deepens","label":"Deepens it","valence":"pos"},{"id":"distances","label":"Distances","valence":"neg"}],"key":{"a":"deepens","b":"distances","c":"deepens","d":"distances","e":"deepens","f":"distances"},"relearn":"Listening, remembering and staying curious deepen connection; half-attention and assuming distance you.","persona":"any","source":"staying curious"},
  {"id":"cb-1371","cat":"what-it-takes","type":"sort","hook":"Sort: solid reason to ask for couples counselling, or a myth about it?","items":[{"id":"a","text":"\"We keep having the same fight.\""},{"id":"b","text":"\"Counselling means we've failed.\""},{"id":"c","text":"\"We want to communicate better.\""},{"id":"d","text":"\"Only broken couples go.\""},{"id":"e","text":"\"A neutral third view could help.\""},{"id":"f","text":"\"Asking for help is weakness.\""}],"bins":[{"id":"solid","label":"Solid reason","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"solid","b":"myth","c":"solid","d":"myth","e":"solid","f":"myth"},"relearn":"A recurring fight or wanting to communicate better are good reasons for a counsellor; \"only failures go\" is a myth.","persona":"Saxena","source":"counselling normalised"},
  {"id":"cb-1372","cat":"what-it-takes","type":"sort","hook":"Sort: respecting their separateness, or controlling it?","items":[{"id":"a","text":"Trusting them out with friends"},{"id":"b","text":"Demanding their location all day"},{"id":"c","text":"Welcoming their differing opinion"},{"id":"d","text":"Sulking when they say no to you"},{"id":"e","text":"Encouraging time with their family"},{"id":"f","text":"Reading their messages uninvited"}],"bins":[{"id":"respect","label":"Respects it","valence":"pos"},{"id":"control","label":"Controls it","valence":"neg"}],"key":{"a":"respect","b":"control","c":"respect","d":"control","e":"respect","f":"control"},"relearn":"Trusting, welcoming differences and their own people respects separateness; tracking and sulking control it.","persona":"any","source":"respect vs control"},
  {"id":"cb-1373","cat":"what-it-takes","type":"sort","hook":"Sort: warmth that holds long-term love, or coldness that thins it?","items":[{"id":"a","text":"A small kind word in a busy week"},{"id":"b","text":"Eye-rolling when they speak"},{"id":"c","text":"A hand on the shoulder, no reason"},{"id":"d","text":"Contempt dressed up as a joke"},{"id":"e","text":"Saying \"I'm glad it's you\""},{"id":"f","text":"Treating them as background noise"}],"bins":[{"id":"warmth","label":"Warmth","valence":"pos"},{"id":"cold","label":"Coldness","valence":"neg"}],"key":{"a":"warmth","b":"cold","c":"warmth","d":"cold","e":"warmth","f":"cold"},"relearn":"Small kindness, touch and gladness hold long-term love; eye-rolls, contempt and indifference thin it.","persona":"any","source":"warmth vs contempt"},
  {"id":"cb-1374","cat":"what-it-takes","type":"role-play","persona":"any","source":"don't fire back","hook":"Yusuf snaps at you the moment he walks in, clearly wound tight from work.","setup":"He drops his bag hard and goes quiet.","steps":[{"prompt":"Yusuf snaps: \"Can you just not talk to me right now?\"","options":[{"text":"\"That stung a bit. Long day? Want to talk or rest first?\"","then":"He deflates. \"Sorry. Yeah. Really long day. Just, give me a minute?\"","best":true},{"text":"\"Wow, don't take your mood out on me like that, ever again.\"","then":"He bristles further. \"I said sorry basically, can we not do this now?\""},{"text":"\"Fine, I'll just leave you alone then.\"","then":"He nods and disappears into the other room, the tension unresolved."},{"text":"\"What's your problem tonight?\"","then":"He snaps back. \"My problem is I need five minutes, apparently.\""}],"why":"Naming the sting without attacking leaves room for his day, not swallowing it."},{"prompt":"A few minutes later, Yusuf returns: \"Sorry about that. Work was brutal today.\"","options":[{"text":"\"Thank you for coming back to say that. Want to talk about it?\"","then":"He sits down, relieved. \"Actually, yeah. Kind of a lot happened.\"","best":true},{"text":"\"It's fine, honestly, these things happen sometimes I suppose.\"","then":"He nods, though the earlier sting never really gets acknowledged."},{"text":"\"You really shouldn't snap at me like that.\"","then":"He sighs. \"I know. I said sorry. Can we move past it?\""},{"text":"\"Next time just warn me before you're like that.\"","then":"He nods, a little wary, and it feels more like a warning than a talk."}],"why":"Welcoming the repair, not just accepting it, keeps the door open for the real story."},{"prompt":"He asks: \"How do we handle it better next time I'm like this?\"","options":[{"text":"\"Maybe a heads-up: 'rough day' before anything else. That'd help.\"","then":"He nods. \"I can do that. A warning, not a wall. I like that.\"","best":true},{"text":"\"I don't know, maybe I'll just learn to expect it eventually.\"","then":"He looks uneasy. \"I don't want you having to just expect it, though.\""},{"text":"\"Just try not to be like that at all.\"","then":"He looks discouraged. \"I can't promise that, not every day.\""},{"text":"\"Honestly, I'll probably just fire back next time too.\"","then":"He looks worried. \"Then we'd both just be snapping at each other.\""}],"why":"A small heads-up signal, agreed together, turns a hard moment manageable."},{"prompt":"A week later, Yusuf walks in and says: \"Rough day. Just warning you before anything else.\"","options":[{"text":"\"Thanks for the heads-up. Take whatever space you need.\"","then":"He relaxes instantly. \"That actually helps so much, thank you.\"","best":true},{"text":"\"Okay, noted, though I hope this doesn't become an everyday thing.\"","then":"He nods, a little deflated, and the warmth of the moment fades."},{"text":"\"Good, at least you warned me this time.\"","then":"He winces. \"I'm trying here, that came out a bit sharp.\""},{"text":"\"Still not really an excuse to be short with me, though.\"","then":"He sighs. \"I'm not trying to be short, I'm trying to warn you first.\""}],"why":"Meeting the heads-up with space, not a test, makes the new habit worth keeping."}],"relearn":"Name the sting gently and leave room for their day, rather than firing back an attack."},
  {"id":"cb-1375","cat":"what-it-takes","type":"role-play","persona":"Pooja","source":"own a share","hook":"You realise you've quietly become the one doing all the laundry and cleaning, every week.","setup":"Saturday morning, mid-load of laundry, Karthik wanders in.","steps":[{"prompt":"Karthik asks: \"Need anything from the store while I'm out?\"","options":[{"text":"\"Actually, let's split the home stuff. Which bits will you own?\"","then":"He pauses, surprised. \"Oh. I hadn't thought about splitting it like that.\"","best":true},{"text":"\"Could you maybe just help me out a little more sometimes?\"","then":"He nods. \"Sure, just let me know when.\" The laundry stays yours regardless."},{"text":"\"No, I've got it, like I always do.\"","then":"He nods and heads out, and the pattern continues unnoticed."},{"text":"\"You could just pitch in without me having to ask.\"","then":"He looks caught off guard. \"I didn't realise you were waiting for that.\""}],"why":"Asking him to own specific pieces, not just 'help', makes the split real."},{"prompt":"Later that day, Karthik asks: \"Okay. What are all the chores, actually?\"","options":[{"text":"\"Laundry, dishes, cleaning, groceries. Pick yours.\"","then":"He considers it. \"I'll take laundry and dishes. Fully, not just sometimes.\"","best":true},{"text":"\"Whatever you feel like doing on a given day, I suppose.\"","then":"He nods vaguely, and \"feel like doing\" ends up meaning not very often."},{"text":"\"I'll keep doing most of it, just chip in when you can.\"","then":"He agrees easily, and the actual balance barely shifts at all."},{"text":"\"You choose. I don't really mind which.\"","then":"He hesitates. \"I'd rather we figured this out together, honestly.\""}],"why":"Naming specific tasks as fully his turns a vague promise into an actual plan."},{"prompt":"Two weeks later, Karthik says: \"I realised I skipped my share of the chores again.\"","options":[{"text":"\"Thanks for noticing. Let's figure out what makes it easy to skip.\"","then":"He nods. \"Honestly, I think I need a reminder until it's a real habit.\"","best":true},{"text":"\"It's fine. I'll just do it this week since it's already piling up.\"","then":"He looks relieved, and laundry quietly drifts back toward you again."},{"text":"\"You said you'd own that, so own it.\"","then":"He winces. \"I know. I'm working on it, I promise.\""},{"text":"\"I knew this wouldn't actually last.\"","then":"He looks discouraged. \"That's not exactly motivating, honestly.\""}],"why":"Solving the slip together, not silently absorbing it, keeps the split from unraveling."}],"relearn":"Ask your partner to own a fair share, not to 'help' you; the work is both of yours."},
  {"id":"cb-1376","cat":"what-it-takes","type":"role-play","persona":"any","source":"clean repair","hook":"You forgot to make the dinner reservation for Leena's birthday tonight.","setup":"She's dressed and ready when you realise.","steps":[{"prompt":"Leena asks: \"Wait, what time's our reservation again?\"","options":[{"text":"\"I dropped the ball, I never booked it. I'm sorry. Let me fix this now.\"","then":"She looks disappointed but softens. \"Okay. Thank you for just being honest.\"","best":true},{"text":"\"It slipped my mind. It's honestly not a big deal. Let's just wing it tonight.\"","then":"She looks hurt. \"It's my birthday. It kind of is a big deal.\""},{"text":"\"I thought you were handling that, actually.\"","then":"She looks stunned. \"I definitely wasn't. This was yours.\""},{"text":"\"We can just order in instead.\"","then":"She goes quiet. \"That's not really what I was hoping for tonight.\""}],"why":"Owning the mistake plainly, then acting, is what actually starts to repair it."},{"prompt":"Leena asks: \"Okay. So what's the plan now?\"","options":[{"text":"\"Calling around now. If nothing's free, I'll cook for you.\"","then":"She manages a small smile. \"Okay. That actually sounds kind of sweet.\"","best":true},{"text":"\"I'll figure something out. Don't worry about it too much.\"","then":"She nods, though \"figure something out\" isn't really an actual plan."},{"text":"\"Honestly, any place will probably do at this point.\"","then":"She sighs. \"I'd rather you actually thought about it, tonight especially.\""},{"text":"\"You pick somewhere. I clearly can't be trusted with this.\"","then":"She looks tired. \"I don't want to plan my own birthday, though.\""}],"why":"A concrete backup plan turns the apology into something she can actually feel."},{"prompt":"Later, over the dinner you ended up having, Leena says: \"This actually turned out really nice.\"","options":[{"text":"\"I'm glad. And I'm setting a reminder so this never happens again.\"","then":"She smiles. \"I appreciate that. It means you're taking it seriously.\"","best":true},{"text":"\"Yeah, see, it worked out fine in the end, no real harm done.\"","then":"She pauses. \"I mean, it did, but that's not really the point.\""},{"text":"\"Told you it would all work out somehow.\"","then":"She looks unconvinced. \"It worked out because you scrambled, though.\""},{"text":"\"Let's just not talk about the reservation thing anymore.\"","then":"She nods, though the same mistake stays a real risk next time."}],"why":"Naming a concrete fix for next time shows the repair outlasts tonight's scramble."}],"relearn":"Own the slip and offer a concrete repair, instead of brushing it off as no big deal."},
  {"id":"cb-1377","cat":"what-it-takes","type":"role-play","persona":"any","source":"invite, don't accuse","hook":"Weeks of back-to-back schedules have left you and Farhan barely talking.","setup":"Tonight you're both on the couch, phones out, not really together.","steps":[{"prompt":"Farhan glances up: \"Sorry, work's been insane. You good?\"","options":[{"text":"\"I've missed us lately. Can we carve out an evening, just us?\"","then":"He puts his phone down. \"Yeah. Honestly, I've missed this too.\"","best":true},{"text":"\"You've made me feel pretty alone in this lately, if I'm honest.\"","then":"He looks stung. \"That's not fair. I've been swamped, not distant on purpose.\""},{"text":"\"I'm fine, just tired I guess.\"","then":"He nods and goes back to his phone, and the distance stays exactly the same."},{"text":"\"We really need to talk about how little we talk.\"","then":"He sighs. \"Can we not turn this into a whole thing right now?\""}],"why":"Naming what you miss, not accusing, invites him in instead of the defence."},{"prompt":"The next morning, Farhan says: \"We should make time for us. What night works for you?\"","options":[{"text":"\"Thursday. Let's actually protect it, no phones, no work talk.\"","then":"He nods. \"Deal. I'll block it off properly, not just half-mean it.\"","best":true},{"text":"\"Whenever's easiest for you, honestly, I really don't mind either way at all.\"","then":"He nods vaguely, and the plan stays soft enough to slip later."},{"text":"\"Whenever work finally slows down for you.\"","then":"He winces. \"That could be a while, honestly. Let's not wait for that.\""},{"text":"\"Doesn't matter. We'll probably just cancel anyway.\"","then":"He looks a little hurt. \"Way to already assume it won't happen.\""}],"why":"A specific, protected night turns the invitation into a real plan."},{"prompt":"Wednesday, Farhan texts: \"Work's throwing a late thing tomorrow. Still want to try?\"","options":[{"text":"\"Yes. Even an hour matters more than skipping it entirely.\"","then":"He replies: \"Okay. I'll make the hour count, I promise.\"","best":true},{"text":"\"Let's just push it to whenever things finally calm down at work for you.\"","then":"He agrees, then texts again: \"Actually, let's keep tomorrow.\""},{"text":"\"Of course work comes first again.\"","then":"He replies, stung: \"That's not fair, I'm trying to still make time.\""},{"text":"\"Forget it, we'll just try some other week.\"","then":"He hesitates, then says: \"No. Let's keep it, even short.\""}],"why":"Protecting even a shortened version keeps the reconnection from disappearing."},{"prompt":"Thursday night, one real hour in, Farhan says: \"This actually feels like us again.\"","options":[{"text":"\"It does. Let's keep doing this, not just when we notice the gap.\"","then":"He nods. \"Agreed. Let's not wait until we're this distant again.\"","best":true},{"text":"\"Yeah, we should probably try to do this again sometime soon.\"","then":"He nods, though \"sometime soon\" has a way of quietly becoming never."},{"text":"\"See, we didn't even need a whole evening.\"","then":"He pauses. \"I mean, sure, but let's not shrink it every time either.\""},{"text":"\"Let's just see how busy things get.\"","then":"He looks uncertain whether tonight actually changes anything going forward."}],"why":"Naming a standing intention, not a one-off night, is what keeps you both close."}],"relearn":"Invite closeness with an 'I've missed us' opener, rather than accusing them of the distance."},
  {"id":"cb-1378","cat":"what-it-takes","type":"role-play","persona":"any","source":"appreciate out loud","hook":"Down with a fever for two days, you realise Sana has quietly handled everything.","setup":"Feeling better tonight, you notice the apartment spotless, dinner ready.","steps":[{"prompt":"Sana asks: \"Feeling any better? I made soup again.\"","options":[{"text":"\"I noticed you've handled everything for two days. Thank you.\"","then":"She pauses, touched. \"I wasn't sure you'd even noticed, being so sick.\"","best":true},{"text":"\"You're honestly the best. I don't know what I'd do without you.\"","then":"She smiles, though it's unclear what specifically you're thanking her for."},{"text":"\"Thanks for everything, you're great.\"","then":"She smiles, but it's still a little vague what you actually noticed."},{"text":"\"You didn't have to do all that, honestly.\"","then":"She shrugs. \"Someone had to. Don't make a big thing of it.\""}],"why":"Naming exactly what she did, specifically, is what makes the thanks land."},{"prompt":"Sana says: \"It was honestly no trouble, don't make a big thing of it.\"","options":[{"text":"\"It is a thing, though. The bills, the meals, all of it. I saw it.\"","then":"She softens. \"Okay. Thank you for actually saying that out loud.\"","best":true},{"text":"\"Okay, if you insist, I really won't make a big deal of any of it then.\"","then":"She nods, then mentions how tiring the bills and meals were."},{"text":"\"Fine, I'll stop going on about it.\"","then":"She looks deflated, so you name what you saw after all."},{"text":"\"You always say that, though.\"","then":"She shrugs. \"I mean it every time, too.\""}],"why":"Naming the specific list, not backing off, is what makes the appreciation real."},{"prompt":"Later, Sana says quietly: \"That actually really helped, hearing it named like that.\"","options":[{"text":"\"I want to keep saying it, not assume you know.\"","then":"She smiles. \"I'd really like that. It's easy to feel invisible otherwise.\"","best":true},{"text":"\"I'll try to remember to do that more often when I can.\"","then":"She nods, though \"when I can\" leaves it a little uncertain."},{"text":"\"I mean, you probably already knew anyway.\"","then":"She shakes her head. \"Honestly, I didn't. Not until you said it.\""},{"text":"\"Well, don't get used to it.\"","then":"She laughs, though something in it lands a little flat."}],"why":"Naming the intention to keep doing it turns one thank-you into a habit."}],"relearn":"Say the appreciation out loud and specifically; assuming they 'just know' starves the bond."},
  {"id":"cb-1379","cat":"what-it-takes","type":"role-play","persona":"any","source":"us vs the problem","hook":"You and Diya disagree about buying a car now versus saving two more years.","setup":"It's starting to feel like a standoff.","steps":[{"prompt":"Diya says: \"I really don't see why we can't just buy it now.\"","options":[{"text":"\"We see this differently. Let's work out something that fits us both.\"","then":"She exhales. \"Okay. I don't want this to turn into a fight, honestly.\"","best":true},{"text":"\"My way's obviously the more sensible one, so let's just go with that.\"","then":"She bristles. \"That's not really a conversation, that's just you deciding.\""},{"text":"\"Fine, let's just buy it, if it stops the arguing.\"","then":"She looks uneasy. \"I don't want you to just give in, though.\""},{"text":"\"You clearly haven't thought this through properly.\"","then":"She stiffens. \"I have, actually. Just differently from you.\""}],"why":"Naming it as two views, not a fight to win, keeps you on the same side."},{"prompt":"Diya asks: \"Okay, so what's actually behind your wanting to wait?\"","options":[{"text":"\"I want more of a cushion first. What's behind wanting it now?\"","then":"She thinks. \"Honestly, the commute is wearing me down more than I've said.\"","best":true},{"text":"\"I just have a bad feeling about spending that much right now.\"","then":"She nods, though the actual reason underneath stays a little vague."},{"text":"\"I don't need a reason. I just think it's smarter.\"","then":"She frowns. \"That doesn't really tell me anything, though.\""},{"text":"\"Because you always want things right away.\"","then":"She looks hurt. \"That's not really fair, or accurate.\""}],"why":"Naming your real reason and asking for hers turns a standoff into information."},{"prompt":"She admits: \"The commute's honestly been exhausting me more than I let on.\"","options":[{"text":"\"I didn't know that. Let's find something that eases it.\"","then":"She looks relieved. \"Thank you for actually asking instead of deciding.\"","best":true},{"text":"\"That's fair. I guess we'll just have to buy it now, then.\"","then":"She nods, though the actual budget conversation never quite happens."},{"text":"\"You should have just said that from the start.\"","then":"She looks defensive. \"I'm saying it now, isn't that enough?\""},{"text":"\"That doesn't really change the money situation, though.\"","then":"She looks deflated. \"So none of this actually mattered, then?\""}],"why":"Solving the real problem together, once named, beats winning the argument."},{"prompt":"A few days later, Diya says: \"I looked into carpooling options for the commute.\"","options":[{"text":"\"Let's go through them together and see what actually works.\"","then":"She smiles. \"I was hoping you'd say that. Let's look now.\"","best":true},{"text":"\"Just pick whichever one seems easiest and I'll go along with it.\"","then":"She hesitates. \"I'd rather we decided this one together, honestly.\""},{"text":"\"Great, so we don't need to talk about the car anymore then.\"","then":"She pauses. \"Maybe, but let's actually finish that conversation too.\""},{"text":"\"I'm sure whatever you picked is fine.\"","then":"She looks uncertain whether you're actually engaged in this."}],"why":"Following through together on the real fix is what makes 'us vs the problem' real."}],"relearn":"Frame a disagreement as you both against the problem, not as your way winning over theirs."},
  {"id":"cb-1380","cat":"what-it-takes","type":"role-play","persona":"any","source":"pause, don't shut down","hook":"An argument with Neel about his mother's comments is spiralling fast.","setup":"Your voice is starting to shake.","steps":[{"prompt":"Neel says, voice raised: \"So what, now I can't even talk about my own mother?\"","options":[{"text":"\"I need ten minutes to cool down. Then let's finish this properly.\"","then":"He pauses, startled by the shift. \"Okay. Ten minutes. I'll be here.\"","best":true},{"text":"\"Forget it, honestly, I'm completely done talking to you right now.\"","then":"He looks stricken. \"Done? What does that even mean, done?\""},{"text":"\"Fine, defend her all you want then.\"","then":"He snaps back. \"That's not what I'm doing, and you know it.\""},{"text":"\"You always do this, every single time.\"","then":"He raises his voice further. \"And you always bring up 'every time'.\""}],"why":"Naming a real pause, with a promise to return, stops the words you'd regret."},{"prompt":"You step out to cool down, and Neel asks, quieter now: \"Are you coming back, or is this just walking away?\"","options":[{"text":"\"Coming back. I don't want to say something I can't take back.\"","then":"He nods slowly. \"Okay. That actually makes sense. I'll wait.\"","best":true},{"text":"\"I honestly don't know yet. I just need some space right now.\"","then":"He looks unsettled, unsure if there's actually a plan to return."},{"text":"\"That depends on you, honestly.\"","then":"He looks wounded. \"So this is a test now, is that it?\""},{"text":"\"Just trust me, okay?\"","then":"He nods, though the uncertainty doesn't really go anywhere."}],"why":"Naming the reason for the pause reassures him it's a break, not an exit."},{"prompt":"Ten minutes later, you return, and Neel asks: \"Better?\"","options":[{"text":"\"Better. Can we talk about your mother's comment calmly?\"","then":"He nods. \"Yeah. I actually thought about it while you were gone, too.\"","best":true},{"text":"\"A bit, I guess, though I'm still not totally sure how I feel.\"","then":"He nods cautiously, unsure if the conversation will heat up again."},{"text":"\"Sure, whatever, let's just get this over with.\"","then":"He tenses. \"That doesn't sound like better, honestly.\""},{"text":"\"I'm fine now, forget I said anything earlier.\"","then":"He looks confused. \"So we're not actually finishing this, then?\""}],"why":"Returning and naming the real topic again makes the pause a tool, not a dodge."},{"prompt":"A month later, a new argument heats up, and Neel says: \"I think I need ten minutes, actually.\"","options":[{"text":"\"Okay. Take it. I'll be here when you're ready.\"","then":"He nods and steps away, returning calmer, ready to actually talk.","best":true},{"text":"\"Fine, but I hope this doesn't become how we handle everything.\"","then":"He hesitates, the pause feeling a little more fraught than it should."},{"text":"\"We don't really have time for that right now.\"","then":"He looks frustrated. \"This is literally what we agreed to do, though.\""},{"text":"\"Sure, take forever. I don't even care at this point.\"","then":"He pauses, hurt, unsure if you mean that."}],"why":"Letting him use the same tool shows the pause belongs to both of you."}],"relearn":"Ask for a short pause and a promise to return, rather than storming off and shutting down."},
  {"id":"cb-1381","cat":"what-it-takes","type":"role-play","persona":"any","source":"listen before fixing","hook":"Ira comes home stressed about a conflict with her manager.","setup":"She starts explaining, visibly frustrated.","steps":[{"prompt":"Ira says: \"My manager basically dismissed everything I said in that meeting.\"","options":[{"text":"\"That sounds heavy. Do you want ideas, or should I just listen?\"","then":"She exhales. \"Just listen, actually. I need to vent before I problem-solve.\"","best":true},{"text":"\"Here's exactly what you should do: email her directly about it.\"","then":"She looks frustrated. \"I just wanted to vent, not a whole action plan.\""},{"text":"\"That manager sounds awful, honestly.\"","then":"She nods but keeps talking, still visibly wound up."},{"text":"\"Did you maybe misread the situation a little?\"","then":"She looks stung. \"No, I don't think I did, actually.\""}],"why":"Asking what she needs first respects that venting and fixing aren't the same ask."},{"prompt":"Ira continues: \"It's just exhausting, feeling unheard in every single meeting.\"","options":[{"text":"\"That does sound exhausting. I'm just here, keep going.\"","then":"She keeps talking, visibly relaxing as she gets it all out.","best":true},{"text":"\"Maybe try writing your points down beforehand next time.\"","then":"She sighs. \"I said I just wanted to vent, remember?\""},{"text":"\"You should probably talk to HR about this.\"","then":"She looks tired. \"Can I just finish talking first, please?\""},{"text":"\"Try not to let it get to you so much.\"","then":"She looks hurt. \"That's kind of dismissing it too, honestly.\""}],"why":"Staying with her, not redirecting to advice, is what she actually asked for."},{"prompt":"After a while, Ira asks: \"Okay, now can I actually hear your thoughts on it?\"","options":[{"text":"\"Now I'm glad to. Want to hear a few ideas?\"","then":"She nods, relaxed now. \"Yes, actually. Now I'm ready to hear them.\"","best":true},{"text":"\"I already had some thoughts earlier, let me finally get to them.\"","then":"She listens, though it lands like it was waiting to happen anyway."},{"text":"\"I don't really have any ideas, honestly.\"","then":"She looks surprised. \"Oh, I thought you might, given how quiet you were.\""},{"text":"\"Let's talk about it tomorrow instead.\"","then":"She looks a little deflated that the moment passed."}],"why":"Waiting until she asks is what makes the advice land as helpful, not imposed."}],"relearn":"Ask whether they want help or just to be heard, before jumping to fix their worry."},
  {"id":"cb-1382","cat":"what-it-takes","type":"role-play","persona":"any","source":"get underneath","hook":"You and Omar keep having the same argument about visiting his parents every weekend.","setup":"It's come up again tonight, word for word like always.","steps":[{"prompt":"Omar says: \"Can we please not have this exact argument again?\"","options":[{"text":"\"We keep clashing on this. What do you really need here?\"","then":"He pauses, thinking. \"Honestly, I'm not totally sure. Let me think.\"","best":true},{"text":"\"Why do we always have to fight about the exact same thing?\"","then":"He sighs. \"I don't know. Maybe neither of us says what we mean.\""},{"text":"\"Fine, let's just do whatever you want, like always.\"","then":"He looks uneasy. \"That's not really resolving anything, though.\""},{"text":"\"You clearly care more about your parents than me.\"","then":"He looks hurt, then goes quiet, thinking."}],"why":"Asking what's underneath moves past replaying the same fight again."},{"prompt":"Omar admits: \"I think I feel guilty if we skip a weekend, like I'm failing them.\"","options":[{"text":"\"That makes sense. What do you think I actually need in this?\"","then":"He considers it. \"Maybe some weekends that are just ours? I hadn't asked.\"","best":true},{"text":"\"Okay, well, I just need us to have some time that's actually ours.\"","then":"He nods, though he hasn't named what's under his own side yet."},{"text":"\"That guilt isn't really my problem to fix, though.\"","then":"He looks stung. \"I wasn't asking you to fix it, just to understand it.\""},{"text":"\"You shouldn't feel guilty. It's not logical.\"","then":"He looks frustrated. \"Telling me not to feel it doesn't really help.\""}],"why":"Naming his guilt, then asking about your need too, gets under both sides."},{"prompt":"He asks: \"So, some weekends theirs, some weekends ours? Would that work?\"","options":[{"text":"\"Yes. Let's actually split it, and name it so it isn't a fight again.\"","then":"He nods, relieved. \"Okay. Let's write it down, even. Make it real.\"","best":true},{"text":"\"I suppose we could try that out, though I'm honestly not sure it'll actually stick.\"","then":"He nods uncertainly, and the plan stays a little too vague to hold."},{"text":"\"We'll just see how it goes week to week.\"","then":"He looks unconvinced. \"That's basically what we're already doing, though.\""},{"text":"\"Sure, whatever keeps the peace for now.\"","then":"He nods, though the underlying guilt and need never quite got named."}],"why":"Naming a concrete split turns the newly understood needs into a real fix."},{"prompt":"A month later, Omar says: \"My mother's invited us for an extra weekend, out of the blue.\"","options":[{"text":"\"Let's check our plan. Is this an 'ours' weekend or not?\"","then":"He checks. \"It's actually one of ours. Let's tell her gently, together.\"","best":true},{"text":"\"I suppose we could make an exception this one time for her.\"","then":"He agrees, and the plan quietly starts bending less than a month in."},{"text":"\"That's your call. She's your mother.\"","then":"He looks uneasy. \"I thought we were deciding this together now.\""},{"text":"\"Just say no. We already have a system.\"","then":"He hesitates. \"Even without checking what kind of weekend it is?\""}],"why":"Checking the plan together, even under a new ask, keeps the system real."}],"relearn":"Ask what each of you really needs underneath a recurring clash, instead of replaying the surface fight."},
  {"id":"cb-1383","cat":"what-it-takes","type":"role-play","persona":"any","source":"couple-unit","hook":"Tanya's parents expect you both at every family function, pulling you two apart.","setup":"Another invitation arrives, clashing with existing plans.","steps":[{"prompt":"Tanya says: \"My parents will be upset if we skip this one too.\"","options":[{"text":"\"Let's agree our line first, then face your family together.\"","then":"She pauses. \"Together, not me choosing between you and them. I like that.\"","best":true},{"text":"\"Just do whatever your parents want. Honestly, it's easier.\"","then":"She nods, then frowns: \"But we need some line, don't we?\""},{"text":"\"Your family asks for way too much, honestly.\"","then":"She stiffens. \"That's my family you're talking about.\""},{"text":"\"You decide. I don't really want to get involved.\"","then":"She looks alone in it. \"I don't want to decide this alone, though.\""}],"why":"Deciding your shared line first keeps you a team facing family, not opponents."},{"prompt":"Tanya asks: \"Okay, so what's our actual line, then?\"","options":[{"text":"\"Big events, yes. Every single weekly gathering, not automatically.\"","then":"She nods slowly. \"That actually sounds fair. Let's tell them together.\"","best":true},{"text":"\"Whatever feels manageable at the time, I suppose, week to week.\"","then":"She nods, though \"manageable\" ends up meaning almost every time still."},{"text":"\"Just say yes to everything, less hassle overall.\"","then":"She looks tired. \"That's what we're already doing, and it's exhausting.\""},{"text":"\"Say no to all of it. Let's just protect our time.\"","then":"She hesitates. \"All of it feels like it might hurt them, though.\""}],"why":"Naming a real, specific line makes it something you can both actually hold."},{"prompt":"Tanya's mother calls, upset: \"You're skipping again? What's going on with you two?\"","options":[{"text":"\"We're not skipping everything, just being intentional with our time.\"","then":"Tanya, listening in, squeezes your hand, grateful you said \"we\".","best":true},{"text":"\"That's honestly between us. We really don't need to explain every choice we make.\"","then":"Tanya looks uneasy, caught between you and her mother's hurt."},{"text":"\"That's really Tanya's decision, not mine to explain.\"","then":"Tanya looks stung, suddenly standing alone in the conversation."},{"text":"\"We're just busy, nothing's going on, don't worry.\"","then":"Her mother sounds unconvinced, and the real line never gets explained."}],"why":"Answering as 'we' shows the line is a shared decision, not one partner's fault."}],"relearn":"Set your shared line together first and face family as a couple-unit, rather than defaulting to one side."},
  {"id":"cb-1384","cat":"what-it-takes","type":"role-play","persona":"any","source":"weekly check-in","hook":"You and Kabir realise you haven't had a real conversation in almost two weeks.","setup":"Passing each other in the kitchen, it finally hits you.","steps":[{"prompt":"Kabir says: \"Oh, hey. Didn't realise you'd be up this early.\"","options":[{"text":"\"Can we keep ten minutes a week to ask how we're doing?\"","then":"He pauses. \"Yeah. Honestly, I didn't realise we'd drifted this much.\"","best":true},{"text":"\"We never talk anymore, and honestly it's kind of on you.\"","then":"He looks defensive. \"On me? You've been just as busy, though.\""},{"text":"\"It's fine. We're both just busy right now.\"","then":"He nods and heads out, and the drift continues unnoticed."},{"text":"\"I guess we should talk more, someday.\"","then":"He nods vaguely, and \"someday\" never quite seems to arrive."}],"why":"A specific, small ask is easier to start than a vague 'let's talk more'."},{"prompt":"That evening, Kabir says: \"We should make time to actually talk. When would that even happen?\"","options":[{"text":"\"Sunday mornings, before the week gets away from us again.\"","then":"He nods. \"That actually works. Let's put it somewhere we'll see it.\"","best":true},{"text":"\"Whenever we both happen to be free at the same time.\"","then":"He nods, though \"whenever\" is exactly what led to the drift before."},{"text":"\"Whenever you remember to bring it up.\"","then":"He looks uneasy. \"I'd rather this not rest only on me remembering.\""},{"text":"\"Let's not overschedule something this small.\"","then":"He shrugs, and the check-in stays vague enough to quietly not happen."}],"why":"A fixed time is what actually protects the habit from the same busy drift."},{"prompt":"That weekend, Kabir asks: \"Okay, so, how are you really doing this week?\"","options":[{"text":"\"Actually a bit stretched thin. How about you, really?\"","then":"He exhales. \"Same, honestly. Good to actually say that out loud.\"","best":true},{"text":"\"Fine, I guess, nothing much to really report on my end.\"","then":"He nods, though the check-in stays surface-level rather than real."},{"text":"\"Good, great, everything's totally fine.\"","then":"He looks unconvinced but doesn't push past the easy answer."},{"text":"\"Can we skip this week? I'm not really in the mood.\"","then":"He looks disappointed. \"That's kind of the point of doing it weekly.\""}],"why":"Answering honestly, not just 'fine', is what makes the ten minutes count."},{"prompt":"A month later, Kabir says: \"I actually look forward to Sundays now, is that weird?\"","options":[{"text":"\"Not weird at all. Same here, honestly.\"","then":"He smiles. \"Let's not let this one slip, whatever else gets busy.\"","best":true},{"text":"\"A little weird, maybe, but I guess it's nice, sort of.\"","then":"He laughs, though it lands a bit more awkward than warm."},{"text":"\"I mean, it's just ten minutes, not a big deal.\"","then":"He looks a little deflated. \"It's felt like more than that to me.\""},{"text":"\"Let's not jinx it by talking about it too much.\"","then":"He shrugs, and the moment passes without either of you naming it."}],"why":"Naming that the habit matters to you too keeps you both protecting it."}],"relearn":"Propose a small regular check-in to stay connected, rather than blaming them for the drift."},
  {"id":"cb-1385","cat":"what-it-takes","type":"role-play","persona":"any","source":"name reliability","hook":"Vihaan promised to handle the flat's lease renewal, a thing you'd worried about for weeks.","setup":"Tonight he mentions, almost in passing, that it's done.","steps":[{"prompt":"Vihaan says: \"Oh, by the way, I sorted the lease renewal today.\"","options":[{"text":"\"You said you'd handle it, and you did. That means a lot.\"","then":"He looks pleased. \"Oh. I wasn't sure you'd even track that I said that.\"","best":true},{"text":"\"Cool, thanks. I'd honestly forgotten it was even due.\"","then":"He nods, and the moment passes without either of you dwelling on it."},{"text":"\"Finally, that was stressing me out for weeks.\"","then":"He looks a little deflated. \"I did say I'd get to it, though.\""},{"text":"\"Good, one less thing on my list to worry about.\"","then":"He nods, though it reads more like relief than actual appreciation."}],"why":"Naming the follow-through specifically makes the reliability feel seen."},{"prompt":"Vihaan asks, a little unsure: \"Did you even notice I'd said I'd do that?\"","options":[{"text":"\"Of course. When you follow through, I notice. It matters.\"","then":"He smiles. \"That's really good to know. I'll keep that up, then.\"","best":true},{"text":"\"I mean, sort of. I didn't really think about it too much.\"","then":"He shrugs, and it lands more like a coincidence than real appreciation."},{"text":"\"I remember everything you don't do too, for the record.\"","then":"He looks stung. \"That took a turn. I thought this was a good moment.\""},{"text":"\"I guess I got lucky remembering that one.\"","then":"He laughs it off, though the moment loses some of its warmth."}],"why":"Naming that follow-through gets noticed encourages him to keep choosing it."},{"prompt":"Weeks later, after following through again, Vihaan asks, half-joking: \"Did you notice this time too?\"","options":[{"text":"\"I saw that too. You're building a real pattern here.\"","then":"He grins, genuinely pleased. \"A pattern. I like the sound of that.\"","best":true},{"text":"\"Nice, though I probably would have handled it myself anyway.\"","then":"He deflates slightly. \"Right. Good to know, I guess.\""},{"text":"\"You don't need to keep checking if I noticed, you know.\"","then":"He looks a little embarrassed. \"Fair, sorry, ignore that.\""},{"text":"\"Two for two, don't let it go to your head.\"","then":"He laughs, though it lands a bit more guarded than warm."}],"why":"Naming the pattern, not just the one act, makes reliability feel real to him."}],"relearn":"Name when your partner follows through; reliability noticed out loud makes them want to keep it up."},
  {"id":"cb-1386","cat":"what-it-takes","type":"role-play","persona":"any","source":"money, not blame","hook":"Money's been tight for months, and you're ready to finally talk about it with Devansh.","setup":"Tonight, another card decline reminds you it can't wait any longer.","steps":[{"prompt":"Devansh says, embarrassed: \"Sorry, must be low balance again.\"","options":[{"text":"\"Money's on my mind. Can we look at it together this weekend?\"","then":"He nods slowly. \"Yeah. Honestly, I've been avoiding thinking about it too.\"","best":true},{"text":"\"You're the reason we're always broke lately, if I'm honest.\"","then":"He looks stung. \"That's not really fair, we both spend, you know.\""},{"text":"\"It's fine, don't worry about it.\"","then":"He nods, relieved, and the worry stays unspoken between you both."},{"text":"\"We really need to sort out our finances.\"","then":"He tenses slightly. \"Our finances, or my spending, is what you mean?\""}],"why":"Naming it as a shared worry, not a fault, invites him in, not on the defence."},{"prompt":"That weekend, Devansh sits down with the bank statements and asks: \"Where do we even start?\"","options":[{"text":"\"Let's list everything coming in and going out, together.\"","then":"He nods. \"Okay. That actually feels more doable than I expected.\"","best":true},{"text":"\"Let's figure out who's spending more than they should be, first.\"","then":"He tenses. \"That sounds like it's about to become about me again.\""},{"text":"\"You track it, you're better with the numbers.\"","then":"He looks uneasy. \"I'd rather we did this one together, honestly.\""},{"text":"\"Let's not get too deep into detail, just the big picture.\"","then":"He shrugs, though the big picture alone won't really solve much."}],"why":"Looking at everything together, plainly, keeps it a shared problem, not a hunt."},{"prompt":"Going through it, Devansh admits: \"I've been spending on stuff I don't really need.\"","options":[{"text":"\"Thanks for saying that. Let's figure out a plan, not a punishment.\"","then":"He exhales. \"A plan, not a punishment. Okay. I can work with that.\"","best":true},{"text":"\"I knew it, I honestly suspected that for a while now, if I'm being truthful.\"","then":"He looks defensive. \"Okay, well, now it just feels like I was right to worry.\""},{"text":"\"That explains a lot, honestly.\"","then":"He looks small. \"Yeah. I know. I'm sorry.\""},{"text":"\"We'll need to cut that out completely, starting now.\"","then":"He nods, though \"completely\" already sounds hard to actually keep."}],"why":"Naming a plan, not a punishment, keeps him honest instead of defensive."},{"prompt":"A month later, Devansh says: \"I actually spent less this month, mostly.\"","options":[{"text":"\"That's real progress. Let's look at the numbers again.\"","then":"He smiles, relieved. \"Yeah, let's see how it actually went.\"","best":true},{"text":"\"Mostly, though, so not completely, I'm guessing?\"","then":"He deflates a little. \"I said mostly. I thought that still counted.\""},{"text":"\"Good, so we don't need these weekly check-ins anymore, then.\"","then":"He looks unsure. \"I think I'd rather we kept doing them, actually.\""},{"text":"\"We'll see if it actually lasts this time.\"","then":"He looks discouraged. \"I'm trying. That doesn't feel like much credit.\""}],"why":"Celebrating progress together keeps the shared plan a habit, not a one-time fix."}],"relearn":"Open money as a shared problem to solve together, rather than pinning it on your partner."},
  {"id":"cb-1387","cat":"what-it-takes","type":"role-play","persona":"Aditya","source":"presence over minimising","hook":"Dev comes home from work looking drained, dropping onto the couch without a word.","setup":"Aditya sets aside what he was doing and turns toward him.","steps":[{"prompt":"Dev says quietly: \"Don't mind me, just a rough day.\"","options":[{"text":"\"Rough one? I'm right here. Want to talk, or just sit with me?\"","then":"Dev leans into him. \"Just sit, for now. That's honestly perfect.\"","best":true},{"text":"\"You always overthink everything, honestly, just try to relax.\"","then":"Dev stiffens slightly. \"That's not really what I needed to hear.\""},{"text":"\"Want me to leave you alone for a bit?\"","then":"Dev hesitates. \"Actually, no, I don't think that's what I want.\""},{"text":"\"What happened this time?\"","then":"Dev sighs. \"Can we not do the whole play-by-play right now?\""}],"why":"Offering presence and a real choice meets him without minimising the day."},{"prompt":"After a quiet moment, Dev says: \"It's just been one thing after another lately.\"","options":[{"text":"\"That sounds like a lot to carry. I'm not going anywhere.\"","then":"Dev exhales, some tension easing. \"Thank you. That actually helps.\"","best":true},{"text":"\"It'll pass, these things always do eventually, don't worry.\"","then":"Dev nods, and you stop yourself from saying more."},{"text":"\"You've had a lot of rough weeks lately, come to think of it.\"","then":"Dev tenses. \"Is this really the moment to point that out?\""},{"text":"\"Want me to handle dinner so you can just rest?\"","then":"Dev nods, grateful, though he still seems a little far away."}],"why":"Naming the weight as real, without rushing past it, is what presence looks like."},{"prompt":"Later, Dev says: \"Thanks for not trying to fix it or brush it off tonight.\"","options":[{"text":"\"Always. Being here matters more than the right words.\"","then":"Dev smiles, settling further into the couch beside him.","best":true},{"text":"\"Of course, I mean, what else would I even do here.\"","then":"Dev nods, though the moment loses a little of its warmth."},{"text":"\"I figured you'd tell me if you wanted advice.\"","then":"Dev nods. \"I would have. Tonight I just needed this, though.\""},{"text":"\"See, sometimes just relaxing does help, right?\"","then":"Dev pauses. \"That's not quite what tonight was about, actually.\""}],"why":"Choosing presence over fixing, plainly named, is what actually landed tonight."}],"relearn":"Offer steady presence and a choice, instead of minimising what your partner is carrying."},
  {"id":"cb-1388","cat":"what-it-takes","type":"branch","persona":"any","source":"settle the split","hook":"You keep clashing over the same chore split.","steps":[{"prompt":"The dishes pile up again and tempers flare. What do you do?","options":[{"text":"Do them yourself silently","then":"The sink's empty tonight. The same clash is waiting for tomorrow."},{"text":"Snap and then drop it","then":"The snap clears the air for an hour, and nothing else changes."},{"text":"Quietly resent it and say absolutely nothing","then":"The resentment builds, and the chores stay exactly as they were."},{"text":"Suggest sitting down to agree a system","then":"Your partner puts the sponge down, ready to actually talk about it.","best":true}],"why":"Sitting down to agree a system replaces the weekly friction with an actual plan."},{"prompt":"That weekend, your partner asks to sort the chores out properly. What do you bring?","options":[{"text":"A demand they just try harder","then":"\"Try harder\" doesn't tell either of you who's doing what."},{"text":"A vague promise to split things evenly","then":"Vague and evenly turn out to mean different things to each of you."},{"text":"A plan to revisit \"whenever it comes up\"","then":"Whenever it comes up turns out to be never, until it's a fight again."},{"text":"A fixed list of who owns what going forward","then":"You both leave with the same list in your heads.","best":true}],"why":"A fixed list of who owns what replaces guessing with something you can both point to."},{"prompt":"Two weeks later, one task keeps slipping. What do you do?","options":[{"text":"Silently absorb it again","then":"The list looks fine on paper, and one line quietly isn't true anymore."},{"text":"Snap about it once more","then":"The snap says something's wrong, without saying what to fix."},{"text":"Drop the whole system and go back to before","then":"Without the list, you're back to guessing and clashing."},{"text":"Name it and adjust the list","then":"You cross one name out and write another, and it holds again.","best":true}],"why":"Naming the slip and adjusting the list keeps the system fair instead of letting it quietly break."}],"debrief":"A recurring chore clash needs a clear agreement, not silent absorbing or snapping.","relearn":"Agree who owns what. Absorbing it or snapping just repeats the clash."},
  {"id":"cb-1389","cat":"what-it-takes","type":"branch","persona":"any","source":"don't escalate","hook":"Your partner says something hurtful mid-argument.","steps":[{"prompt":"The words land and sting. What do you do?","options":[{"text":"Fire back something that wounds more","then":"One hurtful line becomes two, and the fight gets bigger, not clearer."},{"text":"Go silent and store it","then":"The sting stays exactly where it landed, just unspoken now."},{"text":"Pretend it didn't bother you","then":"It bothered you. Pretending just delays when that shows up."},{"text":"Name the hurt calmly and ask to slow down","then":"Your partner pauses, like they hear how that landed.","best":true}],"why":"Naming the hurt and slowing down stops the fight from escalating past the original issue."},{"prompt":"They apologise, but the argument's original topic is still unresolved. What do you do?","options":[{"text":"Drop the topic entirely to keep the peace","then":"The peace holds today, and the topic waits, unresolved, for later."},{"text":"Bring up old hurts too, now that it's open","then":"The conversation grows bigger than the one thing you needed to settle."},{"text":"Insist on finishing the fight immediately","then":"You're both still raw, and the timing works against you."},{"text":"Return to the topic once things are calmer","then":"You come back to it later, and it's easier to actually hear each other.","best":true}],"why":"Returning to the real topic once you're calmer gets it solved instead of just cooled off."},{"prompt":"A similarly heated moment almost happens again later. What do you do?","options":[{"text":"Let it fly this time since you're tired","then":"Tired or not, the same spiral starts up again."},{"text":"Match their tone to \"teach them\"","then":"Matching the tone teaches the fight to escalate faster, not slower."},{"text":"Go quiet and disengage","then":"Disengaging avoids the sting, and avoids solving anything too."},{"text":"Catch it and ask for a pause again","then":"It's quicker to catch this time. You've done it before.","best":true}],"why":"Catching it and pausing again is what turns one good moment into an actual habit."}],"debrief":"When words hurt mid-fight, name it and slow down, rather than wounding back or storing it.","relearn":"Name a hurt and slow the talk down, not hit back or store it silently."},
  {"id":"cb-1390","cat":"what-it-takes","type":"branch","persona":"any","source":"restart kindness","hook":"You've slowly stopped doing the little kind things for each other.","steps":[{"prompt":"You notice the warmth has faded. What do you do?","options":[{"text":"Wait to feel romantic again first","then":"The feeling doesn't arrive on its own, and neither does the warmth."},{"text":"Assume it'll pass on its own","then":"It doesn't pass. It just becomes the new normal."},{"text":"Mention it as a complaint","then":"Your partner gets defensive instead of curious."},{"text":"Do one small kind thing today","then":"Your partner looks up, a little surprised, and smiles.","best":true}],"why":"Doing one small kind thing starts the warmth moving again, instead of waiting to feel it first."},{"prompt":"The next day, you make your partner's tea without being asked, and they smile. What do you do next?","options":[{"text":"Stop there since you made your point","then":"The one gesture stands alone, and the old pattern creeps back tomorrow."},{"text":"Wait for them to reciprocate before continuing","then":"You both end up waiting for the other to go first."},{"text":"Mention how long you'd stopped doing this","then":"The nice moment gets a slightly guilty edge to it."},{"text":"Keep it going as a regular habit","then":"The small gestures start showing up more than once this week.","best":true}],"why":"Turning one gesture into a habit is what actually rebuilds the warmth over time."},{"prompt":"A busy week makes even small kind things feel like too much. What do you do?","options":[{"text":"Skip it. This week doesn't count","then":"This week becomes an easy excuse, and so does the next one."},{"text":"Quietly feel guilty and skip it anyway","then":"The guilt doesn't make the gesture happen either."},{"text":"Wait until things calm down to restart","then":"Calm doesn't arrive on schedule, and neither does the habit."},{"text":"Do a small version anyway","then":"It takes two minutes, and the habit survives the busy week.","best":true}],"why":"A small version on a busy day keeps the habit alive instead of losing it to a bad week."}],"debrief":"Warmth returns by doing small kind things, not waiting to feel it or assuming it self-runs.","relearn":"Restart a small kindness now. Warmth comes through action, not waiting to feel it."},
  {"id":"cb-1391","cat":"what-it-takes","type":"branch","persona":"any","source":"leave the door open","hook":"Your partner seems off but says \"nothing's wrong.\"","steps":[{"prompt":"They go quiet for the evening. What do you do?","options":[{"text":"Drop it, decide it's not your problem","then":"The quiet sits there all evening, untouched by either of you."},{"text":"Demand they tell you right now what's wrong","then":"They pull back further instead of opening up."},{"text":"Pretend you haven't noticed","then":"They notice you noticing, and not saying anything."},{"text":"Stay gently available and say you're there","then":"They don't say much, but they stay close instead of drifting off.","best":true}],"why":"Staying gently available keeps a door open that pushing or ignoring would close."},{"prompt":"The next day they're still distant. What do you do?","options":[{"text":"Push harder for an answer","then":"The harder push gets a shorter answer, not a truer one."},{"text":"Give up and match their distance","then":"Now there are two people being distant instead of one."},{"text":"Tell others about your worry instead of them","then":"Everyone knows except the person who actually needs to hear it."},{"text":"Gently check in again without pressure","then":"They glance up, like the second gentle check-in landed differently.","best":true}],"why":"A second gentle check-in, without pressure, shows you're still there without cornering them."},{"prompt":"They finally open up a little. What do you do?","options":[{"text":"Interrupt with your own reaction fast","then":"They stop partway through, like the door's closing again."},{"text":"Change the subject once it's said","then":"What they finally said gets no room to actually land."},{"text":"Judge whether their reason was \"good enough\"","then":"They read the judgment, and it's the last thing they say tonight."},{"text":"Listen without rushing them","then":"They keep going, a little more each time you don't jump in.","best":true}],"why":"Listening without rushing is what makes it safe for them to keep opening up."}],"debrief":"When \"I'm fine\" rings hollow, stay gently available. Don't drop it or demand answers.","relearn":"Stay gently available when a partner withdraws. Don't dismiss or force it."},
  {"id":"cb-1392","cat":"what-it-takes","type":"branch","persona":"any","source":"rebuild after a slip","hook":"You forgot something you promised, and your partner is upset.","steps":[{"prompt":"They tell you they're hurt. What do you do?","options":[{"text":"List how busy you've been","then":"The list explains your week, and does nothing for the hurt."},{"text":"Promise vaguely it won't happen again","then":"The vague promise sounds a lot like the last one."},{"text":"Get defensive about being blamed","then":"The hurt gets pushed aside by the defending."},{"text":"Own it fully without excuses","then":"They exhale, like the excuse they braced for never came.","best":true}],"why":"Owning it without excuses lets them feel heard instead of having to argue their hurt."},{"prompt":"They ask what happens next time. What do you do?","options":[{"text":"Say you'll just try harder","then":"\"Try harder\" doesn't tell them what's actually going to change."},{"text":"Say it's not that big a deal","then":"It was a big enough deal to bring up. Saying otherwise reopens it."},{"text":"Promise perfection from now on","then":"Perfection is a promise you can't actually keep."},{"text":"Set up a concrete reminder","then":"They watch you actually set the reminder, right there.","best":true}],"why":"A concrete reminder gives them something real to trust, not just another promise."},{"prompt":"A similar situation comes up weeks later. What do you do?","options":[{"text":"Forget again and hope they don't notice","then":"They notice. It costs more than the first time did."},{"text":"Wait for them to remind you","then":"The reminder job quietly lands back on them."},{"text":"Apologise in advance just in case","then":"The advance apology doesn't replace the reminder actually working."},{"text":"Use the reminder system you built","then":"It catches you this time, exactly like it was supposed to.","best":true}],"why":"Actually using the system you built proves the repair was real, not just words."},{"prompt":"They mention they still feel a little wary. What do you do?","options":[{"text":"Get frustrated they haven't fully moved on","then":"The frustration adds a new hurt on top of the old one."},{"text":"Insist they should trust you now","then":"Insisting doesn't speed up something that has to be earned."},{"text":"Avoid the topic so it doesn't come up","then":"Avoiding it doesn't make the wariness go away either."},{"text":"Acknowledge it takes time and keep showing up","then":"They relax a little more, seeing you're not rushing them past it.","best":true}],"why":"Acknowledging it takes time, and showing up anyway, is what actually rebuilds trust."}],"debrief":"After dropping a promise, own it and build a real fix, not a defence or an empty promise.","relearn":"Own a broken promise and put a real fix in place. Vague promises don't rebuild trust."},
  {"id":"cb-1393","cat":"what-it-takes","type":"branch","persona":"any","source":"stay a whole person","hook":"You've slowly given up your own friends and interests since the relationship began.","steps":[{"prompt":"A friend invites you out and you almost say no again. What do you do?","options":[{"text":"Cancel like usual to stay available at home","then":"You're home again, and something in you quietly notices the pattern."},{"text":"Resent your partner silently instead of deciding","then":"The resentment grows, aimed at a decision you haven't actually made."},{"text":"Go without mentioning it at all","then":"You have a good time, and a small secret sits oddly next to it."},{"text":"Go, and tell your partner why it matters to you","then":"Your partner looks a little surprised, then says okay, genuinely.","best":true}],"why":"Going, and saying why it matters, keeps the choice honest instead of resentful or secret."},{"prompt":"Your friends invite you again, and your partner asks why it matters so much now. What do you do?","options":[{"text":"Get defensive, as if accused of something","then":"The question wasn't an accusation, and now it feels like a fight."},{"text":"Downplay it to avoid a discussion","then":"Downplaying it buries the actual reason you wanted to go."},{"text":"Say nothing and hope they drop the question soon","then":"They don't drop it. They just stop asking out loud."},{"text":"Explain that keeping it makes you a better partner","then":"Your partner actually considers that, instead of just accepting it.","best":true}],"why":"Explaining the real reason helps your partner see it as good for both of you, not against them."},{"prompt":"The old pull to cancel plans returns the next month. What do you do?","options":[{"text":"Shrink back to avoid any friction","then":"The friction avoided today becomes the resentment building for later."},{"text":"Cancel just this once again","then":"\"Just this once\" is exactly how the old pattern started."},{"text":"Blame your partner for wanting you home","then":"The blame lands on them for a pattern that was actually yours to change."},{"text":"Keep the plan","then":"You go, and the old guilt is quieter than you expected.","best":true}],"why":"Keeping the plan, even when the old pull returns, is what makes the change actually stick."},{"prompt":"Partner mentions missing your time together. What do you do?","options":[{"text":"Give up the reclaimed thing to smooth it over","then":"The old shrinking pattern quietly starts again."},{"text":"Feel guilty and go quiet","then":"The guilt doesn't actually answer what they said."},{"text":"Dismiss their feelings as unreasonable","then":"They stop mentioning it, and start quietly minding it instead."},{"text":"Find a balance that keeps room for both","then":"You both leave the conversation with a plan that fits both needs.","best":true}],"why":"Finding a balance keeps room for your own life without dismissing what your partner said."}],"debrief":"If you've shrunk into the relationship, reclaim a piece of yourself instead of shrinking or stewing.","relearn":"Reclaim something yours and say why. Losing yourself to keep peace breeds resentment."},
  {"id":"cb-1394","cat":"what-it-takes","type":"branch","persona":"any","source":"reach the real need","hook":"The same fight keeps coming back despite feeling \"resolved\" each time.","steps":[{"prompt":"It flares up again for the third time. What do you do?","options":[{"text":"Agree to just never mention the topic again","then":"Banning the topic doesn't ban the feeling underneath it."},{"text":"Keep re-arguing the same surface points","then":"The same points get louder, not clearer."},{"text":"Decide one of you is simply wrong","then":"Being \"wrong\" doesn't explain why this keeps coming back."},{"text":"Ask what need isn't being met underneath","then":"Your partner pauses, like the question caught something real.","best":true}],"why":"Asking about the unmet need is what a returning fight is actually asking you to notice."},{"prompt":"A day later, your partner admits the fight is about something else underneath. What do you do?","options":[{"text":"Brush it off as not the real issue","then":"The thing they just risked saying gets waved away."},{"text":"Argue that your need matters more","then":"It turns into a contest instead of a conversation."},{"text":"Change the subject","then":"The real thing, finally named, goes quiet again."},{"text":"Take it seriously and ask more","then":"Your partner keeps going, encouraged that you didn't brush it off.","best":true}],"why":"Taking the real need seriously is what finally gets underneath the fight that keeps returning."},{"prompt":"A version of the old fight almost starts again the next week. What do you do?","options":[{"text":"Let it spiral like before","then":"It plays out exactly like the last time, not the last."},{"text":"Ban the topic this time instead, for everyone's sake","then":"The ban buries it again, right where you just dug it out from."},{"text":"Ignore it and hope it passes","then":"It doesn't pass. It just waits for the next opening."},{"text":"Name the real need early","then":"It's shorter this time, because you both know what it's really about.","best":true}],"why":"Naming the real need early stops the fight from becoming yet another repeat."}],"debrief":"A returning fight is driven by an unnamed need. Surface fixes and topic bans miss it.","relearn":"Dig for the unmet need under a recurring fight. Banning or re-arguing won't settle it."},
  {"id":"cb-1395","cat":"what-it-takes","type":"branch","persona":"any","source":"drop the scoreboard","hook":"You're keeping a mental tally of who does more in the relationship.","steps":[{"prompt":"The tally crosses your mind again during an argument. What do you do?","options":[{"text":"Bring up the tally to win the fight this time","then":"The tally wins the argument, and loses something else in the process."},{"text":"Bottle it and stay quiet","then":"The tally grows by one more entry, unsaid."},{"text":"Keep counting silently","then":"The counting continues, and so does the distance it's building."},{"text":"Say plainly that you've felt unsupported","then":"Your partner stops mid-argument, like that landed differently than the fight.","best":true}],"why":"Naming the feeling directly opens a real conversation that the tally alone can't."},{"prompt":"Later, your partner notices you've been distant and asks what would actually help. What do you do?","options":[{"text":"List every past incident as evidence","then":"The list turns the conversation back into the argument you just left."},{"text":"Say \"you should just know\"","then":"They're left guessing at something you could have just said."},{"text":"Stay vague so as not to ask for too much","then":"The vague answer gives them nothing to actually change."},{"text":"Name one specific thing that would help now","then":"Your partner nods, like a specific ask is easier to actually meet.","best":true}],"why":"One specific, doable ask gives them something real to act on, not just a feeling to guess at."},{"prompt":"A week later you notice the old tally forming again. What do you do?","options":[{"text":"Let it build up again silently","then":"The tally is back, quietly doing the same damage as before."},{"text":"Use it as ammunition in the next fight","then":"The next fight gets bigger, armed with everything you've been counting."},{"text":"Assume nothing will change so why bother","then":"Not bothering guarantees exactly that."},{"text":"Name the feeling again before it builds","then":"It's a shorter conversation this time, before the tally gets very long.","best":true}],"why":"Naming the feeling early, before the tally grows, keeps it from turning into ammunition."}],"debrief":"A scoreboard means you feel unsupported: say that, don't weaponise the tally or bottle it.","relearn":"Trade the scoreboard for naming you feel unsupported. Tallies become ammunition or resentment."},
  {"id":"cb-1396","cat":"what-it-takes","type":"branch","persona":"any","source":"tired, not enemies","hook":"You're both exhausted and snapping at each other most evenings.","steps":[{"prompt":"Another short-tempered evening starts. What do you do?","options":[{"text":"Blame them for the bad mood","then":"The blame lands, and the exhaustion underneath it doesn't move."},{"text":"Push through the evening and hope it sorts itself","then":"It doesn't sort itself. Tomorrow starts just as tired."},{"text":"Snap back to match their tone","then":"Two short tempers make the evening shorter and sharper."},{"text":"Name the pattern and suggest protecting rest","then":"Your partner exhales, like naming it out loud already helps a little.","best":true}],"why":"Naming the exhaustion as a shared problem stops it from turning into a nightly blame match."},{"prompt":"By the weekend, you're both too tired to keep going like this. What do you try?","options":[{"text":"One of you rests while the other still does everything","then":"The rest for one becomes one more thing for the other to carry."},{"text":"Waiting until you're both less busy to start","then":"Less busy keeps not arriving, and neither does the rest."},{"text":"One big holiday to fix it all","then":"The holiday helps for a week, and the evenings are still what they were."},{"text":"A plan where you both actually get a break","then":"You both get an actual evening off this week, on purpose.","best":true}],"why":"A plan that gives you both real rest is what actually eases the nightly snapping."},{"prompt":"A demanding week makes rest feel impossible again. What do you do?","options":[{"text":"Drop rest entirely this week","then":"The old short-tempered evenings slot right back in."},{"text":"Snap at each other like before","then":"The snapping is back, right on schedule."},{"text":"Silently resent the interruption","then":"The resentment adds itself to the exhaustion, quietly."},{"text":"Keep a smaller break anyway","then":"Even a shorter break takes the worst edge off the evening.","best":true}],"why":"Protecting even a smaller version of the plan keeps it alive through a genuinely hard week."}],"debrief":"When exhaustion fuels nightly snapping, name it as shared and rest, instead of blaming or coasting.","relearn":"Tackle shared exhaustion as a team and rest. Nightly blame deepens the spiral."},
  {"id":"cb-1397","cat":"what-it-takes","type":"branch","persona":"any","source":"make the load seen","hook":"A friend does all the unseen work in her marriage, and it's wearing her down.","steps":[{"prompt":"She vents about it again over coffee. What do you do?","options":[{"text":"Tell her to just communicate better","then":"The advice quietly makes the fairness her job to fix."},{"text":"Say that's just how marriage is for women","then":"The load gets treated as normal instead of something that could change."},{"text":"Change the subject to cheer her up","then":"She's cheered up, but later texts that she's scared to raise it at home."},{"text":"Help her name the load out loud","then":"She starts listing things she's never actually said aloud before.","best":true}],"why":"Helping her name the load out loud is what makes it visible enough to actually address."},{"prompt":"She says she's scared raising it will start a fight. What do you do?","options":[{"text":"Tell her to drop it then","then":"The load stays hers, along with the fear of ever raising it."},{"text":"Say she should just accept it","then":"Accepting it doesn't make it any lighter to carry."},{"text":"Offer to raise it with her husband yourself","then":"It becomes your conversation instead of a change in their marriage."},{"text":"Help her think through a calm way to raise it","then":"She starts to sound less afraid and more prepared.","best":true}],"why":"Helping her prepare a calm approach gives her a way in that doesn't feel like starting a fight."},{"prompt":"A week later, she tells you her husband finally noticed how much she does, and seemed surprised. What do you do?","options":[{"text":"Say \"I told you so\"","then":"The moment becomes about being right instead of what happens next."},{"text":"Warn her not to expect real change","then":"The warning takes the wind out of a conversation that actually went well."},{"text":"Tell her to wait and see quietly","then":"Waiting quietly is exactly the pattern that got them here."},{"text":"Suggest specific things to share","then":"She leaves with concrete ideas instead of just a good feeling.","best":true}],"why":"Concrete suggestions turn his surprise into something he can actually act on."},{"prompt":"A few weeks later she's unsure if anything's really different. What do you do?","options":[{"text":"Assume it's fixed since he agreed","then":"The assumption means no one's actually checking if it changed."},{"text":"Tell her to stop bringing it up","then":"Not bringing it up is how the load quietly came back last time."},{"text":"Decide it's not your business anymore","then":"She's back to sorting this out entirely alone."},{"text":"Ask her gently how it's actually going now","then":"She stops to actually notice what's changed and what hasn't.","best":true}],"why":"Checking in again helps her notice real change instead of assuming it happened."}],"debrief":"Support a friend's unseen load by naming and sharing it, not making it her job.","relearn":"Name the invisible load and ask the partner to share it. Fairness isn't her job to \"communicate.\""},
  {"id":"cb-1398","cat":"what-it-takes","type":"choose","persona":"any","source":"two whole people","hook":"Shreya and Kunal have been together three years, through some rough patches too.","prompt":"Which of these show love being built?","options":[{"text":"Showing up after a hard week","fits":true,"note":"Showing up in a hard week is a choice repeated, which is how bonds get built."},{"text":"Working through a disagreement","fits":true,"note":"Working through a disagreement, rather than around it, is love in action."},{"text":"Posting couple photos often","fits":false,"note":"Photos can be sweet, but they show a feeling, not the building of one."},{"text":"Butterflies on a good date","fits":false,"note":"Butterflies feel wonderful, but they fade and were never proof of anything."},{"text":"Feeling it was always meant to be","fits":false,"note":"Feeling it was meant to be is a nice story, not something either of them built."},{"text":"Never once doubting the relationship","fits":false,"note":"Never doubting is rare and not required; working through doubt is what counts."}],"relearn":"A partnership is two whole people choosing each other again; love is built, not just felt."},
  {"id":"cb-1399","cat":"what-it-takes","type":"choose","persona":"any","source":"repair over perfection","hook":"Fatima and Rahul had a sharp argument last night about his mother's visit.","prompt":"Which moves actually repair things?","options":[{"text":"Naming what hurt, once both are calm","fits":true,"note":"Naming what hurt, once calm, is how the actual issue gets addressed."},{"text":"Actually apologising for their part","fits":true,"note":"A real apology for your own part is what rebuilds trust after a fight."},{"text":"Checking in later that it's really okay","fits":true,"note":"Checking back later shows the repair wasn't just for show."},{"text":"Buying a gift instead of talking","fits":false,"note":"A gift can feel nice, but it skips the conversation that's actually needed."},{"text":"Asking what the other needed then","fits":true,"note":"Understanding what they needed in that moment helps it go better next time."},{"text":"Promising to never fight again","fits":false,"note":"No couple avoids every fight, so this promise sets them up to break it."}],"relearn":"Repair after a fight matters more than never fighting; coming back is what holds a bond."},
  {"id":"cb-1400","cat":"what-it-takes","type":"choose","persona":"any","source":"small daily efforts","hook":"Anjali and Vivek have been married four years, through ordinary and busy days.","prompt":"Which efforts hold a partnership together for years?","options":[{"text":"A good morning text most days","fits":true,"note":"A daily good morning text is tiny, but it adds up over years."},{"text":"Asking how their day actually went","fits":true,"note":"Actually asking about their day, and listening, is steady care."},{"text":"A small thank you for little things","fits":true,"note":"A small thank you noticed daily builds more warmth than it costs."},{"text":"Checking in when the other seems low","fits":true,"note":"Checking in when someone seems low is quiet, reliable care."},{"text":"An expensive anniversary trip","fits":false,"note":"A lovely trip once a year can't carry the rest of the year on its own."},{"text":"One grand, surprise gesture a year","fits":false,"note":"One grand yearly gesture is memorable, but it isn't what holds daily life together."}],"relearn":"Small, steady daily efforts hold a partnership more than the occasional grand gesture."},
  {"id":"cb-1401","cat":"what-it-takes","type":"choose","persona":"any","source":"space strengthens us","hook":"Saanvi and Irfan are figuring out how much of their lives to share.","prompt":"Which choices are healthy for them as a couple?","options":[{"text":"Saanvi keeps her Sunday running club","fits":true,"note":"Keeping her own hobby means she stays a whole person inside the relationship."},{"text":"Irfan still meets his college friends","fits":true,"note":"His own friendships give him a life that isn't only about the two of them."},{"text":"Doing every single activity together","fits":false,"note":"Doing everything together sounds close, but it leaves no room to be one self."},{"text":"Dropping a friend the other dislikes","fits":false,"note":"Dropping a friend to please a partner hands your circle over to them."},{"text":"Sharing every password to prove trust","fits":false,"note":"Trust is shown over time, not proven by handing over every password."},{"text":"Checking in constantly when apart","fits":false,"note":"Constant check-ins sound caring, but they can quietly become monitoring."}],"relearn":"Keeping your own friends and interests can make the 'us' stronger, not weaker."},
  {"id":"cb-1402","cat":"what-it-takes","type":"choose","persona":"any","source":"turning toward","hook":"It's a tiring Tuesday, and Pallavi and Karan are both exhausted from work.","prompt":"Which small habits actually keep them connected?","options":[{"text":"A two-minute check-in before bed","fits":true,"note":"A short check-in on a tired night is small, but it's real connection."},{"text":"Sharing a quick dinner, even tired","fits":true,"note":"A quick shared dinner still counts as time turned toward each other."},{"text":"Saving real talk for the weekend","fits":false,"note":"Saving real talk for the weekend leaves a lot of ordinary nights unspent."},{"text":"Waiting for a holiday to reconnect","fits":false,"note":"Waiting for a holiday means most of the year goes unattended."},{"text":"Scrolling phones side by side on the sofa","fits":false,"note":"Being in the same room isn't the same as connecting."},{"text":"Assuming all is fine since nobody complained","fits":false,"note":"Quiet isn't always fine; a small check-in finds out."}],"relearn":"Turning toward each other in small moments, night after night, is the real work of love."},
  {"id":"cb-1403","cat":"what-it-takes","type":"choose","persona":"any","source":"help is care","hook":"Since moving cities for Meher's job, Ishaan and Meher keep feeling far apart.","prompt":"Where could they reach for support together?","options":[{"text":"A couples counsellor","fits":true,"note":"A counsellor gives them tools and a neutral space to use them."},{"text":"An older couple they trust","fits":true,"note":"A couple who has been through moves and distance can offer a steadier view."},{"text":"A workshop on talking things through","fits":true,"note":"Learning shared tools together can reset how they talk to each other."},{"text":"Friends who'll take one side","fits":false,"note":"Picking sides turns a shared problem into a contest."},{"text":"Posting about it on social media","fits":false,"note":"Airing it publicly adds an audience, not help."},{"text":"Waiting for it to pass on its own","fits":false,"note":"Distance tends to grow when nobody tends it."}],"relearn":"Seeking help as a couple is a sign of care, not failure."},
  {"id":"cb-1404","cat":"what-it-takes","type":"choose","persona":"any","source":"spoken appreciation","hook":"Simran handled every call to the plumber this week while Nikhil was away for work.","prompt":"Which ways of saying thanks would actually land?","options":[{"text":"Naming exactly what she did","fits":true,"note":"Naming the exact thing he noticed makes the thanks feel real, not generic."},{"text":"Saying it out loud, not just thinking it","fits":true,"note":"Said out loud, thanks actually reaches her instead of staying in his head."},{"text":"A short note of appreciation for her","fits":true,"note":"A small written note is proof the effort was actually seen."},{"text":"Assuming she already knows","fits":false,"note":"Assuming she knows means the thanks never actually reaches her."},{"text":"Saving it for their anniversary","fits":false,"note":"Saving thanks for one occasion leaves most weeks unacknowledged."},{"text":"Saying 'you're the best' in passing","fits":false,"note":"Kind, but vague praise doesn't show what he actually noticed."}],"relearn":"Appreciation said out loud is small to give and big to receive, so don't leave it unspoken."},
  {"id":"cb-1405","cat":"what-it-takes","type":"spot","hook":"Spot the two lines that erode a partnership.","scene":[{"id":"a","text":"\"I felt hurt. Can we talk about it?\"","trick":false},{"id":"b","text":"\"You always ruin everything.\"","trick":true},{"id":"c","text":"\"Thanks for handling that today.\"","trick":false},{"id":"d","text":"\"I'm keeping score of who does more.\"","trick":true},{"id":"e","text":"\"Help me understand your side.\"","trick":false}],"why":"\"You always\" attacks and scorekeeping erode a partnership; \"I felt\", thanks and curiosity build it.","relearn":"\"You always\" attacks and scorekeeping erode a partnership; \"I felt\" openers and thanks build it.","persona":"any","source":"spot the eroders"},
  {"id":"cb-1406","cat":"what-it-takes","type":"spot","hook":"Spot the two moves that break trust.","scene":[{"id":"a","text":"Doing what you promised you'd do","trick":false},{"id":"b","text":"Checking their messages in secret","trick":true},{"id":"c","text":"Telling a hard truth gently","trick":false},{"id":"d","text":"Hiding a big money worry","trick":true},{"id":"e","text":"Showing up when you said you would","trick":false}],"why":"Secret snooping and hiding things break trust; kept promises and honest gentleness build it.","relearn":"Snooping and hiding things break trust; kept promises and honest gentleness build it.","persona":"any","source":"spot trust-breakers"},
  {"id":"cb-1407","cat":"what-it-takes","type":"spot","hook":"Spot the two fake apologies.","scene":[{"id":"a","text":"\"I was wrong, and I'm sorry I hurt you.\"","trick":false},{"id":"b","text":"\"Sorry you took it that way.\"","trick":true},{"id":"c","text":"\"Here's what I'll do differently.\"","trick":false},{"id":"d","text":"\"Sorry, but honestly you started it.\"","trick":true},{"id":"e","text":"Naming exactly what you got wrong","trick":false}],"why":"\"Sorry you felt that\" and \"sorry, but you started it\" dodge ownership; the others actually repair.","relearn":"\"Sorry you felt that way\" and blame-shifting are fake apologies; owning the wrong is real repair.","persona":"any","source":"spot fake apologies"},
  {"id":"cb-1408","cat":"what-it-takes","type":"spot","hook":"Spot the two lines that erase your separateness.","scene":[{"id":"a","text":"\"Go enjoy the trip with your friends.\"","trick":false},{"id":"b","text":"\"You don't need anyone but me.\"","trick":true},{"id":"c","text":"\"Tell me what you actually think.\"","trick":false},{"id":"d","text":"\"Ask me before you make any plan.\"","trick":true},{"id":"e","text":"\"I love that you have your own thing.\"","trick":false}],"why":"\"You need only me\" and \"ask me before any plan\" erase your separateness; the others respect two whole people.","relearn":"\"You need only me\" and needing permission erase your separateness; healthy is two whole people.","persona":"any","source":"spot the erasers"},
  {"id":"cb-1409","cat":"what-it-takes","type":"spot","hook":"Spot the two lines that dump the load onto one person.","scene":[{"id":"a","text":"\"I'll own the school stuff fully.\"","trick":false},{"id":"b","text":"\"Just give me a list and I'll do it.\"","trick":true},{"id":"c","text":"\"I tracked the bills this month.\"","trick":false},{"id":"d","text":"\"You're better at remembering it all.\"","trick":true},{"id":"e","text":"\"I noticed we were low on groceries.\"","trick":false}],"why":"\"Give me a list\" and \"you're better at remembering\" keep the mental load on one person; the rest share it.","relearn":"\"Just give me a list\" and \"you remember it better\" dump the mental load; owning and noticing share it.","persona":"Pooja","source":"spot the load-dumpers"},
  {"id":"cb-1410","cat":"what-it-takes","type":"spot","hook":"Spot the two moves that escalate a fight.","scene":[{"id":"a","text":"Taking a short breather, then returning","trick":false},{"id":"b","text":"Threatening to walk out for effect","trick":true},{"id":"c","text":"Staying on the actual issue","trick":false},{"id":"d","text":"Dragging their family in to score points","trick":true},{"id":"e","text":"Asking \"help me understand\"","trick":false}],"why":"Walk-out threats and family-scoring escalate a fight; a breather, staying on-topic and curiosity calm it.","relearn":"Threats to leave and dragging in family escalate a fight; a breather and staying on the issue repair it.","persona":"any","source":"spot the escalators"},
  {"id":"cb-1411","cat":"what-it-takes","type":"spot","hook":"Spot the two myths about couples counselling.","scene":[{"id":"a","text":"\"It can help us communicate better.\"","trick":false},{"id":"b","text":"\"Going means we've already failed.\"","trick":true},{"id":"c","text":"\"Strong couples use it to build, too.\"","trick":false},{"id":"d","text":"\"Only broken couples ever need it.\"","trick":true},{"id":"e","text":"\"A neutral third view could help us.\"","trick":false}],"why":"\"It means we've failed\" and \"only broken couples go\" are myths; counselling is for building better, not only crises.","relearn":"\"Counselling means we failed\" and \"only broken couples go\" are myths; strong couples use it to build.","persona":"Saxena","source":"spot counselling myths"},
  {"id":"cb-1412","cat":"what-it-takes","type":"spot","hook":"Spot the two coasting habits that let love fade.","scene":[{"id":"a","text":"Protecting time to actually talk","trick":false},{"id":"b","text":"Assuming the spark runs itself","trick":true},{"id":"c","text":"Naming what you appreciate","trick":false},{"id":"d","text":"Treating each other as furniture","trick":true},{"id":"e","text":"A small shared ritual each week","trick":false}],"why":"Assuming the spark self-runs and treating each other as furniture let love fade; the rest keep it alive.","relearn":"Assuming the spark runs itself and going on autopilot let love fade; rituals and appreciation keep it alive.","persona":"any","source":"spot the coasters"},
  {"id":"cb-1413","cat":"what-it-takes","type":"match","hook":"Match the partnership skill to what it builds.","pairs":[{"left":"An \"I felt…\" opener","right":"A safe way to raise an issue"},{"left":"A sincere repair","right":"Closing a rupture"},{"left":"Spoken appreciation","right":"Keeping the bond warm"},{"left":"Kept promises","right":"Day-to-day trust"},{"left":"Protected talk-time","right":"Staying connected"}],"relearn":"\"I felt\" openers, repair, appreciation, kept promises and protected time each build a part of the partnership.","persona":"any","source":"skill to outcome"},
  {"id":"cb-1414","cat":"what-it-takes","type":"match","hook":"Match the unhealthy habit to what it erodes.","pairs":[{"left":"Scorekeeping","right":"The feeling of being a team"},{"left":"Hiding things","right":"Trust"},{"left":"\"You always…\" attacks","right":"Safety to be honest"},{"left":"Taking each other for granted","right":"Warmth over time"},{"left":"Stonewalling","right":"A path back to repair"}],"relearn":"Scorekeeping, hiding, blame, taking for granted and stonewalling each erode a different part of the bond.","persona":"any","source":"habit to harm"},
  {"id":"cb-1415","cat":"what-it-takes","type":"match","hook":"Match the moment to the repair move that fits it.","pairs":[{"left":"You hurt them in a fight","right":"Own it and apologise sincerely"},{"left":"The same fight keeps returning","right":"Dig for the real need underneath"},{"left":"It's getting too heated","right":"Ask for a short breather"},{"left":"You're quietly resentful about chores","right":"Name the feeling, not a tally"},{"left":"You've drifted apart","right":"Protect regular time to reconnect"}],"relearn":"Each rough moment has a fitting repair: own it, dig deeper, pause, name the feeling, or protect time.","persona":"any","source":"moment to repair"},
  {"id":"cb-1416","cat":"what-it-takes","type":"match","hook":"Match the spoken line to the partnership skill it shows.","pairs":[{"left":"\"Help me understand your side.\"","right":"Curiosity in conflict"},{"left":"\"I'll own bedtime this week.\"","right":"Sharing the load"},{"left":"\"I was wrong, I'm sorry.\"","right":"Clean repair"},{"left":"\"Thank you for handling that.\"","right":"Appreciation out loud"},{"left":"\"Let's decide this together.\"","right":"Acting as a team"}],"relearn":"Curiosity, sharing the load, clean repair, spoken thanks and deciding together each show a partnership skill.","persona":"any","source":"line to skill"},
  {"id":"cb-1417","cat":"what-it-takes","type":"match","hook":"Match the warning sign to the healthier move it points to.","pairs":[{"left":"Walking on eggshells","right":"Build safety to speak honestly"},{"left":"Silent treatment","right":"Ask for a pause, then return"},{"left":"Losing yourself in them","right":"Keep your own friends and goals"},{"left":"Grand gestures, no follow-through","right":"Small steady reliability"},{"left":"Mind-reading expectations","right":"Name what you need plainly"}],"relearn":"Each warning sign points to a healthier move: speak safely, pause-and-return, stay whole, be reliable, name needs.","persona":"any","source":"sign to fix"},
  {"id":"cb-1418","cat":"what-it-takes","type":"match","hook":"Match what a couple invests in to the strength it grows.","pairs":[{"left":"Repairing after fights","right":"Resilience"},{"left":"Sharing the mental load","right":"Fairness"},{"left":"Regular honest check-ins","right":"Closeness"},{"left":"Following through reliably","right":"Trust"},{"left":"Backing each other's goals","right":"Interdependence"}],"relearn":"Repair, sharing the load, check-ins, reliability and backing each other grow resilience, fairness, trust and closeness.","persona":"any","source":"invest to strength"},
  {"id":"cb-1419","cat":"what-it-takes","type":"match","hook":"Match the everyday scenario to the partnership skill it calls for.","pairs":[{"left":"Partner snaps after a long day","right":"Respond gently, don't fire back"},{"left":"They share a worry","right":"Ask: listen or help?"},{"left":"In-laws pull you two apart","right":"Decide as a couple-unit"},{"left":"You forgot something important","right":"Own it and make a repair"},{"left":"You've stopped really talking","right":"Restart a regular check-in"}],"relearn":"Each everyday moment calls for a skill: respond gently, ask before fixing, unite, repair, or reconnect.","persona":"any","source":"scenario to skill"},
  {"id":"cb-1420","cat":"what-it-takes","type":"match","hook":"Match the half-truth to the fuller truth about partnership.","pairs":[{"left":"\"Love means never working at it\"","right":"Closeness is built, not just felt"},{"left":"\"Conflict means we're failing\"","right":"Repair through it is what matters"},{"left":"\"Become one person\"","right":"Two whole people, a team"},{"left":"\"They should just know\"","right":"Name your needs plainly"},{"left":"\"Saying sorry first means losing\"","right":"It chooses the relationship"}],"relearn":"Each half-truth has a fuller one: love is built, repair matters, stay two whole people, name needs, repair isn't losing.","persona":"any","source":"half-truth to truth"},
];

